INSERT INTO content_sections VALUES(1,1,NULL,'heading',1,1,1,'Kolumbryna 🐙','kolumbryna','Systemowa analiza degradacji Rosji, logiki przetrwania Putina, rozpadu Iranu, transformacji energetycznej i narzędzi analitycznych. Kończy się adversarialną korektą własnych tez.',1,NULL,'Kolumbryna 🐙','A systems analysis of Russia''s degradation, Putin''s survival logic, Iran''s disintegration, the energy transition, and analytical tools. It ends with an adversarial correction of its own theses.',NULL,NULL);
INSERT INTO content_sections VALUES(2,1,1,'heading',2,2,2,'Rozdział 1. Front i spirala OPL — trójkąt spalania','front-spirala-opl','Kurcząca się armia, OPL i uderzenia w rafinerie tworzą sprzężenie degradujące front i zaplecze.',2,NULL,'Chapter 1. The Front and the Air-Defence Spiral — the Combustion Triangle','A shrinking army, air defence and strikes on refineries form a feedback loop that degrades both the front and the rear.',NULL,NULL);
INSERT INTO content_sections VALUES(3,1,1,'heading',2,2,3,'Rozdział 2. Arsenał nuklearny — odstraszanie na papierze','arsenal-nuklearny','Odstraszanie pozostaje, lecz starzejące się nośniki i opóźniony Sarmat ograniczają status supermocarstwa.',3,NULL,'Chapter 2. The Nuclear Arsenal — Deterrence on Paper','Deterrence remains, but ageing delivery systems and the delayed Sarmat programme constrain Russia''s superpower status.',NULL,NULL);
INSERT INTO content_sections VALUES(4,1,1,'heading',2,2,4,'Rozdział 3. Budżet, NWF i paradoks Hormuz','budzet-nwf-hormuz','Wojenny budżet, szybki deficyt i kurczący się NWF zderzone z paradoksem chwilowych zysków z drogiej ropy.',4,NULL,'Chapter 3. The Budget, the NWF and the Hormuz Paradox','A wartime budget, a rapidly widening deficit and a shrinking NWF collide with the paradox of temporary gains from expensive oil.',NULL,NULL);
INSERT INTO content_sections VALUES(5,1,1,'heading',2,2,5,'Rozdział 4. Eksport, dewizy i majątek — co jeszcze działa','eksport-dewizy-majatek','Utrata europejskiego gazu, degradacja eksportu i shadow fleet ograniczają trwały dopływ dewiz.',5,NULL,'Chapter 4. Exports, Foreign Currency and Assets — What Still Works','The loss of European gas markets, degrading exports and the shadow fleet limit the durable inflow of foreign currency.',NULL,NULL);
INSERT INTO content_sections VALUES(6,1,1,'heading',2,2,6,'Rozdział 5. Infrastruktura się sypie — kolej, rury, samoloty','infrastruktura-kolej-rury-samoloty','Kolej, rurociągi i lotnictwo ujawniają kumulację wieloletnich zaniedbań, braków części i zdolności odtworzeniowych.',6,NULL,'Chapter 5. Infrastructure Is Falling Apart — Railways, Pipelines, Aircraft','Railways, pipelines and aviation reveal the accumulation of years of neglect, parts shortages and weak replacement capacity.',NULL,NULL);
INSERT INTO content_sections VALUES(7,1,1,'heading',2,2,7,'Rozdział 6. Społeczeństwo na krawędzi — brain drain, pensje, policja','spoleczenstwo-na-krawedzi','Brain drain, presja płacowa i wakaty w policji osłabiają zdolność państwa do obsługi i kontroli społeczeństwa.',7,NULL,'Chapter 6. Society on the Edge — Brain Drain, Wages, Police','Brain drain, wage pressure and police vacancies weaken the state''s capacity to serve and control society.',NULL,NULL);
INSERT INTO content_sections VALUES(8,1,1,'heading',2,2,8,'Rozdział 7. Bestiariusz — 24 szare nosorożce i ich sprzężenia','bestiariusz-szare-nosorozce','24 równoległe procesy erozyjne potraktowane jako jeden sprzężony system, nie lista osobnych kryzysów.',8,NULL,'Chapter 7. Bestiary — 24 Grey Rhinos and Their Feedback Loops','Twenty-four parallel erosion processes are treated as one coupled system, not as a list of separate crises.',NULL,NULL);
INSERT INTO content_sections VALUES(9,1,1,'heading',2,2,9,'Rozdział 8. Patologia informacyjna i dlaczego nie Korea Północna','patologia-informacyjna','Patologia informacyjna dyktatury i granice analogii Rosji z Koreą Północną.',9,NULL,'Chapter 8. Information Pathology and Why This Is Not North Korea','The information pathology of dictatorship and the limits of comparing Russia with North Korea.',NULL,NULL);
INSERT INTO content_sections VALUES(10,1,1,'heading',2,2,10,'Rozdział 9. Chemia pożarów, uzależnienie i sezonowość','chemia-pozarow-uzaleznienie-sezonowosc','Pożary i backdraft jako model opóźnionej katastrofy; uzależnienie i sezonowość wzmacniają ryzyko.',10,NULL,'Chapter 9. Fire Chemistry, Addiction and Seasonality','Fire and backdraft as a model of delayed catastrophe; addiction and seasonality amplify the risk.',NULL,NULL);
INSERT INTO content_sections VALUES(11,1,1,'heading',2,2,11,'Rozdział 10. Jest już za późno — konkluzja Części I','za-pozno-konkluzja-czesci-i','Synteza Części I: system przekroczył punkt łatwej autokorekty; dalsze trajektorie ujęte probabilistycznie.',11,NULL,'Chapter 10. It Is Already Too Late — Conclusion to Part I','Part I synthesis: the system has passed the point of easy self-correction; further trajectories are framed probabilistically.',NULL,NULL);
INSERT INTO content_sections VALUES(12,1,1,'heading',2,2,12,'Rozdział 11. Dlaczego to nie jest pytanie o pieniądze','nie-pytanie-o-pieniadze','Putin oceniany nie przez dobro Rosji, lecz przez osobistą funkcję celu dyktatora bez bezpiecznej emerytury.',12,NULL,'Chapter 11. Why This Is Not a Question of Money','Putin is assessed not through Russia''s welfare, but through the personal objective function of a dictator with no safe retirement.',NULL,NULL);
INSERT INTO content_sections VALUES(13,1,1,'heading',2,2,13,'Rozdział 12. Zasoby, skreślenia i dziewięć scenariuszy desperacji','zasoby-skreslenia-scenariusze-desperacji','Pozostałe zasoby i dziewięć scenariuszy desperacji, od dealu politycznego po eskalację i scorched earth.',13,NULL,'Chapter 12. Resources, Write-Offs and Nine Scenarios of Desperation','Remaining resources and nine desperation scenarios, from a political deal to escalation and scorched earth.',NULL,NULL);
INSERT INTO content_sections VALUES(14,1,1,'heading',2,2,14,'Rozdział 13. Kiedy elity odłączą się od Putina?','elity-odlaczaja-sie-od-putina','Moment, w którym koszt lojalności elit wobec Putina przewyższa koszt odejścia.',14,NULL,'Chapter 13. When Will the Elites Detach from Putin?','The point at which the cost of elite loyalty to Putin exceeds the cost of defection.',NULL,NULL);
INSERT INTO content_sections VALUES(15,1,1,'heading',2,2,15,'Rozdział 14. Rozpad irańskiej państwowości i koncepcja operacyjna','rozpad-iranu-koncepcja-operacyjna','Rozpad koordynacji Iranu otwiera warianty Aras–Zagros i przesuwa układ Kaukazu oraz Zatoki.',15,NULL,'Chapter 14. The Disintegration of Iranian Statehood and an Operational Concept','The breakdown of Iranian coordination opens Aras–Zagros variants and shifts the balance in the Caucasus and the Gulf.',NULL,NULL);
INSERT INTO content_sections VALUES(16,1,1,'heading',2,2,16,'Rozdział 15. Mapa aktorów i ryzyka krytyczne','mapa-aktorow-ryzyka-krytyczne','Interesy kluczowych aktorów, ich zbieżności i sprzeczności oraz ryzyka, z materiałem jądrowym na czele.',16,NULL,'Chapter 15. Actor Map and Critical Risks','The interests of key actors, their convergences and conflicts, and critical risks, with nuclear material at the top of the list.',NULL,NULL);
INSERT INTO content_sections VALUES(17,1,1,'heading',2,2,17,'Rozdział 16. Hanza 2.0 — porządek bez architekta','hanza-2-0','Hanza 2.0 jako porządek regionalny utrzymywany interesami i kapitałem, bez jednego architekta.',17,NULL,'Chapter 16. Hanseatic League 2.0 — Order Without an Architect','Hanseatic League 2.0 as a regional order sustained by interests and capital rather than by a single architect.',NULL,NULL);
INSERT INTO content_sections VALUES(18,1,1,'heading',2,2,18,'Rozdział 17. Od Ormuzu do panelu — struktura, szok i substytucja','od-ormuzu-do-panelu','Szok Ormuz jako impuls do substytucji ropy i gazu oraz przyspieszenia elektryfikacji i OZE.',18,NULL,'Chapter 17. From Hormuz to the Solar Panel — Structure, Shock and Substitution','The Hormuz shock as an impulse to substitute away from oil and gas and accelerate electrification and renewables.',NULL,NULL);
