INSERT INTO content_sections VALUES(20,1,1,'heading',2,2,20,'Rozdział 19. Disinfolklore i Dark Legitimacy — trucizna i ciemna strona','disinfolklore-dark-legitimacy','Disinfolklore i dark legitimacy jako narzędzia opisu dezinformacji i paradoksalnego wzmacniania dyktatury przez ujawnianie patologii.',20,NULL,'Chapter 19. Disinfolklore and Dark Legitimacy — Poison and the Dark Side','Disinfolklore and dark legitimacy as tools for describing disinformation and the paradoxical strengthening of dictatorship through exposing pathology.',NULL,NULL);
INSERT INTO content_sections VALUES(21,1,1,'heading',2,2,21,'Rozdział 20. Źródła, etyka i granice poznania','zrodla-etyka-granice-poznania','Źródła, bias, etyka analizy wojny i jawne granice tego, co można uczciwie wnioskować.',21,NULL,'Chapter 20. Sources, Ethics and the Limits of Knowledge','Sources, bias, the ethics of analysing war, and explicit limits on what can be inferred honestly.',NULL,NULL);
INSERT INTO content_sections VALUES(22,1,1,'heading',2,2,22,'Rozdział 21. Steelmanning systemu — Chiny, inercja, zmęczenie Zachodu','steelmanning-systemu','Najmocniejsze argumenty za trwałością systemu: Chiny, inercja, zdolność adaptacji i zmęczenie Zachodu.',22,NULL,'Chapter 21. Steelmanning the System — China, Inertia, Western Fatigue','The strongest arguments for system durability: China, inertia, adaptive capacity and Western fatigue.',NULL,NULL);
