INSERT INTO content_sections VALUES(184,3,NULL,'heading',1,1,1,'lista celów','lista-celow','Chronologiczny rejestr strategicznych uderzeń od stycznia do czerwca 2026: cele, skutki, zasięg i zmieniający się rytm kampanii.',1,NULL,'Target List','A chronological register of strategic strikes from January to June 2026: targets, effects, reach and the campaign''s changing rhythm.',NULL,NULL);
