INSERT INTO content_sections VALUES(194,3,185,'heading',3,3,11,'okres 7 od 29.03 do 11.04','okres-7','Rejestr uderzeń 29 marca–11 kwietnia: selektywna pauza, nie pełne wstrzymanie.',11,NULL,'Period 7: 29 March–11 April','Register of strikes from 29 March–11 April: a selective pause, not a full halt.',NULL,NULL);
