INSERT INTO content_sections VALUES(198,3,185,'heading',3,3,15,'okres 10 od 10.05 do 16.05','okres-10','Rejestr uderzeń 10–16 maja: demembranizacja perymetru Moskwy i dalsza kompresja rafinerii.',15,NULL,'Period 10: 10–16 May','Register of strikes from 10–16 May: demembranisation of Moscow''s perimeter and further compression of refinery repair cycles.',NULL,NULL);
INSERT INTO content_sections VALUES(199,3,198,'heading',4,4,16,'Nota o zmianie rytmu — od maja tydzień','okres-10-nota-rytm','Tempo zdarzeń wymusza przejście rejestru z okresów dwutygodniowych na tygodniowe.',16,NULL,'Note on the Change in Rhythm — Weekly from May','The tempo of events forces the register to shift from fortnightly to weekly periods.',NULL,NULL);
INSERT INTO content_sections VALUES(200,3,185,'heading',3,3,17,'okres 11 od 17.05 do 23.05','okres-11','Rejestr 17–23 maja: uderzenia połączone z kampanią komunikacyjną i sygnalizacją.',17,NULL,'Period 11: 17–23 May','Register of 17–23 May: strikes combined with a communications and signalling campaign.',NULL,NULL);
