INSERT INTO content_sections VALUES(202,3,185,'heading',3,3,19,'okres 12 od 24.05 do 30.05','okres-12','Rejestr 24–30 maja: kulminacja uderzeń głębokich i formalizacja „long-range sanctions”.',19,NULL,'Period 12: 24–30 May','Register of 24–30 May: culmination of deep strikes and formalisation of “long-range sanctions”.',NULL,NULL);
INSERT INTO content_sections VALUES(203,3,202,'heading',4,4,20,'27.05 — największy pakiet uderzeń głębokich w wojnie','okres-12-pakiet-2705','27 maja: największy dotąd pakiet równoległych uderzeń głębokich.',20,NULL,'27 May — the Largest Deep-Strike Package of the War','27 May: the largest package of parallel deep strikes to date.',NULL,NULL);
INSERT INTO content_sections VALUES(204,3,185,'heading',3,3,21,'Statystyki maja — Naczelny Dowódca ZSU (gen. Syrski)','statystyki-maja-syrski','Oficjalny bilans ZSU za maj: cele Deep Strike, straty, terytorium i obrona powietrzna.',21,NULL,'May Statistics — Commander-in-Chief of the Armed Forces of Ukraine (Gen. Syrskyi)','The official Ukrainian Armed Forces balance for May: Deep Strike targets, losses, territory and air defence.',NULL,NULL);
