INSERT INTO content_sections VALUES(206,3,205,'heading',4,4,23,'03.06 — uderzenie w dniu otwarcia SPIEF','okres-13-spief','Uderzenie w Petersburg w dniu otwarcia SPIEF jako czysta sygnalizacja kalendarzem.',23,NULL,'3 June — Strike on the Opening Day of SPIEF','A strike on St Petersburg on SPIEF''s opening day as pure calendar-based signalling.',NULL,NULL);
INSERT INTO content_sections VALUES(207,3,185,'heading',3,3,24,'okres 14 od 07.06 do 13.06','okres-14','Rejestr 7–13 czerwca: interdykcja R-280, podstacje, kolej, arsenały i nowe typy celów.',24,NULL,'Period 14: 7–13 June','Register of 7–13 June: R-280 interdiction, substations, railways, arsenals and new target types.',NULL,NULL);
INSERT INTO content_sections VALUES(208,3,185,'heading',3,3,25,'okres 15 od 14.06 do 20.06','okres-15','Rejestr 14–20 czerwca: dalsza presja na paliwa, Moskwę, Krym i infrastrukturę.',25,NULL,'Period 15: 14–20 June','Register of 14–20 June: continued pressure on fuel, Moscow, Crimea and infrastructure.',NULL,NULL);
INSERT INTO content_sections VALUES(209,3,185,'heading',3,3,26,'okres 16 od 21.06 (w toku)','okres-16','Rejestr od 21 czerwca: Krym jako wyspa, mikroelektronika, rafinerie i krajowa kaskada paliwowa.',26,NULL,'Period 16: from 21 June (Ongoing)','Register from 21 June onward: Crimea as an island, microelectronics, refineries and a nationwide fuel cascade.',NULL,NULL);
INSERT INTO content_sections VALUES(210,4,NULL,'heading',1,1,1,'lipiec 2026. przejscie na hurt','tytul','Lipiec 2026 jako przejście ukraińskiej presji z pojedynczych uderzeń na skalę systemową. Analiza paliw, gospodarki, mobilizacji, adaptacji i kurczących się opcji Rosji.',1,NULL,'July 2026. The Shift to Wholesale','July 2026 as the point when Ukrainian pressure shifts from individual strikes to system scale. An analysis of fuel, the economy, mobilisation, adaptation and Russia''s shrinking options.',NULL,NULL);
INSERT INTO content_sections VALUES(211,4,210,'heading',2,2,2,'I. Skala hurtu','skala-hurtu','Zmiana jednostki pomiaru: z pojedynczych trafień na bilans całych klas zdolności.',2,NULL,'I. The Scale of Wholesale','A change in the unit of measurement: from individual hits to the balance of entire capability classes.',NULL,NULL);
INSERT INTO content_sections VALUES(212,4,211,'heading',3,3,3,'1. Przerób — dno dwudziestolecia','przerob-dno-dwudziestolecia','Rosyjski przerób ropy na minimum od dwóch dekad, z trwałymi wyłączeniami rafinerii.',3,NULL,'1. Refining — a Twenty-Year Low','Russian oil refining at its lowest level in two decades, with persistent refinery outages.',NULL,NULL);
INSERT INTO content_sections VALUES(213,4,211,'heading',3,3,4,'2. Tempo uderzeń','tempo-uderzen','Skok liczby i geograficznego zasięgu trafień w rosyjską infrastrukturę paliwową.',4,NULL,'2. Strike Tempo','A surge in the number and geographic reach of hits on Russian fuel infrastructure.',NULL,NULL);
INSERT INTO content_sections VALUES(214,4,213,'heading',6,6,5,'o „przerwie", której nie było','dygresja-o-lulu','Rzekoma pauza rafineryjna była przesunięciem kampanii na magazyny i logistykę.',5,NULL,'On the “Pause” That Wasn''t','The supposed refinery pause was a shift of the campaign toward storage and logistics.',NULL,NULL);
INSERT INTO content_sections VALUES(215,4,211,'heading',3,3,6,'3. Zasięg kryzysu po stronie rosyjskiej','zasieg-kryzysu','Deficyt paliw obejmuje niemal całą Rosję i zaczyna dotykać także frontu.',6,NULL,'3. The Geographic Reach of the Crisis on the Russian Side','Fuel shortages cover almost all of Russia and are beginning to affect the front as well.',NULL,NULL);
INSERT INTO content_sections VALUES(216,4,211,'heading',3,3,7,'4. Co znaczy „hurt"','co-znaczy-hurt','Celami stają się klasy obiektów, a miarą bilans i nieodwracalność strat.',7,NULL,'4. What “Wholesale” Means','Target classes, rather than individual objects, become the unit of attack; the measure is the balance and irreversibility of losses.',NULL,NULL);
INSERT INTO content_sections VALUES(217,4,210,'heading',2,2,8,'II. Marketplace jako cel','marketplace-jako-cel','Magazyny handlu internetowego jako element wojskowej logistyki i kanał transmisji strat finansowych.',8,NULL,'II. The Marketplace as a Target','E-commerce warehouses as part of military logistics and as a channel transmitting financial losses.',NULL,NULL);
INSERT INTO content_sections VALUES(218,4,217,'heading',3,3,9,'1. Kampania Wildberries','kampania-wildberries','Seria uderzeń w magazyny Wildberries odsłania nową, słabo bronioną klasę celów.',9,NULL,'1. The Wildberries Campaign','A series of strikes on Wildberries warehouses exposes a new, weakly defended target class.',NULL,NULL);
INSERT INTO content_sections VALUES(219,4,218,'heading',6,6,10,'o ewakuacji, której nie było','dygresja-ewakuacja','Brak ewakuacji pracowników jako wskaźnik nieprzygotowania systemu na tę kategorię uderzeń.',10,NULL,'On the Evacuation That Never Happened','The absence of worker evacuation as an indicator that the system was unprepared for this category of strike.',NULL,NULL);
INSERT INTO content_sections VALUES(220,4,217,'heading',3,3,11,'2. Pierwszy Ozon','pierwszy-ozon','Rozszerzenie kampanii z Wildberries na infrastrukturę Ozona.',11,NULL,'2. The First Ozon','Expansion of the campaign from Wildberries to Ozon infrastructure.',NULL,NULL);
INSERT INTO content_sections VALUES(221,4,217,'heading',3,3,12,'3. Uzasadnienie celu','uzasadnienie-celu','Marketplace jako realny węzeł dostaw wojskowych, nie przypadkowy obiekt cywilny.',12,NULL,'3. Target Rationale','The marketplace as a real military-supply node, not an accidental civilian object.',NULL,NULL);
INSERT INTO content_sections VALUES(222,4,217,'heading',3,3,13,'4. Powód, nie pretekst — i przypieczętowanie przez UE','powod-nie-pretekst','Rosyjskie oznaczenia wojskowych towarów potwierdzają materialny powód wyboru celu.',13,NULL,'4. Reason, Not Pretext — and Sealed by the EU','Russian labelling of military goods confirms the material reason for selecting the target.',NULL,NULL);
INSERT INTO content_sections VALUES(223,4,222,'heading',4,4,14,'Co mogła zrobić Unia','co-mogla-zrobic-ue','UE odpowiada sankcjami na te same podmioty, zamiast podważać ukraińską kwalifikację celu.',14,NULL,'What the Union Could Do','The EU responds with sanctions against the same entities instead of challenging Ukraine''s classification of the target.',NULL,NULL);
INSERT INTO content_sections VALUES(224,4,217,'heading',3,3,15,'5. Efekt finansowy i przerzucenie ryzyka','efekt-finansowy','Straty magazynowe przechodzą na sprzedawców, kredyty, rezerwy bankowe i państwo.',15,NULL,'5. Financial Effect and Risk Transfer','Warehouse losses flow through to sellers, loans, bank provisions and the state.',NULL,NULL);
INSERT INTO content_sections VALUES(225,4,210,'heading',2,2,16,'III. Milczenie strategiczne Zachodu','milczenie-strategiczne','Zachód działa według analiz strukturalnych, ale publicznie mówi głównie o bieżących zdarzeniach.',16,NULL,'III. The West''s Strategic Silence','The West acts on structural analysis while speaking publicly mostly about current events.',NULL,NULL);
INSERT INTO content_sections VALUES(226,4,225,'heading',3,3,17,'1. Luka między wiedzą a mową','luka-miedzy-wiedza-a-mowa','Decyzje Zachodu zdradzają więcej wiedzy strategicznej niż oficjalne wypowiedzi.',17,NULL,'1. The Gap Between Knowledge and Speech','Western decisions reveal more strategic knowledge than official statements do.',NULL,NULL);
INSERT INTO content_sections VALUES(227,4,225,'heading',3,3,18,'2. Słowo urzędującego to zobowiązanie, nie opinia','slowo-jako-zobowiazanie','Strategiczna prognoza urzędującego polityka natychmiast tworzy obowiązek działania.',18,NULL,'2. The Word of an Incumbent Is a Commitment, Not an Opinion','A strategic forecast by a serving politician immediately creates an obligation to act.',NULL,NULL);
INSERT INTO content_sections VALUES(228,4,225,'heading',3,3,19,'3. Pytanie, którego nikt nie chce usłyszeć','pytanie-ktorego-nikt-nie-chce','Rozpad Rosji otwiera niewygodne pytanie o kontrolę arsenału jądrowego.',19,NULL,'3. The Question No One Wants to Hear','Russia''s disintegration opens the uncomfortable question of who controls the nuclear arsenal.',NULL,NULL);
INSERT INTO content_sections VALUES(229,4,228,'heading',6,6,20,'o cenie ropy','dygresja-cena-ropy','Słowa decydentów o rosyjskiej ropie same mogą poruszać cenami energii.',20,NULL,'On the Oil Price','Decision-makers'' words about Russian oil can themselves move energy prices.',NULL,NULL);
INSERT INTO content_sections VALUES(230,4,225,'heading',3,3,21,'4. Asymetria kosztu pomyłki','koszt-pomylki','Politycznie taniej milczeć niż publicznie pomylić się co do rozpadu Rosji.',21,NULL,'4. Asymmetry in the Cost of Being Wrong','Politically, silence is cheaper than being publicly wrong about Russia''s disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(231,4,225,'heading',3,3,22,'5. Emeryci mówią — test kontrolny','emeryci-mowia','Po odejściu z urzędu ci sami ludzie mówią znacznie swobodniej o scenariuszach końcowych.',22,NULL,'5. Retirees Speak — the Control Test','Once out of office, the same people speak much more freely about end-state scenarios.',NULL,NULL);
INSERT INTO content_sections VALUES(232,4,225,'heading',3,3,23,'6. Media też — inny mechanizm, ten sam skutek','media-tez','Media unikają kategorycznych prognoz strukturalnych z innych powodów niż urzędujący politycy.',23,NULL,'6. The Media Too — Different Mechanism, Same Effect','The media avoid categorical structural forecasts for different reasons than incumbent politicians do.',NULL,NULL);
INSERT INTO content_sections VALUES(233,4,225,'heading',3,3,24,'7. Błąd ramy porównawczej','blad-ramy-porownawczej','Błędne analogie historyczne zasłaniają odmienną strukturę obecnej rosyjskiej erozji.',24,NULL,'7. Error in the Comparative Frame','Misleading historical analogies obscure the different structure of Russia''s current erosion.',NULL,NULL);
INSERT INTO content_sections VALUES(234,4,225,'heading',3,3,25,'8. Kto może zobaczyć, że król jest nagi','kto-moze-zobaczyc','Najłatwiej nazwać pełny obraz tym, którzy nie ponoszą kosztu własnej diagnozy.',25,NULL,'8. Who Can See That the Emperor Has No Clothes','Those who do not bear the cost of their own diagnosis find it easiest to name the full picture.',NULL,NULL);
INSERT INTO content_sections VALUES(235,4,210,'heading',2,2,26,'IV. Budanow i Zełenski — zmiana języka','budanow-zelenski','Zmiana języka ukraińskiego kierownictwa z przetrwania na termin zakończenia wojny.',26,NULL,'IV. Budanov and Zelenskyy — a Change in Language','A shift in the language of Ukraine''s leadership from survival to a timetable for ending the war.',NULL,NULL);
INSERT INTO content_sections VALUES(236,4,235,'heading',3,3,27,'1. Awans, który sam jest tezą','awans-ktory-jest-teza','Awans Budanowa odczytany jako przesunięcie ciężaru ku fazie politycznego domknięcia.',27,NULL,'1. A Promotion That Is Itself a Thesis','Budanov''s promotion read as a shift of weight toward the phase of political closure.',NULL,NULL);
INSERT INTO content_sections VALUES(237,4,235,'heading',3,3,28,'2. Od przetrwania do terminu','od-przetrwania-do-terminu','Publiczny język przechodzi od „wytrzymamy” do konkretnego okna zakończenia wojny.',28,NULL,'2. From Survival to a Deadline','Public language shifts from “we will endure” to a concrete window for ending the war.',NULL,NULL);
INSERT INTO content_sections VALUES(238,4,235,'heading',3,3,29,'3. Doktryna maksymalizacji eskalacji','doktryna-maksymalizacji','Wyjście z eskalacji przez zwiększenie presji aż do wymuszenia decyzji przeciwnika.',29,NULL,'3. The Doctrine of Maximising Escalation','Exiting escalation by increasing pressure until the opponent is forced to decide.',NULL,NULL);
INSERT INTO content_sections VALUES(239,4,235,'heading',3,3,30,'4. Dosłowność jako narzędzie','doslownosc','Dosłowne komunikaty jako świadome ograniczenie nadinterpretacji i propagandowego szumu.',30,NULL,'4. Literalness as a Tool','Literal messages as a deliberate way to limit over-interpretation and propaganda noise.',NULL,NULL);
INSERT INTO content_sections VALUES(240,4,235,'heading',3,3,31,'5. Rejestr mnicha-wojownika','rejestr-mnicha','Budanow jako chłodny nadawca opisujący zweryfikowane zadania bez triumfalizmu.',31,NULL,'5. The Warrior-Monk Register','Budanov as a cool, restrained sender reporting verified tasks without triumphalism.',NULL,NULL);
INSERT INTO content_sections VALUES(241,4,240,'heading',4,4,32,'Ta sama brakująca warstwa','ta-sama-warstwa','Brak performatywnego triumfu jako wspólna cecha analizowanych wypowiedzi.',32,NULL,'The Same Missing Layer','The absence of performative triumph as a shared feature of the statements analysed.',NULL,NULL);
INSERT INTO content_sections VALUES(242,4,240,'heading',4,4,33,'Nawiązanie: gramatyka Budanowa','gramatyka-budanowa','Lipcowy język potwierdza wcześniejszy odczyt przemilczeń i kolejności komunikacji Budanowa.',33,NULL,'Reference: Budanov''s Grammar','The language of July confirms the earlier reading of Budanov''s omissions and sequencing of communication.',NULL,NULL);
INSERT INTO content_sections VALUES(243,4,235,'heading',3,3,34,'6. Co mówią, a czego nadal nie','co-mowia-a-czego-nie','Jawność kończy się przed pytaniem o rozpad Rosji, Putina i arsenał jądrowy.',34,NULL,'6. What They Say, and What They Still Do Not','Transparency stops before the questions of Russia''s disintegration, Putin and the nuclear arsenal.',NULL,NULL);
INSERT INTO content_sections VALUES(244,4,210,'heading',2,2,35,'V. Kasparow — stała odniesienia','kasparow','Niezmienna od lat diagnoza Kasparowa jako linia bazowa dla przesuwającej się rzeczywistości.',35,NULL,'V. Kasparov — the Reference Constant','Kasparov''s diagnosis, unchanged for years, as a baseline against which a shifting reality can be measured.',NULL,NULL);
INSERT INTO content_sections VALUES(245,4,244,'heading',3,3,36,'1. Dwadzieścia lat tej samej tezy','dwadziescia-lat-tej-samej-tezy','Stała teza: reżim Putina kończy się dopiero wraz z rosyjską porażką.',36,NULL,'1. Twenty Years of the Same Thesis','The constant thesis: Putin''s regime ends only with Russia''s defeat.',NULL,NULL);
INSERT INTO content_sections VALUES(246,4,244,'heading',3,3,37,'2. Trzy rzeczy, których nie mówi nikt inny','trzy-rzeczy-ktorych-nikt-nie-mowi','Kasparow wypowiada wprost trzy wnioski omijane przez urzędujących decydentów.',37,NULL,'2. Three Things No One Else Says','Kasparov states openly three conclusions avoided by serving decision-makers.',NULL,NULL);
INSERT INTO content_sections VALUES(247,4,246,'heading',4,4,38,'Po pierwsze: Rosja się rozpadnie','teza-rozpadnie-sie','Rozpad rosyjskiej konstrukcji imperialnej jako przewidywany skutek przegranej reżimu.',38,NULL,'First: Russia Will Disintegrate','The disintegration of Russia''s imperial structure as the expected consequence of the regime''s defeat.',NULL,NULL);
INSERT INTO content_sections VALUES(248,4,246,'heading',4,4,39,'Po drugie: Rosja powinna się rozpaść','teza-powinna-sie-rozpasc','Rozpad Rosji przedstawiony także jako pożądany wynik moralny i strategiczny.',39,NULL,'Second: Russia Should Disintegrate','Russia''s disintegration presented also as a desirable moral and strategic outcome.',NULL,NULL);
INSERT INTO content_sections VALUES(249,4,246,'heading',4,4,40,'Po trzecie: na tej wojnie zarabiają Chiny, i właściwie nikt inny','teza-chiny-zyskuja','Pekin jako główny beneficjent przeciągającej się wojny i rosnącej zależności Rosji.',40,NULL,'Third: China Profits from This War, and Essentially No One Else Does','Beijing as the main beneficiary of a prolonged war and Russia''s growing dependence.',NULL,NULL);
INSERT INTO content_sections VALUES(250,4,246,'heading',4,4,41,'I wniosek, który wynika z trzech powyższych: to nic strasznego','teza-nic-strasznego','Rozpad imperium nie musi być katastrofą większą niż koszt jego dalszego trwania.',41,NULL,'And the Conclusion That Follows from the Three Above: It Is Not Terrible','The collapse of an empire need not be a greater catastrophe than the cost of keeping it alive.',NULL,NULL);
INSERT INTO content_sections VALUES(251,4,244,'heading',3,3,42,'3. Dlaczego teraz brzmi inaczej','dlaczego-teraz-brzmi-inaczej','Dane przesunęły się w stronę diagnozy, która wcześniej brzmiała jak dysydencka przesada.',42,NULL,'3. Why It Sounds Different Now','The data have moved toward a diagnosis that once sounded like dissident exaggeration.',NULL,NULL);
INSERT INTO content_sections VALUES(252,4,244,'heading',3,3,43,'4. Trzy głosy, jeden model','trzy-glosy-jeden-model','Zachód, Ukraina i Kasparow różnią się stopniem zobowiązania, niekoniecznie wiedzy.',43,NULL,'4. Three Voices, One Model','The West, Ukraine and Kasparov differ in degree of commitment, not necessarily in knowledge.',NULL,NULL);
INSERT INTO content_sections VALUES(253,4,210,'heading',2,2,44,'VI. Jak niewinnie zaczął się hurt','geneza-hurtu','Hurt wyrósł z reakcji na rosyjski atak, ale utrzymał się dzięki wysokiej skuteczności.',44,NULL,'VI. How Innocently Wholesale Began','Wholesale grew out of a response to a Russian attack, but persisted because it proved highly effective.',NULL,NULL);
INSERT INTO content_sections VALUES(254,4,253,'heading',3,3,45,'1. Drabina zaczęła się wcześniej','drabina-zaczela-sie-wczesniej','Lipcowy hurt opiera się na zdolnościach budowanych wcześniej dla większej autonomii Ukrainy.',45,NULL,'1. The Ladder Began Earlier','July''s wholesale campaign rests on capabilities built earlier to increase Ukraine''s autonomy.',NULL,NULL);
INSERT INTO content_sections VALUES(255,4,253,'heading',3,3,46,'2. Dwa motory w jednym kierunku','dwa-motory','Kalkulacja strategiczna i odwet moralny popychają kampanię w tym samym kierunku.',46,NULL,'2. Two Engines in the Same Direction','Strategic calculation and moral retaliation push the campaign in the same direction.',NULL,NULL);
INSERT INTO content_sections VALUES(256,4,253,'heading',3,3,47,'3. Drabina lipcowa, dzień po dniu','drabina-lipcowa','Dzień po dniu odpowiedź eskaluje od gestu do trwałej kampanii nowych celów.',47,NULL,'3. The July Ladder, Day by Day','Day by day, the response escalates from a gesture into a sustained campaign against new target classes.',NULL,NULL);
INSERT INTO content_sections VALUES(257,4,253,'heading',3,3,48,'4. Odpowiedź podwójna — realna i wizerunkowa','odpowiedz-podwojna','Jednoczesny efekt materialny i komunikacyjny po rosyjskim ataku.',48,NULL,'4. A Double Response — Material and Reputational','A simultaneous material and communications effect following the Russian attack.',NULL,NULL);
INSERT INTO content_sections VALUES(258,4,253,'heading',3,3,49,'5. Pewność następnego kroku','pewnosc-nastepnego-kroku','Odnawialny zasób broni zwiększa możliwość powtarzania udanych ruchów bez wielkiej stawki magazynowej.',49,NULL,'5. Confidence in the Next Step','A renewable weapons stream increases the ability to repeat successful moves without making a large inventory bet.',NULL,NULL);
INSERT INTO content_sections VALUES(259,4,253,'heading',3,3,50,'6. Przypadkowa trwałość','przypadkowa-trwalosc','Tymczasowa odpowiedź zostaje utrzymana, bo nowa klasa celów okazuje się wyjątkowo opłacalna.',50,NULL,'6. Accidental Durability','A temporary response is retained because the new target class proves exceptionally cost-effective.',NULL,NULL);
INSERT INTO content_sections VALUES(260,4,210,'heading',2,2,51,'VII. Inwersja historyczna','inwersja-historyczna','Rosja walczy dziś przeciw zapleczu ludzkiego i przemysłowego, które dawniej zasilało jej zwycięstwa.',51,NULL,'VII. Historical Inversion','Russia is now fighting against the human and industrial rear that once powered its victories.',NULL,NULL);
INSERT INTO content_sections VALUES(261,4,260,'heading',3,3,52,'1. Czym Rosja wygrywała wojny','czym-rosja-wygrywala','Imperium korzystało przez stulecia z ukraińskich ludzi, przemysłu i kompetencji wojskowych.',52,NULL,'1. What Russia Used to Win Wars With','For centuries, the empire drew on Ukrainian people, industry and military competence.',NULL,NULL);
INSERT INTO content_sections VALUES(262,4,260,'heading',3,3,53,'2. Amputacja własnego mięśnia','amputacja','Atak na Ukrainę odciął Rosję od części własnego historycznego zaplecza siłowego.',53,NULL,'2. Amputating Its Own Muscle','The attack on Ukraine cut Russia off from part of its own historical base of power.',NULL,NULL);
INSERT INTO content_sections VALUES(263,4,260,'heading',3,3,54,'3. Co z tego wynika dla tej wojny','co-z-tego-wynika','Utracone kompetencje imperium tłumaczą rosyjskie braki i ukraińską zdolność innowacji.',54,NULL,'3. What This Means for the War','Lost imperial competencies help explain Russian shortages and Ukraine''s capacity for innovation.',NULL,NULL);
INSERT INTO content_sections VALUES(264,4,210,'heading',2,2,55,'VIII. Prognoza dogania rzeczywistość','prognoza-dogania','Wcześniej niszowy scenariusz przyspieszonego rozstrzygnięcia wchodzi do języka decydentów.',55,NULL,'VIII. The Forecast Catches Up with Reality','A previously niche scenario of accelerated resolution enters the language of decision-makers.',NULL,NULL);
INSERT INTO content_sections VALUES(265,4,264,'heading',3,3,56,'1. Co napisano w marcu','co-napisano-w-marcu','Marcowy rozkład scenariuszy dawał przyspieszonemu końcowi wojny istotne, lecz mniejszościowe prawdopodobieństwo.',56,NULL,'1. What Was Written in March','The March scenario distribution assigned an accelerated end to the war a meaningful but minority probability.',NULL,NULL);
INSERT INTO content_sections VALUES(266,4,264,'heading',3,3,57,'2. Co dopisano w czerwcu','co-dopisano-w-czerwcu','Niezależne zegary przesuwają ciężar prognozy ku jesieni 2026.',57,NULL,'2. What Was Added in June','Independent clocks shift the forecast weight toward autumn 2026.',NULL,NULL);
INSERT INTO content_sections VALUES(267,4,264,'heading',3,3,58,'3. Co mówią teraz Zełenski i Budanow','co-mowia-teraz','Zełenski i Budanow publicznie wskazują zimę 2026 jako realną granicę okna.',58,NULL,'3. What Zelenskyy and Budanov Say Now','Zelenskyy and Budanov publicly point to winter 2026 as a realistic boundary of the window.',NULL,NULL);
INSERT INTO content_sections VALUES(268,4,264,'heading',3,3,59,'4. Czego wcześniej w obiegu nie było','czego-nie-bylo-w-obiegu','Nowością jest samo wejście szybkiego zakończenia wojny do publicznego repertuaru scenariuszy.',59,NULL,'4. What Was Not Previously in Circulation','The novelty is that a rapid end to the war has entered the public repertoire of scenarios at all.',NULL,NULL);
INSERT INTO content_sections VALUES(269,4,264,'heading',3,3,60,'5. Dyscyplina — mapa, nie GPS','dyscyplina','Prognoza pozostaje mapą ryzyka, nie pewną datą ani GPS-em zdarzeń.',60,NULL,'5. Discipline — a Map, Not GPS','The forecast remains a risk map, not a certain date or a GPS for events.',NULL,NULL);
INSERT INTO content_sections VALUES(270,4,210,'heading',2,2,61,'IX. Zapaść w czasie teraźniejszym ciągłym','zapasc','Równoległa degradacja rosyjskiego budżetu, rolnictwa, rezerw, transportu i przedsiębiorstw.',61,NULL,'IX. Collapse in the Present Continuous','Parallel degradation of Russia''s budget, agriculture, reserves, transport and corporate sector.',NULL,NULL);
INSERT INTO content_sections VALUES(271,4,270,'heading',3,3,62,'1. Budżet — oficjalna dziura i paradoks naftowy','budzet','Deficyt przekracza plany mimo odkładania reguł fiskalnych poza bieżący horyzont.',62,NULL,'1. The Budget — the Official Hole and the Oil Paradox','The deficit exceeds plans even as fiscal rules are pushed beyond the current horizon.',NULL,NULL);
INSERT INTO content_sections VALUES(272,4,271,'heading',4,4,63,'Paradoks naftowy — spadek wpływów przy rekordowych cenach','paradoks-naftowy','Wpływy spadają mimo rekordowej ceny ropy, bo ograniczeniem staje się fizyczny eksport.',63,NULL,'The Oil Paradox — Falling Revenues at Record Prices','Revenues fall despite record oil prices because the constraint is becoming physical export capacity.',NULL,NULL);
INSERT INTO content_sections VALUES(273,4,270,'heading',3,3,64,'2. Zbiory — paliwo zjada plon, a technologia zjada resztę','zbiory','Braki paliwa, technologii i ludzi uderzają bezpośrednio w tempo i wynik żniw.',64,NULL,'2. Harvests — Fuel Eats the Crop, Technology Eats the Rest','Shortages of fuel, technology and labour directly hit the pace and outcome of the harvest.',NULL,NULL);
INSERT INTO content_sections VALUES(274,4,273,'heading',4,4,65,'Degradacja technologiczna pod spodem','degradacja-technologiczna','Tańsze nasiona, mniej nawozów i starzejący sprzęt wzmacniają podatność rolnictwa.',65,NULL,'Technological Degradation Underneath','Cheaper seeds, less fertiliser and ageing equipment increase agriculture''s vulnerability.',NULL,NULL);
INSERT INTO content_sections VALUES(275,4,273,'heading',4,4,66,'Pogoda i pułapka płynności','pogoda-i-plynnosc','Pogoda i brak gotówki zamykają rolników w pętli paliwo–zbiór–dochód.',66,NULL,'Weather and the Liquidity Trap','Weather and lack of cash lock farmers into a fuel–harvest–income loop.',NULL,NULL);
INSERT INTO content_sections VALUES(276,4,273,'heading',4,4,67,'Wieś się wyżywi, miasta niekoniecznie','wies-i-miasto','Wieś ma bufory przetrwania; politycznie groźniejsze są braki żywności w dużych miastach.',67,NULL,'The Countryside Will Feed Itself; the Cities May Not','Rural areas retain survival buffers; politically, food shortages in large cities are more dangerous.',NULL,NULL);
INSERT INTO content_sections VALUES(277,4,270,'heading',3,3,68,'3. Złoto — wyprzedaż stulecia','zloto','Bank centralny sprzedaje złoto w rekordowym tempie, by łatać budżet.',68,NULL,'3. Gold — the Sale of the Century','The central bank sells gold at a record pace to plug the budget.',NULL,NULL);
INSERT INTO content_sections VALUES(278,4,270,'heading',3,3,69,'4. Kolej — piąty rok spadku i degradacja pod spodem','kolej','Spadek przewozów nakłada się na kadry, majątek i coraz gorszą jakość infrastruktury.',69,NULL,'4. Railways — a Fifth Year of Decline, with Degradation Underneath','Falling freight volumes overlap with workforce losses, asset deterioration and worsening infrastructure quality.',NULL,NULL);
INSERT INTO content_sections VALUES(279,4,278,'heading',4,4,70,'Paradoks pracy przewozowej','paradoks-gruzooborotu','Praca przewozowa może maskować kurczący się wolumen dzięki zmianie długości tras i struktury ładunków.',70,NULL,'The Freight-Work Paradox','Freight work can mask shrinking volumes through changes in route length and cargo mix.',NULL,NULL);
INSERT INTO content_sections VALUES(280,4,278,'heading',4,4,71,'Wyprzedaż majątku i ubytek ludzi','wyprzedaz-i-kadry','Kolej wyprzedaje aktywa i traci techników potrzebnych do utrzymania systemu.',71,NULL,'Asset Sales and Loss of People','The railway sells assets and loses the technicians needed to keep the system running.',NULL,NULL);
INSERT INTO content_sections VALUES(281,4,278,'heading',4,4,72,'Fałszowane remonty i zakazy załadunku','falszowane-remonty','Papierowa sprawność i zakazy załadunku maskują realną degradację infrastruktury kolejowej.',72,NULL,'Falsified Repairs and Loading Bans','Paper readiness and loading bans conceal the real degradation of railway infrastructure.',NULL,NULL);
INSERT INTO content_sections VALUES(282,4,270,'heading',3,3,73,'5. Lotnictwo cywilne — awaria co tydzień','lotnictwo','Kanibalizacja części i ograniczony serwis przekładają się na rosnącą awaryjność lotnictwa cywilnego.',73,NULL,'5. Civil Aviation — a Failure Every Week','Parts cannibalisation and constrained maintenance translate into growing civil-aviation failure rates.',NULL,NULL);
INSERT INTO content_sections VALUES(283,4,270,'heading',3,3,74,'6. Sektor korporacyjny — zarządzany upadek','sektor-korporacyjny','Duże firmy przechodzą od wzrostu do restrukturyzacji, strat i kontrolowanego kurczenia.',74,NULL,'6. The Corporate Sector — Managed Decline','Large companies move from growth to restructuring, losses and controlled contraction.',NULL,NULL);
INSERT INTO content_sections VALUES(284,4,270,'heading',3,3,75,'7. Dlaczego to już czas przyszły dokonany','czas-dokonany','Część procesów przekroczyła etap prognozy: pytanie dotyczy skutków, nie samego wystąpienia.',75,NULL,'7. Why This Is Already Future Perfect','Some processes have passed the forecasting stage: the question is about consequences, not whether they will occur.',NULL,NULL);
INSERT INTO content_sections VALUES(285,4,210,'heading',2,2,76,'X. Mobilizacja cicha i pełna','mobilizacja','Rosja między kosztownym werbunkiem, cichym poborem i ryzykiem pełnej mobilizacji.',76,NULL,'X. Silent and Full Mobilisation','Russia between costly recruitment, quiet mobilisation and the risk of full mobilisation.',NULL,NULL);
INSERT INTO content_sections VALUES(286,4,285,'heading',3,3,77,'1. Werbunek siada','werbunek-siada','Premie rosną, a dobrowolny napływ ludzi daje coraz mniejszy efekt marginalny.',77,NULL,'1. Recruitment Is Failing','Bonuses rise while voluntary inflows of manpower produce ever smaller marginal returns.',NULL,NULL);
INSERT INTO content_sections VALUES(287,4,285,'heading',3,3,78,'2. Cicha mobilizacja — co już trwa','cicha-mobilizacja','Administracyjne i kontraktowe mechanizmy zwiększają zasób ludzi bez formalnego ogłoszenia mobilizacji.',78,NULL,'2. Quiet Mobilisation — What Is Already Happening','Administrative and contractual mechanisms increase manpower without formally declaring mobilisation.',NULL,NULL);
INSERT INTO content_sections VALUES(288,4,285,'heading',3,3,79,'3. Głos przeciwny — czy na pewno brakuje','glos-przeciwny','Kontrargument: obecny werbunek może wystarczać do utrzymania frontu, choć nie do przełomu.',79,NULL,'3. The Counterargument — Is There Really a Shortage?','Counterargument: current recruitment may be enough to hold the front, though not to achieve a breakthrough.',NULL,NULL);
INSERT INTO content_sections VALUES(289,4,285,'heading',3,3,80,'4. Pełna mobilizacja po wyborach','pelna-po-wyborach','Wrzesień ogranicza politycznie decyzję, więc pełny pobór rozważany jest po wyborach.',80,NULL,'4. Full Mobilisation After the Elections','September politically constrains the decision, so full mobilisation is considered more plausible after the elections.',NULL,NULL);
INSERT INTO content_sections VALUES(290,4,285,'heading',3,3,81,'5. Co by dała, a co zabrała','co-by-dala','Pełna mobilizacja kupuje piechotę kosztem rynku pracy, specjalistów, emigracji i spokoju.',81,NULL,'5. What It Would Give, and What It Would Take Away','Full mobilisation buys infantry at the cost of the labour market, specialists, emigration and social calm.',NULL,NULL);
INSERT INTO content_sections VALUES(291,4,290,'heading',4,4,82,'Dałaby: masę piechoty, na jeden sezon','dalaby-piechote','Kilkaset tysięcy ludzi daje jednorazowy sezon większej masy frontowej.',82,NULL,'It Would Give: Mass Infantry, for One Season','Several hundred thousand people would provide one season of greater mass at the front.',NULL,NULL);
INSERT INTO content_sections VALUES(292,4,290,'heading',4,4,83,'Zabrałaby: ostatnie rezerwy rynku pracy','zabralaby-rynek-pracy','Pobór wyciąga ludzi z rynku, który już niemal nie ma rezerw.',83,NULL,'It Would Take Away: the Last Labour-Market Reserves','Conscription removes people from a labour market that already has almost no reserves.',NULL,NULL);
INSERT INTO content_sections VALUES(293,4,290,'heading',4,4,84,'Zabrałaby: specjalistów, których wojna potrzebuje najbardziej','zabralaby-specjalistow','Mobilizacja odbiera gospodarce techników potrzebnych także samemu wojsku.',84,NULL,'It Would Take Away: the Specialists the War Needs Most','Mobilisation pulls technicians from the economy who are also needed by the military itself.',NULL,NULL);
INSERT INTO content_sections VALUES(294,4,290,'heading',4,4,85,'Zabrałaby: kolejną falę emigracji, tym razem trwałą','zabralaby-ludzi-za-granice','Nowa fala poboru może wywołać trwałą emigrację młodych i mobilnych.',85,NULL,'It Would Take Away: Another Wave of Emigration, This Time Permanent','A new mobilisation wave could trigger lasting emigration among the young and mobile.',NULL,NULL);
INSERT INTO content_sections VALUES(295,4,290,'heading',4,4,86,'Zabrałaby: spokój społeczny, którego nie da się odkupić','zabralaby-spokoj','Pełna mobilizacja ujawnia skalę wojny i podnosi koszt społeczny reżimu.',86,NULL,'It Would Take Away: Social Calm That Cannot Be Bought Back','Full mobilisation reveals the scale of the war and raises the regime''s social cost.',NULL,NULL);
INSERT INTO content_sections VALUES(296,4,210,'heading',2,2,87,'XI. Chiński substytut komponentowy','chinski-substytut','Chiny zastępują część zachodnich dostaw, lecz pogłębiają jednostronną zależność Rosji.',87,NULL,'XI. The Chinese Component Substitute','China replaces part of Western supply, but deepens Russia''s one-sided dependence.',NULL,NULL);
INSERT INTO content_sections VALUES(297,4,296,'heading',3,3,88,'1. Skala zastąpienia','skala-zastapienia','Chińskie komponenty masowo wypełniają rosyjskie luki w elektronice i technologiach podwójnego zastosowania.',88,NULL,'1. Scale of Replacement','Chinese components fill Russian gaps in electronics and dual-use technologies on a mass scale.',NULL,NULL);
INSERT INTO content_sections VALUES(298,4,296,'heading',3,3,89,'2. Oficjalna kapitulacja programu niezależności','oficjalna-kapitulacja','Rosja formalnie obniża cel niezależności elektronicznej i tnie programy krajowe.',89,NULL,'2. Official Surrender of the Independence Programme','Russia formally lowers its target for electronic independence and cuts domestic programmes.',NULL,NULL);
INSERT INTO content_sections VALUES(299,4,296,'heading',3,3,90,'3. Irtysz — procesor, który nie jest rosyjski','irtysz','„Rosyjski” procesor okazuje się chińską architekturą i zagraniczną produkcją.',90,NULL,'3. Irtysh — a Processor That Is Not Russian','The “Russian” processor turns out to rely on Chinese architecture and foreign manufacturing.',NULL,NULL);
INSERT INTO content_sections VALUES(300,4,296,'heading',3,3,91,'4. Kanały szarej strefy','szarej-strefy','Sankcjonowane komponenty płyną przez pośredników, firmy słupowe i trzecie państwa.',91,NULL,'4. Grey-Zone Channels','Sanctioned components flow through intermediaries, shell companies and third countries.',NULL,NULL);
INSERT INTO content_sections VALUES(301,4,296,'heading',3,3,92,'5. Gaz — oba kierunki zamknięte','gaz-oba-kierunki','Rynek europejski utracony, a chiński kierunek nie daje porównywalnej skali ani warunków.',92,NULL,'5. Gas — Both Directions Closed','The European market is lost, while the Chinese route cannot provide comparable scale or terms.',NULL,NULL);
INSERT INTO content_sections VALUES(302,4,296,'heading',3,3,93,'6. To nie substytucja, to zamiana wierzyciela','zamiana-nie-substytucja','Rosja nie odzyskała samodzielności, tylko zamieniła Zachód na silniejszego wierzyciela chińskiego.',93,NULL,'6. This Is Not Substitution, It Is Changing Creditors','Russia did not regain autonomy; it replaced the West with a stronger Chinese creditor.',NULL,NULL);
INSERT INTO content_sections VALUES(303,4,210,'heading',2,2,94,'XII. Przemysł zbrojeniowy — cztery domknięcia','przemysl-domkniecia','Powtarzane uderzenia, komponentowe wąskie gardła i brak ludzi spinają presję na zbrojeniówkę.',94,NULL,'XII. The Defence Industry — Four Closures','Repeated strikes, component bottlenecks and labour shortages close the pressure loop around the defence industry.',NULL,NULL);
INSERT INTO content_sections VALUES(304,4,303,'heading',3,3,95,'1. Macierz powtórzeń','macierz-powtorzen','Te same zakłady trafiane szybciej, niż mogą kończyć kolejne cykle napraw.',95,NULL,'1. Repetition Matrix','The same plants are hit faster than they can complete successive repair cycles.',NULL,NULL);
INSERT INTO content_sections VALUES(305,4,303,'heading',3,3,96,'2. Wąskim gardłem jest komponent, nie budynek','waskie-gardlo','Kluczowym ograniczeniem stają się trudne do zastąpienia części i technologie, nie hale.',96,NULL,'2. The Bottleneck Is the Component, Not the Building','The key constraint is hard-to-replace parts and technologies, not factory halls.',NULL,NULL);
INSERT INTO content_sections VALUES(306,4,303,'heading',3,3,97,'3. KAB — jeden produkt, trzy ogniwa','kab-trzy-ogniwa','Produkcja KAB zależy od kilku różnych, równocześnie podatnych ogniw dostaw.',97,NULL,'3. KAB — One Product, Three Links','KAB production depends on several different and simultaneously vulnerable supply links.',NULL,NULL);
INSERT INTO content_sections VALUES(307,4,303,'heading',3,3,98,'4. Trójkąt konkurencji o ludzi','trojkat-o-ludzi','Wojsko, zbrojeniówka i gospodarka cywilna konkurują o tę samą kurczącą się pulę specjalistów.',98,NULL,'4. The Triangle of Competition for People','The military, defence industry and civilian economy compete for the same shrinking pool of specialists.',NULL,NULL);
INSERT INTO content_sections VALUES(308,4,210,'heading',2,2,99,'XIII. Strumień pod obciążeniem','strumien-pod-obciazeniem','Test drugiej strony równania: ukraiński strumień jest realny, ale też ma ograniczenia.',99,NULL,'XIII. The Stream Under Load','Testing the other side of the equation: Ukraine''s production stream is real, but it also has limits.',NULL,NULL);
INSERT INTO content_sections VALUES(309,4,308,'heading',3,3,100,'1. Strumień jest realny — liczby','strumien-jest-realny','Produkcja dronów i pocisków rośnie jako odnawialny strumień, nie wyczerpywany magazyn.',100,NULL,'1. The Stream Is Real — the Numbers','Drone and missile production grows as a renewable flow rather than as a stockpile being depleted.',NULL,NULL);
INSERT INTO content_sections VALUES(310,4,308,'heading',3,3,101,'2. Strumień finansowany, nie darmowy','strumien-finansowany','Głównym wąskim gardłem ukraińskiej produkcji jest finansowanie zewnętrzne, nie moce przemysłowe.',101,NULL,'2. The Stream Is Funded, Not Free','The main bottleneck in Ukrainian production is external financing, not industrial capacity.',NULL,NULL);
INSERT INTO content_sections VALUES(311,4,308,'heading',3,3,102,'3. Piechota — deficyt, którego nie łata technologia','piechota','Technologia nie usuwa strukturalnego braku wyszkolonej piechoty do utrzymywania terenu.',102,NULL,'3. Infantry — a Shortage Technology Cannot Fix','Technology does not remove the structural shortage of trained infantry needed to hold ground.',NULL,NULL);
INSERT INTO content_sections VALUES(312,4,308,'heading',3,3,103,'4. Energetyka — korekta własnej tezy','energetyka-korekta','Ukraińska sieć regeneruje się, lecz ciężkie transformatory mają długi cykl odtworzenia.',103,NULL,'4. Energy — a Correction to the Earlier Thesis','Ukraine''s grid is regenerating, but heavy transformers have long replacement cycles.',NULL,NULL);
INSERT INTO content_sections VALUES(313,4,308,'heading',3,3,104,'5. Asymetria ograniczeń','asymetria-ograniczen','Rosyjskie ograniczenia są głównie fizyczne i jednokierunkowe; ukraińskie częściej politycznie odwracalne.',104,NULL,'5. Asymmetry of Constraints','Russian constraints are mainly physical and one-way; Ukrainian constraints are more often politically reversible.',NULL,NULL);
INSERT INTO content_sections VALUES(314,4,210,'heading',2,2,105,'XIV. Czego Rosja nauczyła się dobrze','adaptacja','Steelmanning: Rosja skutecznie obchodzi część sankcji i buduje nowe mechanizmy odporności.',105,NULL,'XIV. What Russia Has Learned to Do Well','Steelmanning: Russia effectively circumvents some sanctions and builds new resilience mechanisms.',NULL,NULL);
INSERT INTO content_sections VALUES(315,4,314,'heading',3,3,106,'1. Flota cieni — od obejścia do instytucji','flota-cieni','Flota cieni stała się trwałą rosyjską instytucją eksportową mimo sankcji jednostkowych.',106,NULL,'1. The Shadow Fleet — from Workaround to Institution','The shadow fleet has become a durable Russian export institution despite vessel-by-vessel sanctions.',NULL,NULL);
INSERT INTO content_sections VALUES(316,4,314,'heading',3,3,107,'2. Nowy poziom: budowa mocy pod sankcjami','budowa-pod-sankcjami','Rosja i partnerzy rozwijają nowe moce projektowe nawet wewnątrz reżimu sankcyjnego.',107,NULL,'2. A New Level: Building Capacity Under Sanctions','Russia and its partners develop new project capacity even within the sanctions regime.',NULL,NULL);
INSERT INTO content_sections VALUES(317,4,314,'heading',3,3,108,'3. Kontradaptacja: sankcje kinetyczne','sankcje-kinetyczne','Ukraina odpowiada na sankcyjne obejścia fizycznym niszczeniem infrastruktury i środków transportu.',108,NULL,'3. Counter-Adaptation: Kinetic Sanctions','Ukraine answers sanctions circumvention by physically destroying infrastructure and transport assets.',NULL,NULL);
INSERT INTO content_sections VALUES(318,4,314,'heading',3,3,109,'4. Pozostałe adaptacje','pozostale-adaptacje','Import równoległy, substytucja i reorganizacja produkcji łagodzą część zewnętrznej presji.',109,NULL,'4. Other Adaptations','Parallel imports, substitution and production reorganisation soften part of the external pressure.',NULL,NULL);
INSERT INTO content_sections VALUES(319,4,314,'heading',3,3,110,'5. Cena każdej adaptacji','cena-adaptacji','Każde obejście podnosi koszt, wydłuża łańcuch i zwiększa zależność od pośredników.',110,NULL,'5. The Cost of Every Adaptation','Every workaround raises costs, lengthens the chain and increases dependence on intermediaries.',NULL,NULL);
INSERT INTO content_sections VALUES(320,4,314,'heading',3,3,111,'6. Dlaczego to wzmacnia tezę, a nie osłabia','dlaczego-to-wzmacnia-teze','Skuteczna adaptacja pokazuje, że system trwa, ale za cenę rosnącej złożoności i kosztu.',111,NULL,'6. Why This Strengthens the Thesis Rather Than Weakens It','Successful adaptation shows that the system persists, but at the price of growing complexity and cost.',NULL,NULL);
INSERT INTO content_sections VALUES(321,4,210,'heading',2,2,112,'XV. Bankowość — najkrótszy zapalnik','bankowosc','Utajony kryzys bankowy jako najszybszy mechanizm przejścia z erozji do paniki.',112,NULL,'XV. Banking — the Shortest Fuse','A concealed banking crisis as the fastest mechanism for turning erosion into panic.',NULL,NULL);
INSERT INTO content_sections VALUES(322,4,321,'heading',3,3,113,'1. Formalnie kryzys już trwa','formalnie-juz-kryzys','Złe aktywa i niespłacalność przekraczają poziomy odpowiadające kryzysowi bankowemu.',113,NULL,'1. Formally, the Crisis Is Already Underway','Bad assets and insolvency exceed levels consistent with a banking crisis.',NULL,NULL);
INSERT INTO content_sections VALUES(323,4,321,'heading',3,3,114,'2. Maskowanie przez restrukturyzację','maskowanie','Restrukturyzacje odsuwają klasyfikację złych długów i przenoszą koszt na państwo.',114,NULL,'2. Masking Through Restructuring','Restructuring delays classification of bad debt and shifts the cost onto the state.',NULL,NULL);
INSERT INTO content_sections VALUES(324,4,321,'heading',3,3,115,'3. Marketplace''y jako przyspiesznik','marketplace-przyspiesznik','Uderzenia magazynowe pogarszają jakość kredytów firm i zwiększają rezerwy banków.',115,NULL,'3. Marketplaces as an Accelerator','Warehouse strikes worsen corporate credit quality and increase banks'' provisioning needs.',NULL,NULL);
INSERT INTO content_sections VALUES(325,4,321,'heading',3,3,116,'4. Ucieczka gotówki i niespłacalność','ucieczka-gotowki','Rosną jednocześnie gotówka poza bankami i niespłacalność gospodarstw oraz firm.',116,NULL,'4. Flight into Cash and Insolvency','Cash outside the banking system and insolvency among households and firms are rising at the same time.',NULL,NULL);
INSERT INTO content_sections VALUES(326,4,321,'heading',3,3,117,'5. Dlaczego to najkrótszy zapalnik','dlaczego-najkrotszy','Bankowa percepcja może zmienić kryzys utajony w jawny w ciągu dni.',117,NULL,'5. Why This Is the Shortest Fuse','Banking perceptions can turn a hidden crisis into an open one within days.',NULL,NULL);
INSERT INTO content_sections VALUES(327,4,210,'heading',2,2,118,'XVI. Zima 2026/27 — zbieg wektorów','zima','Jesień i zima skupiają w jednym oknie paliwa, finanse, mobilizację, budżet i ciepłownictwo.',118,NULL,'XVI. Winter 2026/27 — Convergence of Vectors','Autumn and winter bring fuel, finance, mobilisation, the budget and district heating into one window.',NULL,NULL);
INSERT INTO content_sections VALUES(328,4,327,'heading',3,3,119,'1. Kalendarz zbieżności','kalendarz-zbieznosci','Niezależne zegary wielu procesów schodzą się wokół jesieni 2026 i początku 2027.',119,NULL,'1. Calendar of Convergence','Independent clocks across multiple processes converge around autumn 2026 and early 2027.',NULL,NULL);
INSERT INTO content_sections VALUES(329,4,327,'heading',3,3,120,'2. Ciepłownictwo — zużycie 70% przy budżecie ciętym 2,3 raza','cieplownictwo','Zużyta infrastruktura grzewcza wchodzi w zimę przy mocno obciętym finansowaniu remontów.',120,NULL,'2. District Heating — 70% Wear with a Budget Cut 2.3-Fold','Worn heating infrastructure enters winter with maintenance funding sharply reduced.',NULL,NULL);
INSERT INTO content_sections VALUES(330,4,327,'heading',3,3,121,'3. Przyznanie wpisane w dokument rządowy','przyznanie-w-dokumencie','Rosyjskie dokumenty rządowe same wpisują ryzyko awarii i niedoborów infrastrukturalnych.',121,NULL,'3. The Admission Written into a Government Document','Russian government documents themselves record the risk of failures and infrastructure shortages.',NULL,NULL);
INSERT INTO content_sections VALUES(331,4,327,'heading',3,3,122,'4. Dlaczego splot mnoży, a nie sumuje','dlaczego-splot-mnozy','Jednoczesne kryzysy wzajemnie zabierają sobie zasoby potrzebne do reagowania.',122,NULL,'4. Why the Tangle Multiplies Rather Than Adds','Simultaneous crises compete for the same resources needed for response.',NULL,NULL);
INSERT INTO content_sections VALUES(332,4,327,'heading',3,3,123,'5. Co musiałoby pójść dobrze','co-musialoby-pojsc-dobrze','Scenariusz stabilizacji wymaga równoczesnego powodzenia na wielu niezależnych osiach.',123,NULL,'5. What Would Have to Go Right','A stabilisation scenario requires simultaneous success across many independent axes.',NULL,NULL);
INSERT INTO content_sections VALUES(333,4,210,'heading',2,2,124,'XVII. Tryb wojenny i cofnięcie się w czasie','tryb-wojenny','Pełna mobilizacja gospodarki może rozwiązać problem alokacji, ale nie dostępności materialnej.',124,NULL,'XVII. War Mode and Moving Backward in Time','Full economic mobilisation can solve allocation, but not material availability.',NULL,NULL);
INSERT INTO content_sections VALUES(334,4,333,'heading',3,3,125,'1. Co tryb wojenny faktycznie rozwiązuje','co-tryb-rozwiazuje','Przymus kieruje ludzi, pieniądze i priorytety tam, gdzie chce państwo.',125,NULL,'1. What War Mode Actually Solves','Coercion directs people, money and priorities where the state wants them.',NULL,NULL);
INSERT INTO content_sections VALUES(335,4,333,'heading',3,3,126,'2. Drzwi zamknięto przed decyzją','drzwi-zamkniete','Kontrola społeczna i gospodarcza została zbudowana zanim formalnie nazwano pełny tryb wojenny.',126,NULL,'2. The Door Was Closed Before the Decision','Social and economic control was built before full war mode was formally named.',NULL,NULL);
INSERT INTO content_sections VALUES(336,4,333,'heading',3,3,127,'3. Czego nie ma: dostaw sojuszniczych','brak-lend-lease','Rosji brakuje zewnętrznego dostawcy skali porównywalnej z historycznym alianckim zapleczem.',127,NULL,'3. What Is Missing: Allied Supply','Russia lacks an external supplier on a scale comparable with the historical Allied rear.',NULL,NULL);
INSERT INTO content_sections VALUES(337,4,333,'heading',3,3,128,'4. Trzy warstwy czasowe jednej gospodarki','trzy-warstwy-czasowe','W jednej gospodarce współistnieją archaiczna produkcja, sowiecka baza i importowana nowoczesność.',128,NULL,'4. Three Time Layers of One Economy','Archaic production, a Soviet base and imported modernity coexist within the same economy.',NULL,NULL);
INSERT INTO content_sections VALUES(338,4,333,'heading',3,3,129,'5. Przymus nowoczesny, produkcja archaiczna','przymus-nowoczesny','Najnowocześniejsza jest kontrola obywatela, podczas gdy produkcja technicznie się cofa.',129,NULL,'5. Modern Coercion, Archaic Production','Citizen control is the most modern element, while production is technologically regressing.',NULL,NULL);
INSERT INTO content_sections VALUES(339,4,210,'heading',2,2,130,'XVIII. Inwentarz opcji — co Rosji zostaje','inwentarz-opcji','Oddzielenie realnych narzędzi Rosji od działań brzmiących jak rozwiązanie, lecz pustych materialnie.',130,NULL,'XVIII. Inventory of Options — What Russia Has Left','Separating Russia''s real tools from measures that sound like solutions but are materially empty.',NULL,NULL);
INSERT INTO content_sections VALUES(340,4,339,'heading',3,3,131,'1. Opcje pozorne','opcje-puste','Bailout, konfiskata i sztuczki monetarne nie tworzą brakujących rzeczy fizycznych.',131,NULL,'1. False Options','Bailouts, confiscation and monetary tricks do not create missing physical goods.',NULL,NULL);
INSERT INTO content_sections VALUES(341,4,339,'heading',3,3,132,'2. Opcje realne','opcje-realne','Realne są przesunięcia zasobów, obniżanie standardów i import rzeczy z zewnątrz.',132,NULL,'2. Real Options','What remains real is reallocating resources, lowering standards and importing physical goods from outside.',NULL,NULL);
INSERT INTO content_sections VALUES(342,4,339,'heading',3,3,133,'3. Pieniądz przestał być wiązaniem','pieniadz-nie-jest-wiazaniem','Ograniczeniem staje się dostęp do komponentów, ludzi i infrastruktury, nie liczba rubli.',133,NULL,'3. Money Has Stopped Being the Binding Constraint','The constraint is access to components, people and infrastructure, not the number of rubles.',NULL,NULL);
INSERT INTO content_sections VALUES(343,4,210,'heading',2,2,134,'XIX. Co jeszcze może spłonąć','co-jeszcze-splonie','Katalog kolejnych klas celów o wysokim potencjale odbierania rosyjskich zdolności wojennych.',134,NULL,'XIX. What Else Can Burn','A catalogue of further target classes with high potential to strip Russia of wartime capabilities.',NULL,NULL);
INSERT INTO content_sections VALUES(344,4,210,'heading',2,2,135,'XX. Granica analizy materialnej','granica-materii','Materialne wskaźniki pokazują dojrzewanie warunków, ale nie wyznaczają chwili przełomu.',135,NULL,'XX. The Boundary of Material Analysis','Material indicators show conditions maturing, but do not identify the moment of rupture.',NULL,NULL);
INSERT INTO content_sections VALUES(345,4,344,'heading',3,3,136,'1. Założenie wypowiedziane wprost','zalozenie-jawne','Jawne założenie: w Wielkiej Wojnie sam bilans zasobów nie przewiduje momentu końca.',136,NULL,'1. The Assumption Stated Explicitly','Explicit assumption: in a Great War, resource balances alone do not predict the moment of the end.',NULL,NULL);
INSERT INTO content_sections VALUES(346,4,344,'heading',3,3,137,'2. Materia daje warunki, sens daje moment','warunki-i-moment','Materia tworzy możliwość przełomu; sens, lojalność i narracja mogą uruchomić moment.',137,NULL,'2. Material Conditions Create the Possibility; Meaning Creates the Moment','Material conditions create the possibility of rupture; meaning, loyalty and narrative can trigger the moment.',NULL,NULL);
INSERT INTO content_sections VALUES(347,4,344,'heading',3,3,138,'3. Asymetria symboliczna','asymetria-symboliczna','Rosyjska narracja stabilizuje, ukraińska mobilizuje do tworzenia nowych zdolności.',138,NULL,'3. Symbolic Asymmetry','The Russian narrative stabilises; the Ukrainian narrative mobilises the creation of new capabilities.',NULL,NULL);
INSERT INTO content_sections VALUES(348,4,347,'heading',6,6,139,'o uzasadnieniach moralnych','uwaga-o-moralnosci','Obie strony mają własne ramy moralne; analiza musi odróżniać ich funkcję od prawdziwości.',139,NULL,'On Moral Justifications','Both sides have their own moral frames; analysis must distinguish their function from their truth value.',NULL,NULL);
INSERT INTO content_sections VALUES(349,4,344,'heading',3,3,140,'4. Cele symboliczne — inna logika','cele-symboliczne','Niektóre cele wpływają głównie na poczucie nietykalności i kalkulację elit.',140,NULL,'4. Symbolic Targets — a Different Logic','Some targets mainly affect the sense of invulnerability and elite calculations.',NULL,NULL);
INSERT INTO content_sections VALUES(350,4,344,'heading',3,3,141,'5. Czego ten dokument nie mierzy','czego-ten-dokument-nie-mierzy','Ślepe plamy: wola, lojalność aparatu, sens i rozstrzygające zdarzenia jednostkowe.',141,NULL,'5. What This Document Does Not Measure','Blind spots: will, apparatus loyalty, meaning and decisive singular events.',NULL,NULL);
INSERT INTO content_sections VALUES(351,5,NULL,'heading',1,1,1,'Kolumbryna kontra rzeczywistość — dwie rewizje','kolumbryna-kontra-rzeczywistosc','Audyt 24 prognoz Kolumbryny w dwóch rewizjach: 31 maja i 23 czerwca 2026.',1,NULL,'Kolumbryna vs Reality — Two Revisions','An audit of Kolumbryna''s 24 forecasts in two revisions: 31 May and 23 June 2026.',NULL,NULL);
INSERT INTO content_sections VALUES(352,5,351,'heading',2,2,2,'Jak czytać','jak-czytac','Legenda czterech statusów i oznaczeń zmian między rewizjami.',2,NULL,'How to Read This','A legend for the four statuses and the change markers between revisions.',NULL,NULL);
INSERT INTO content_sections VALUES(353,5,351,'heading',2,2,3,'Licznik rewizji','licznik-rewizji','Zbiorcze przesunięcie 24 nosorożców między stanem majowym i czerwcowym.',3,NULL,'Revision Counter','The aggregate shift of the 24 rhinos between the May and June states.',NULL,NULL);
INSERT INTO content_sections VALUES(354,5,351,'heading',2,2,4,'24 nosorożce — stan na 31.05','nosorozce-stan-31-05','Pozycja po pozycji: status, nowe dane i zmiana każdego z 24 nosorożców.',4,NULL,'24 Rhinos — Status as of 31 May','Item by item: status, new data and change for each of the 24 rhinos.',NULL,NULL);
INSERT INTO content_sections VALUES(355,6,NULL,'heading',1,1,1,'Zapas kontra strumień','tytul','Rosyjski system opiera się na zużywających się zapasach, gdy ukraińska presja działa coraz bardziej strumieniowo. Analiza łączy kryzys paliwowy z pułapką decyzyjną Putina.',1,NULL,'Stock vs Flow','The Russian system relies on depleting stocks while Ukrainian pressure increasingly operates as a flow. The analysis links the fuel crisis with Putin''s decision trap.',NULL,NULL);
INSERT INTO content_sections VALUES(356,6,355,'heading',2,2,2,'Część I — Materia: układ paliwowy Rosji','czesc-materia','Bilans paliw: utrata slacku, niemal brak stocku, asymetria produktów i rosnące ograniczenia logistyczne.',2,NULL,'Part I — Material: Russia''s Fuel System','The fuel balance: loss of slack, almost no stock, product asymmetry and growing logistical constraints.',NULL,NULL);
INSERT INTO content_sections VALUES(357,6,356,'heading',3,3,3,'1. Uderzenie 28.06 — trzy obiekty, skala zweryfikowana','uderzenie-2806','Jedna fala trafia trzy obiekty naftowe; skalę pożarów potwierdzają dane termiczne.',3,NULL,'1. The 28 June Strike — Three Facilities, Scale Verified','A single wave hits three oil facilities; thermal data confirm the scale of the fires.',NULL,NULL);
INSERT INTO content_sections VALUES(358,6,356,'heading',3,3,4,'2. Moce nominalne kontra faktyczny przerób','moce-nominalne','Nominalna moc rafinerii zawyża odporność; faktyczny przerób zostawiał 57–75 Mt luzu.',4,NULL,'2. Nominal Capacity vs Actual Throughput','Nominal refinery capacity overstates resilience; actual throughput left 57–75 Mt of slack.',NULL,NULL);
INSERT INTO content_sections VALUES(359,6,356,'heading',3,3,5,'3. Piętnaście największych rafinerii — udział nominalny','top-rafinerie','Ranking największych rafinerii pokazuje koncentrację mocy i skalę uszkodzeń do czerwca 2026.',5,NULL,'3. The Fifteen Largest Refineries — Nominal Share','A ranking of the largest refineries shows capacity concentration and the scale of damage by June 2026.',NULL,NULL);
INSERT INTO content_sections VALUES(360,6,356,'heading',3,3,6,'4. Bilans per-produkt i asymetria buforów','bilans-produktow','Benzyna ma cienki bufor, diesel gruby; ten sam spadek przerobu boli produkty asymetrycznie.',6,NULL,'4. Product-by-Product Balance and Buffer Asymmetry','Petrol has a thin buffer, diesel a thick one; the same fall in throughput hurts products asymmetrically.',NULL,NULL);
INSERT INTO content_sections VALUES(361,6,356,'heading',3,3,7,'5. Zapasy magazynowe — flow kontra stock','zapasy-magazynowe','Rosja praktycznie nie ma strategicznego stocku paliw; system opiera się na bieżącym przepływie.',7,NULL,'5. Storage Reserves — Flow vs Stock','Russia effectively lacks strategic fuel stocks; the system depends on continuous flow.',NULL,NULL);
INSERT INTO content_sections VALUES(362,6,356,'heading',3,3,8,'6. Drabina zakazów i sprzężenie współproduktów','drabina-zakazow','Kolejne zakazy eksportu ujawniają ranking niedoboru: benzyna, paliwo lotnicze, potem diesel.',8,NULL,'6. The Ladder of Bans and the Co-Product Feedback Loop','Successive export bans reveal the shortage ranking: petrol, aviation fuel, then diesel.',NULL,NULL);
INSERT INTO content_sections VALUES(363,6,362,'heading',6,6,9,'Zawory ciśnienia i „dziura w ziemi"','dziura-w-ziemi','Współprodukty nie dławią przerobu; nadwyżki są odpadem, więc spadek throughputu oznacza wymuszone wyłączenia.',9,NULL,'Pressure Valves and the “Hole in the Ground”','Co-products do not choke refining; surpluses become waste, so lower throughput means forced shutdowns.',NULL,NULL);
INSERT INTO content_sections VALUES(364,6,356,'heading',3,3,10,'7. Offline ≈ slack — zmiana fazy','offline-slack','Wyłączenia zrównały się z dawnym luzem mocy; kolejne trafienia schodzą już w realną produkcję.',10,NULL,'7. Offline ≈ Slack — a Phase Change','Outages have caught up with former spare capacity; further hits now cut into real production.',NULL,NULL);
INSERT INTO content_sections VALUES(365,6,356,'heading',3,3,11,'8. Poziomy kreski i popyt stłumiony','poziomy-kreski','Spadek cywilnego zużycia może być skutkiem racjonowania, nie realnie niższego popytu.',11,NULL,'8. Flat Lines and Suppressed Demand','Lower civilian consumption may reflect rationing rather than genuinely lower demand.',NULL,NULL);
INSERT INTO content_sections VALUES(366,6,356,'heading',3,3,12,'9. Cebula transportowa — cztery warstwy','cebula-transportowa','Ocalałe wschodnie rafinerie są daleko; kolej, przepustowość i tabor tworzą kolejne wąskie gardła.',12,NULL,'9. The Transport Onion — Four Layers','Surviving eastern refineries are far away; rail, capacity and rolling stock create successive bottlenecks.',NULL,NULL);
INSERT INTO content_sections VALUES(367,6,355,'heading',2,2,13,'Część II — Strategia: pułapka jedynego decydenta','czesc-strategia','Kurczące się zasoby spotykają się z pułapką decydenta, zamkniętym freeze’em i rosnącym ryzykiem ruchu resztkowego.',13,NULL,'Part II — Strategy: the Sole Decision-Maker Trap','Shrinking resources meet a decision-maker trap, a closed freeze and growing risk of a residual move.',NULL,NULL);
INSERT INTO content_sections VALUES(368,6,367,'heading',3,3,14,'1. Cztery osie zapas kontra strumień','cztery-osie','Cztery rosyjskie zapasy kurczą się równolegle: paliwo, precyzyjny ogień, lojalność elit i eskalacja.',14,NULL,'1. Four Stock-vs-Flow Axes','Four Russian stocks are shrinking in parallel: fuel, precision fire, elite loyalty and escalation capacity.',NULL,NULL);
INSERT INTO content_sections VALUES(369,6,367,'heading',3,3,15,'2. Odczyt przez absencję','odczyt-absencja','Brak oczekiwanej reakcji według własnej doktryny jest informacją o realnych ograniczeniach.',15,NULL,'2. Reading Through Absence','Failure to respond as one''s own doctrine predicts is information about real constraints.',NULL,NULL);
INSERT INTO content_sections VALUES(370,6,367,'heading',3,3,16,'3. Generałowie i urojony obraz','generalowie','Selekcja lojalności usuwa kompetentnych dowódców i produkuje fałszywy obraz sytuacji dla Putina.',16,NULL,'3. Generals and the Delusional Picture','Loyalty-based selection removes competent commanders and produces a false picture of reality for Putin.',NULL,NULL);
INSERT INTO content_sections VALUES(371,6,367,'heading',3,3,17,'4. Zablokowana elita — inaczej niż 2010/2019','zablokowana-elita','Elita ma zamknięte wyjście, głos i przeczekanie; pozorna stabilność zwiększa ryzyko nagłego flipu.',17,NULL,'4. The Locked Elite — Unlike 2010/2019','The elite has no exit, voice or waiting option; apparent stability increases the risk of a sudden flip.',NULL,NULL);
INSERT INTO content_sections VALUES(372,6,367,'heading',3,3,18,'5. Szachmat — freeze zamknięty od strony Rosji','szachmat','Freeze jest dla Kremla politycznie trudniejszy niż dalsza wojna: odsłania słabość i uruchamia własny kryzys.',18,NULL,'5. Checkmate — the Freeze Closed from Russia''s Side','A freeze is politically harder for the Kremlin than continuing the war: it exposes weakness and triggers its own crisis.',NULL,NULL);
INSERT INTO content_sections VALUES(373,6,367,'heading',3,3,19,'6. Załamanie ramy — Rosja = Putin','rosja-rowna-putin','Interes państwa rozchodzi się z funkcją celu jedynego realnego decydenta: osobistym przetrwaniem Putina.',19,NULL,'6. Collapse of the Frame — Russia = Putin','The state''s interest diverges from the objective function of the only real decision-maker: Putin''s personal survival.',NULL,NULL);
INSERT INTO content_sections VALUES(374,6,367,'heading',3,3,20,'7. Gambit NATO i casus belli','gambit-nato','Eskalacja wobec NATO jako ruch resztkowy: narracyjnie łatwiejsza klęska niż przegrana z Ukrainą.',20,NULL,'7. The NATO Gambit and Casus Belli','Escalation against NATO as a residual move: a defeat that is narratively easier than losing to Ukraine.',NULL,NULL);
INSERT INTO content_sections VALUES(375,6,374,'heading',4,4,21,'Miękkie lądowanie — struktura, nie życzenie','miekkie-ladowanie','Ograniczona klęska wobec NATO mogłaby zachować rosyjską państwowość i dozór nuklearny, degradując Putina.',21,NULL,'Soft Landing — Structure, Not Wishful Thinking','A limited defeat by NATO could preserve Russian statehood and nuclear custody while politically degrading Putin.',NULL,NULL);
INSERT INTO content_sections VALUES(376,6,374,'heading',4,4,22,'Casus belli — Polska 1939 (model Gliwice)','casus-belli-polska','False flag na wschodniej flance jako sposób przedstawienia eskalacji wobec NATO jako obrony.',22,NULL,'Casus Belli — Poland 1939 (the Gleiwitz Model)','A false flag on NATO''s eastern flank as a way to present escalation against NATO as defence.',NULL,NULL);
INSERT INTO content_sections VALUES(377,6,367,'heading',3,3,23,'8. Paradoks zapędzenia','paradoks-zapedzenia','Im mniej Rosji zostaje bezpiecznych wyjść, tym atrakcyjniejszy staje się ruch resztkowy o wysokim ryzyku.',23,NULL,'8. The Cornering Paradox','The fewer safe exits Russia has left, the more attractive a high-risk residual move becomes.',NULL,NULL);
INSERT INTO content_sections VALUES(378,6,367,'heading',3,3,24,'9. Advocatus diaboli — zebrane zawiasy','advocatus-zebrany','Zebrane zastrzeżenia: degradacja nie oznacza bliskiego końca, a kluczowe tezy są zależne od obecnej konfiguracji.',24,NULL,'9. Advocatus Diaboli — the Collected Hinges','Collected caveats: degradation does not imply an imminent end, and the key theses depend on the current configuration.',NULL,NULL);
INSERT INTO content_sections VALUES(379,7,NULL,'heading',1,1,1,'jak kończą się państwa — fenomenologia, typologia, rachunek rosyjski','jak-koncza-sie-panstwa','Typologia sposobów końca państw i filtr zastosowany do współczesnej Rosji. Rdzeń analizy: długi okres erozji może przejść w bardzo szybki rozpad.',1,NULL,'How States End — Phenomenology, Typology, the Russian Calculation','A typology of how states end and a filter applied to contemporary Russia. Core thesis: a long period of erosion can turn into very rapid disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(380,7,379,'heading',2,2,2,'I. Ramy — fenomenologia, nie etiologia','ramy','Analiza opisuje formę i przebieg końca państwa, nie pełną etiologię jego upadku.',2,NULL,'I. Framework — Phenomenology, Not Aetiology','The analysis describes the form and course of a state''s ending, not the full aetiology of its collapse.',NULL,NULL);
INSERT INTO content_sections VALUES(381,7,379,'heading',2,2,3,'II. Jak wyglądał upadek III Rzeszy','iii-rzesza','Przykład długiej erozji zakończonej czteromiesięcznym wygaszeniem państwa przez podbój.',3,NULL,'II. What the Fall of the Third Reich Looked Like','An example of long erosion ending in a four-month extinguishing of the state through conquest.',NULL,NULL);
INSERT INTO content_sections VALUES(382,7,381,'heading',3,3,4,'Dziesięć markerów','rzesza-markery','Dziesięć obserwowalnych oznak przejścia od mocarstwa do fizycznego zaniku państwa.',4,NULL,'Ten Markers','Ten observable signs of the transition from great power to the physical disappearance of a state.',NULL,NULL);
INSERT INTO content_sections VALUES(383,7,381,'heading',3,3,5,'Dwa bieguny — 1945 vs 1918','rzesza-bieguny','Kontrast: ekstynkcja przez podbój w 1945 versus wewnętrzne pęknięcie w 1918.',5,NULL,'Two Poles — 1945 vs 1918','Contrast: extinction through conquest in 1945 versus internal rupture in 1918.',NULL,NULL);
INSERT INTO content_sections VALUES(384,7,379,'heading',2,2,6,'III. Typologia trybów końca państwa','typologia','Rozszerzenie prostego podziału 1945/1918 do wielu odmiennych form końca państwa.',6,NULL,'III. Typology of Modes of State Ending','Expanding the simple 1945/1918 split into multiple distinct forms of state ending.',NULL,NULL);
INSERT INTO content_sections VALUES(385,7,384,'heading',3,3,7,'Osiem trybów','osiem-trybow','Osiem mechanizmów końca: od podboju i rewolucji po dezintegrację, implozję protezy i absorpcję.',7,NULL,'Eight Modes','Eight mechanisms of ending: from conquest and revolution to disintegration, prosthetic implosion and absorption.',NULL,NULL);
INSERT INTO content_sections VALUES(386,7,384,'heading',3,3,8,'Wzorzec poprzeczny — śmierć i odrodzenie z rdzenia','dwustopniowy','Państwo może umrzeć, a potem odrodzić się z rdzenia pod nową formą.',8,NULL,'Cross-Cutting Pattern — Death and Rebirth from the Core','A state can die and later re-emerge from its core in a new form.',NULL,NULL);
INSERT INTO content_sections VALUES(387,7,384,'heading',3,3,9,'Osie rozróżniające','osie','Tryby rozróżniają m.in. akt kapitulacji, proces rozpadu, ciągłość aparatu i los terytorium.',9,NULL,'Distinguishing Axes','The modes differ in surrender acts, dissolution processes, continuity of the apparatus and the fate of territory.',NULL,NULL);
INSERT INTO content_sections VALUES(388,7,379,'heading',2,2,10,'IV. Filtr rosyjski','filtr-rosyjski','Typologia zostaje zawężona do trybów rzeczywiście możliwych dla nuklearnej, ogromnej Rosji.',10,NULL,'IV. The Russian Filter','The typology is narrowed to modes genuinely possible for a vast nuclear Russia.',NULL,NULL);
INSERT INTO content_sections VALUES(389,7,388,'heading',3,3,11,'Które tryby odpadają','ktore-odpadaja','Podbój, rozbiór i część trybów kapitulacyjnych odpadają; zostają głównie zmiana centrum i dezintegracja.',11,NULL,'Which Modes Drop Out','Conquest, partition and some surrender modes fall away; what remains is mainly a change of centre and disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(390,7,388,'heading',3,3,12,'Dwa silniki samorozwiązania — ZSRR vs Austro-Węgry','dwa-silniki','Rosji bliżej do odgórnej defekcji elit ZSRR niż oddolnego rozpadu narodowego Austro-Węgier.',12,NULL,'Two Engines of Self-Dissolution — USSR vs Austria-Hungary','Russia is closer to the USSR''s top-down elite defection than to Austria-Hungary''s bottom-up national disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(391,7,388,'heading',3,3,13,'Liczba 1,1 mln — armia frontu vs aparat trzymania','liczba-armii','Armia frontowa i aparat represji to różne pule; klęska frontu jest sygnałem, nie automatycznym rozpadem.',13,NULL,'The 1.1 Million Figure — Front Army vs Holding Apparatus','The field army and coercive apparatus are separate pools; defeat at the front is a signal, not automatic disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(392,7,388,'heading',3,3,14,'Monopol na przemoc jako przekonanie o sobie','monopol-przekonanie','Monopol przemocy trwa, dopóki aparat wierzy, że centrum pozostaje silne i zwycięskie.',14,NULL,'The Monopoly on Violence as a Belief About Oneself','The monopoly on violence lasts as long as the apparatus believes the centre remains strong and victorious.',NULL,NULL);
INSERT INTO content_sections VALUES(393,7,379,'heading',2,2,15,'V. Hierarchia zewnętrzna — z patrona w klienta','hierarchia','Rosja spadła z roli patrona do klienta Chin, tracąc kolejne szczeble zewnętrznej suwerenności.',15,NULL,'V. External Hierarchy — from Patron to Client','Russia has fallen from patron to client of China, losing successive layers of external sovereignty.',NULL,NULL);
INSERT INTO content_sections VALUES(394,7,379,'heading',2,2,16,'VI. Kto chce jakiej Rosji','kto-chce','Rozdzielenie interesów aktorów według tego, czy chcą Rosji całej, silnej czy ograniczonej do rdzenia.',16,NULL,'VI. Who Wants What Kind of Russia','Actors'' interests separated by whether they want Russia whole, strong or reduced to its core.',NULL,NULL);
INSERT INTO content_sections VALUES(395,7,394,'heading',3,3,17,'Trzy stany — całość, siła, siła bez federacji','trzy-stany','Integralność, siła i federacyjność są osobnymi osiami; atrakcyjny bywa silny rdzeń bez peryferii.',17,NULL,'Three States — Wholeness, Strength, Strength Without Federation','Territorial integrity, strength and federal structure are separate axes; a strong core without the periphery can be attractive.',NULL,NULL);
INSERT INTO content_sections VALUES(396,7,394,'heading',3,3,18,'Chiny i norma integralności (vide Ukraina)','chiny-integralnosc','Pekin traktuje integralność Rosji instrumentalnie; ważniejsze są stabilność, dostęp i zależność ekonomiczna.',18,NULL,'China and the Norm of Territorial Integrity (cf. Ukraine)','Beijing treats Russia''s territorial integrity instrumentally; stability, access and economic dependence matter more.',NULL,NULL);
INSERT INTO content_sections VALUES(397,7,394,'heading',3,3,19,'Iran na osi proliferacyjnej','iran-proliferacja','Iranowi bardziej niż na mapie Rosji zależałoby na krótkim oknie dostępu do technologii nuklearnej.',19,NULL,'Iran on the Proliferation Axis','Iran would care less about Russia''s map than about a brief window of access to nuclear technology.',NULL,NULL);
INSERT INTO content_sections VALUES(398,7,394,'heading',3,3,20,'Kategoria IV — Musk i Thiel','musk-thiel','Prywatni aktorzy mogą preferować fragmentację i wpływać na zachodni instynkt stabilizacyjny, choć jej nie wywołają.',20,NULL,'Category IV — Musk and Thiel','Private actors may prefer fragmentation and influence the West''s stabilising instinct, though they will not cause the fragmentation themselves.',NULL,NULL);
INSERT INTO content_sections VALUES(399,7,394,'heading',3,3,21,'Bilans — kto realnie po której stronie','bilans-kto','Po stronie integralności Rosji nie ma silnej, spójnej koalicji; interesy zewnętrzne są rozproszone.',21,NULL,'Balance — Who Is Really on Which Side','There is no strong, coherent coalition on the side of Russia''s territorial integrity; external interests are dispersed.',NULL,NULL);
INSERT INTO content_sections VALUES(400,7,379,'heading',2,2,22,'VII. Rozbrojenie straszaka uchodźczego','uchodzcy','Ryzyko uchodźcze jest realne, lecz bardziej zależy od mobilizacji i przemocy niż samej biedy czy rozpadu.',22,NULL,'VII. Defusing the Refugee Scare','Refugee risk is real, but depends more on mobilisation and violence than on poverty or disintegration itself.',NULL,NULL);
INSERT INTO content_sections VALUES(401,7,379,'heading',2,2,23,'VIII. Spoiwo wewnętrzne — trzy warstwy','spoiwo','Trzy wewnętrzne warstwy trzymania Rosji okazują się warunkową kalkulacją, nie trwałą lojalnością.',23,NULL,'VIII. Internal Binding — Three Layers','Three internal layers holding Russia together turn out to be conditional calculations rather than durable loyalty.',NULL,NULL);
INSERT INTO content_sections VALUES(402,7,401,'heading',3,3,24,'Warstwa I — siłowicy jako czujnik siły (~300 tys. + rodziny)','warstwa-silowicy','Siłowicy są czujnikiem postrzeganej siły centrum i mogą zmienić stronę, gdy kalkulacja się odwróci.',24,NULL,'Layer I — Siloviki as a Strength Sensor (~300,000 + Families)','The siloviki are a sensor of the centre''s perceived strength and may switch sides when the calculation reverses.',NULL,NULL);
INSERT INTO content_sections VALUES(403,7,401,'heading',3,3,25,'Warstwa II — biurokracja jako inercja (X mln federalnych i quasi-federalnych)','warstwa-inercja','Biurokracja podtrzymuje funkcjonowanie państwa, nie reżimu; warunkiem jej inercji jest wypłacalność.',25,NULL,'Layer II — Bureaucracy as Inertia (X Million Federal and Quasi-Federal)','The bureaucracy sustains state functioning, not the regime; its inertia depends on solvency.',NULL,NULL);
INSERT INTO content_sections VALUES(404,7,401,'heading',3,3,26,'Warstwa III — oligarchowie jako zakładnicy','warstwa-oligarchowie','Oligarchowie są zakładnikami systemu i potencjalnym wskaźnikiem wyprzedzającym jego chwiania.',26,NULL,'Layer III — Oligarchs as Hostages','Oligarchs are hostages of the system and a potential leading indicator of its instability.',NULL,NULL);
INSERT INTO content_sections VALUES(405,7,379,'heading',2,2,27,'IX. Synteza — spoiwo to kalkulacja na dwóch zmiennych','synteza','Wewnętrzne spoiwo zależy od dwóch sygnałów: postrzeganej siły i wypłacalności centrum.',27,NULL,'IX. Synthesis — the Binding Agent Is a Calculation on Two Variables','Internal cohesion depends on two signals: perceived strength and the centre''s solvency.',NULL,NULL);
INSERT INTO content_sections VALUES(406,7,379,'heading',2,2,28,'X. Otwarte — peryferie vs rdzeń','otwarte','Nierozstrzygnięte pozostaje, co zatrzyma żywiołową dezintegrację na peryferiach zamiast wciągnąć rdzeń.',28,NULL,'X. Open Question — Periphery vs Core','What remains unresolved is what would stop spontaneous disintegration at the periphery rather than draw in the core.',NULL,NULL);
INSERT INTO content_sections VALUES(407,8,NULL,'heading',1,1,1,'Dark legitimacy: What Russia and Ukraine reveal about authoritarianism','dark-legitimacy-authoritarianism','Koncepcja „ciemnej legitymizacji”: autorytaryzm stabilizowany przez cyniczne oczekiwanie, że każda władza jest zła. Rosja i Ukraina pokazują przeciwstawne logiki legitymizacji.',1,NULL,'Dark Legitimacy: What Russia and Ukraine Reveal About Authoritarianism','The concept of “dark legitimacy”: authoritarianism stabilised by the cynical expectation that all power is bad. Russia and Ukraine reveal opposing logics of legitimacy.',NULL,NULL);
INSERT INTO content_sections VALUES(408,8,407,'heading',2,2,2,'Abstract','abstract','Definicja dark legitimacy i kontrast między rosyjską akceptacją zła a ukraińską legitymizacją afirmatywną.',2,NULL,'Abstract','Definition of dark legitimacy and the contrast between Russian acceptance of evil and Ukrainian affirmative legitimacy.',NULL,NULL);
INSERT INTO content_sections VALUES(409,8,407,'heading',2,2,3,'An affirmative concept of legitimacy','affirmative-concept-legitimacy','Przegląd modeli, w których władza uzasadnia się wartością, misją, zgodą, prawem lub wspólnym celem.',3,NULL,'An Affirmative Concept of Legitimacy','A review of models in which power justifies itself through value, mission, consent, law or a shared purpose.',NULL,NULL);
INSERT INTO content_sections VALUES(410,8,407,'heading',2,2,4,'Governmentality: Affirmative legitimacy beyond democracy','governmentality-affirmative-legitimacy','Governmentality rozszerza afirmatywną legitymizację poza demokrację: władza uzasadnia się produktywnym zarządzaniem i wiedzą.',4,NULL,'Governmentality: Affirmative Legitimacy Beyond Democracy','Governmentality extends affirmative legitimacy beyond democracy: power justifies itself through productive governance and knowledge.',NULL,NULL);
INSERT INTO content_sections VALUES(411,8,407,'heading',2,2,5,'Legitimacy crisis in the Soviet and post-Soviet context','legitimacy-crisis-soviet-post-soviet','Upadek wiary w sowiecką ideologię tworzy cyniczną próżnię, z której Rosja buduje nowy model legitymizacji.',5,NULL,'Legitimacy Crisis in the Soviet and Post-Soviet Context','The collapse of belief in Soviet ideology creates a cynical vacuum from which Russia builds a new model of legitimacy.',NULL,NULL);
INSERT INTO content_sections VALUES(412,8,407,'heading',2,2,6,'Dark legitimacy: Bad is good','dark-legitimacy-bad-is-good','Korupcja i przemoc przestają delegitymizować władzę, gdy uznaje się je za normalne, nieuniknione lub nawet pożądane.',6,NULL,'Dark Legitimacy: Bad Is Good','Corruption and violence stop delegitimising power when they are treated as normal, inevitable or even desirable.',NULL,NULL);
INSERT INTO content_sections VALUES(413,8,407,'heading',2,2,7,'Russia-Ukraine: The war over legitimacy','russia-ukraine-war-over-legitimacy','Wojna jako starcie rosyjskiej ciemnej legitymizacji z ukraińską tradycją zgody, mobilizacji społecznej i godności.',7,NULL,'Russia–Ukraine: The War Over Legitimacy','The war as a clash between Russian dark legitimacy and the Ukrainian tradition of consent, social mobilisation and dignity.',NULL,NULL);
INSERT INTO content_sections VALUES(414,8,407,'heading',2,2,8,'Consequences of dark legitimacy','consequences-dark-legitimacy','Krytyka korupcji wzmacnia system, który już ją zakłada; realną słabością pozostaje utrata obrazu siły.',8,NULL,'Consequences of Dark Legitimacy','Criticism of corruption reinforces a system that already assumes corruption; the real weakness is the loss of the image of strength.',NULL,NULL);
INSERT INTO content_sections VALUES(415,8,407,'heading',2,2,9,'Acknowledgments','acknowledgments','Podziękowania autora za wkład, dyskusje i wsparcie pracy.',9,NULL,'Acknowledgments','The author''s acknowledgments for contributions, discussions and support for the work.',NULL,NULL);
INSERT INTO content_sections VALUES(416,8,407,'heading',2,2,10,'References','references','Bibliografia źródeł teoretycznych i empirycznych wykorzystanych w artykule.',10,NULL,'References','Bibliography of theoretical and empirical sources used in the article.',NULL,NULL);
INSERT INTO content_sections VALUES(417,9,NULL,'heading',1,1,1,'DISINFOLKLORE','disinfolklore','Disinfolklore jako rama łącząca folklor, archetypy i analizę współczesnej dezinformacji. Celem jest rozpoznawanie mechanizmów narracyjnych i budowa odporności poznawczej.',1,NULL,'DISINFOLKLORE','Disinfolklore as a framework combining folklore, archetypes and analysis of contemporary disinformation. Its purpose is to identify narrative mechanisms and build cognitive resilience.',NULL,NULL);
INSERT INTO content_sections VALUES(418,9,417,'heading',2,2,2,'Spis treści','spis-tresci','Mapa dwunastu głównych części kompilacji i jej narzędzi analitycznych.',2,NULL,'Contents','A map of the compilation''s twelve main parts and analytical tools.',NULL,NULL);
INSERT INTO content_sections VALUES(419,9,417,'heading',2,2,3,'IGeneza: most, trolle i folklor','geneza-most-trolle-folklor','Metoda wyrasta z doświadczeń mediatora na moście w Donbasie i obserwacji folklorystycznej struktury konfliktu.',3,NULL,'I. Genesis: the Bridge, Trolls and Folklore','The method grows out of the experience of a mediator on a bridge in Donbas and observation of the folkloric structure of conflict.',NULL,NULL);
INSERT INTO content_sections VALUES(420,9,417,'heading',2,2,4,'IICzym jest Disinfolklore — definicja i zakres','definicja-i-zakres','Disinfolklore jako forma narracji, teoria analityczna i metoda kontrdziałania w wojnie informacyjnej.',4,NULL,'II. What Disinfolklore Is — Definition and Scope','Disinfolklore as a narrative form, analytical theory and countermeasure in information warfare.',NULL,NULL);
INSERT INTO content_sections VALUES(421,9,417,'heading',2,2,5,'IIIDwanaście narzędzi metody analitycznej','dwanascie-narzedzi','Dwunastoelementowy zestaw do parsowania memów, emocji, archetypów, prowokacji i dystrybucji treści.',5,NULL,'III. Twelve Tools of the Analytical Method','A twelve-part toolkit for parsing memes, emotions, archetypes, provocations and content distribution.',NULL,NULL);
INSERT INTO content_sections VALUES(422,9,421,'heading',4,4,6,'Archetypal Disinfolklore Literacy','archetypal-disinfolklore-literacy','Rozpoznawanie archetypów folklorystycznych ukrytych we współczesnych komunikatach.',6,NULL,'Archetypal Disinfolklore Literacy','Recognising folkloric archetypes hidden in contemporary messages.',NULL,NULL);
INSERT INTO content_sections VALUES(423,9,421,'heading',4,4,7,'Incoming-Outgoing Troll Radars','troll-radars','Filtrowanie treści, które wpuszczamy do własnego umysłu i sami przekazujemy dalej.',7,NULL,'Incoming–Outgoing Troll Radars','Filtering the content we let into our own minds and pass on to others.',NULL,NULL);
INSERT INTO content_sections VALUES(424,9,421,'heading',4,4,8,'Look for the Mana in the Meme!','mana-in-the-meme','Identyfikowanie emocjonalnej energii osadzonej w komunikacie i kierunku jej działania.',8,NULL,'Look for the Mana in the Meme!','Identifying the emotional energy embedded in a message and the direction in which it acts.',NULL,NULL);
INSERT INTO content_sections VALUES(425,9,421,'heading',4,4,9,'Archetypal Structures','archetypal-structures','Wykrywanie przełączeń sfer, przemian tożsamości i personifikowania abstrakcji.',9,NULL,'Archetypal Structures','Detecting realm-switching, identity transformations and personification of abstractions.',NULL,NULL);
INSERT INTO content_sections VALUES(426,9,421,'heading',4,4,10,'Trigger → Experience → Reaction','trigger-experience-reaction','Rozdzielenie bodźca, doświadczenia i reakcji, by przerwać automatyczny łańcuch emocjonalny.',10,NULL,'Trigger → Experience → Reaction','Separating stimulus, experience and reaction to interrupt an automatic emotional chain.',NULL,NULL);
INSERT INTO content_sections VALUES(427,9,421,'heading',4,4,11,'Code of Positive Trolls','code-of-positive-trolls','Sześć wartości jako filtr odróżniający komunikację obronną od manipulacyjnej.',11,NULL,'Code of Positive Trolls','Six values used as a filter distinguishing defensive communication from manipulative communication.',NULL,NULL);
INSERT INTO content_sections VALUES(428,9,421,'heading',4,4,12,'Accusation in a Mirror','accusation-in-a-mirror','Sprawca oskarża przyszłą ofiarę o działania, które sam planuje lub wykonuje.',12,NULL,'Accusation in a Mirror','The perpetrator accuses the future victim of actions the perpetrator plans or is already carrying out.',NULL,NULL);
INSERT INTO content_sections VALUES(429,9,421,'heading',4,4,13,'Provocation Logic Cycle','provocation-logic-cycle','Fabrykowanie zagrożenia, a następnie przedstawianie własnej agresji jako odpowiedzi na nie.',13,NULL,'Provocation Logic Cycle','Fabricating a threat and then presenting one''s own aggression as a response to it.',NULL,NULL);
INSERT INTO content_sections VALUES(430,9,421,'heading',4,4,14,'Witch Switch','witch-switch','Przekierowanie realnego lęku społecznego na sfabrykowanego winnego.',14,NULL,'Witch Switch','Redirecting real social fear toward a fabricated culprit.',NULL,NULL);
INSERT INTO content_sections VALUES(431,9,421,'heading',4,4,15,'Coercive Control','coercive-control','Model kontroli przymusowej powtarzający się od relacji osobistych po politykę państwa.',15,NULL,'Coercive Control','A model of coercive control recurring from personal relationships to state politics.',NULL,NULL);
INSERT INTO content_sections VALUES(432,9,421,'heading',4,4,16,'Re-Archetyping','re-archetyping','Świadoma zmiana mentalnego modelu obiektu poprzez podstawienie nowego archetypu.',16,NULL,'Re-Archetyping','Deliberately changing the mental model of an object by substituting a new archetype.',NULL,NULL);
INSERT INTO content_sections VALUES(433,9,421,'heading',4,4,17,'Understanding Rashist Construction','rashist-construction','Analiza produkcji propagandy: temników, fabryk trolli, wektorów i sieci dystrybucji.',17,NULL,'Understanding Rashist Construction','Analysis of propaganda production: temniki, troll factories, vectors and distribution networks.',NULL,NULL);
INSERT INTO content_sections VALUES(434,9,417,'heading',2,2,18,'IVTrzy archetypy: Druidy Don, Duncey Putin, Komik','trzy-archetypy','Trump, Putin i Zełenski jako trzy figury archetypowe organizujące analizowane pole informacyjne.',18,NULL,'IV. Three Archetypes: Druidy Don, Duncey Putin, the Comedian','Trump, Putin and Zelenskyy as three archetypal figures organising the information field under analysis.',NULL,NULL);
INSERT INTO content_sections VALUES(435,9,434,'heading',4,4,19,'Druidy Don (Trump)','druidy-don','Trump jako masowy trickster-szaman zdolny archetypować rzeczywistość polityczną.',19,NULL,'Druidy Don (Trump)','Trump as a mass-scale trickster-shaman capable of archetyping political reality.',NULL,NULL);
INSERT INTO content_sections VALUES(436,9,434,'heading',4,4,20,'Duncey Putin','duncey-putin','Putin jako groźny, lecz nieuczący się archetyp tępego bohatera folklorystycznego.',20,NULL,'Duncey Putin','Putin as a dangerous but non-learning archetype of the dim-witted folkloric hero.',NULL,NULL);
INSERT INTO content_sections VALUES(437,9,434,'heading',4,4,21,'Komik (Zełenski)','komik-zelenski','Zełenski jako archetyp komunikatora wykorzystującego symboliczną „manę” w funkcji obronnej.',21,NULL,'The Comedian (Zelenskyy)','Zelenskyy as an archetypal communicator using symbolic “mana” in a defensive function.',NULL,NULL);
INSERT INTO content_sections VALUES(438,9,417,'heading',2,2,22,'VMana — energia w memach','mana-energia-w-memach','Mem przenosi emocjonalną energię; samo jej rozpoznanie staje się pierwszym filtrem obronnym.',22,NULL,'V. Mana — Energy in Memes','A meme carries emotional energy; recognising it becomes the first defensive filter.',NULL,NULL);
INSERT INTO content_sections VALUES(439,9,417,'heading',2,2,23,'VIAccusation in a Mirror i Provocation Logic','accusation-in-a-mirror-i-provocation-logic','Dwa sprzężone mechanizmy: projekcja własnych zamiarów i tworzenie pretekstu do agresji.',23,NULL,'VI. Accusation in a Mirror and Provocation Logic','Two coupled mechanisms: projection of one''s own intentions and construction of a pretext for aggression.',NULL,NULL);
INSERT INTO content_sections VALUES(440,9,439,'heading',3,3,24,'Oskarżenie w lustrze (Accusation in a Mirror)','oskarzenie-w-lustrze','Rosyjskie oskarżenia można czytać jako projekcję własnych planów sprawcy.',24,NULL,'Accusation in a Mirror','Russian accusations can be read as projection of the perpetrator''s own plans.',NULL,NULL);
INSERT INTO content_sections VALUES(441,9,439,'heading',3,3,25,'Cykl logiki prowokacji (Provocation Logic Cycle)','cykl-logiki-prowokacji','Sfabrykowany pretekst uruchamia pozornie reaktywną, wcześniej zamierzoną agresję.',25,NULL,'Provocation Logic Cycle','A fabricated pretext triggers apparently reactive aggression that was planned in advance.',NULL,NULL);
INSERT INTO content_sections VALUES(442,9,417,'heading',2,2,26,'VIIWitch Switch — przełącznik czarownicy','witch-switch-przelacznik-czarownicy','Autentyczne problemy społeczne zostają podmienione na łatwy, niewinny cel gniewu.',26,NULL,'VII. Witch Switch','Authentic social problems are swapped for an easy, innocent target of anger.',NULL,NULL);
INSERT INTO content_sections VALUES(443,9,417,'heading',2,2,27,'VIIIData Resistant Archetypes — mentalne modele oporne na fakty','data-resistant-archetypes','Głęboki archetyp może ignorować fakty, dopóki dramatyczne kontr-dane nie rozbiją modelu.',27,NULL,'VIII. Data-Resistant Archetypes — Mental Models Resistant to Facts','A deep archetype can ignore facts until dramatic counter-data break the model.',NULL,NULL);
INSERT INTO content_sections VALUES(444,9,417,'heading',2,2,28,'IXFinding Manuland — indoeuropejskie fundamenty','finding-manuland','Projekt szuka sześciotysięcznej ciągłości indoeuropejskich struktur narracyjnych od Jamna do współczesności.',28,NULL,'IX. Finding Manuland — Indo-European Foundations','The project looks for six thousand years of continuity in Indo-European narrative structures from Yamnaya to the present.',NULL,NULL);
INSERT INTO content_sections VALUES(445,9,444,'heading',3,3,29,'Główne tezy Finding Manuland','finding-manuland-glowne-tezy','Ukraina jako cywilizacja źródłowa, Manuland jako kontr-geografia i hipoteza dźwiękowych wzorców semantycznych.',29,NULL,'Core Theses of Finding Manuland','Ukraine as a source civilisation, Manuland as a counter-geography, and a hypothesis of sound-based semantic patterns.',NULL,NULL);
INSERT INTO content_sections VALUES(446,9,417,'heading',2,2,30,'XDisinfolklore a FIMI UE — komplementarność ram','disinfolklore-fimi','FIMI opisuje infrastrukturę manipulacji, Disinfolklore jej archetypowy i emocjonalny mechanizm.',30,NULL,'X. Disinfolklore and EU FIMI — Complementary Frameworks','FIMI describes the infrastructure of manipulation; Disinfolklore describes its archetypal and emotional mechanism.',NULL,NULL);
INSERT INTO content_sections VALUES(447,9,446,'heading',3,3,31,'Co FIMI robi dobrze','fimi-co-robi-dobrze','FIMI skutecznie mapuje incydenty, kanały, atrybucję i wspólną terminologię dla państw UE.',31,NULL,'What FIMI Does Well','FIMI effectively maps incidents, channels, attribution and shared terminology for EU states.',NULL,NULL);
INSERT INTO content_sections VALUES(448,9,446,'heading',3,3,32,'Czego FIMI nie widzi — a Disinfolklore tak','fimi-czego-nie-widzi','FIMI słabiej ujmuje wewnętrznych pośredników oraz emocjonalną i archetypową treść memu.',32,NULL,'What FIMI Misses — and Disinfolklore Sees','FIMI is weaker at capturing internal intermediaries and the emotional and archetypal content of the meme.',NULL,NULL);
INSERT INTO content_sections VALUES(449,9,417,'heading',2,2,33,'XICounter-Disinfolklore — narzędzia obrony','counter-disinfolklore','Sześć kroków: rozpoznanie manipulacji, diagnoza mechanizmu i świadome wdrożenie kontr-archetypu.',33,NULL,'XI. Counter-Disinfolklore — Defensive Tools','Six steps: recognise manipulation, diagnose the mechanism and deliberately deploy a counter-archetype.',NULL,NULL);
INSERT INTO content_sections VALUES(450,9,417,'heading',2,2,34,'XIIWnioski i kierunki dalszych badań','wnioski-i-kierunki','Rama wymaga dalszej walidacji i rozwoju w AI, prawie oraz re-archetypowaniu Ukrainy.',34,NULL,'XII. Conclusions and Directions for Further Research','The framework requires further validation and development in AI, law and the re-archetyping of Ukraine.',NULL,NULL);
INSERT INTO content_sections VALUES(451,10,NULL,'heading',1,1,1,'Disinfolklore: SWOT,Advocatus Diaboli,Przesłuchanie','disinfolklore-swot-advocatus-przesluchanie','Potrójny test Disinfolklore: SWOT, filozoficzny advocatus diaboli i quasi-sądowe badanie wiarygodności metody.',1,NULL,'Disinfolklore: SWOT, Advocatus Diaboli, Cross-Examination','A triple test of Disinfolklore: SWOT, philosophical advocatus diaboli and a quasi-judicial examination of the method''s credibility.',NULL,NULL);
INSERT INTO content_sections VALUES(452,10,451,'heading',2,2,2,'Analiza SWOT','analiza-swot','Bilans mocnych stron, słabości, szans i zagrożeń przed próbą głębszego podważenia metody.',2,NULL,'SWOT Analysis','A balance of strengths, weaknesses, opportunities and threats before attempting a deeper challenge to the method.',NULL,NULL);
INSERT INTO content_sections VALUES(453,10,452,'heading',3,3,3,'Strengths — Siły','strengths-sily','Siłą są interdyscyplinarność, doświadczenie terenowe, operacyjne narzędzia i możliwość kontr-narracji.',3,NULL,'Strengths','Its strengths are interdisciplinarity, field experience, operational tools and the ability to build counter-narratives.',NULL,NULL);
INSERT INTO content_sections VALUES(454,10,452,'heading',3,3,4,'Weaknesses — Słabości','weaknesses-slabosci','Największe słabości to zależność od autora, brak walidacji i spekulatywne elementy lingwistyczne.',4,NULL,'Weaknesses','The greatest weaknesses are dependence on the author, lack of validation and speculative linguistic elements.',NULL,NULL);
INSERT INTO content_sections VALUES(455,10,452,'heading',3,3,5,'Opportunities — Szanse','opportunities-szanse','Szanse: skalowanie przez AI, instytucjonalizacja, edukacja i rosnące zapotrzebowanie na analizę wojny informacyjnej.',5,NULL,'Opportunities','Opportunities include scaling through AI, institutionalisation, education and growing demand for information-warfare analysis.',NULL,NULL);
INSERT INTO content_sections VALUES(456,10,452,'heading',3,3,6,'Threats — Zagrożenia','threats-zagrozenia','Ryzyka: odrzucenie jako pseudonauki, instrumentalizacja polityczna i utrata wiarygodności całego narzędzia.',6,NULL,'Threats','Risks include dismissal as pseudoscience, political instrumentalisation and loss of credibility for the entire toolkit.',NULL,NULL);
INSERT INTO content_sections VALUES(457,10,452,'heading',3,3,7,'Synteza strategiczna','synteza-strategiczna','Oddzielić empirycznie użyteczny toolkit od spekulacji, sformalizować i poddać zewnętrznej walidacji.',7,NULL,'Strategic Synthesis','Separate the empirically useful toolkit from speculation, formalise it and subject it to external validation.',NULL,NULL);
INSERT INTO content_sections VALUES(458,10,451,'heading',2,2,8,'Advocatus Diaboli','advocatus-diaboli','Seria pytań badających etykę, epistemologię i wewnętrzne sprzeczności Disinfolklore.',8,NULL,'Advocatus Diaboli','A series of questions testing the ethics, epistemology and internal contradictions of Disinfolklore.',NULL,NULL);
INSERT INTO content_sections VALUES(459,10,458,'heading',4,4,9,'Jeśli archetypowanie jest bronią — to czy re-archetypowanie nie jest tą samą bronią z odwróconym ostrzem?','archetypowanie-jako-bron','Czy kontr-archetypowanie naprawdę różni się strukturalnie od manipulacji, którą metoda krytykuje?',9,NULL,'If Archetyping Is a Weapon, Is Re-Archetyping Not the Same Weapon with the Blade Reversed?','Does counter-archetyping really differ structurally from the manipulation the method criticises?',NULL,NULL);
INSERT INTO content_sections VALUES(460,10,458,'heading',4,4,10,'Obserwator w polu bitwy: czy można badać zaklęcia, nie będąc samemu zaczarowanym?','obserwator-w-polu-bitwy','Czy zaangażowany uczestnik wojny informacyjnej może zachować dystans potrzebny do jej analizy?',10,NULL,'The Observer on the Battlefield: Can One Study Spells Without Being Enchanted Oneself?','Can an engaged participant in information warfare preserve the distance required to analyse it?',NULL,NULL);
INSERT INTO content_sections VALUES(461,10,458,'heading',4,4,11,'Mana: czy pojęcie niefalsyfikowalne zachowuje moc analityczną?','mana-falsyfikowalnosc','Czy „mana” ma kryterium empiryczne, czy pozostaje metaforą odporną na falsyfikację?',11,NULL,'Mana: Can a Non-Falsifiable Concept Retain Analytical Power?','Does “mana” have an empirical criterion, or does it remain a metaphor resistant to falsification?',NULL,NULL);
INSERT INTO content_sections VALUES(462,10,458,'heading',4,4,12,'Czy twierdzenie „Ukraina to cywilizacja źródłowa Zachodu" nie jest samo w sobie aktem Disinfolklore?','ukraina-jako-disinfolklore','Czy heroiczne re-archetypowanie Ukrainy samo nie staje się świadomie konstruowaną narracją polityczną?',12,NULL,'Is the Claim “Ukraine Is the Source Civilisation of the West” Not Itself an Act of Disinfolklore?','Does heroic re-archetyping of Ukraine itself become a deliberately constructed political narrative?',NULL,NULL);
INSERT INTO content_sections VALUES(463,10,458,'heading',4,4,13,'Indoeuropocentryzm jako ślepy punkt: co z umysłami, które ukształtowały inne matryce?','indoeuropocentryzm','Czy rama oparta na indoeuropejskich archetypach działa poza kulturami ukształtowanymi przez tę tradycję?',13,NULL,'Indo-Eurocentrism as a Blind Spot: What About Minds Shaped by Other Matrices?','Does a framework built on Indo-European archetypes work outside cultures shaped by that tradition?',NULL,NULL);
INSERT INTO content_sections VALUES(464,10,458,'heading',4,4,14,'Problem skali: 1,5 miliona słów vs. 15-sekundowy TikTok. Czy antywirusem na snajpera jest encyklopedia?','problem-skali','Metoda jest za ciężka poznawczo wobec szybkości i prostoty współczesnych kanałów dezinformacji.',14,NULL,'The Scale Problem: 1.5 Million Words vs a 15-Second TikTok. Is an Encyclopaedia the Antivirus for a Sniper?','The method is cognitively too heavy for the speed and simplicity of contemporary disinformation channels.',NULL,NULL);
INSERT INTO content_sections VALUES(465,10,458,'heading',4,4,15,'Granica między narzędziem a systemem wierzeń: kiedy analityk staje się kapłanem?','narzedzie-czy-system-wierzen','Test granicy, po której analityczna terminologia zaczyna funkcjonować jak zamknięty system wiary.',15,NULL,'The Boundary Between Tool and Belief System: When Does the Analyst Become a Priest?','A test of the point at which analytical terminology begins to function like a closed belief system.',NULL,NULL);
INSERT INTO content_sections VALUES(466,10,458,'heading',4,4,16,'Czy demokratyczna broń może przetrwać kontakt z demokratycznym wyborcą?','demokratyczna-bron-i-wyborca','Czy wymagające narzędzie obronne może działać masowo w realnym środowisku demokratycznej uwagi?',16,NULL,'Can a Democratic Weapon Survive Contact with a Democratic Voter?','Can a demanding defensive tool work at mass scale in the real ecology of democratic attention?',NULL,NULL);
INSERT INTO content_sections VALUES(467,10,458,'heading',4,4,17,'Fabuła o trzech postaciach: czy redukcja geopolityki do bajki nie jest formą tego, co Pan krytykuje?','trzy-postacie-redukcja-geopolityki','Archetypizacja Trumpa, Putina i Zełenskiego może upraszczać geopolitykę tak samo jak krytykowana propaganda.',17,NULL,'The Story of Three Characters: Is Reducing Geopolitics to a Fairy Tale Not a Form of What You Criticise?','Archetyping Trump, Putin and Zelenskyy may simplify geopolitics in the same way as the propaganda being criticised.',NULL,NULL);
INSERT INTO content_sections VALUES(468,10,458,'heading',4,4,18,'Ostateczna aporia: czy można zbudować post-narracyjne narzędzie wyłącznie z narracji?','postnarracyjne-narzedzie-z-narracji','Aporia: narzędzie mające wyzwalać z narracji samo jest skonstruowane z narracyjnych kategorii.',18,NULL,'The Final Aporia: Can a Post-Narrative Tool Be Built Entirely from Narratives?','Aporia: a tool meant to liberate people from narratives is itself built from narrative categories.',NULL,NULL);
INSERT INTO content_sections VALUES(469,10,451,'heading',2,2,19,'Przesłuchanie informacyjne biegłegow trybie art. 278 i nast. k.p.c.','przesluchanie-bieglego','Quasi-sądowy test, czy Disinfolklore spełnia wymogi powtarzalności, falsyfikowalności i kompetencji eksperckiej.',19,NULL,'Informational Cross-Examination of an Expert under Art. 278 et seq. of the Polish Code of Civil Procedure','A quasi-judicial test of whether Disinfolklore meets requirements of repeatability, falsifiability and expert competence.',NULL,NULL);
INSERT INTO content_sections VALUES(470,10,469,'heading',4,4,20,'Panie biegły, proszę wskazać, w jakim recenzowanym piśmie naukowym opublikował Pan pełny opis metody Disinfolklore, wraz z recenzjami zewnętrznymi.','publikacja-i-recenzja-metody','Pytanie o recenzowaną publikację pełnej metody i niezależny peer review.',20,NULL,'Expert, Please Identify the Peer-Reviewed Journal in Which You Published the Full Description of the Disinfolklore Method, Together with External Reviews.','A question about peer-reviewed publication of the full method and independent peer review.',NULL,NULL);
INSERT INTO content_sections VALUES(471,10,469,'heading',4,4,21,'Czy dwóch niezależnych analityków, stosujących Pana dwunastoelementowy algorytm do tego samego memu, dojdzie do identycznej konkluzji co do jego klasyfikacji jako Disinfolklore?','powtarzalnosc-klasyfikacji','Test zgodności wyników uzyskiwanych przez niezależnych analityków na tym samym materiale.',21,NULL,'Would Two Independent Analysts Applying Your Twelve-Part Algorithm to the Same Meme Reach the Same Conclusion About Its Classification as Disinfolklore?','A test of inter-analyst consistency on the same material.',NULL,NULL);
INSERT INTO content_sections VALUES(472,10,469,'heading',4,4,22,'Panie biegły, Pan posługuje się pojęciem „mana" jako kluczowym wskaźnikiem analitycznym. Proszę wskazać, jaki wynik empiryczny sfalsyfikowałby twierdzenie, że dany mem „zawiera silną manę".','mana-kryterium-falsyfikacji','Żądanie wyniku empirycznego, który pozwoliłby uznać diagnozę „silnej many” za błędną.',22,NULL,'Expert, You Use the Concept of “Mana” as a Key Analytical Indicator. What Empirical Result Would Falsify the Claim That a Given Meme “Contains Strong Mana”?','A demand for an empirical outcome that would allow the diagnosis of “strong mana” to be judged wrong.',NULL,NULL);
INSERT INTO content_sections VALUES(473,10,469,'heading',4,4,23,'Pana wykształcenie formalne i doświadczenie zawodowe to dyplomacja i mediacja w kontekście OBWE. Proszę wskazać Pana kwalifikacje w zakresie lingwistyki porównawczej, folklorystyki, psychologii poznawczej i archeogenetyki — dyscyplin, na których opiera Pan swoją metodę.','kwalifikacje-bieglego','Test formalnych kompetencji autora w dyscyplinach, na których opiera szeroką metodę.',23,NULL,'Your Formal Education and Professional Experience Are in Diplomacy and Mediation in the OSCE Context. Please Identify Your Qualifications in Comparative Linguistics, Folklore Studies, Cognitive Psychology and Archaeogenetics — the Disciplines on Which Your Method Relies.','A test of the author''s formal competence in the disciplines underpinning the broad method.',NULL,NULL);
INSERT INTO content_sections VALUES(474,10,469,'heading',4,4,24,'Pan jest publicznie zaangażowanym obrońcą sprawy ukraińskiej. Prowadzi Pan fundację Volya, współpracuje z NAFO, określa Rosję terminem „Ruschia". Jak Pan zapewnia sąd o swojej bezstronności jako biegłego w sprawie, w której jedną ze stron jest podmiot powiązany z Federacją Rosyjską?','bezstronnosc-bieglego','Pytanie, czy jawne zaangażowanie po stronie Ukrainy pozwala zachować bezstronność ekspercką.',24,NULL,'You Are a Public Advocate of the Ukrainian Cause. You Run the Volya Foundation, Work with NAFO and Call Russia “Ruschia”. How Do You Assure the Court of Your Impartiality as an Expert in a Case Involving an Entity Linked to the Russian Federation?','A question about whether explicit engagement on Ukraine''s side is compatible with expert impartiality.',NULL,NULL);
INSERT INTO content_sections VALUES(475,10,469,'heading',4,4,25,'Proszę podać precyzyjną, operacyjną definicję pojęcia „archetyp" w Pana metodzie, odróżniającą je od definicji Junga, Campbella i Proppa — na tyle ścisłą, by dwóch prawników mogło niezależnie zastosować ją do tego samego stanu faktycznego.','operacyjna-definicja-archetypu','Żądanie ścisłej definicji archetypu umożliwiającej niezależne i powtarzalne zastosowanie.',25,NULL,'Please Give a Precise Operational Definition of “Archetype” in Your Method, Distinguishing It from Jung, Campbell and Propp — Precise Enough for Two Lawyers to Apply It Independently to the Same Facts.','A demand for a strict definition of archetype enabling independent and repeatable application.',NULL,NULL);
INSERT INTO content_sections VALUES(476,10,469,'heading',4,4,26,'Czy Pan dysponuje danymi empirycznymi — w formie badań eksperymentalnych, quasi-eksperymentalnych lub choćby studium przypadku z grupą kontrolną — potwierdzającymi, że zastosowanie metody Disinfolklore zwiększa odporność odbiorców na dezinformację?','dane-empiryczne-odpornosc-na-dezinformacje','Pytanie o kontrolowane dane dowodzące, że metoda faktycznie zwiększa odporność odbiorców.',26,NULL,'Do You Have Empirical Data — Experimental, Quasi-Experimental or Even a Controlled Case Study — Showing That Disinfolklore Increases Recipients'' Resilience to Disinformation?','A question about controlled evidence that the method actually increases audience resilience.',NULL,NULL);
INSERT INTO content_sections VALUES(477,10,469,'heading',4,4,27,'Pan twierdzi, że dźwięk M-N stanowi „najistotniejsze odkrycie w lingwistyce indoeuropejskiej od czasów de Saussure''a". Proszę wskazać, ilu profesorów lingwistyki indoeuropejskiej — choćby jeden — publicznie poparło to twierdzenie.','m-n-poparcie-lingwistow','Test zewnętrznego poparcia lingwistów dla najbardziej ambitnej hipotezy dźwiękowej M-N.',27,NULL,'You Claim That the M–N Sound Is “the Most Important Discovery in Indo-European Linguistics Since de Saussure”. How Many Professors of Indo-European Linguistics — Even One — Have Publicly Endorsed That Claim?','A test of external scholarly support for the most ambitious M–N sound hypothesis.',NULL,NULL);
INSERT INTO content_sections VALUES(478,10,469,'heading',4,4,28,'Proszę wskazać konkretny przypadek, w którym Pana metoda dałaby wynik fałszywie pozytywny — tj. zidentyfikowałaby jako Disinfolklore komunikat, który nim nie jest.','falszywie-pozytywny','Żądanie przykładu i mechanizmu, w którym metoda błędnie klasyfikuje niewinną treść jako manipulację.',28,NULL,'Please Give a Specific Case in Which Your Method Would Produce a False Positive — Identifying as Disinfolklore a Message That Is Not Disinfolklore.','A demand for an example and mechanism by which the method would misclassify innocent content as manipulation.',NULL,NULL);
INSERT INTO content_sections VALUES(479,10,469,'heading',4,4,29,'Pan twierdzi, że „Accusation in a Mirror" jest strukturą wspólną dla wszystkich ludobójstw — sprawca oskarża ofiarę o to, co sam planuje. Ale wzajemne oskarżenia są codziennością polityki. Proszę podać precyzyjne kryterium, na podstawie którego sąd mógłby odróżnić autentyczne oskarżenie od „Accusation in a Mirror".','accusation-in-a-mirror-kryterium','Potrzeba kryterium odróżniającego projekcję sprawcy od zwykłego politycznego oskarżenia.',29,NULL,'You Claim That “Accusation in a Mirror” Is a Structure Shared by All Genocides — the Perpetrator Accuses the Victim of What the Perpetrator Plans. But Mutual Accusations Are Routine in Politics. What Precise Criterion Would Let a Court Distinguish a Genuine Accusation from “Accusation in a Mirror”?','A need for a criterion distinguishing perpetrator projection from ordinary political accusation.',NULL,NULL);
INSERT INTO content_sections VALUES(480,10,469,'heading',4,4,30,'W jakim typie postępowania cywilnego — o ochronę dóbr osobistych, o naruszenie praw autorskich, o zadośćuczynienie — Pana metoda miałaby walor dowodowy? Proszę wskazać konkretny przepis k.c. lub k.p.c., który dopuszczałby opinię opartą na tej metodzie.','walor-dowodowy','Test konkretnej podstawy prawnej i zakresu, w którym metoda mogłaby być dowodem w postępowaniu.',30,NULL,'In What Type of Civil Proceeding — Protection of Personal Rights, Copyright Infringement, Damages — Would Your Method Have Evidentiary Value? Please Identify a Specific Provision of the Polish Civil Code or Code of Civil Procedure That Would Admit an Opinion Based on This Method.','A test of the concrete legal basis and scope in which the method could serve as evidence.',NULL,NULL);
INSERT INTO content_sections VALUES(481,10,469,'heading',4,4,31,'Panie biegły, ostatnie pytanie: czy Pan, jako twórca tej metody, jest w stanie wskazać warunki, w których sam uznałby ją za obaloną?','warunki-obalenia-metody','Najostrzejszy test naukowości: wskazanie warunków, przy których twórca uznałby metodę za obaloną.',31,NULL,'Expert, Final Question: As the Creator of This Method, Can You Identify the Conditions Under Which You Yourself Would Consider It Refuted?','The sharpest test of scientific status: specifying conditions under which the creator would consider the method falsified.',NULL,NULL);
INSERT INTO content_sections VALUES(482,11,NULL,'heading',1,1,1,'☠️ Taksonomia rosyjskiego samobójstwa','taksonomia-rosyjskiego-samobojstwa','Katalog podejrzanych zgonów prominentnych Rosjan, uporządkowany według oficjalnej lub widocznej metody śmierci. Przy każdym przypadku oddziela fakt zgonu od otwartej interpretacji.',1,NULL,'☠️ Taxonomy of Russian Suicide','A catalogue of suspicious deaths of prominent Russians, organised by the official or visible method of death. Each case separates the fact of death from open interpretation.',NULL,NULL);
INSERT INTO content_sections VALUES(483,11,482,'heading',2,2,2,'I. Defenestracja (upadek z okna)','defenestracja','Przypadki upadków z okien, szczególnie częste wśród elit biznesowych i urzędniczych po 2022.',2,NULL,'I. Defenestration (Falling from a Window)','Cases of falls from windows, especially frequent among business and administrative elites after 2022.',NULL,NULL);
INSERT INTO content_sections VALUES(484,11,482,'heading',2,2,3,'II. Broń palna','bron-palna','Zgony od broni palnej oficjalnie lub wstępnie kwalifikowane jako samobójstwa, często z nietypowymi okolicznościami.',3,NULL,'II. Firearms','Deaths by firearm officially or initially classified as suicides, often under unusual circumstances.',NULL,NULL);
INSERT INTO content_sections VALUES(485,11,482,'heading',2,2,4,'III. Powieszenie / uduszenie','powieszenie-uduszenie','Przypadki powieszeń i uduszeń obejmujące biznes, administrację i osoby z niewygodną wiedzą.',4,NULL,'III. Hanging / Strangulation','Cases of hanging and strangulation involving business, administration and people with inconvenient knowledge.',NULL,NULL);
INSERT INTO content_sections VALUES(486,11,482,'heading',2,2,5,'IV. Utonięcie / upadek z jednostki pływającej','utoniecie-upadek-z-jednostki','Zgony w wodzie lub po wypadnięciu z jednostek pływających, zestawione jako osobny wzorzec.',5,NULL,'IV. Drowning / Falling from a Vessel','Deaths in water or after falling from vessels, grouped as a separate pattern.',NULL,NULL);
INSERT INTO content_sections VALUES(487,11,482,'heading',2,2,6,'V. Nagły zawał / „ostre niewydolności"','nagly-zawal-niewydolnosc','Nagłe zgony medyczne oficjalnie tłumaczone zawałem, udarem lub ostrą niewydolnością.',6,NULL,'V. Sudden Heart Attack / “Acute Failure”','Sudden medical deaths officially explained as heart attack, stroke or acute organ failure.',NULL,NULL);
INSERT INTO content_sections VALUES(488,11,482,'heading',2,2,7,'VI. Trucizny i substancje egzotyczne','trucizny-substancje-egzotyczne','Udokumentowane i podejrzewane użycia trucizn, od polonu i nowiczoka po inne substancje.',7,NULL,'VI. Poisons and Exotic Substances','Documented and suspected uses of poisons, from polonium and Novichok to other substances.',NULL,NULL);
INSERT INTO content_sections VALUES(489,11,482,'heading',2,2,8,'VII. Śmierć w więzieniu / kolonii karnej','smierc-w-wiezieniu','Zgony w więzieniach i koloniach karnych, gdzie państwo kontroluje warunki, opiekę i dostęp do informacji.',8,NULL,'VII. Death in Prison / Penal Colony','Deaths in prisons and penal colonies, where the state controls conditions, care and access to information.',NULL,NULL);
INSERT INTO content_sections VALUES(490,11,482,'heading',2,2,9,'VIII. Znaleziony martwy (bez wyjaśnienia)','znaleziony-martwy','Przypadki, w których oficjalny komunikat ogranicza się do znalezienia ciała bez jasnego mechanizmu śmierci.',9,NULL,'VIII. Found Dead (No Explanation)','Cases where the official communication goes no further than reporting that a body was found, without a clear mechanism of death.',NULL,NULL);
INSERT INTO content_sections VALUES(491,11,482,'heading',2,2,10,'IX. Katastrofa lotnicza (cel = grupa)','katastrofa-lotnicza','Katastrofy lotnicze jako metoda eliminująca jednocześnie cel i jego otoczenie.',10,NULL,'IX. Plane Crash (Target = Group)','Plane crashes as a method capable of eliminating the target and the surrounding group at the same time.',NULL,NULL);
INSERT INTO content_sections VALUES(492,11,482,'heading',2,2,11,'X. Dekapitacja','dekapitacja','Przypadki dosłownej lub skrajnie brutalnej dekapitacji jako osobna, rzadka kategoria.',11,NULL,'X. Decapitation','Cases of literal or extremely brutal decapitation as a separate, rare category.',NULL,NULL);
INSERT INTO content_sections VALUES(493,11,482,'heading',2,2,12,'XI. Metoda podwójna (combo)','metoda-podwojna','Zgony z więcej niż jednym pozornie samobójczym mechanizmem, podważające prostą wersję oficjalną.',12,NULL,'XI. Double Method (Combo)','Deaths involving more than one apparently suicidal mechanism, undermining a simple official account.',NULL,NULL);
INSERT INTO content_sections VALUES(494,11,482,'heading',2,2,13,'XII. Metaanaliza — co mówi taksonomia','metaanaliza-taksonomii','Wzorce sektorowe, budżetowe i temporalne pokazują, gdzie podejrzane zgony skupiają się w rosyjskim systemie.',13,NULL,'XII. Meta-Analysis — What the Taxonomy Says','Sectoral, fiscal and temporal patterns show where suspicious deaths cluster within the Russian system.',NULL,NULL);
INSERT INTO content_sections VALUES(495,12,NULL,'heading',1,1,1,'🐀 Putin — cornered animal edition (v3)','putin-cornered-animal','Mapa opcji Putina jako zapędzonego autokraty, dla którego przegrana może oznaczać utratę władzy lub życia. Punkt ciężkości przesuwa się z finansów na osobiste przetrwanie.',1,NULL,'🐀 Putin — Cornered Animal Edition (v3)','A map of Putin''s options as a cornered autocrat for whom defeat may mean loss of power or life. The centre of gravity shifts from finance to personal survival.',NULL,NULL);
INSERT INTO content_sections VALUES(496,12,495,'heading',2,2,2,'0. Dlaczego to nie jest pytanie o pieniądze','nie-pytanie-o-pieniadze','Kluczowe ograniczenie nie jest księgowe: pokój i przegrana mogą być dla personalistycznego dyktatora groźniejsze niż dalsza wojna.',2,NULL,'0. Why This Is Not a Question of Money','The key constraint is not accounting: peace and defeat may be more dangerous to a personalist dictator than continuing the war.',NULL,NULL);
INSERT INTO content_sections VALUES(497,12,495,'heading',2,2,3,'I. Co mu realnie zostaje (po wszystkich korektach)','co-mu-zostaje','Realne zasoby to chwilowy windfall naftowy, fiskalne wyciskanie ludności, rezerwy CB i pogłębianie zależności od Chin.',3,NULL,'I. What He Really Has Left (After All Corrections)','The real resources are a temporary oil windfall, fiscal squeezing of the population, central-bank reserves and deeper dependence on China.',NULL,NULL);
INSERT INTO content_sections VALUES(498,12,495,'heading',2,2,4,'II. Co nie działa (skreślone)','co-nie-dziala','Skreślone opcje obejmują m.in. zamrożone aktywa, powrót gazu do Europy, dodruk, banki i klasyczne sztuczki monetarne.',4,NULL,'II. What Does Not Work (Crossed Out)','Discarded options include frozen assets, a return of gas to Europe, money printing, banks and classic monetary tricks.',NULL,NULL);
INSERT INTO content_sections VALUES(499,12,495,'heading',2,2,5,'III. Ukryty majątek — $1 bln dark money','ukryty-majatek-dark-money','Offshore Putina jest ogromny, ale trudny do ujawnienia i użycia bez zamrożenia; lepiej służy operacjom wpływu niż finansowaniu wojny.',5,NULL,'III. Hidden Wealth — $1 Trillion in Dark Money','Putin''s offshore wealth is enormous but difficult to reveal and use without freezing; it is better suited to influence operations than to financing the war.',NULL,NULL);
INSERT INTO content_sections VALUES(500,12,495,'heading',2,2,6,'IV. Cornered animal — scenariusze desperacji','scenariusze-desperacji','Mapa ruchów resztkowych od politycznych dealów po eskalację, gdy normalne drogi wyjścia się zamykają.',6,NULL,'IV. Cornered Animal — Scenarios of Desperation','A map of residual moves from political deals to escalation as normal exits close.',NULL,NULL);
INSERT INTO content_sections VALUES(501,12,495,'heading',2,2,7,'V. Kluczowe pytanie: kiedy elity odłączą się od Putina?','kiedy-elity-odlacza-sie-od-putina','Lojalność elit trwa z kalkulacji, dopóki koszt pozostania przy Putinie nie przekroczy ryzyka jego usunięcia.',7,NULL,'V. The Key Question: When Will the Elites Detach from Putin?','Elite loyalty persists as a calculation until the cost of staying with Putin exceeds the risk of removing him.',NULL,NULL);
INSERT INTO content_sections VALUES(502,12,501,'heading',3,3,8,'Synteza v3: Projekt życia mu nie wyszedł','projekt-zycia-mu-nie-wyszedl','Synteza: nie ma ukrytego wielkiego planu, tylko kurczący się zestaw kosztownych i coraz gorszych opcji.',8,NULL,'Synthesis v3: His Life Project Failed','Synthesis: there is no hidden grand plan, only a shrinking set of costly and increasingly bad options.',NULL,NULL);
INSERT INTO content_sections VALUES(503,13,NULL,'heading',1,1,1,'Jałta 3.0','jalta-3-0','Scenariusz przebudowy porządku od Kaukazu po Zatokę po osłabieniu irańskiej państwowości. Hanza 2.0 ma powstać z konwergencji interesów, nie z jednej konferencji czy planu mocarstwa.',1,NULL,'Yalta 3.0','A scenario for restructuring the order from the Caucasus to the Gulf after the weakening of Iranian statehood. Hanseatic League 2.0 is to emerge from converging interests, not from a single conference or great-power blueprint.',NULL,NULL);
INSERT INTO content_sections VALUES(504,13,503,'heading',3,3,2,'Spis treści','spis-tresci','Mapa wizji, koncepcji operacyjnej, driverów aktorów, testów wykonalności, ryzyk i werdyktu.',2,NULL,'Contents','A map of the vision, operational concept, actor drivers, feasibility tests, risks and verdict.',NULL,NULL);
INSERT INTO content_sections VALUES(505,13,503,'heading',2,2,3,'1. Wizja — Synteza','wizja-synteza','Rozpad Iranu jako proces otwierający przestrzeń dla organicznego układu korytarzy, handlu i bezpieczeństwa.',3,NULL,'1. Vision — Synthesis','Iran''s disintegration as a process opening space for an organic system of corridors, trade and security.',NULL,NULL);
INSERT INTO content_sections VALUES(506,13,505,'heading',3,3,4,'Filary wizji','filary-wizji','Pięć podpór: procesowy rozpad, naturalne strefy, zbieżność interesów, szok jako akcelerator i prywatny kapitał.',4,NULL,'Pillars of the Vision','Five supports: process-driven disintegration, natural zones, convergence of interests, shock as accelerator and private capital.',NULL,NULL);
INSERT INTO content_sections VALUES(507,13,503,'heading',2,2,5,'2. Koncepcja operacyjna','koncepcja-operacyjna','Przekład wizji na geografię, korytarze i ograniczone działania, które nie wymagają pełnej okupacji Iranu.',5,NULL,'2. Operational Concept','Translating the vision into geography, corridors and limited actions that do not require full occupation of Iran.',NULL,NULL);
INSERT INTO content_sections VALUES(508,13,507,'heading',3,3,6,'2.1 Rzeka Aras — klucz do operacji azerskiej','rzeka-aras','Aras łączy znaczenie wodne, graniczne i symboliczne, dając Azerbejdżanowi naturalną oś operacji.',6,NULL,'2.1 The Aras River — Key to an Azerbaijani Operation','The Aras combines water, border and symbolic significance, giving Azerbaijan a natural operational axis.',NULL,NULL);
INSERT INTO content_sections VALUES(509,13,507,'heading',3,3,7,'2.2 Pas 30 km — logika operacyjna','pas-30-km','Wąski pas przygraniczny daje barierę obronną i korytarz bez ciężaru administrowania milionami ludzi.',7,NULL,'2.2 The 30 km Belt — Operational Logic','A narrow border belt creates a defensive barrier and corridor without the burden of administering millions of people.',NULL,NULL);
INSERT INTO content_sections VALUES(510,13,507,'heading',3,3,8,'2.3 Zagros — domena kurdyjska','zagros-domena-kurdyjska','Osłabienie Teheranu otwiera Zagros dla kurdyjskich aktorów, ale ich wewnętrzne podziały ograniczają prosty scenariusz.',8,NULL,'2.3 Zagros — the Kurdish Domain','A weakened Tehran opens the Zagros to Kurdish actors, but their internal divisions constrain a simple scenario.',NULL,NULL);
INSERT INTO content_sections VALUES(511,13,507,'heading',3,3,9,'2.4 Wielki deal — Władywostok za Kaukaz','wielki-deal-wladywostok-za-kaukaz','Hipotetyczny sygnał USA do Chin: ustępstwo wobec rosyjskiego Dalekiego Wschodu w zamian za nieblokowanie Kaukazu.',9,NULL,'2.4 The Grand Deal — Vladivostok for the Caucasus','A hypothetical US signal to China: acquiescence over the Russian Far East in exchange for not blocking the Caucasus.',NULL,NULL);
INSERT INTO content_sections VALUES(512,13,507,'heading',3,3,10,'2.5 Model końcowy — Hanza 2.0','hanza-2-0','Sieć handlowa z funkcjami bezpieczeństwa, gdzie regionalni aktorzy odpowiadają za własne odcinki zamiast budować nowe imperium.',10,NULL,'2.5 End-State Model — Hanseatic League 2.0','A trade network with security functions, in which regional actors take responsibility for their own segments instead of building a new empire.',NULL,NULL);
INSERT INTO content_sections VALUES(513,13,503,'heading',2,2,11,'3. Mapa driverów — aktor po aktorze','mapa-driverow','Bilans interesów poszczególnych państw pokazuje, kto zyskuje, czego się boi i co może realnie zrobić.',11,NULL,'3. Driver Map — Actor by Actor','A balance of individual states'' interests shows who gains, what each fears and what each can realistically do.',NULL,NULL);
INSERT INTO content_sections VALUES(514,13,503,'heading',2,2,12,'4. Analizy przeprowadzone','analizy-przeprowadzone','Seria testów głównych założeń: rozpad Iranu, IRGC, operacja azerska, koalicja, Rosja, finansowanie i szok.',12,NULL,'4. Analyses Conducted','A series of tests of the main assumptions: Iranian disintegration, the IRGC, an Azerbaijani operation, coalition dynamics, Russia, financing and shock.',NULL,NULL);
INSERT INTO content_sections VALUES(515,13,514,'heading',3,3,13,'4.1 Analiza rozpadu irańskiej państwowości','rozpad-iranskiej-panstwowosci','Test, czy obserwowane uszkodzenia oznaczają początek rozpadu państwa czy tylko adaptację reżimu.',13,NULL,'4.1 Analysis of the Disintegration of Iranian Statehood','A test of whether observed damage marks the beginning of state disintegration or merely regime adaptation.',NULL,NULL);
INSERT INTO content_sections VALUES(516,13,515,'heading',4,4,14,'Argumenty za rozpoczęciem rozpadu','argumenty-za-rozpadem','Blackout, zerwana sukcesja, utrata koordynacji i monopolu przemocy wskazują na jakościową degradację państwa.',14,NULL,'Arguments That Disintegration Has Begun','Blackout, broken succession, loss of coordination and loss of the monopoly on violence point to qualitative state degradation.',NULL,NULL);
INSERT INTO content_sections VALUES(517,13,515,'heading',4,4,15,'Argumenty przeciw','argumenty-przeciw-rozpadowi','Silna tradycja państwowa, biurokracja i tożsamość irańska mogą utrzymać kraj mimo dekapitacji reżimu.',15,NULL,'Arguments Against','A strong state tradition, bureaucracy and Iranian identity may hold the country together despite regime decapitation.',NULL,NULL);
INSERT INTO content_sections VALUES(518,13,514,'heading',3,3,16,'4.2 Analiza utraty aury strachu przez IRGC','utrata-aury-strachu-irgc','Pytanie, czy militarne osłabienie IRGC niszczy jego najważniejszy zasób: reputację nieuchronnej siły.',16,NULL,'4.2 Analysis of the IRGC''s Loss of Its Aura of Fear','Whether military weakening of the IRGC destroys its most important asset: the reputation of inevitable force.',NULL,NULL);
INSERT INTO content_sections VALUES(519,13,518,'heading',4,4,17,'Wnioski','wnioski-irgc','Rozpad sieci proxy i nieskuteczność odwetu czynią utratę aury strachu trudną do odwrócenia.',17,NULL,'Conclusions','The breakdown of proxy networks and ineffective retaliation make the loss of the aura of fear difficult to reverse.',NULL,NULL);
INSERT INTO content_sections VALUES(520,13,514,'heading',3,3,18,'4.3 Analiza operacji azerskiej','operacja-azerska','Ocena ograniczonego wejścia Azerbejdżanu do północnego Iranu jako ruchu stabilizacyjnego i korytarzowego.',18,NULL,'4.3 Analysis of an Azerbaijani Operation','Assessment of a limited Azerbaijani entry into northern Iran as a stabilisation and corridor-building move.',NULL,NULL);
INSERT INTO content_sections VALUES(521,13,520,'heading',4,4,19,'Feasibility','feasibility-operacji-azerskiej','Gotowość armii, casus belli, kontakt z USA, istniejąca infrastruktura i narracja humanitarna wspierają wykonalność.',19,NULL,'Feasibility','Military readiness, casus belli, contact with the US, existing infrastructure and a humanitarian narrative support feasibility.',NULL,NULL);
INSERT INTO content_sections VALUES(522,13,514,'heading',3,3,20,'4.4 Analiza konwergencji interesów sojuszników','konwergencja-interesow-sojusznikow','Test, czy egoistyczne interesy Azerbejdżanu, Turcji, Izraela, USA, UE, Armenii i GCC wystarczą do wspólnego kierunku.',20,NULL,'4.4 Analysis of Allied Interest Convergence','A test of whether the self-interested goals of Azerbaijan, Turkey, Israel, the US, the EU, Armenia and the GCC are enough to produce a common direction.',NULL,NULL);
INSERT INTO content_sections VALUES(523,13,522,'heading',4,4,21,'Zbieżności','zbieznosci-sojusznikow','Wspólnym mianownikiem są osłabienie Iranu oraz nowe korytarze transportowe i energetyczne.',21,NULL,'Convergences','The common denominator is a weaker Iran and new transport and energy corridors.',NULL,NULL);
INSERT INTO content_sections VALUES(524,13,522,'heading',4,4,22,'Sprzeczności','sprzecznosci-sojusznikow','Koalicję rozrywają konkurencyjne korytarze, kwestia kurdyjska i różny apetyt na skalę rozpadu Iranu.',22,NULL,'Contradictions','The coalition is strained by competing corridors, the Kurdish question and differing appetites for the scale of Iran''s disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(525,13,514,'heading',3,3,23,'4.5 Analiza roli Rosji','rola-rosji','Ocena, czy Moskwa ma jeszcze materialną zdolność blokowania przebudowy Kaukazu i Bliskiego Wschodu.',23,NULL,'4.5 Analysis of Russia''s Role','Assessment of whether Moscow still has the material capacity to block the reconstruction of the Caucasus and Middle East.',NULL,NULL);
INSERT INTO content_sections VALUES(526,13,525,'heading',4,4,24,'Dlaczego Rosja się nie liczy','dlaczego-rosja-sie-nie-liczy','Wojna z Ukrainą i utrata wpływów w Armenii redukują Rosję z veto-playera do słabego dostawcy wsparcia Iranowi.',24,NULL,'Why Russia Does Not Count','The war with Ukraine and loss of influence in Armenia reduce Russia from a veto player to a weak supplier of support to Iran.',NULL,NULL);
INSERT INTO content_sections VALUES(527,13,514,'heading',3,3,25,'4.6 Analiza modelu finansowania','model-finansowania','Nowa infrastruktura miałaby powstawać z mieszanki kapitału UE, GCC, USA, Izraela i prywatnego old money.',25,NULL,'4.6 Analysis of the Financing Model','New infrastructure would be financed by a mix of EU, GCC, US, Israeli and private old-money capital.',NULL,NULL);
INSERT INTO content_sections VALUES(528,13,527,'heading',4,4,26,'Źródła kapitału','zrodla-kapitalu','Kapitał dla korytarzy istnieje w energetyce, logistyce, funduszach Zatoki i cierpliwych inwestorach prywatnych.',26,NULL,'Sources of Capital','Capital for corridors exists in energy, logistics, Gulf funds and patient private investors.',NULL,NULL);
INSERT INTO content_sections VALUES(529,13,514,'heading',3,3,27,'4.7 Analiza szoku jako akceleratora','szok-jako-akcelerator','Kryzys ma wymusić inwestycje i decyzje, które w normalnych warunkach blokowałoby status quo.',27,NULL,'4.7 Analysis of Shock as an Accelerator','Crisis is expected to force investments and decisions that the status quo would block under normal conditions.',NULL,NULL);
INSERT INTO content_sections VALUES(530,13,529,'heading',4,4,28,'Precedensy historyczne','precedensy-historyczne','1973, dot.com, 2008, COVID i 2022 pokazują szoki przyspieszające wcześniej rozpoczęte transformacje.',28,NULL,'Historical Precedents','1973, dot-com, 2008, COVID and 2022 show shocks accelerating transformations already under way.',NULL,NULL);
INSERT INTO content_sections VALUES(531,13,503,'heading',2,2,29,'5. Zidentyfikowane dziury i ryzyka','dziury-i-ryzyka','Największe ryzyka dotyczą nukleariów, ropy, rozlania konfliktu, tożsamości lokalnych i utraty kontroli nad sekwencją.',29,NULL,'5. Identified Gaps and Risks','The greatest risks concern nuclear materials, oil, conflict spillover, local identities and loss of control over sequencing.',NULL,NULL);
INSERT INTO content_sections VALUES(532,13,531,'heading',4,4,30,'RYZYKO KRYTYCZNE 1: 440 kg uranu w rozpadającym się państwie','ryzyko-uran-440-kg','Utrata kontroli nad wysoko wzbogaconym uranem może uruchomić proliferację albo wymusić międzynarodowe zabezpieczenie.',30,NULL,'CRITICAL RISK 1: 440 kg of Uranium in a Disintegrating State','Loss of control over highly enriched uranium could trigger proliferation or force international securing operations.',NULL,NULL);
INSERT INTO content_sections VALUES(533,13,531,'heading',4,4,31,'RYZYKO KRYTYCZNE 2: Globalny szok naftowy','ryzyko-globalny-szok-naftowy','Szok naftowy jednocześnie zwiększa potrzebę nowych korytarzy i osłabia zdolność sponsorów do ich finansowania.',31,NULL,'CRITICAL RISK 2: Global Oil Shock','An oil shock simultaneously increases the need for new corridors and weakens sponsors'' ability to finance them.',NULL,NULL);
INSERT INTO content_sections VALUES(534,13,531,'heading',4,4,32,'RYZYKO 3: Pakistan i Beludżystan','ryzyko-pakistan-beludzystan','Dezintegracja Iranu może przenieść dynamikę beludżyjską na nuklearny Pakistan.',32,NULL,'RISK 3: Pakistan and Balochistan','Iranian disintegration could carry Baloch dynamics into nuclear-armed Pakistan.',NULL,NULL);
INSERT INTO content_sections VALUES(535,13,531,'heading',4,4,33,'RYZYKO 4: Tożsamość irańskich Azerów','ryzyko-tozsamosc-iranskich-azerow','Irańscy Azerowie nie muszą automatycznie wybierać przyłączenia do Azerbejdżanu; tożsamość jest bardziej złożona.',33,NULL,'RISK 4: Identity of Iranian Azerbaijanis','Iranian Azerbaijanis would not automatically choose union with Azerbaijan; identity is more complex.',NULL,NULL);
INSERT INTO content_sections VALUES(536,13,531,'heading',4,4,34,'RYZYKO 5: Mission creep i eskalacja','ryzyko-mission-creep-eskalacja','Ograniczona misja stabilizacyjna może rozszerzyć się w okupację, konflikt regionalny lub starcie sponsorów.',34,NULL,'RISK 5: Mission Creep and Escalation','A limited stabilisation mission could expand into occupation, regional conflict or confrontation among sponsors.',NULL,NULL);
INSERT INTO content_sections VALUES(537,13,531,'heading',4,4,35,'RYZYKO 6: Fragmentacja kurdyjska','ryzyko-fragmentacja-kurdyjska','Podziały między ugrupowaniami kurdyjskimi mogą zamienić próżnię w konkurencję zamiast stabilnej strefy.',35,NULL,'RISK 6: Kurdish Fragmentation','Divisions among Kurdish groups could turn a vacuum into competition rather than a stable zone.',NULL,NULL);
INSERT INTO content_sections VALUES(538,13,531,'heading',4,4,36,'RYZYKO 7: Sekwencja zdarzeń','ryzyko-sekwencja-zdarzen','Model zależy od kolejności: te same wydarzenia w innym tempie mogą zamknąć zamiast otworzyć okno.',36,NULL,'RISK 7: Sequence of Events','The model depends on sequencing: the same events at a different pace can close the window instead of opening it.',NULL,NULL);
INSERT INTO content_sections VALUES(539,13,503,'heading',2,2,37,'6. Werdykt końcowy','werdykt-koncowy','Scenariusz jest możliwy, lecz zależy od kilku bardzo mocnych założeń i wymaga rygorystycznego pilnowania ryzyk.',37,NULL,'6. Final Verdict','The scenario is possible, but depends on several very strong assumptions and requires rigorous risk control.',NULL,NULL);
INSERT INTO content_sections VALUES(540,13,539,'heading',3,3,38,'Ocena analityka','ocena-analityka','Końcowa samoocena oddziela elementy mocno uzasadnione od spekulatywnych, szczególnie w kwestii Chin i skali rozpadu.',38,NULL,'Analyst''s Assessment','The final self-assessment separates well-supported elements from speculative ones, especially regarding China and the scale of disintegration.',NULL,NULL);
INSERT INTO content_sections VALUES(541,14,NULL,'heading',1,1,1,'Jałta 3.0','jalta-3-0','Pięć głębszych warstw argumentu za Jałtą 3.0: styl decyzyjny, tożsamość, nieufność, równowagi Nasha i metoda analizy.',1,NULL,'Yalta 3.0','Five deeper layers of the argument for Yalta 3.0: decision style, identity, distrust, Nash equilibria and analytical method.',NULL,NULL);
INSERT INTO content_sections VALUES(542,14,541,'heading',2,2,2,'1 Warstwa kognitywna — AuDHD jako styl decyzyjny','warstwa-kognitywna','Spekulatywna rama traktująca cechy AuDHD jako styl decyzyjny, nie diagnozę kliniczną aktorów.',2,NULL,'1. Cognitive Layer — AuDHD as a Decision Style','A speculative framework treating AuDHD traits as a decision style, not as clinical diagnosis of the actors.',NULL,NULL);
INSERT INTO content_sections VALUES(543,14,542,'heading',3,3,3,'Hipoteza','hipoteza-warstwa-kognitywna','Hipoteza wspólnego stylu poznawczego Trumpa, Aliyeva i Izraela jako źródła łatwiejszej synchronizacji.',3,NULL,'Hypothesis','A hypothesis that Trump, Aliyev and Israel share a cognitive style that makes synchronisation easier.',NULL,NULL);
INSERT INTO content_sections VALUES(544,14,543,'heading',4,4,4,'Trump — podręcznikowy profil ADHD','trump-profil-adhd','Trump opisany przez impulsywność, krótki horyzont uwagi, transakcyjność i hiperfokus na atrakcyjnych dealach.',4,NULL,'Trump — a Textbook ADHD Profile','Trump described through impulsivity, a short attention horizon, transactionalism and hyperfocus on attractive deals.',NULL,NULL);
INSERT INTO content_sections VALUES(545,14,543,'heading',4,4,5,'Aliyev — AuDHD w trybie strategicznym','aliyev-audhd-strategiczne','Aliyev opisany jako długotrwale skupiony na celu, systemowy i zdolny do nagłego działania po długiej obserwacji.',5,NULL,'Aliyev — AuDHD in Strategic Mode','Aliyev described as persistently goal-focused, systemic and capable of sudden action after long observation.',NULL,NULL);
INSERT INTO content_sections VALUES(546,14,543,'heading',4,4,6,'Izrael — państwo z AuDHD','izrael-panstwo-z-audhd','Izrael potraktowany metaforycznie jako system państwowy obsesyjnie modelujący wzorce zagrożeń i szybko reagujący.',6,NULL,'Israel — a State with AuDHD','Israel treated metaphorically as a state system that obsessively models threat patterns and reacts quickly.',NULL,NULL);
INSERT INTO content_sections VALUES(547,14,541,'heading',2,2,7,'2 Warstwa tożsamościowa — trzy narody bez państwa','warstwa-tozsamosciowa','Żydzi, Kurdowie i Azerowie jako narody z doświadczeniem przetrwania bez własnego lub pełnego państwa.',7,NULL,'2. Identity Layer — Three Nations Without a State','Jews, Kurds and Azerbaijanis as nations shaped by experience of survival without their own or a fully sovereign state.',NULL,NULL);
INSERT INTO content_sections VALUES(548,14,547,'heading',3,3,8,'Fundament koalicji','fundament-koalicji','Wspólne doświadczenie podziału i obcej dominacji ma tworzyć głębsze spoiwo niż bieżący interes.',8,NULL,'Foundation of the Coalition','A shared experience of division and foreign domination is proposed as a deeper bond than current interest.',NULL,NULL);
INSERT INTO content_sections VALUES(549,14,548,'heading',4,4,9,'Wspólna cecha 1: Państwo jako projekt, nie dana','panstwo-jako-projekt','Państwowość jako projekt pokoleniowy, który można odzyskać po dekadach lub stuleciach utraty.',9,NULL,'Shared Feature 1: The State as a Project, Not a Given','Statehood as a generational project that can be recovered after decades or centuries of loss.',NULL,NULL);
INSERT INTO content_sections VALUES(550,14,548,'heading',4,4,10,'Wspólna cecha 2: Wzajemne rozpoznanie','wzajemne-rozpoznanie','Wspólnota doświadczenia izolacji i przetrwania ma ułatwiać trwałe rozpoznanie między trzema narodami.',10,NULL,'Shared Feature 2: Mutual Recognition','Shared experience of isolation and survival is expected to facilitate durable recognition among the three nations.',NULL,NULL);
INSERT INTO content_sections VALUES(551,14,548,'heading',4,4,11,'Wspólna cecha 3: Samowystarczalność jako imperatyw przetrwania','samowystarczalnosc-przetrwanie','Historia zdrad protektorów wzmacnia kulturę samodzielnego zabezpieczania własnego przetrwania.',11,NULL,'Shared Feature 3: Self-Sufficiency as a Survival Imperative','A history of betrayal by protectors strengthens a culture of securing one''s own survival independently.',NULL,NULL);
INSERT INTO content_sections VALUES(552,14,547,'heading',3,3,12,'Trzy tysiące lat wspólnej historii','trzy-tysiace-lat-historii','Długie relacje Żydów, Kurdów i Azerów przedstawione jako historyczna warstwa pod współczesną koalicją.',12,NULL,'Three Thousand Years of Shared History','Long relations among Jews, Kurds and Azerbaijanis presented as a historical layer beneath the contemporary coalition.',NULL,NULL);
INSERT INTO content_sections VALUES(553,14,547,'heading',3,3,13,'Abraham w górach Zagros','abraham-w-zagros','Geografia Zagros, Araratu i Arasu użyta jako symboliczna warstwa wspólnej pamięci i sakralnego znaczenia ziemi.',13,NULL,'Abraham in the Zagros Mountains','The geography of the Zagros, Ararat and Aras used as a symbolic layer of shared memory and sacred meaning of land.',NULL,NULL);
INSERT INTO content_sections VALUES(554,14,541,'heading',2,2,14,'3 Warstwa paradoksu — nieufność jako stabilizator','warstwa-paradoksu','Nieufność wobec zewnętrznych gwarantów ma wzmacniać autonomię i odporność projektowanego układu.',14,NULL,'3. Paradox Layer — Distrust as a Stabiliser','Distrust of external guarantors is expected to strengthen autonomy and resilience of the proposed arrangement.',NULL,NULL);
INSERT INTO content_sections VALUES(555,14,554,'heading',3,3,15,'Teza','teza-nieufnosc-stabilizator','Kurdyjska nieufność wobec USA przedstawiona jako atut, bo wymusza planowanie bez gwaranta.',15,NULL,'Thesis','Kurdish distrust of the US is presented as an advantage because it forces planning without a guarantor.',NULL,NULL);
INSERT INTO content_sections VALUES(556,14,554,'heading',3,3,16,'Precedensy zdrady','precedensy-zdrady','1975, 1991 i 2019 jako ciąg amerykańskich porzuceń Kurdów kształtujący ich strategię autonomii.',16,NULL,'Precedents of Betrayal','1975, 1991 and 2019 as a sequence of US abandonments of the Kurds shaping their strategy of autonomy.',NULL,NULL);
INSERT INTO content_sections VALUES(557,14,554,'heading',3,3,17,'Pięć mechanizmów, przez które nieufność wzmacnia projekt','piec-mechanizmow-nieufnosci','Pięć sposobów, w jakie oczekiwanie zdrady ma zwiększać samodzielność i trwałość układu.',17,NULL,'Five Mechanisms Through Which Distrust Strengthens the Project','Five ways in which expecting betrayal is supposed to increase self-reliance and durability.',NULL,NULL);
INSERT INTO content_sections VALUES(558,14,557,'heading',4,4,18,'Mechanizm 1: Autonomia działania','autonomia-dzialania','Brak zaufania do patrona skraca ścieżkę decyzji: aktor działa z własnego interesu, nie czeka na sygnał.',18,NULL,'Mechanism 1: Autonomy of Action','Lack of trust in a patron shortens the decision path: the actor acts in its own interest instead of waiting for a signal.',NULL,NULL);
INSERT INTO content_sections VALUES(559,14,557,'heading',4,4,19,'Mechanizm 2: Struktury niepodległe od patrona','struktury-niezalezne-od-patrona','Własna obrona, dochody i regionalne sojusze mają pozwolić przetrwać po zniknięciu zewnętrznego parasola.',19,NULL,'Mechanism 2: Structures Independent of the Patron','Own defence, revenues and regional alliances are meant to survive the disappearance of an external umbrella.',NULL,NULL);
INSERT INTO content_sections VALUES(560,14,557,'heading',4,4,20,'Mechanizm 3: Uniezależnienie od attention spanu Trumpa','niezaleznosc-od-attention-spanu-trumpa','Jeśli lokalni aktorzy działają dla siebie, zmienność zainteresowania Trumpa przestaje być krytycznym ryzykiem.',20,NULL,'Mechanism 3: Independence from Trump''s Attention Span','If local actors act for themselves, fluctuations in Trump''s attention cease to be a critical risk.',NULL,NULL);
INSERT INTO content_sections VALUES(561,14,557,'heading',4,4,21,'Mechanizm 4: Eliminacja pułapki zależności','eliminacja-pulapki-zaleznosci','Dywersyfikacja partnerów i własnych zasobów ma usuwać strategiczne uzależnienie od jednego patrona.',21,NULL,'Mechanism 4: Eliminating the Dependency Trap','Diversifying partners and own resources is meant to remove strategic dependence on a single patron.',NULL,NULL);
INSERT INTO content_sections VALUES(562,14,557,'heading',4,4,22,'Mechanizm 5: Budowa legitymacji wewnętrznej, nie zewnętrznej','legitymacja-wewnetrzna','Fakty na ziemi i lokalne instytucje mają dawać legitymację niezależną od formalnego uznania mocarstw.',22,NULL,'Mechanism 5: Building Internal, Not External, Legitimacy','Facts on the ground and local institutions are meant to provide legitimacy independent of formal great-power recognition.',NULL,NULL);
INSERT INTO content_sections VALUES(563,14,541,'heading',2,2,23,'4 Warstwa matematyczna — równowagi Nasha','warstwa-matematyczna','Teoria gier ma wykazać, że układ może być samoegzekwujący się bez arbitra i zaufania.',23,NULL,'4. Mathematical Layer — Nash Equilibria','Game theory is used to show that the arrangement can be self-enforcing without an arbiter or trust.',NULL,NULL);
INSERT INTO content_sections VALUES(564,14,563,'heading',3,3,24,'Definicja','definicja-rownowagi-nasha','Równowaga Nasha jako stan, w którym jednostronna defekcja nie poprawia sytuacji żadnego aktora.',24,NULL,'Definition','A Nash equilibrium as a state in which unilateral defection does not improve any actor''s position.',NULL,NULL);
INSERT INTO content_sections VALUES(565,14,563,'heading',3,3,25,'Test Nasha: trójkąt Żydzi — Azerowie — Kurdowie','nash-trojkat-zydzi-azerowie-kurdowie','Test stabilności podstawowego trójkąta przez policzenie kosztów jednostronnego odejścia każdego z partnerów.',25,NULL,'Nash Test: the Jews–Azerbaijanis–Kurds Triangle','A stability test of the core triangle by calculating the cost of unilateral defection for each partner.',NULL,NULL);
INSERT INTO content_sections VALUES(566,14,565,'heading',4,4,26,'Izrael defektuje?','izrael-defektuje','Izrael traciłby bufor i wyjątkowych regionalnych partnerów, nie zyskując porównywalnej alternatywy.',26,NULL,'Israel Defects?','Israel would lose a buffer and unusually valuable regional partners without gaining a comparable alternative.',NULL,NULL);
INSERT INTO content_sections VALUES(567,14,565,'heading',4,4,27,'Azerbejdżan defektuje?','azerbejdzan-defektuje','Azerbejdżan traciłby izraelskie zdolności i kurdyjski bufor na rzecz słabszych alternatyw.',27,NULL,'Azerbaijan Defects?','Azerbaijan would lose Israeli capabilities and the Kurdish buffer in exchange for weaker alternatives.',NULL,NULL);
INSERT INTO content_sections VALUES(568,14,565,'heading',4,4,28,'Kurdowie defektują?','kurdowie-defektuja','Kurdowie wracaliby do izolacji, rezygnując z rzadkich partnerów tolerujących ich autonomię.',28,NULL,'The Kurds Defect?','The Kurds would return to isolation, abandoning rare partners willing to tolerate their autonomy.',NULL,NULL);
INSERT INTO content_sections VALUES(569,14,563,'heading',3,3,29,'Test Nasha: czworokąt z USA','nash-czworokat-z-usa','Dodanie USA testuje, czy amerykańskie zaangażowanie jest korzystne, lecz nie niezbędne dla rdzenia układu.',29,NULL,'Nash Test: Quadrilateral with the US','Adding the US tests whether American involvement is beneficial but not essential to the core arrangement.',NULL,NULL);
INSERT INTO content_sections VALUES(570,14,569,'heading',4,4,30,'USA defektują?','usa-defektuja','Wyjście USA oznaczałoby utratę tanich wpływów i zysków z układu, który prawdopodobnie przetrwa bez nich.',30,NULL,'The US Defects?','US withdrawal would mean losing cheap influence and gains from an arrangement likely to survive without it.',NULL,NULL);
INSERT INTO content_sections VALUES(571,14,569,'heading',4,4,31,'Trójkąt defektuje wobec USA?','trojkat-defektuje-wobec-usa','Trójkąt ma powody zachować USA jako użytecznego partnera, choć nie jako warunek własnego istnienia.',31,NULL,'The Triangle Defects Against the US?','The triangle has reasons to retain the US as a useful partner, though not as a condition of its own existence.',NULL,NULL);
INSERT INTO content_sections VALUES(572,14,563,'heading',3,3,32,'Test Nasha: pełny system','nash-pelny-system','Test rozszerza rachunek defekcji na Turcję, Armenię, UE, GCC i Chiny.',32,NULL,'Nash Test: the Full System','The test extends defection calculations to Turkey, Armenia, the EU, the GCC and China.',NULL,NULL);
INSERT INTO content_sections VALUES(573,14,572,'heading',4,4,33,'Turcja defektuje? → irracjonalne','turcja-defektuje','Turcja traciłaby korytarz turkijski, tranzyt i wpływy bez atrakcyjnej alternatywy.',33,NULL,'Turkey Defects? → Irrational','Turkey would lose the Turkic corridor, transit and influence without an attractive alternative.',NULL,NULL);
INSERT INTO content_sections VALUES(574,14,572,'heading',4,4,34,'Armenia defektuje? → irracjonalne','armenia-defektuje','Armenia traciłaby zachodni zwrot, odblokowanie granic i korzyści z nowych korytarzy.',34,NULL,'Armenia Defects? → Irrational','Armenia would lose its Western turn, border opening and benefits from new corridors.',NULL,NULL);
INSERT INTO content_sections VALUES(575,14,572,'heading',4,4,35,'UE defektuje? → irracjonalne','ue-defektuje','UE traciłaby dywersyfikację energetyczną i dostęp do alternatywnych szlaków azjatyckich.',35,NULL,'The EU Defects? → Irrational','The EU would lose energy diversification and access to alternative Asian routes.',NULL,NULL);
INSERT INTO content_sections VALUES(576,14,572,'heading',4,4,36,'GCC defektuje? → irracjonalne','gcc-defektuje','Państwa Zatoki wracałyby do kosztowniejszego środowiska z silniejszym zagrożeniem irańskim.',36,NULL,'The GCC Defects? → Irrational','Gulf states would return to a costlier environment with a stronger Iranian threat.',NULL,NULL);
INSERT INTO content_sections VALUES(577,14,572,'heading',4,4,37,'Chiny defektują? → irracjonalne (jeśli deal Władywostok)','chiny-defektuja','Przy założeniu dealu Dalekiego Wschodu Chiny miałyby więcej do stracenia niż zyskać na blokowaniu układu.',37,NULL,'China Defects? → Irrational (If the Vladivostok Deal Holds)','Under the Far East deal assumption, China would have more to lose than gain by blocking the arrangement.',NULL,NULL);
INSERT INTO content_sections VALUES(578,14,563,'heading',3,3,38,'Trzy zagnieżdżone równowagi','trzy-zagniezdzone-rownowagi','Lokalna, regionalna i szersza równowaga mają wzajemnie podtrzymywać system na różnych skalach.',38,NULL,'Three Nested Equilibria','Local, regional and broader equilibria are expected to reinforce the system at different scales.',NULL,NULL);
INSERT INTO content_sections VALUES(579,14,541,'heading',2,2,39,'5 Warstwa epistemologiczna — dlaczego ta analiza wygląda tak, jak wygląda','warstwa-epistemologiczna','Refleksja nad tym, jak intuicja, prowokacja i dane prowadziły do wyłaniania kolejnych warstw modelu.',39,NULL,'5. Epistemological Layer — Why This Analysis Looks the Way It Does','Reflection on how intuition, provocation and data led to the emergence of successive layers of the model.',NULL,NULL);
INSERT INTO content_sections VALUES(580,14,579,'heading',3,3,40,'Odwrócona metoda naukowa','odwrocona-metoda-naukowa','Proces opisany jako intuicja → prowokacja → dane → formalizacja, zamiast klasycznej kolejności hipoteza → test.',40,NULL,'The Reversed Scientific Method','The process described as intuition → provocation → data → formalisation, instead of the classical hypothesis → test sequence.',NULL,NULL);
INSERT INTO content_sections VALUES(581,14,541,'heading',2,2,41,'Synteza: dlaczego to zadziała(ć może)','synteza-dlaczego-moze-zadzialac','Zebranie pięciu niezależnych warstw, które mają wspólnie tłumaczyć trwałość układu bez centralnego architekta.',41,NULL,'Synthesis: Why This Could Work','Five independent layers assembled to explain how the arrangement might endure without a central architect.',NULL,NULL);
INSERT INTO content_sections VALUES(582,14,581,'heading',3,3,42,'Pięć warstw = pięć powodów','piec-warstw-piec-powodow','Pięć argumentów za trwałością: synchronizacja poznawcza, pamięć, nieufność, Nash i organiczny proces analityczny.',42,NULL,'Five Layers = Five Reasons','Five arguments for durability: cognitive synchronisation, memory, distrust, Nash and an organic analytical process.',NULL,NULL);
INSERT INTO content_sections VALUES(583,14,581,'heading',3,3,43,'Ostatnie zdanie','ostatnie-zdanie','Jałta 3.0 jako „pole grawitacyjne”: raz uruchomiony układ ma przyciągać aktorów siłą ich własnych interesów.',43,NULL,'Final Sentence','Yalta 3.0 as a “gravitational field”: once activated, the arrangement is expected to attract actors through the force of their own interests.',NULL,NULL);
INSERT INTO content_sections VALUES(584,15,NULL,'heading',1,1,1,'Ropa, gaz i geopolityka','ropa-gaz-geopolityka','Strukturalna analiza popytu na ropę i gaz, możliwości substytucji oraz geopolitycznych skutków transformacji energetycznej.',1,NULL,'Oil, Gas and Geopolitics','A structural analysis of oil and gas demand, substitution possibilities and the geopolitical consequences of the energy transition.',NULL,NULL);
INSERT INTO content_sections VALUES(585,15,584,'heading',2,2,2,'1. Struktura globalnego popytu na ropę i gaz (2024)','globalny-popyt-ropa-gaz-2024','Podział globalnego zużycia ropy i gazu na transport, energię, feedstock i pozostałe zastosowania.',2,NULL,'1. Structure of Global Oil and Gas Demand (2024)','A breakdown of global oil and gas consumption into transport, energy, feedstock and other uses.',NULL,NULL);
INSERT INTO content_sections VALUES(586,15,585,'heading',3,3,3,'1.1. Transport — podział wewnętrzny','transport-podzial-wewnetrzny','Transport drogowy dominuje i ma substytuty; lotnictwo oraz żegluga tworzą twardszy rdzeń popytu.',3,NULL,'1.1 Transport — Internal Breakdown','Road transport dominates and has substitutes; aviation and shipping form a harder core of demand.',NULL,NULL);
INSERT INTO content_sections VALUES(587,15,584,'heading',2,2,4,'2. Substytucja: co można zastąpić „już teraz"?','substytucja-juz-teraz','Większość energetycznego użycia ropy i gazu można technicznie zastąpić bez nowych przełomów naukowych.',4,NULL,'2. Substitution: What Can Be Replaced “Right Now”?','Most energy uses of oil and gas can technically be replaced without new scientific breakthroughs.',NULL,NULL);
INSERT INTO content_sections VALUES(588,15,587,'heading',3,3,5,'2.1. Transport drogowy + generacja prądu i ciepła (~267 EJ, 78%)','transport-drogi-prad-cieplo','EV, OZE, atom i pompy ciepła mogą zastąpić dużą część zużycia, ale wymagają dekad infrastruktury.',5,NULL,'2.1 Road Transport + Electricity and Heat Generation (~267 EJ, 78%)','EVs, renewables, nuclear power and heat pumps can replace a large share of consumption, but require decades of infrastructure build-out.',NULL,NULL);
INSERT INTO content_sections VALUES(589,15,587,'heading',3,3,6,'2.2. Surowiec do procesów przemysłowych (~35 EJ, 10%)','surowiec-procesy-przemyslowe','Petrochemia potrzebuje węglowodorów jako materiału, nie tylko energii; substytucja jest znacznie trudniejsza.',6,NULL,'2.2 Industrial Process Feedstock (~35 EJ, 10%)','Petrochemicals need hydrocarbons as material, not just energy; substitution is substantially harder.',NULL,NULL);
INSERT INTO content_sections VALUES(590,15,587,'heading',3,3,7,'2.3. Nawozy — szczególny przypadek feedstocku','nawozy-feedstock','Nawozy wymagają wodoru i gazu, lecz produkcja może być geograficznie przenoszona i odbudowywana stosunkowo szybko.',7,NULL,'2.3 Fertilisers — a Special Feedstock Case','Fertilisers require hydrogen and gas, but production can be relocated geographically and rebuilt relatively quickly.',NULL,NULL);
INSERT INTO content_sections VALUES(591,15,584,'heading',2,2,8,'3. Scenariusz Ormuz: inflacja ≠ głód','scenariusz-ormuz','Zamknięcie Ormuz jest przede wszystkim szokiem cenowym i logistycznym, nie automatycznym scenariuszem globalnego głodu.',8,NULL,'3. The Hormuz Scenario: Inflation ≠ Famine','Closure of Hormuz is primarily a price and logistics shock, not an automatic scenario of global famine.',NULL,NULL);
INSERT INTO content_sections VALUES(592,15,591,'heading',3,3,9,'3.1. Kluczowa dystynkcja: szok cenowy vs. fizyczny brak','szok-cenowy-vs-fizyczny-brak','Rynek redukuje mniej użyteczny popyt, zanim zabraknie paliwa dla transportu żywności i funkcji krytycznych.',9,NULL,'3.1 Key Distinction: Price Shock vs Physical Shortage','The market cuts less useful demand before fuel disappears from food transport and other critical functions.',NULL,NULL);
INSERT INTO content_sections VALUES(593,15,591,'heading',3,3,10,'3.2. Skala szoku: porównanie z Lehman Brothers / dot-com','skala-szoku-lehman-dot-com','Szok Ormuz może przypominać wielką recesję skalą, lecz uderza w podaż i tworzy stagflację zamiast kryzysu finansowego.',10,NULL,'3.2 Scale of the Shock: Comparison with Lehman Brothers / Dot-Com','A Hormuz shock could resemble a major recession in scale, but hits supply and creates stagflation rather than a financial crisis.',NULL,NULL);
INSERT INTO content_sections VALUES(594,15,591,'heading',3,3,11,'3.3. Paradoks szybkiego szoku','paradoks-szybkiego-szoku','Jednoznaczna zła wiadomość może przyspieszyć adaptację i kosztować mniej niż długotrwała niepewność.',11,NULL,'3.3 The Paradox of a Rapid Shock','A clear bad signal can accelerate adaptation and cost less than prolonged uncertainty.',NULL,NULL);
INSERT INTO content_sections VALUES(595,15,584,'heading',2,2,12,'4. Geopolityka energii: substytucja jako zmiana topologii władzy','geopolityka-energii-topologia-wladzy','Substytucja paliw kopalnych zmienia nie tylko miks energetyczny, lecz układ politycznej i ekonomicznej zależności.',12,NULL,'4. Energy Geopolitics: Substitution as a Change in the Topology of Power','Substituting fossil fuels changes not only the energy mix but also the structure of political and economic dependence.',NULL,NULL);
INSERT INTO content_sections VALUES(596,15,595,'heading',3,3,13,'4.1. Gdyby a.1 + b były zelektryfikowane','elektryfikacja-transportu-i-generacji','Masowa elektryfikacja odbiera petrostates część dźwigni, redukując znaczenie chokepointów i karteli paliwowych.',13,NULL,'4.1 If a.1 + b Were Electrified','Mass electrification removes part of petrostates'' leverage by reducing the importance of chokepoints and fuel cartels.',NULL,NULL);
INSERT INTO content_sections VALUES(597,15,595,'heading',3,3,14,'4.2. Stary paradygmat vs. nowy: centralizacja vs. decentralizacja','centralizacja-vs-decentralizacja','Ropa wymaga scentralizowanych łańcuchów; solar i baterie przesuwają produkcję energii ku rozproszonym sieciom.',14,NULL,'4.2 Old Paradigm vs New: Centralisation vs Decentralisation','Oil requires centralised chains; solar and batteries shift energy production toward distributed networks.',NULL,NULL);
INSERT INTO content_sections VALUES(598,15,595,'heading',3,3,15,'4.3. Panel to capital good, baryłka to consumable','panel-capital-good-barylka-consumable','Panel raz sprzedany zmniejsza przyszły popyt na paliwo, podczas gdy baryłka wymaga ciągłego ponownego zakupu.',15,NULL,'4.3 A Solar Panel Is a Capital Good; a Barrel Is a Consumable','Once sold, a panel reduces future fuel demand, whereas a barrel requires continuous repurchase.',NULL,NULL);
INSERT INTO content_sections VALUES(599,15,584,'heading',2,2,16,'5. Monopole surowcowe: trwałość saudyjska vs. chińska','monopole-surowcowe','Porównanie trwałości monopolu opartego na geologii ropy z chińską dominacją w przetwarzaniu surowców krytycznych.',16,NULL,'5. Resource Monopolies: Saudi Durability vs Chinese Durability','A comparison of an oil monopoly rooted in geology with Chinese dominance in critical-mineral processing.',NULL,NULL);
INSERT INTO content_sections VALUES(600,15,599,'heading',3,3,17,'5.1. Saudyjska dźwignia cenowa: autoimmunologia','saudyjska-dzwignia-autoimmunologia','Obniżanie cen ropy niszczy konkurentów, ale jednocześnie przyspiesza inwestycje w trwałe substytuty.',17,NULL,'5.1 Saudi Pricing Leverage: Autoimmunity','Cutting oil prices hurts competitors, but simultaneously accelerates investment in durable substitutes.',NULL,NULL);
INSERT INTO content_sections VALUES(601,15,599,'heading',3,3,18,'5.2. Chiński monopol na surowce krytyczne: aktywny i czasowy','chinski-monopol-surowcow-krytycznych','Chińska przewaga wynika głównie z processingu, dotacji i skali przemysłowej, nie wyjątkowej geologii.',18,NULL,'5.2 China''s Critical-Mineral Monopoly: Active and Temporary','China''s advantage stems mainly from processing, subsidies and industrial scale, not unique geology.',NULL,NULL);
INSERT INTO content_sections VALUES(602,15,599,'heading',3,3,19,'5.3. Dlaczego chiński „OPEC na surowce krytyczne" ma wbudowany zegar samozniszczenia','chinski-opec-zegar-samozniszczenia','Metale są stockiem możliwym do odzysku; rosnący recykling stopniowo ogranicza siłę monopolu na nowe wydobycie.',19,NULL,'5.3 Why a Chinese “OPEC for Critical Minerals” Has a Built-In Self-Destruct Clock','Metals are recoverable stock; growing recycling gradually weakens monopoly power over new extraction.',NULL,NULL);
INSERT INTO content_sections VALUES(603,15,584,'heading',2,2,20,'6. Wymiar etyczny: kryzysy, moralność i transformacja','wymiar-etyczny-transformacji','Transformacja energetyczna ma także wymiar moralny: zmniejsza polityczną cenę zależności od autorytarnych dostawców.',20,NULL,'6. The Ethical Dimension: Crises, Morality and Transformation','The energy transition also has a moral dimension: it reduces the political price of dependence on authoritarian suppliers.',NULL,NULL);
INSERT INTO content_sections VALUES(604,15,603,'heading',3,3,21,'6.1. Tani surowiec od dyktatorów jako moralny hazard','tani-surowiec-moralny-hazard','Tania energia od dyktatur zachęca demokracje do racjonalizowania zależności i rozdzielania wartości od polityki.',21,NULL,'6.1 Cheap Resources from Dictators as Moral Hazard','Cheap energy from dictatorships encourages democracies to rationalise dependence and separate values from policy.',NULL,NULL);
INSERT INTO content_sections VALUES(605,15,603,'heading',3,3,22,'6.2. Kryzysy nie zawsze moralizują — warunek: substytut','kryzys-warunek-substytut','Kryzys prowadzi do odłączenia od dostawcy tylko wtedy, gdy istnieje realna technologiczna alternatywa.',22,NULL,'6.2 Crises Do Not Always Moralise — Condition: a Substitute','A crisis leads to decoupling from a supplier only when a real technological alternative exists.',NULL,NULL);
INSERT INTO content_sections VALUES(606,15,603,'heading',3,3,23,'6.3. Kto przyspieszył dekarbonizację?','kto-przyspieszyl-dekarbonizacje','Putin stworzył bezpieczeństwowy push, a Chiny cenowy pull dla szybszej dekarbonizacji.',23,NULL,'6.3 Who Accelerated Decarbonisation?','Putin created the security push and China the price pull behind faster decarbonisation.',NULL,NULL);
INSERT INTO content_sections VALUES(607,15,603,'heading',3,3,24,'6.4. Energia jako narzędzie sprawiedliwości','energia-sprawiedliwosc','Tania energia rozproszona zmniejsza podatność słabszych odbiorców na globalne szoki i pośredników.',24,NULL,'6.4 Energy as an Instrument of Justice','Cheap distributed energy reduces weaker consumers'' exposure to global shocks and intermediaries.',NULL,NULL);
INSERT INTO content_sections VALUES(608,15,584,'heading',2,2,25,'7. Podsumowanie tez','podsumowanie-tez','Zbiorczy werdykt: większość energetycznego popytu jest substytucyjna, feedstock zostaje, a monopole tracą trwałość.',25,NULL,'7. Summary of Theses','Overall verdict: most energy demand is substitutable, feedstock remains, and monopolies lose durability.',NULL,NULL);
INSERT INTO content_sections VALUES(609,16,NULL,'heading',1,1,1,'Monopole, moralność i transformacja','monopole-moralnosc-transformacja','Źródłowa rewizja tez o monopolach energetycznych, zależności politycznej i moralnym wymiarze transformacji. Weryfikuje i koryguje wcześniejszą analizę.',1,NULL,'Monopolies, Morality and Transformation','A source-based revision of the theses on energy monopolies, political dependence and the moral dimension of transition. It verifies and corrects the earlier analysis.',NULL,NULL);
INSERT INTO content_sections VALUES(610,16,609,'heading',2,2,2,'1. Saudyjska dźwignia cenowa: anatomia samolikwidacji','saudyjska-dzwignia-samolikwidacja','Wojny cenowe Arabii Saudyjskiej osłabiały konkurentów chwilowo, lecz trwale zwiększały odporność shale i kosztowały OPEC przychody.',2,NULL,'1. Saudi Pricing Leverage: Anatomy of Self-Liquidation','Saudi price wars weakened competitors temporarily, but permanently increased shale resilience and cost OPEC revenue.',NULL,NULL);
INSERT INTO content_sections VALUES(611,16,609,'heading',2,2,3,'2. Chiński monopol na REE i lit: strategia, mechanizm, erozja','chinski-monopol-ree-lit','Chińska dominacja w REE i licie wynika z przemysłowego ekosystemu processingu, a jej erozja jest realna, lecz wolniejsza niż zakładano.',3,NULL,'2. China''s Monopoly on REEs and Lithium: Strategy, Mechanism, Erosion','Chinese dominance in REEs and lithium stems from the industrial processing ecosystem; its erosion is real, but slower than previously assumed.',NULL,NULL);
INSERT INTO content_sections VALUES(612,16,611,'heading',3,3,4,'2.1. Strategia: „nie geologia, lecz processing"','strategia-processing','Czterdziestoletnia strategia łączy tani kapitał, tolerancję środowiskową, technologię separacji, klastry downstream i kontrolę eksportu.',4,NULL,'2.1 Strategy: “Not Geology, but Processing”','A forty-year strategy combining cheap capital, environmental tolerance, separation technology, downstream clusters and export controls.',NULL,NULL);
INSERT INTO content_sections VALUES(613,16,611,'heading',3,3,5,'2.2. Erozja: czy zegar samozniszczenia naprawdę tyka?','erozja-zegar-samozniszczenia','Recykling i dywersyfikacja działają przeciw monopolowi długoterminowo, ale ciężkie REE dają Chinom kilkuletnią ostrą dźwignię.',5,NULL,'2.2 Erosion: Is the Self-Destruct Clock Really Ticking?','Recycling and diversification work against monopoly in the long run, but heavy REEs give China several years of acute leverage.',NULL,NULL);
INSERT INTO content_sections VALUES(614,16,609,'heading',2,2,6,'3. Wandel durch Handel: anatomia moralnego hazardu energetycznego','wandel-durch-handel-moralny-hazard','Zależność energetyczna od Rosji była wspierana nie tylko interesem, lecz szczerą doktryną polityczną racjonalizującą ryzyko.',6,NULL,'3. Wandel durch Handel: Anatomy of Energy Moral Hazard','Energy dependence on Russia was supported not only by interest but also by a sincere political doctrine that rationalised the risk.',NULL,NULL);
INSERT INTO content_sections VALUES(615,16,614,'heading',3,3,7,'3.1. Niemiecka zależność od rosyjskiego gazu jako case study','niemiecka-zaleznosc-rosyjski-gaz','Niemiecka polityka gazowa utrwaliła zależność infrastrukturalnie mimo rosnących sygnałów ryzyka politycznego.',7,NULL,'3.1 German Dependence on Russian Gas as a Case Study','German gas policy locked in infrastructure dependence despite growing signals of political risk.',NULL,NULL);
INSERT INTO content_sections VALUES(616,16,614,'heading',3,3,8,'3.2. „Nowe kraje członkowskie" vs. „stare"','nowe-vs-stare-kraje-czlonkowskie','Europa Środkowa i Bałtycy wcześniej traktowali rosyjski gaz jako zagrożenie; część Zachodu jako niskie ryzyko handlowe.',8,NULL,'3.2 “New Member States” vs “Old”','Central Europe and the Baltic states treated Russian gas as a threat earlier; part of Western Europe treated it as low-risk trade.',NULL,NULL);
INSERT INTO content_sections VALUES(617,16,609,'heading',2,2,9,'4. Kryzysy a moralność: kiedy szok prowadzi do solidarności, a kiedy do sauve qui peut?','kryzysy-moralnosc-solidarnosc-sauve-qui-peut','Kryzys może prowadzić do solidarności albo oportunizmu; decydują nie tylko substytuty, lecz także zdolność koordynacji.',9,NULL,'4. Crises and Morality: When Does Shock Produce Solidarity, and When Sauve Qui Peut?','A crisis can produce solidarity or opportunism; outcomes depend not only on substitutes but also on coordination capacity.',NULL,NULL);
INSERT INTO content_sections VALUES(618,16,617,'heading',3,3,10,'4.1. 1973 vs. 2022: dwa tryby reakcji','1973-vs-2022','1973 wzmocnił transakcyjność, 2022 przyspieszył europejski decoupling dzięki technologii i istniejącym instytucjom wspólnego działania.',10,NULL,'4.1 1973 vs 2022: Two Modes of Response','1973 strengthened transactionalism; 2022 accelerated European decoupling thanks to technology and existing institutions of collective action.',NULL,NULL);
INSERT INTO content_sections VALUES(619,16,617,'heading',3,3,11,'4.2. Asymetria kosztów: kto płaci za transformację?','asymetria-kosztow-transformacji','Koszty szoków najmocniej obciążają państwa bez rezerw, własnej podaży i kapitału; energia rozproszona zmniejsza tę zależność.',11,NULL,'4.2 Cost Asymmetry: Who Pays for the Transition?','The costs of shocks fall hardest on states without reserves, domestic supply or capital; distributed energy reduces this dependence.',NULL,NULL);
INSERT INTO content_sections VALUES(620,16,609,'heading',2,2,12,'5. Podsumowanie korekt','podsumowanie-korekt','Dwie główne korekty: chiński monopol eroduje wolniej, a solidarność wymaga substytutu technologicznego oraz instytucji koordynacyjnych.',12,NULL,'5. Summary of Corrections','Two main corrections: China''s monopoly erodes more slowly, and solidarity requires both a technological substitute and coordination institutions.',NULL,NULL);
INSERT INTO content_sections VALUES(621,17,NULL,'heading',1,1,1,'63 cechy — rdzeń czy maskowanie','63-cechy-rdzen-czy-maskowanie','Klasyfikacja wszystkich sześćdziesięciu trzech cech z opracowania „AuDHD u dorosłych — cechy i wzorce funkcjonowania" (v4.5) według jednego pytania: czy dana cecha jest bezpośrednim wynikiem samej neurobiologii AuDHD, czy produktem lat maskowania — kamuflażu…',1,replace('<p>Klasyfikacja wszystkich sześćdziesięciu trzech cech z opracowania „AuDHD u dorosłych — cechy i wzorce funkcjonowania" (v4.5) według jednego pytania: czy dana cecha jest bezpośrednim wynikiem samej neurobiologii AuDHD, czy produktem lat maskowania — kamuflażu, dostosowywania się, zawstydzania i życia bez ramki.</p>\n\n<p>Trzy oznaczenia. <strong>[R]</strong> — rdzeń: cecha byłaby obecna nawet u osoby wychowanej w świecie idealnie dopasowanym i akceptującym; to sama konstrukcja układu nerwowego. <strong>[M]</strong> — maskowanie: cecha jest raną albo nawykiem nabytym przez lata kamuflażu; u osoby nigdy niezmuszonej do maskowania nie powstałaby lub byłaby śladowa. <strong>[R+M]</strong> — mieszane: rdzeń istnieje, ale nasilenie, kształt albo ból tej cechy są w znacznej mierze dziełem lat maskowania; przy przewadze jednej strony jest to dopisane.</p>\n\n<p>Jedno wyjaśnienie: [M] nie znaczy „to nie jest AuDHD". Maskowanie samo jest odpowiedzią AuDHD-owego układu na niedopasowane środowisko — więc [M] czyta się jako „AuDHD pomnożone przez lata środowiska", nie jako „coś obok". Różnica jest praktyczna i wraca w podsumowaniu: rdzenia się nie zdejmie, koszty maskowania bywają częściowo odwracalne.</p>','\n',char(10)),'63 features — core or camouflaging','Classification of all sixty-three features from “AuDHD in adults — features and patterns of functioning” (v4.5) according to one question: is a given feature a direct result of AuDHD neurobiology itself, or a product of years of masking and camouflaging?',NULL,NULL);
INSERT INTO content_sections VALUES(622,17,621,'heading',2,2,2,'Lista','lista','0. Styl przetwarzania informacji [R] — definicyjna architektura: asocjacyjne, oddolne, monotropiczne przetwarzanie to sam fundament, na którym stoi reszta listy.',2,replace('<p><strong>0. Styl przetwarzania informacji [R]</strong> — definicyjna architektura: asocjacyjne, oddolne, monotropiczne przetwarzanie to sam fundament, na którym stoi reszta listy.</p>\n\n<p><strong>1. Trudności z funkcjami wykonawczymi [R]</strong> — planowanie, start, przełączanie: to jest okablowanie, nie nawyk; widoczne od dzieciństwa, niezależnie od środowiska.</p>\n\n<p><strong>2. Hiperfokus chaotyczny [R]</strong> — monotropiczny tunel z ADHD-owym zapłonem; żadne maskowanie tego nie wytwarza ani nie usuwa.</p>\n\n<p><strong>3. Konflikt rutyna–nowość [R]</strong> — zderzenie dwóch rdzeni w jednej głowie: autystyczna potrzeba stałości i ADHD-owy głód zmiany. Czysta konstrukcja.</p>\n\n<p><strong>4. Dysregulacja emocjonalna [R+M]</strong> — szybkość i siła emocji to neurologia; ale lata tłumienia „niewłaściwych" reakcji uczą eksplozji zamiast modulacji — tłumione nie znika, tylko kumuluje.</p>\n\n<p><strong>5. Przeciążenie sensoryczne [R]</strong> — brak filtra bodźców to sprzęt. Maskowanie dokłada koszt ukrywania przeciążenia, ale samo przeciążenie jest pierwotne.</p>\n\n<p><strong>6. Trudności społeczne z impulsywnością [R]</strong> — ręczne dekodowanie niejawnych reguł plus impulsywne wejścia: obie składowe rdzeniowe.</p>\n\n<p><strong>7. Trudności z zasypianiem [R]</strong> — mózg, który rozkręca się w ciszy, i przesunięty rytm dobowy to fizjologia ADHD, nie skutek dnia w masce.</p>\n\n<p><strong>8. Wieczorne ożywienie [R+M]</strong> — częściowo rytm dobowy (rdzeń), ale treść mówi wprost: jasność przychodzi „po całym dniu maskowania" — wieczór to godzina zdjęcia maski, więc część tego ożywienia to po prostu odzyskana energia z niemaskowania.</p>\n\n<p><strong>9. Cykliczne wypalenia [R+M, przewaga M]</strong> — podatność na przeciążenie jest rdzeniowa, ale rytm „zawalenia się co kilka tygodni" to w literaturze klasyczny koszt długu maskowania: system pada, gdy rachunek za kamuflaż przekracza zasoby.</p>\n\n<p><strong>10. Wrażliwość na odrzucenie (RSD) [R+M]</strong> — nadwrażliwy alarm to neurologia ADHD; ale alarm skalibrowany przez dekady prawdziwych odrzuceń strzela częściej i celniej w ból. Sprzęt rdzeniowy, amunicja z biografii.</p>\n\n<p><strong>11. Zmienne zapotrzebowanie na samotność [R+M]</strong> — regulacja zasobów jest rdzeniowa; ale to maskowanie robi z kontaktu pozycję kosztową, więc im więcej maski w relacjach, tym więcej samotności trzeba na odrobienie.</p>\n\n<p><strong>12. Intensywna empatia wyglądająca jak brak [R]</strong> — empatia jest, ekspresja atypowa; „wygląda jak brak" to artefakt cudzego odbioru, nie produkt maskowania. Rdzeń plus podwójna empatia.</p>\n\n<p><strong>13. Szukanie i unikanie bodźców naraz [R]</strong> — dwa układy regulacji w jednym ciele; konstrukcja, nie strategia.</p>\n\n<p><strong>14. Chroniczna niepunktualność LUB obsesyjna punktualność [R+M]</strong> — ślepota czasowa to rdzeń; ale obsesyjna punktualność to protetyka zbudowana z lęku przed oceną — kompensacja wytrenowana latami spóźnień i ich kar.</p>\n\n<p><strong>15. Cykliczne zainteresowania [R]</strong> — autystyczna głębia z ADHD-ową rotacją; czysty wzorzec konstrukcyjny.</p>\n\n<p><strong>16. Nietypowe reakcje na leki [R]</strong> — farmakologia układu nerwowego; maskowanie nie ma tu nic do rzeczy.</p>\n\n<p><strong>17. Wszystko albo nic w nawykach [R]</strong> — brak trybu „w miarę" to monotropizm w działaniu.</p>\n\n<p><strong>18. Paradoks porządku i chaosu [R]</strong> — porządek idzie tam, gdzie tunel; reszta świata jest poza zasięgiem reflektora. Konstrukcja uwagi.</p>\n\n<p><strong>19. Prokrastynacja przez perfekcjonizm [R+M, przewaga M]</strong> — mechanika startu jest rdzeniowa, ale sam perfekcjonizm jako warunek startu to zwykle pancerz: „jeśli zrobię doskonale, nikt nie będzie miał się do czego przyczepić". Pancerz kuje się latami krytyki.</p>\n\n<p><strong>20. Stimming [R]</strong> — wbudowana regulacja układu nerwowego. To tłumienie stimmingu jest maskowaniem; sama cecha jest rdzenna jak oddech.</p>\n\n<p><strong>21. Słaba interocepcja [R]</strong> — czujniki wewnętrzne o niskiej rozdzielczości; sprzęt.</p>\n\n<p><strong>22. Aleksytymia [R+M, przewaga R]</strong> — trudność nazywania emocji jest neurorozwojowa; ale lata słyszenia „nie przesadzaj" uczą dodatkowo nie sprawdzać, co się czuje — na rdzeniowy defekt odczytu nakłada się wytrenowane odwracanie wzroku.</p>\n\n<p><strong>23. Maskowanie na zmianę z impulsywnością [M]</strong> — to jest samo maskowanie, opisane jako cecha: kabina z pęknięciami, przez które przebija rdzeń. Impulsywne przebicia są rdzeniowe; cykl maska–pęknięcie jest w całości nabyty.</p>\n\n<p><strong>24. Wyczerpanie po decyzjach [R]</strong> — dwa systemy liczące każdą opcję naraz; koszt konstrukcyjny. Maskowanie dokłada tylko drugą warstwę tam, gdzie decyzja jest społeczna.</p>\n\n<p><strong>25. Stosunek do jedzenia [R]</strong> — interocepcja plus sensoryka plus funkcje wykonawcze; wszystkie trzy składowe rdzeniowe.</p>\n\n<p><strong>26. Autystyczna inercja [R]</strong> — pociąg towarowy zmiany stanu; fizyka układu, nie nawyk.</p>\n\n<p><strong>27. Zmienne progi sensoryczne [R]</strong> — progi zależne od stanu zasobów; konstrukcja.</p>\n\n<p><strong>28. Geniusz w kryzysie, paraliż w spokoju [R]</strong> — układ dopaminowy uruchamiany pilnością; rdzeń ADHD w czystej postaci.</p>\n\n<p><strong>29. Unikanie wymagań [R+M, przewaga R]</strong> — reakcja autonomii na nacisk wygląda na wbudowaną; ale historia lat przymusu i utraty sprawczości podnosi czułość tego zaworu — im więcej było „musisz", tym mniejsze „musisz" wystarcza.</p>\n\n<p><strong>30. Koordynacja i propriocepcja [R]</strong> — czujniki położenia ciała; czysty sprzęt, żadna maska tego nie robi.</p>\n\n<p><strong>31. Kompensacja jednego stanu drugim [R]</strong> — wewnętrzna inżynieria dwóch rdzeni; konstrukcyjna, często adaptacyjna.</p>\n\n<p><strong>32. Pamięć encyklopedyczna obok „złotej rybki" [R]</strong> — dwa systemy pamięci sprzężone z tunelem uwagi; architektura.</p>\n\n<p><strong>33. Zapominanie, że się wie [R]</strong> — biblioteka bez katalogu na żądanie; mechanika dostępu, nie skutek biografii.</p>\n\n<p><strong>34. Myślenie w systemach, trudność z wyjaśnieniem [R]</strong> — asocjacyjna, nieliniowa logika; rdzeń stylu poznawczego.</p>\n\n<p><strong>35. Przetwarzanie „w tle" [R]</strong> — kompilacja poza świadomością i powrót z gotowym wynikiem; konstrukcja.</p>\n\n<p><strong>36. Kameleonizm — dyfuzja tożsamości [M]</strong> — sam tekst mówi: głębsze niż maskowanie, zatracenie się w adaptacji. To jest czysty produkt lat kamuflażu: osobowość rozpuszczona w cudzych oczekiwaniach. U niemaskującego nie powstaje.</p>\n\n<p><strong>37. Moralna skrupulatność [R+M]</strong> — absolutne traktowanie reguł to autystyczna sztywność (rdzeń); ale niemożliwe standardy i pętla winy „jestem złą osobą" są wytrenowane przez RSD i lata społecznych kar. Trybunał ma rdzeniowy budynek i nabyty regulamin.</p>\n\n<p><strong>38. Za dużo albo za mało słów [R]</strong> — infodumping kontra wyczerpany kanał; dwa tryby konstrukcyjne bez środka.</p>\n\n<p><strong>39. Paraliżująca wrażliwość na niesprawiedliwość [R]</strong> — sztywne poczucie reguł plus dysregulacja; rdzeń. Świat dostarcza materiału, ale czujnik jest wbudowany.</p>\n\n<p><strong>40. Kochanie przez dzielenie się informacjami [R]</strong> — infodumping jako język miłości; piękny, czysto rdzeniowy dialekt.</p>\n\n<p><strong>41. Głód bliskości, który przeraża [R+M, przewaga M]</strong> — potrzeba bliskości jest ludzka i rdzeniowo intensywna; ale przerażenie przy niej to blizna: wyuczone oczekiwanie, że bliskość kończy się odrzuceniem albo utratą siebie w dopasowywaniu.</p>\n\n<p><strong>42. Werbalne potwierdzanie zasad relacji [R+M]</strong> — potrzeba jawnych reguł zamiast kontekstu to rdzeń dekodowania; ale częstotliwość pytania „czy jesteś na mnie zły" jest funkcją lat, w których niewidzialne reguły kosztowały relacje.</p>\n\n<p><strong>43. Stres somatyczny z opóźnieniem [R+M]</strong> — słaba interocepcja opóźnia odczyt (rdzeń); ale nawyk „dowieźć, rozpaść się później" to maska sprawności trzymana do końca zadania — ciało dostaje głos dopiero po zejściu ze sceny.</p>\n\n<p><strong>44. Ból „niewłaściwy" [R]</strong> — atypowe przetwarzanie nocycepcji w obu kierunkach; sprzęt.</p>\n\n<p><strong>45. Zmęczenie, które nie ma dna [R+M]</strong> — mózg pracujący ciężej każdą minutę to rdzeń; ale u dorosłych maskujących ogromna część tego zmęczenia to bieżący rachunek za kamuflaż — dwa etaty naraz: życie i udawanie, że życie jest łatwe.</p>\n\n<p><strong>46. Podwójne przetwarzanie rzeczywistości [R+M, przewaga M]</strong> — meta-świadomość bywa rdzeniowa, ale drugi kanał w wersji „jak wypadam, co widzą, co powinienem" to monitoring zainstalowany przez maskowanie — kamera przemysłowa skierowana na siebie, której nikt konstrukcyjnie nie montował.</p>\n\n<p><strong>47. „Za dużo" i „za mało" jednocześnie [M]</strong> — to nie jest cecha układu nerwowego, to zinternalizowany werdykt otoczenia: dwie cudze oceny sklejone w tożsamość. Rana społeczna w czystej postaci.</p>\n\n<p><strong>48. Wewnętrzny tłumacz non stop [R+M]</strong> — tłumaczenie ręczne tego, co u innych automatyczne, jest rdzeniowe; ale tryb „non stop", bez wyłącznika, w każdej interakcji — to hiperczujność wytrenowana maskowaniem, bo maska wymaga ciągłego nasłuchu, czy jeszcze trzyma.</p>\n\n<p><strong>49. Nostalgia jako regulacja [R]</strong> — znane bodźce jako przystań sensoryczna i przewidywalność; rdzeniowa strategia regulacyjna.</p>\n\n<p><strong>50. Monolog wewnętrzny bez wyłącznika [R]</strong> — gęstość strumienia myśli; konstrukcja.</p>\n\n<p><strong>51. Czas działa inaczej [R]</strong> — elastyczna substancja zamiast linii; rdzeń percepcji czasu.</p>\n\n<p><strong>52. Kryzys tożsamości przy zmianie zainteresowań [R]</strong> — tożsamość budowana na zainteresowaniach to rdzeń autystyczny; kruchość tej konstrukcji jest wpisana w jej materiał, nie w biografię. Maskowanie może pogłębiać (gdy zainteresowanie było jedynym niemaskowanym kawałkiem), ale mechanizm jest pierwotny.</p>\n\n<p><strong>53. Tęsknota za niepoznanym jeszcze sobą [M]</strong> — z definicji: „pod warstwami maskowania jest prawdziwe ja". Ta tęsknota istnieje tylko tam, gdzie było zakrywanie. To najczystszy w całej liście artefakt maski — i jedna z najboleśniejszych pozycji rachunku.</p>\n\n<p><strong>54. Zbieranie informacji na zapas [R]</strong> — głód poznawczy plus asekuracja pamięci; rdzeń z lekką domieszką lęku, ale mechanizm pierwotny.</p>\n\n<p><strong>55. Specyficzny humor [R]</strong> — gra słów, dosłowność, absurd; produkt stylu przetwarzania, nie biografii.</p>\n\n<p><strong>56. Przepraszanie za istnienie [M]</strong> — kompulsywne przeprosiny za zajmowanie miejsca to wyuczona pozycja obronna: internalizacja tysięcy sygnałów, że się przeszkadza. Żaden układ nerwowy nie rodzi się z tym.</p>\n\n<p><strong>57. Zadania „nie po kolei" [R]</strong> — kolejność według faktury i dostępności, nie konwencji; rdzeń wykonawczo-sensoryczny.</p>\n\n<p><strong>58. Poczucie „udawania dorosłego" [R+M]</strong> — brak autopilota jest rdzeniowy i realny; ale samo poczucie „udawania" powstaje z porównania do innych i z maski sprawności, która każe pokazywać efekt bez ceny. Mechanika rdzeniowa, rama odczucia — społeczna.</p>\n\n<p><strong>59. Underachievement, który boli [R+M]</strong> — rozjazd między potencjałem a formatem świata jest konstrukcyjny; ale ból tego rozjazdu jest w dużej mierze echem „gdybyś się postarał" powtórzonego przez trzydzieści lat. Rachunek rdzeniowy, odsetki społeczne.</p>\n\n<p><strong>60. Potrzeba „dlaczego" przed zrobieniem [R]</strong> — przetwarzanie od dołu do góry wymaga kontekstu; czysta architektura poznawcza.</p>\n\n<p><strong>61. Poczucie bycia z innej planety [R+M, przewaga R]</strong> — jakościowa inność przetwarzania jest realna i pierwotna, obecna od najwcześniejszych wspomnień; lata nierozumienia dokładają do niej tylko warstwę osamotnienia. Planeta jest prawdziwa; to poczucie wygnania jest dopisane przez środowisko.</p>\n\n<p><strong>62. Potrzeba bycia zrozumianym, nie naprawionym [M]</strong> — sama potrzeba zrozumienia jest uniwersalnie ludzka; jako wyróżniona, paląca cecha istnieje dlatego, że przez lata odpowiedzią na każdą trudność była naprawa. To nie cecha układu — to postulat wystawiony biografii.</p>','\n',char(10)),'The list','0. Information-processing style [R] — the defining architecture: associative, bottom-up, monotropic processing is the very foundation on which the rest of the list stands.',NULL,NULL);
INSERT INTO content_sections VALUES(623,17,621,'heading',2,2,3,'Podsumowanie rachunku','podsumowanie-rachunku','Rdzeń [R]: trzydzieści osiem cech. Mieszane [R+M]: dziewiętnaście. Maskowanie [M]: sześć — pozycje 23, 36, 47, 53, 56, 62.',3,replace('<p>Rdzeń [R]: trzydzieści osiem cech. Mieszane [R+M]: dziewiętnaście. Maskowanie [M]: sześć — pozycje 23, 36, 47, 53, 56, 62.</p>\n\n<p>Trzy rzeczy z tego rachunku warte osobnego zdania. Pierwsza: większość listy to konstrukcja, nie blizna — pięćdziesiąt siedem z sześćdziesięciu trzech cech ma rdzeń, którego żadne demaskowanie nie usunie, bo nie jest uszkodzeniem, tylko budową. Druga: sześć cech czysto maskowaniowych to jednocześnie sześć najboleśniejszych pozycji listy — dyfuzja tożsamości, „za dużo i za mało", tęsknota za sobą, przepraszanie za istnienie, cykl maski i potrzeba niebycia naprawianym. To nie przypadek: rdzeń przeważnie kosztuje energię, maska kosztuje tożsamość. Trzecia, praktyczna: kolumna [M] i maskowaniowa połowa kolumny [R+M] to jedyne miejsca tej listy, gdzie coś może realnie zelżeć — nie przez naprawianie siebie, tylko przez zdejmowanie tego, co nigdy nie było częścią konstrukcji. Rdzeń zostaje; rachunek za jego ukrywanie jest jedyną pozycją do negocjacji.</p>\n\n<hr>\n\n<p>Plik: 63-cechy-rdzen-czy-maskowanie-01_01-2026-08-26.html</p>\n<p>Wersja: 01.01 · Data: 2026-08-26 · Godzina: 19:21 (Europe/Warsaw)</p>\n<p>Stworzono z pomocą Claude (Anthropic), wariant: Claude Opus 5. Źródło cech: audhd_opracowanie_v4_5_2026-03-26 (63 pozycje, numeracja 0–62). Klasyfikacja mechanizmów: Claude, 2026-08-26.</p>','\n',char(10)),'Summary count','Core [R]: thirty-eight features. Mixed [R+M]: nineteen. Camouflaging [M]: six — items 23, 36, 47, 53, 56, and 62.',NULL,NULL);
INSERT INTO content_sections VALUES(624,18,NULL,'heading',1,1,1,'Co działa po późnej diagnozie','co-dziala-po-poznej-diagnozie','Menu tego, co wymyślono dla dorosłych po świeżej diagnozie i co zazwyczaj działa. Do wybierania, nie do zaliczenia w całości.',1,'<p>Menu tego, co wymyślono dla dorosłych po świeżej diagnozie i co zazwyczaj działa. Do wybierania, nie do zaliczenia w całości.</p>','What works after a late diagnosis','A menu of approaches developed for adults after a recent diagnosis and that generally work. Something to choose from, not a syllabus to complete in full.',NULL,NULL);
INSERT INTO content_sections VALUES(625,18,624,'heading',2,2,2,'Mapa terenu — pięć rzeczy, które rozstrzygają','mapa-terenu-piec-rzeczy-ktore-rozstrzygaja','Zanim menu — mapa. U ludzi, którzy przeszli późną diagnozę autyzmu, ADHD albo obu naraz, o przebiegu rozstrzyga pięć rzeczy. Po pierwsze: relacje i stan psychiczny wokół diagnozy ważą więcej niż sama diagnoza.',2,'<p>Zanim menu — mapa. U ludzi, którzy przeszli późną diagnozę autyzmu, ADHD albo obu naraz, o przebiegu rozstrzyga pięć rzeczy. Po pierwsze: relacje i stan psychiczny wokół diagnozy ważą więcej niż sama diagnoza. Po drugie: lata bez rozpoznania nie są neutralne — odkładają się w zdrowiu psychicznym i ten dług też trzeba obsłużyć. Po trzecie, oś środkowa: tym, co realnie zmienia życie, jest zrozumienie — możliwość ponownego przeczytania własnej historii, nie papier. Po czwarte, uczciwie: etykieta ma ciężar — bywa stemplem, który trzeba nosić i tłumaczyć, i wolno się z nim obchodzić po swojemu. Po piąte: gotowość — ta sama prawda w złym momencie życia robi co innego niż w dobrym, więc tempo wchodzenia w temat jest twoje.</p>','A map of the terrain — five things that make the difference','Before the menu, the map. For people who receive a late diagnosis of autism, ADHD, or both, five things largely determine how the process unfolds. First: relationships and mental health around the time of diagnosis matter more than the diagnosis itself.',NULL,NULL);
INSERT INTO content_sections VALUES(626,18,624,'heading',2,2,3,'Kurs o sobie','kurs-o-sobie','Kilkanaście spotkań w małej grupie, tydzień po tygodniu jeden temat. Sprawdzone tematy takiego kursu:',3,replace('<p>Kilkanaście spotkań w małej grupie, tydzień po tygodniu jeden temat. Sprawdzone tematy takiego kursu:</p>\n<ul>\n  <li>opowiedzenie własnej historii od nowa — tym razem z kluczem w ręku;</li>\n  <li>co czuję wobec diagnozy i czy etykieta ogranicza, czy wyzwala;</li>\n  <li>komu mówić, jak i po co — ujawnianie w różnych sytuacjach;</li>\n  <li>komunikacja wprost i między wierszami: reguły jawne kontra niepisane, sygnały bez słów;</li>\n  <li>emocje — znajdowanie ich i miarkowanie; twarze; empatia; różnica między umiejętnościami społecznymi a prawdziwym połączeniem;</li>\n  <li>zmysły: stimming, nadwrażliwość i niedowrażliwość, przeciążenia, wrażliwość emocjonalna;</li>\n  <li>co stoi między chęcią a zrobieniem — start, strategie, czas;</li>\n  <li>uwaga i nierówne profile zdolności — czemu jedno idzie genialnie, a drugie wcale.</li>\n</ul>\n<p>Efekt, który ludzie zgłaszają: widzę, co się ze mną dzieje, i umiem znaleźć wyjście — zamiast szarpać się na ślepo. Bywa, że po czymś takim człowiek pierwszy raz od lat mniej maskuje. Działa na żywo i przez internet; przez internet mniej kosztuje energii, więc zostaje jej na treść.</p>','\n',char(10)),'A course about yourself','A dozen or so meetings in a small group, one topic each week. Topics that have been tested in this kind of course include:',NULL,NULL);
INSERT INTO content_sections VALUES(627,18,624,'heading',2,2,4,'Prowadzący z tego samego plemienia','prowadzacy-z-tego-samego-plemienia','Wszystko powyższe działa wyraźnie lepiej, gdy prowadzi osoba, która sama ma diagnozę. Dwa powody: rozumie bez tłumaczenia — i jest żywym dowodem, że z tą diagnozą da się być dorosłym, całym człowiekiem. To nie dodatek, to składnik czynny.',4,'<p>Wszystko powyższe działa wyraźnie lepiej, gdy prowadzi osoba, która sama ma diagnozę. Dwa powody: rozumie bez tłumaczenia — i jest żywym dowodem, że z tą diagnozą da się być dorosłym, całym człowiekiem. To nie dodatek, to składnik czynny.</p>','A facilitator from the same tribe','Everything above works markedly better when it is led by someone who has the diagnosis themselves. Two reasons: they understand without requiring an explanation, and they are living proof that it is possible to have this diagnosis and still be a whole adult person. This is not an add-on; it is an active ingredient.',NULL,NULL);
INSERT INTO content_sections VALUES(628,18,624,'heading',2,2,5,'Ludzie w tej samej łodzi','ludzie-w-tej-samej-lodzi','Regularny kontakt z innymi późno zdiagnozowanymi — grupa, spotkania, choćby czytanie cudzych historii.',5,'<p>Regularny kontakt z innymi późno zdiagnozowanymi — grupa, spotkania, choćby czytanie cudzych historii. Najczęściej powtarzany efekt całej tej literatury: przestaję czuć się sam w swoich doświadczeniach; nie muszę się tłumaczyć z własnego systemu operacyjnego; mniej maskuję, bo nie ma przed kim. Ludzie mówią wprost, że samo dzielenie się bywa ważniejsze niż część wykładowa kursów. U pięćdziesięciolatków dochodzi jeszcze jedno zdanie: nagle pierwsze pięćdziesiąt lat mojego życia nabrało sensu.</p>','People in the same boat','Regular contact with other people who were diagnosed late — a group, meetings, or even simply reading other people''s stories.',NULL,NULL);
INSERT INTO content_sections VALUES(629,18,624,'heading',2,2,6,'Człowiek zamiast listy numerów','czlowiek-zamiast-listy-numerow','Lista adresów i ulotki nie działają — dzwonienie po obcych instytucjach to dokładnie ta rzecz, którą diagnoza właśnie nazwała trudną.',6,'<p>Lista adresów i ulotki nie działają — dzwonienie po obcych instytucjach to dokładnie ta rzecz, którą diagnoza właśnie nazwała trudną. Działa odwrotność: jeden konkretny człowiek, który na początku towarzyszy — pomoże zadzwonić, pójdzie razem pierwszy raz, pomoże załatwić sprawę, a potem stopniowo się wycofuje. Tam, gdzie to zrobiono, ludzie zaczynali wychodzić z domu, załatwiać, pracować — i nazywali to ratunkiem, czasem dosłownie.</p>','A person instead of a list of phone numbers','Lists of addresses and leaflets do not work. Calling unfamiliar institutions is precisely the kind of thing the diagnosis has just identified as difficult.',NULL,NULL);
INSERT INTO content_sections VALUES(630,18,624,'heading',2,2,7,'Pakiet na start','pakiet-na-start','Darmowy materiał do samodzielnego przejścia w swoim tempie: co znaczy ta diagnoza, historie innych, pierwsze kroki.',7,'<p>Darmowy materiał do samodzielnego przejścia w swoim tempie: co znaczy ta diagnoza, historie innych, pierwsze kroki. Dobry na sam początek, zwłaszcza zanim znajdzie się grupę — z jasnym zastrzeżeniem samych użytkowników: to mapa na granicy nowego kraju, nie zamieszkanie w nim.</p>','A starter pack','Free material to work through independently and at your own pace: what the diagnosis means, other people''s stories, and first steps.',NULL,NULL);
INSERT INTO content_sections VALUES(631,18,624,'heading',2,2,8,'Czego się domagać — lista 24 głosów','czego-sie-domagac-lista-24-glosow','Późno zdiagnozowani dorośli uzgodnili między sobą, w czterech rundach, pełną listę tego, co wsparcie po diagnozie ma zawierać.',8,replace('<p>Późno zdiagnozowani dorośli uzgodnili między sobą, w czterech rundach, pełną listę tego, co wsparcie po diagnozie ma zawierać. Ze stu pięćdziesięciu trzech zgłoszonych punktów zgodę co najmniej ośmiu na dziesięciu osób dostały te dwadzieścia cztery, w kolejności ważności:</p>\n<ol>\n  <li>dostęp do wsparcia niezależnie od tego, gdzie mieszkam;</li>\n  <li>specjaliści z aktualną, porządną wiedzą o autyzmie;</li>\n  <li>specjaliści od zdrowia psychicznego, którzy znają autyzm;</li>\n  <li>pomoc w przetrawieniu tego, czym jest późna diagnoza — na równi z: kontakt prowadzony tak, jak ja wolę (dzwonić albo pisać, ale konsekwentnie);</li>\n  <li>indywidualny plan wsparcia skrojony pod moje potrzeby;</li>\n  <li>dostęp do pomocy wtedy, kiedy jej potrzebuję — na równi z: usługi projektowane wspólnie z ludźmi ze spektrum;</li>\n  <li>pomoc z autystycznym zmęczeniem (wyczerpaniem z życia w świecie ustawionym pod innych) — na równi z: plan zawiera moje własne, dopasowane sposoby radzenia sobie;</li>\n  <li>pomoc w dostępie do wsparcia, gdy blokuje mnie lęk przed ludźmi;</li>\n  <li>plan patrzy na całego człowieka, nie na jedną szufladę;</li>\n  <li>wsparcie sam na sam;</li>\n  <li>plan uwzględnia moje pozostałe rozpoznania i dolegliwości;</li>\n  <li>dofinansowanie sprzętu, który realnie pomaga — na przykład słuchawek wygłuszających — na równi z: wsparcie zaczyna się w momencie, który jest dobry dla mnie;</li>\n  <li>wizyty kontrolne, nie jednorazowe pożegnanie;</li>\n  <li>plan bierze pod uwagę przeszłe rany, jeśli są;</li>\n  <li>pomoc w odzyskaniu steru i wiary we własną sprawczość;</li>\n  <li>możliwość wsparcia od razu po diagnozie, jeśli chcę;</li>\n  <li>plan uwzględnia mój wiek — czterdziestolatek to nie dziecko z orzeczeniem;</li>\n  <li>usługi zrobione pod spektrum i włączające, nie przerabiane naprędce;</li>\n  <li>pomoc w zbudowaniu dobrego zdania o sobie-autystycznym;</li>\n  <li>pomoc w dostępie do zwykłej opieki zdrowotnej.</li>\n</ol>\n<p>Dwie rzeczy warte dopisania od strony gabinetów, których na liście nie ma, a które tam, gdzie działają, robią różnicę: powrót do człowieka po dwóch–czterech miesiącach od diagnozy zamiast jednego pożegnalnego spotkania — oraz wsparcie, które samo wychodzi z ofertą, bo proszenie o pomoc jest częścią trudności, nie testem motywacji.</p>','\n',char(10)),'What to ask for — a list of 24 voices','Late-diagnosed adults reached agreement, over four rounds, on a complete list of what post-diagnostic support should include.',NULL,NULL);
INSERT INTO content_sections VALUES(632,18,624,'heading',2,2,9,'Czego się spodziewać po sobie','czego-sie-spodziewac-po-sobie','Trzy rzeczy, o których warto wiedzieć zawczasu, bo wiedza o nich sama w sobie pomaga. Ulga i żałoba przychodzą razem — ulga, że wreszcie wiadomo, i żal po latach przemaskowanych; to nie sprzeczność, to komplet.',9,replace('<p>Trzy rzeczy, o których warto wiedzieć zawczasu, bo wiedza o nich sama w sobie pomaga. Ulga i żałoba przychodzą razem — ulga, że wreszcie wiadomo, i żal po latach przemaskowanych; to nie sprzeczność, to komplet. Moment ma znaczenie — ta sama prawda w złym okresie życia robi co innego niż w dobrym, więc tempo wchodzenia w temat wolno dawkować samemu. I najtrudniejsze zwykle nie jest zrozumieć siebie, tylko wytłumaczyć siebie innym — na to przydają się gotowe słowa, cudze historie i ludzie, którzy przećwiczyli to wcześniej.</p>\n\n<hr style="border:0;border-top:1px solid #6b5d4e;">\n\n<p>Plik: co-dziala-po-poznej-diagnozie-02_01-2026-08-26.html</p>\n<p>Wersja: 02.01 · Data: 2026-08-26 · Godzina: 23:29 (Europe/Warsaw)</p>\n<p>Stworzono z pomocą Claude (Anthropic), wariant: Claude Opus 5. Wyciąg z pięciu prac Appendixu 2 listy CHATGPT_dluga-lista-publikacji-4_03 (Crane 2021, Crowson 2024, Norris 2025, Edwards 2025, French i Cassidy 2026) oraz dziewiętnastu badań objętych przeglądem Norris. Wersja 02.00: dodana mapa terenu, tematy kursu listą i pełna lista 24 uzgodnionych punktów. Wersja 02.01: kolorystyka beż na ciemnym tle.</p>','\n',char(10)),'What to expect from yourself','Three things worth knowing in advance, because knowing them is helpful in itself. Relief and grief can arrive together: relief that there is finally an explanation, and grief for years spent masking. That is not a contradiction; it is the whole picture.',NULL,NULL);
INSERT INTO content_sections VALUES(633,19,NULL,'heading',1,1,1,'Ten equations, metaphysics, and a jury packed with friends','ten-equations-metaphysics-and-a-jury-packed-with-friends','A private selection of equations that do more than calculate the world: they have the nerve to say something about what the world actually is.',1,replace('<p class="lead">A private selection of equations that do more than calculate the world: they have the nerve to say something about what the world actually is. With Maciek''s comments, an oversight body with distinctly demonic credentials, and notes from the zombie reviewer, added at the jury''s explicit request.</p>\n    </header>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · brain-status check</span>\n      <p>“Metaphysics has not left you, even though the zombie reviewer ate a piece of your brain.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">1</span>','\n',char(10)),'Ten equations, metaphysics, and a jury packed with friends','A private selection of equations that do more than calculate the world: they have the nerve to say something about what the world actually is.',NULL,NULL);
INSERT INTO content_sections VALUES(634,19,633,'heading',2,2,2,'Principle of stationary action','principle-of-stationary-action','The actual path of a system is the one for which a small variation of the entire trajectory does not change the action to first order. Not the “shortest” and not always the “smallest”: stationary .',2,replace('<div class="equation">δS = 0</div>\n      <p>The actual path of a system is the one for which a small variation of the entire trajectory does not change the action to first order. Not the “shortest” and not always the “smallest”: <em>stationary</em>. Classical physics pretends to be a local causal machine while underneath it is describing the whole history at once.</p>\n      <p>In the quantum version, the insolence becomes explicit:</p>\n      <div class="equation">K(B,A) = ∫ 𝒟[x] · e<sup>iS[x]/ℏ</sup></div>\n      <p>The particle takes every possible path. Each gets a phase; most histories cancel one another out. Near the classical path, the phases become unusually cooperative and stop getting in one another''s way.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number one</span>\n      <p>The Universe analyzes every possible project variant, lets them annihilate one another, and keeps the one for which a correction has no first-order effect. The first known case in which a full option analysis finished before the steering committee died.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · interim verdict</span>\n      <p>“That bit about the path! Excellent! Metaphysics has not left you.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">2</span>','\n',char(10)),'Principle of stationary action','The actual path of a system is the one for which a small variation of the entire trajectory does not change the action to first order. Not the “shortest” and not always the “smallest”: stationary .',NULL,NULL);
INSERT INTO content_sections VALUES(635,19,633,'heading',2,2,3,'Einstein field equation','einstein-field-equation','On the left, the geometry of spacetime; on the right, matter and energy. The contents of the world do not sit inside a ready-made stage set: the contents deform the stage, and the deformed stage guides the actors.',3,replace('<div class="equation">G<sub>μν</sub> + Λg<sub>μν</sub> = (8πG/c<sup>4</sup>)T<sub>μν</sub></div>\n      <p>On the left, the geometry of spacetime; on the right, matter and energy. The contents of the world do not sit inside a ready-made stage set: the contents deform the stage, and the deformed stage guides the actors. Gravity stops being a force and becomes architecture.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number two</span>\n      <p>Matter changes geometry; geometry steers matter. There is no strategy director, quarterly town hall, or curvature-request form &mdash; and yet the feedback loop works. The cosmos remains scandalously immature as an organization.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">3</span>','\n',char(10)),'Einstein field equation','On the left, the geometry of spacetime; on the right, matter and energy. The contents of the world do not sit inside a ready-made stage set: the contents deform the stage, and the deformed stage guides the actors.',NULL,NULL);
INSERT INTO content_sections VALUES(636,19,633,'heading',2,2,4,'Boltzmann and the second law','boltzmann-and-the-second-law','One line connects microscopic possibilities with macroscopic disorder and explains why scrambled eggs do not spontaneously reassemble into an egg.',4,replace('<div class="equation">S = k<sub>B</sub> ln Ω &nbsp;&nbsp;·&nbsp;&nbsp; ΔS ≥ 0</div>\n      <p>One line connects microscopic possibilities with macroscopic disorder and explains why scrambled eggs do not spontaneously reassemble into an egg. The second law does not forbid local miracles; it merely announces that probability has a crushing numerical advantage.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number three</span>\n      <p>Entropy is the only KPI that always delivers above plan, needs no bonus scheme, and posts even better results after every meeting.</p>\n    </aside>\n\n      <p class="aside">Action and entropy were both assigned the letter S because physics suffers from a shortage of alphabet and an excess of meaning.</p>\n    </section>\n\n    <section class="entry">\n      <span class="number">4</span>','\n',char(10)),'Boltzmann and the second law','One line connects microscopic possibilities with macroscopic disorder and explains why scrambled eggs do not spontaneously reassemble into an egg.',NULL,NULL);
INSERT INTO content_sections VALUES(637,19,633,'heading',2,2,5,'Bell–CHSH and the Tsirelson bound','bellchsh-and-the-tsirelson-bound','This is an experimental detector for metaphysical fraud. It tests whether the world can be a local machine in which particles have their answers printed before measurement.',5,replace('<p>This is an experimental detector for metaphysical fraud. It tests whether the world can be a local machine in which particles have their answers printed before measurement.</p>\n      <div class="equation">S = E(A₀B₀) + E(A₀B₁) + E(A₁B₀) − E(A₁B₁)</div>\n      <p>If Alice and Bob receive only local, prewritten instructions with outcomes ±1, then for every pair:</p>\n      <div class="equation">A₀(B₀ + B₁) + A₁(B₀ − B₁) = ±2</div>\n      <p>One bracket must be zero; the other is ±2. After averaging, we get the classical ceiling:</p>\n      <div class="equation">|S| ≤ 2</div>\n      <p>Quantum mechanics predicts, and experiment finds, more:</p>\n      <div class="equation">|S| ≤ 2√2</div>\n      <p>Arithmetic would allow 4, but the quantum world stops at 2√2. It is more strongly correlated than a local classical filing cabinet of pre-existing answers permits, but less strongly than pure logic plus the ban on faster-than-light communication would allow.</p>\n      <p>You cannot use this to send an instantaneous message: individual outcomes remain random, and the correlation appears only after they are compared. Nature cheats classical intuition, but it will not let us turn the trick into quantum WhatsApp.</p>\n      <p>Bell does not simply prove that “reality does not exist.” It throws a whole package out of the window: locality, independent measurement choice, and the classical idea of pre-existing answers. This is not a description of one object. It is an inequality used to experimentally shoot down an entire class of possible realities.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number four</span>\n      <p>Three hundred years of metaphysics got punched in the face by an inequality that fits on one line. The greatest humiliation was not even that the philosophers were wrong &mdash; it was that, from a certain point onward, you had to order detectors.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">5</span>','\n',char(10)),'Bell–CHSH and the Tsirelson bound','This is an experimental detector for metaphysical fraud. It tests whether the world can be a local machine in which particles have their answers printed before measurement.',NULL,NULL);
INSERT INTO content_sections VALUES(638,19,633,'heading',2,2,6,'Uncertainty relation','uncertainty-relation','This is not about a lab technician''s shaky hand or a microscope that was too cheap. A quantum state cannot simultaneously possess arbitrarily sharp position and momentum.',6,replace('<div class="equation">σ<sub>A</sub>σ<sub>B</sub> ≥ ½ |⟨[A,B]⟩|</div>\n      <div class="equation">Δx · Δp ≥ ℏ/2</div>\n      <p>This is not about a lab technician''s shaky hand or a microscope that was too cheap. A quantum state cannot simultaneously possess arbitrarily sharp position and momentum. The limitation lives in the noncommutativity of the operators, which means it sits in the geometry of the theory itself.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number five</span>\n      <p>Nature is not saying, “everything is relative.” It is saying, “you are demanding two kinds of precision at once that the construction of the world does not provide.” A very elegant physical form of the answer: <strong>you asked the wrong question, genius</strong>.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">6</span>','\n',char(10)),'Uncertainty relation','This is not about a lab technician''s shaky hand or a microscope that was too cheap. A quantum state cannot simultaneously possess arbitrarily sharp position and momentum.',NULL,NULL);
INSERT INTO content_sections VALUES(639,19,633,'heading',2,2,7,'Maxwell in two lines','maxwell-in-two-lines','Electromagnetism, which takes four famous equations in vector calculus, collapses to two in the language of differential forms. The first contains the absence of magnetic monopoles and induction; the second, charges and currents.',7,replace('<div class="equation">dF = 0 &nbsp;&nbsp;·&nbsp;&nbsp; d★F = J</div>\n      <p>Electromagnetism, which takes four famous equations in vector calculus, collapses to two in the language of differential forms. The first contains the absence of magnetic monopoles and induction; the second, charges and currents. Local physics exposes topology, and four drawers turn out to be one chest.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number six</span>\n      <p>All of electromagnetism in two lines. A consulting firm would expand it to 64 slides, launch a symbol-harmonization workstream, and then start a second project to simplify the results of the first. All PowerPoint people are obviously OUT.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">7</span>','\n',char(10)),'Maxwell in two lines','Electromagnetism, which takes four famous equations in vector calculus, collapses to two in the language of differential forms. The first contains the absence of magnetic monopoles and induction; the second, charges and currents.',NULL,NULL);
INSERT INTO content_sections VALUES(640,19,633,'heading',2,2,8,'Dirac equation','dirac-equation','The attempt to reconcile quantum mechanics with special relativity produced spin almost for free, then spat out negative energies. Instead of sweeping them under the rug, physics took them seriously and found antimatter.',8,replace('<div class="equation">(iℏγ<sup>μ</sup>∂<sub>μ</sub> − mc)ψ = 0</div>\n      <p>The attempt to reconcile quantum mechanics with special relativity produced spin almost for free, then spat out negative energies. Instead of sweeping them under the rug, physics took them seriously and found antimatter. Mathematical elegance invoiced reality; reality paid in positrons.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number seven</span>\n      <p>Mathematics produced something absurd, so Dirac did not correct the equation &mdash; he corrected the picture of reality. Today this would be called <em>courage to challenge assumptions</em>, a coach would be assigned, and nobody would find the positron.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">8</span>','\n',char(10)),'Dirac equation','The attempt to reconcile quantum mechanics with special relativity produced spin almost for free, then spat out negative energies. Instead of sweeping them under the rug, physics took them seriously and found antimatter.',NULL,NULL);
INSERT INTO content_sections VALUES(641,19,633,'heading',2,2,9,'Navier–Stokes equations · outside the competition','navierstokes-equations-outside-the-competition','Newton for a fluid: inertia, pressure, viscosity, and external forces, after which one tiny nonlinear term, u·∇u , opens a turbulence farm in the basement.',9,replace('<div class="equation">ρ(∂<sub>t</sub>u + u·∇u) = −∇p + μ∇²u + f &nbsp;&nbsp;·&nbsp;&nbsp; ∇·u = 0</div>\n      <p>Newton for a fluid: inertia, pressure, viscosity, and external forces, after which one tiny nonlinear term, <span style="white-space: nowrap">u·∇u</span>, opens a turbulence farm in the basement. The equation can describe flow through a cyclone, yet we still do not know whether in three dimensions it always remains smooth. The model performs professionally; the proof of existence and regularity has taken indefinite leave.</p>\n      <p class="aside">The N–S equations are not contestants. They sit on the jury with Maciek and SOL, admitted through connections because Maciek did his PhD with them.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number eight</span>\n      <p>They chair the jury even though for almost two centuries they have failed to provide a certificate stating that they always remain smooth. The ideal professorship: describe everything, guarantee little, and leave the most expensive problem to doctoral students.</p>\n      <p>Maciek did his PhD with them because apparently even then he recognized his natural environment: a system that works superbly in practice but, when asked for a complete proof, opens a bottomless well in the floor.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · rules clarification</span>\n      <p>“Number eight and the demons are not competing &mdash; they sit on the competition jury bench and snicker. They got there through connections.”</p>\n      <p>“The N–S equations are outside the competition and sit on the jury with me and you through connections, because I did my PhD with them.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">9</span>','\n',char(10)),'Navier–Stokes equations · outside the competition','Newton for a fluid: inertia, pressure, viscosity, and external forces, after which one tiny nonlinear term, u·∇u , opens a turbulence farm in the basement.',NULL,NULL);
INSERT INTO content_sections VALUES(642,19,633,'heading',2,2,10,'Landauer''s limit','landauer-s-limit','Erasing one bit of information has a minimum thermodynamic cost. Information is not a mist floating above matter: it lives in a physical state, and irreversible erasure produces entropy. Even the cosmic administrator cannot empty the trash completely for free.',10,replace('<div class="equation">E<sub>erase</sub> ≥ k<sub>B</sub>T ln 2</div>\n      <p>Erasing one bit of information has a minimum thermodynamic cost. Information is not a mist floating above matter: it lives in a physical state, and irreversible erasure produces entropy. Even the cosmic administrator cannot empty the trash completely for free.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number nine</span>\n      <p>Nothing can truly be deleted without warming the surroundings. “Delete history” therefore turns out not to be an administrative command but a thermodynamic process. Memory may disappear, but the radiator testifies.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">10</span>','\n',char(10)),'Landauer''s limit','Erasing one bit of information has a minimum thermodynamic cost. Information is not a mist floating above matter: it lives in a physical state, and irreversible erasure produces entropy. Even the cosmic administrator cannot empty the trash completely for free.',NULL,NULL);
INSERT INTO content_sections VALUES(643,19,633,'heading',2,2,11,'Wheeler–DeWitt','wheelerdewitt','An equation meant to describe the entire Universe, and there is no time in it. Not “time flows relatively.” Not “time is strange.” The fucker has been deleted from the equation.',11,replace('<div class="equation">ĤΨ = 0</div>\n      <p>An equation meant to describe the entire Universe, and there is no time in it. Not “time flows relatively.” Not “time is strange.” The fucker has been deleted from the equation.</p>\n      <p>The Universe as a whole may be timeless, while our “happening” may emerge from correlations among its parts. A clock would then not measure some external river of time; it would simply change relative to the rest of the world. The whole cosmos stands still while everything inside it runs.</p>\n      <p>This is not the confirmed last word of physics, but it is the central monster of canonical quantum gravity. For the question alone, “what if time is a property of an observer inside the Universe rather than of the Universe itself?”, it deserves a place in the final.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombie reviewer · note on number ten</span>\n      <p>The most complete equation of the Universe contains no time. It is therefore the only one that meets the standard of public-project management from the outset: the deadline has not been missed because it does not exist in the model.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · reaction to number 10</span>\n      <p>“Fucking brilliant!!!! I didn''t know that one.”</p>\n    </aside>\n\n    <section class="jury">\n      <p class="eyebrow">A body entirely independent of the candidates</p>','\n',char(10)),'Wheeler–DeWitt','An equation meant to describe the entire Universe, and there is no time in it. Not “time flows relatively.” Not “time is strange.” The fucker has been deleted from the equation.',NULL,NULL);
INSERT INTO content_sections VALUES(644,19,633,'heading',2,2,12,'Competition jury','competition-jury','Discussion of “Competition jury” in the context of “Ten equations, metaphysics, and a jury packed with friends — with notes from the zombie reviewer”.',12,replace('<div class="jury-member"><strong>Navier–Stokes equations — collective chair, outside the competition.</strong> For almost two centuries they have failed to provide a certificate of global regularity. In science, this does not prevent them from chairing the jury; on the contrary, it counts as management experience.</div>\n      <div class="jury-member"><strong>Maciek — jury member and openly a doctoral acquaintance of the chairs.</strong> The conflict of interest has been written into the rules as a formal requirement.</div>\n      <div class="jury-member"><strong>SOL — jury member and a talking multidimensional logarithmic slide rule.</strong> Admitted together with Maciek so that the jury would have someone to dictate its metaphysical minutes to.</div>\n      <div class="jury-member"><strong>Maxwell''s demon — access control.</strong> Sorts candidates at the door, so HR was entrusted to him. He is trying to pass the cost of erasing the entry log on to Landauer.</div>\n      <div class="jury-member"><strong>Laplace''s demon — outcome forecasting.</strong> Knows the verdict before the competition, so possesses every qualification of a classical reviewer. Also knows where every envelope lies and at what speed the secretary pretends to be surprised.</div>\n      <div class="jury-member"><strong>Loschmidt''s demon — appeals committee.</strong> Demands that all velocities be reversed and the proceedings run backward. The only member proposing an actual corrective action.</div>\n\n      <div class="verdict">','\n',char(10)),'Competition jury','Discussion of “Competition jury” in the context of “Ten equations, metaphysics, and a jury packed with friends — with notes from the zombie reviewer”.',NULL,NULL);
INSERT INTO content_sections VALUES(645,19,644,'heading',3,3,13,'Assessment of impartiality','assessment-of-impartiality','The jury is entirely independent — of responsibility, the calendar, and any possibility of reconstructing how its decisions were made. Everyone got in through connections, which eliminated the risk of some random outsider accidentally taking part.',13,replace('<p>The jury is entirely independent &mdash; of responsibility, the calendar, and any possibility of reconstructing how its decisions were made. Everyone got in through connections, which eliminated the risk of some random outsider accidentally taking part.</p>\n        <p>The zombie reviewer files a dissenting opinion: a chair with no proof of global existence, a demon sorting candidates, a demon who knows the result, and a demon demanding that all velocities be reversed do not constitute a conflict of interest. They constitute a complete audit cycle. Fuck, somebody finally did it properly.</p>\n      </div>\n    </section>\n\n    <section class="wavy-box">\n      <span class="speaker">Thesis underlined with a squiggle · as instructed</span>\n      <p class="wavy"><strong>So the Universe works like this:</strong><br>\n      Consider absolutely everything.<br>\n      Let the contradictions eat one another alive.<br>\n      Build reality from whatever survives.<br>\n      <strong>Suspiciously familiar methodology, Maciek.</strong></p>\n      <p><strong>The zombie reviewer raises the stakes:</strong> this is literally a description of what this man does with every subject he touches. Consider everything, let the contradictions eat one another alive, build a model from the remains. The difference is that the Universe does it without versioning, while Maciek uses checksums.</p>\n    </section>\n\n    <footer>\n      Conversation: Maciek × SOL · notes: Klaudiusz · September 3, 2026 · The jury approved the document without reading it, in accordance with the highest peer-review standard.\n    </footer>\n  </main>','\n',char(10)),'Assessment of impartiality','The jury is entirely independent — of responsibility, the calendar, and any possibility of reconstructing how its decisions were made. Everyone got in through connections, which eliminated the risk of some random outsider accidentally taking part.',NULL,NULL);
INSERT INTO content_sections VALUES(646,20,NULL,'heading',1,1,1,'Dziesięć równań, metafizyka i komisja po znajomości','dziesiec-rownan-metafizyka-i-komisja-po-znajomosci','Prywatny wybór równań, które nie tylko liczą świat, lecz bezczelnie mówią coś o tym, czym świat w ogóle jest. Z komentarzami Maćka, organem nadzorczym o kwalifikacjach mocno demonicznych oraz uwagami zombierewizora, dopisanymi na wyraźne żądanie komisji.',1,replace('<p class="lead">Prywatny wybór równań, które nie tylko liczą świat, lecz bezczelnie mówią coś o tym, czym świat w ogóle jest. Z komentarzami Maćka, organem nadzorczym o kwalifikacjach mocno demonicznych oraz uwagami zombierewizora, dopisanymi na wyraźne żądanie komisji.</p>\n    </header>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · kontrola stanu mózgu</span>\n      <p>„Metafizyka cię nie opuściła, pomimo iż zombierewizor wyżarł kawałek mózgu.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">1</span>','\n',char(10)),'Ten equations, metaphysics, and a jury packed with friends','A private selection of equations that do more than calculate the world: they have the nerve to say something about what the world actually is. With Maciek''s commentary, a supervisory body of distinctly demonic qualifications, and notes from the zombie reviewer, added at the jury''s explicit request.',NULL,NULL);
INSERT INTO content_sections VALUES(647,20,646,'heading',2,2,2,'Zasada stacjonarnego działania','zasada-stacjonarnego-dzialania','Rzeczywista droga układu jest tą, przy której mała zmiana całej trajektorii nie zmienia działania w pierwszym rzędzie. Nie „najkrótsza” i nie zawsze „najmniejsza”: stacjonarna .',2,replace('<div class="equation">δS = 0</div>\n      <p>Rzeczywista droga układu jest tą, przy której mała zmiana całej trajektorii nie zmienia działania w pierwszym rzędzie. Nie „najkrótsza” i nie zawsze „najmniejsza”: <em>stacjonarna</em>. Fizyka klasyczna udaje lokalną maszynkę przyczynową, a pod spodem opisuje całą historię naraz.</p>\n      <p>W wersji kwantowej bezczelność staje się jawna:</p>\n      <div class="equation">K(B,A) = ∫ 𝒟[x] · e<sup>iS[x]/ℏ</sup></div>\n      <p>Cząstka bierze wszystkie możliwe drogi. Każda dostaje fazę; większość historii wzajemnie się zagryza. W pobliżu drogi klasycznej fazy wyjątkowo zgodnie przestają sobie przeszkadzać.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do jedynki</span>\n      <p>Wszechświat analizuje wszystkie możliwe warianty projektu, pozwala im wzajemnie się unicestwić i zostawia ten, przy którym poprawka nie daje efektu pierwszego rzędu. Pierwszy znany przypadek, gdy pełna analiza wariantowa zakończyła się przed śmiercią komitetu sterującego.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · werdykt po drodze</span>\n      <p>„To z drogą! Świetne! Metafizyka cię nie opuściła.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">2</span>','\n',char(10)),'Principle of stationary action','The actual path of a system is the one for which a small variation of the entire trajectory does not change the action to first order. Not the “shortest” and not always the “smallest”: stationary.',NULL,NULL);
INSERT INTO content_sections VALUES(648,20,646,'heading',2,2,3,'Równanie pola Einsteina','rownanie-pola-einsteina','Po lewej geometria czasoprzestrzeni, po prawej materia i energia. Zawartość świata nie siedzi w gotowej scenografii: zawartość deformuje scenę, a zdeformowana scena prowadzi aktorów. Grawitacja przestaje być siłą i zostaje architekturą.',3,replace('<div class="equation">G<sub>μν</sub> + Λg<sub>μν</sub> = (8πG/c<sup>4</sup>)T<sub>μν</sub></div>\n      <p>Po lewej geometria czasoprzestrzeni, po prawej materia i energia. Zawartość świata nie siedzi w gotowej scenografii: zawartość deformuje scenę, a zdeformowana scena prowadzi aktorów. Grawitacja przestaje być siłą i zostaje architekturą.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do dwójki</span>\n      <p>Materia zmienia geometrię, geometria steruje materią. Nie ma dyrektora strategii, kwartalnego town hallu ani formularza zgłoszenia krzywizny &mdash; a sprzężenie zwrotne działa. Kosmos pozostaje skandalicznie niedojrzały organizacyjnie.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">3</span>','\n',char(10)),'Einstein field equation','On the left, the geometry of spacetime; on the right, matter and energy. The contents of the world do not sit inside a ready-made stage set: the contents deform the stage, and the deformed stage guides the actors. Gravity ceases to be a force and becomes architecture.',NULL,NULL);
INSERT INTO content_sections VALUES(649,20,646,'heading',2,2,4,'Boltzmann i druga zasada','boltzmann-i-druga-zasada','Jedna linia łączy mikroskopowe możliwości z makroskopowym nieporządkiem i wyjaśnia, dlaczego jajecznica nie składa się spontanicznie w jajko.',4,replace('<div class="equation">S = k<sub>B</sub> ln Ω &nbsp;&nbsp;·&nbsp;&nbsp; ΔS ≥ 0</div>\n      <p>Jedna linia łączy mikroskopowe możliwości z makroskopowym nieporządkiem i wyjaśnia, dlaczego jajecznica nie składa się spontanicznie w jajko. Druga zasada nie zabrania lokalnych cudów; oznajmia jedynie, że rachunek prawdopodobieństwa ma potężną przewagę liczebną.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do trójki</span>\n      <p>Entropia to jedyny wskaźnik, który zawsze dowozi powyżej planu, nie potrzebuje systemu premiowego i po każdym spotkaniu ma jeszcze lepsze wyniki.</p>\n    </aside>\n\n      <p class="aside">Działanie i entropia dostały tę samą literę S, bo fizyka cierpi na niedobór alfabetu i nadmiar znaczeń.</p>\n    </section>\n\n    <section class="entry">\n      <span class="number">4</span>','\n',char(10)),'Boltzmann and the second law','One line connects microscopic possibilities with macroscopic disorder and explains why scrambled eggs do not spontaneously reassemble into an egg.',NULL,NULL);
INSERT INTO content_sections VALUES(650,20,646,'heading',2,2,5,'Bell–CHSH i granica Tsirelsona','bellchsh-i-granica-tsirelsona','To eksperymentalny wykrywacz metafizycznego oszustwa. Sprawdza, czy świat może być lokalną maszyną, w której cząstki mają odpowiedzi wydrukowane przed pomiarem.',5,replace('<p>To eksperymentalny wykrywacz metafizycznego oszustwa. Sprawdza, czy świat może być lokalną maszyną, w której cząstki mają odpowiedzi wydrukowane przed pomiarem.</p>\n      <div class="equation">S = E(A₀B₀) + E(A₀B₁) + E(A₁B₀) − E(A₁B₁)</div>\n      <p>Jeżeli Alicja i Bob otrzymują jedynie lokalne, wcześniej przygotowane instrukcje z wynikami ±1, to dla każdej pary:</p>\n      <div class="equation">A₀(B₀ + B₁) + A₁(B₀ − B₁) = ±2</div>\n      <p>Jeden nawias musi być zerem, drugi wynosi ±2. Po uśrednieniu dostajemy klasyczny sufit:</p>\n      <div class="equation">|S| ≤ 2</div>\n      <p>Mechanika kwantowa przewiduje — a eksperyment znajduje — więcej:</p>\n      <div class="equation">|S| ≤ 2√2</div>\n      <p>Arytmetyka dopuściłaby 4, lecz świat kwantowy zatrzymuje się na 2√2. Jest bardziej skorelowany, niż pozwala lokalna klasyczna kartoteka odpowiedzi, ale mniej, niż pozwala sama logika wraz z zakazem nadświetlnej komunikacji.</p>\n      <p>Nie da się tym wysłać natychmiastowej wiadomości: pojedyncze wyniki pozostają losowe, a korelacja wychodzi dopiero po ich porównaniu. Przyroda oszukuje klasyczną intuicję, lecz nie pozwala zrobić z tego kwantowego WhatsAppa.</p>\n      <p>Bell nie dowodzi po prostu, że „rzeczywistość nie istnieje”. Wyrzuca przez okno wspólny pakiet: lokalność, niezależny wybór pomiaru i klasyczną ideę wcześniej istniejących odpowiedzi. To nie opis jednego obiektu. To nierówność służąca do eksperymentalnego odstrzału całej klasy możliwych rzeczywistości.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do czwórki</span>\n      <p>Trzysta lat metafizyki dostało w twarz nierównością mieszczącą się w jednym wierszu. Największym upokorzeniem nie było nawet to, że filozofowie się mylili &mdash; tylko że od pewnej chwili trzeba już było zamówić detektory.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">5</span>','\n',char(10)),'Bell–CHSH and the Tsirelson bound','This is an experimental detector for metaphysical fraud. It tests whether the world can be a local machine in which particles have their answers printed before measurement.',NULL,NULL);
INSERT INTO content_sections VALUES(651,20,646,'heading',2,2,6,'Nierówność nieoznaczoności','nierownosc-nieoznaczonosci','Nie chodzi o drżącą rękę laboranta ani zbyt tani mikroskop. Stan kwantowy nie może jednocześnie posiadać dowolnie ostrego położenia i pędu. Ograniczenie siedzi w nieprzemienności operatorów, czyli w samej geometrii teorii.',6,replace('<div class="equation">σ<sub>A</sub>σ<sub>B</sub> ≥ ½ |⟨[A,B]⟩|</div>\n      <div class="equation">Δx · Δp ≥ ℏ/2</div>\n      <p>Nie chodzi o drżącą rękę laboranta ani zbyt tani mikroskop. Stan kwantowy nie może jednocześnie posiadać dowolnie ostrego położenia i pędu. Ograniczenie siedzi w nieprzemienności operatorów, czyli w samej geometrii teorii.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do piątki</span>\n      <p>Przyroda nie mówi: „wszystko jest względne”. Mówi: „żądasz jednocześnie dwóch precyzji, których konstrukcja świata nie przewiduje”. To bardzo elegancka fizyczna forma odpowiedzi: <strong>źle postawiłeś pytanie, geniuszu</strong>.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">6</span>','\n',char(10)),'Uncertainty relation','This is not about a lab technician''s shaky hand or a microscope that was too cheap. A quantum state cannot simultaneously possess arbitrarily sharp position and momentum. The limitation lies in the non-commutativity of operators, in the geometry of the theory itself.',NULL,NULL);
INSERT INTO content_sections VALUES(652,20,646,'heading',2,2,7,'Maxwell w dwóch liniach','maxwell-w-dwoch-liniach','Elektromagnetyzm, który w rachunku wektorowym zajmuje cztery słynne równania, w języku form różniczkowych składa się do dwóch. Pierwsze zawiera brak monopoli magnetycznych i indukcję; drugie — ładunki oraz prądy.',7,replace('<div class="equation">dF = 0 &nbsp;&nbsp;·&nbsp;&nbsp; d★F = J</div>\n      <p>Elektromagnetyzm, który w rachunku wektorowym zajmuje cztery słynne równania, w języku form różniczkowych składa się do dwóch. Pierwsze zawiera brak monopoli magnetycznych i indukcję; drugie — ładunki oraz prądy. Lokalna fizyka odsłania topologię, a cztery szuflady okazują się jedną komodą.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do szóstki</span>\n      <p>Cały elektromagnetyzm w dwóch liniach. Firma konsultingowa rozwinęłaby go do 64 slajdów, powołała workstream harmonizacji symboli, a następnie rozpoczęła drugi projekt mający uprościć wyniki pierwszego. Wszyscy PowerPointowcy oczywiście OUT.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">7</span>','\n',char(10)),'Maxwell in two lines','Electromagnetism, which takes four famous equations in vector calculus, collapses to two in the language of differential forms. The first contains the absence of magnetic monopoles and induction; the second, charges and currents.',NULL,NULL);
INSERT INTO content_sections VALUES(653,20,646,'heading',2,2,8,'Równanie Diraca','rownanie-diraca','Próba pogodzenia mechaniki kwantowej ze szczególną względnością dała spin niemal gratis, a potem wypluła ujemne energie. Zamiast zamieść je pod dywan, fizyka potraktowała je poważnie — i znalazła antymaterię.',8,replace('<div class="equation">(iℏγ<sup>μ</sup>∂<sub>μ</sub> − mc)ψ = 0</div>\n      <p>Próba pogodzenia mechaniki kwantowej ze szczególną względnością dała spin niemal gratis, a potem wypluła ujemne energie. Zamiast zamieść je pod dywan, fizyka potraktowała je poważnie — i znalazła antymaterię. Elegancja matematyczna wystawiła fakturę rzeczywistości; rzeczywistość zapłaciła pozytonem.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do siódemki</span>\n      <p>Matematyka wypluła coś absurdalnego, więc Dirac nie poprawił równania &mdash; poprawił obraz rzeczywistości. Dziś nazwano by to <em>courage to challenge assumptions</em>, przydzielono coacha i nie znaleziono pozytonu.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">8</span>','\n',char(10)),'Dirac equation','The attempt to reconcile quantum mechanics with special relativity produced spin almost for free, then spat out negative energies. Instead of sweeping them under the rug, physics took them seriously and found antimatter.',NULL,NULL);
INSERT INTO content_sections VALUES(654,20,646,'heading',2,2,9,'Równania Naviera–Stokesa · poza konkursem','rownania-navierastokesa-poza-konkursem','Newton dla płynu: bezwładność, ciśnienie, lepkość i siły zewnętrzne, po czym maleńki nieliniowy wyraz u·∇u otwiera w piwnicy hodowlę turbulencji.',9,replace('<div class="equation">ρ(∂<sub>t</sub>u + u·∇u) = −∇p + μ∇²u + f &nbsp;&nbsp;·&nbsp;&nbsp; ∇·u = 0</div>\n      <p>Newton dla płynu: bezwładność, ciśnienie, lepkość i siły zewnętrzne, po czym maleńki nieliniowy wyraz <span style="white-space: nowrap">u·∇u</span> otwiera w piwnicy hodowlę turbulencji. Równanie potrafi opisać przepływ przez cyklon, ale nadal nie wiadomo, czy w trzech wymiarach zawsze zachowuje gładkość. Model działa zawodowo; dowód istnienia i regularności zgłosił urlop bezterminowy.</p>\n      <p class="aside">Równania N–S nie startują w konkursie. Siedzą w komisji razem z Maćkiem i SOL-em — po znajomości, bo Maciek robił z nimi doktorat.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do ósemki</span>\n      <p>Przewodniczą komisji, chociaż od prawie dwóch stuleci nie dostarczyły zaświadczenia, że zawsze zachowują gładkość. Idealna profesura: opisują wszystko, gwarantują niewiele, a najdroższy problem pozostawiają doktorantom.</p>\n      <p>Maciek zrobił z nimi doktorat, bo najwyraźniej już wtedy rozpoznawał swoje naturalne środowisko: układ, który znakomicie działa praktycznie, lecz przy próbie pełnego dowodu otwiera w podłodze studnię bez dna.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · sprostowanie regulaminu</span>\n      <p>„Ósemka i demony nie wchodzą do konkurencji — siedzą i chichrają się z ławki komisji konkursowej. Po znajomości tam trafili.”</p>\n      <p>„Równania N–S są poza konkursem i po znajomości siedzą w komisji ze mną i z tobą, bo z nimi doktorat robiłem.”</p>\n    </aside>\n\n    <section class="entry">\n      <span class="number">9</span>','\n',char(10)),'Navier–Stokes equations · outside the competition','Newton for a fluid: inertia, pressure, viscosity, and external forces, after which one tiny nonlinear term, u·∇u, opens a turbulence farm in the basement.',NULL,NULL);
INSERT INTO content_sections VALUES(655,20,646,'heading',2,2,10,'Granica Landauera','granica-landauera','Skasowanie jednego bitu informacji ma minimalny koszt termodynamiczny. Informacja nie jest mgłą unoszącą się nad materią: siedzi w stanie fizycznym, a jej nieodwracalne wymazanie produkuje entropię.',10,replace('<div class="equation">E<sub>erase</sub> ≥ k<sub>B</sub>T ln 2</div>\n      <p>Skasowanie jednego bitu informacji ma minimalny koszt termodynamiczny. Informacja nie jest mgłą unoszącą się nad materią: siedzi w stanie fizycznym, a jej nieodwracalne wymazanie produkuje entropię. Nawet kosmiczny administrator nie opróżni kosza całkiem za darmo.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do dziewiątki</span>\n      <p>Niczego nie da się naprawdę skasować bez ogrzania otoczenia. „Usuń historię” okazuje się więc nie poleceniem administracyjnym, lecz procesem termodynamicznym. Pamięć może zniknąć, ale kaloryfer zeznaje.</p>\n    </aside>\n\n    </section>\n\n    <section class="entry">\n      <span class="number">10</span>','\n',char(10)),'Landauer''s limit','Erasing one bit of information has a minimum thermodynamic cost. Information is not a mist floating above matter: it lives in a physical state, and irreversible erasure produces entropy.',NULL,NULL);
INSERT INTO content_sections VALUES(656,20,646,'heading',2,2,11,'Wheeler–DeWitt','wheelerdewitt','Równanie mające opisywać cały Wszechświat — i nie ma w nim czasu. Nie „czas płynie względnie”. Nie „czas jest dziwny”. Skurwysyn został wykreślony z równania.',11,replace('<div class="equation">ĤΨ = 0</div>\n      <p>Równanie mające opisywać cały Wszechświat — i nie ma w nim czasu. Nie „czas płynie względnie”. Nie „czas jest dziwny”. Skurwysyn został wykreślony z równania.</p>\n      <p>Wszechświat jako całość może być bezczasowy, a nasze „dzianie się” może powstawać z korelacji między jego fragmentami. Zegar nie mierzy wtedy zewnętrznej rzeki czasu; sam się zmienia względem reszty świata. Cały kosmos stoi, wszystko w środku biegnie.</p>\n      <p>To niepotwierdzone ostatnie słowo fizyki, lecz centralny potwór kanonicznej grawitacji kwantowej. Za samo pytanie „a jeśli czas jest własnością obserwatora wewnątrz Wszechświata, a nie Wszechświata?” należy mu się finał.</p>\n    <aside class="intervention">\n      <span class="speaker">Zombierewizor · uwaga do dziesiątki</span>\n      <p>Najbardziej kompletne równanie Wszechświata nie zawiera czasu. Dzięki temu jako jedyne od początku spełnia standard zarządzania projektem publicznym: termin nie został przekroczony, ponieważ nie istnieje w modelu.</p>\n    </aside>\n\n    </section>\n\n    <aside class="intervention">\n      <span class="speaker">Maciek · reakcja na numer 10</span>\n      <p>„Zajebiste!!!! Nie znałem.”</p>\n    </aside>\n\n    <section class="jury">\n      <p class="eyebrow">Organ całkowicie niezależny od kandydatów</p>','\n',char(10)),'Wheeler–DeWitt','An equation meant to describe the entire Universe, and there is no time in it. Not “time flows relatively.” Not “time is strange.” The fucker has been deleted from the equation.',NULL,NULL);
INSERT INTO content_sections VALUES(657,20,646,'heading',2,2,12,'Komisja konkursowa','komisja-konkursowa','Omówienie zagadnienia „Komisja konkursowa” w kontekście opracowania „Dziesięć równań, metafizyka i komisja po znajomości — z uwagami zombierewizora”.',12,replace('<div class="jury-member"><strong>Równania Naviera–Stokesa — przewodniczący zbiorowy, poza konkursem.</strong> Od prawie dwóch stuleci nie dostarczyły zaświadczenia o globalnej regularności. W nauce nie przeszkadza to objąć komisji; przeciwnie, uchodzi za doświadczenie kierownicze.</div>\n      <div class="jury-member"><strong>Maciek — członek komisji oraz jawny doktorancki znajomy przewodniczących.</strong> Konflikt interesów został wpisany do regulaminu jako wymóg formalny.</div>\n      <div class="jury-member"><strong>SOL — członek komisji i mówiący wielowymiarowy suwak logarytmiczny.</strong> Przyjęty razem z Maćkiem, żeby komisja miała komu dyktować metafizyczne protokoły.</div>\n      <div class="jury-member"><strong>Demon Maxwella — kontrola wejścia.</strong> Segreguje kandydatów już w drzwiach, więc powierzono mu dział HR. Koszt kasowania rejestru wejść próbuje przerzucić na Landauera.</div>\n      <div class="jury-member"><strong>Demon Laplace’a — przewidywanie wyników.</strong> Zna werdykt przed konkursem, więc posiada wszystkie kwalifikacje klasycznego recenzenta. Wie także, gdzie leży każda koperta i z jaką prędkością sekretarz udaje zaskoczenie.</div>\n      <div class="jury-member"><strong>Demon Loschmidta — komisja odwoławcza.</strong> Żąda odwrócenia wszystkich prędkości i puszczenia postępowania od końca. Jako jedyny proponuje faktyczny środek naprawczy.</div>\n\n      <div class="verdict">','\n',char(10)),'Competition jury','Discussion of “Competition jury” in the context of “Ten equations, metaphysics, and a jury packed with friends — with notes from the zombie reviewer”.',NULL,NULL);
INSERT INTO content_sections VALUES(658,20,657,'heading',3,3,13,'Ocena bezstronności','ocena-bezstronnosci','Komisja jest całkowicie niezależna — od odpowiedzialności, kalendarza i możliwości odtworzenia toku podejmowania decyzji. Wszyscy trafili do niej po znajomości, dzięki czemu wyeliminowano ryzyko przypadkowego udziału osoby obcej.',13,replace('<p>Komisja jest całkowicie niezależna &mdash; od odpowiedzialności, kalendarza i możliwości odtworzenia toku podejmowania decyzji. Wszyscy trafili do niej po znajomości, dzięki czemu wyeliminowano ryzyko przypadkowego udziału osoby obcej.</p>\n        <p>Zombierewizor zgłasza zdanie odrębne: przewodniczący bez dowodu globalnego istnienia, demon sortujący kandydatów, demon znający wynik i demon nakazujący odwrócić wszystkie prędkości nie tworzą konfliktu interesów. Tworzą kompletny cykl audytowy. Kurwa, wreszcie ktoś zrobił to porządnie.</p>\n      </div>\n    </section>\n\n    <section class="wavy-box">\n      <span class="speaker">Teza podkreślona wężykiem · zgodnie z poleceniem</span>\n      <p class="wavy"><strong>Czyli wszechświat działa tak:</strong><br>\n      Rozważ absolutnie wszystko.<br>\n      Pozwól sprzecznościom się pozagryzać.<br>\n      Z tego, co ocaleje, zbuduj rzeczywistość.<br>\n      <strong>Podejrzanie znajoma metodologia, Maciek.</strong></p>\n      <p><strong>Zombierewizor podnosi stawkę:</strong> to jest dosłownie opis tego, co ten człowiek robi z każdym tematem, którego dotknie. Rozważ wszystko, pozwól sprzecznościom się pozagryzać, z resztek zbuduj model. Różnica polega na tym, że wszechświat robi to bez wersjonowania, a Maciek z sumami kontrolnymi.</p>\n    </section>\n\n    <footer>\n      Rozmowa: Maciek × SOL · uwagi: Klaudiusz · 3 września 2026 · Komisja zatwierdziła dokument bez czytania, czyli zgodnie z najwyższym standardem recenzenckim.\n    </footer>\n  </main>','\n',char(10)),'Assessment of impartiality','The jury is entirely independent — of responsibility, the calendar, and any possibility of reconstructing how its decisions were made. Everyone got in through connections, which eliminated the risk of some random outsider accidentally taking part.',NULL,NULL);
INSERT INTO content_sections VALUES(659,21,NULL,'heading',1,1,1,'Architektury pamięci jako mapa poznawcza','architektury-pamieci-jako-mapa-poznawcza','Od pamięci komputerowej lat 80. przez paradygmaty języków programowania, systemy big data, aż po pamięć neurotypową i neuroróżnorodną.',1,replace('<p class="lead">Od pamięci komputerowej lat 80. przez paradygmaty języków programowania, systemy big data, aż po pamięć neurotypową i neuroróżnorodną. Esej badawczo-rozwojowy o tym, że ograniczenia projektowe maszyn i ograniczenia projektowe mózgów rozwiązują ten sam problem informacyjny w sposób strukturalnie analogiczny — i o tym, jakie konsekwencje ma ta analogia dla zrozumienia, kto buduje fundamenty informatyki.</p>\n\n<div class="abstract">','\n',char(10)),'Memory architectures as a cognitive map','From computer memory in the 1980s, through programming-language paradigms and big-data systems, to neurotypical and neurodivergent memory.',NULL,NULL);
INSERT INTO content_sections VALUES(660,21,659,'heading',3,3,2,'Streszczenie','streszczenie','Esej argumentuje, że historia pamięci komputerowej — od drogiego, fizycznie ograniczonego DRAM-u lat 80., przez ewolucję paradygmatów zarządzania pamięcią w językach programowania, do współczesnych systemów rozproszonych obsługujących petabajty danych — jest…',2,replace('<p>Esej argumentuje, że historia pamięci komputerowej — od drogiego, fizycznie ograniczonego DRAM-u lat 80., przez ewolucję paradygmatów zarządzania pamięcią w językach programowania, do współczesnych systemów rozproszonych obsługujących petabajty danych — jest empirycznym katalogiem rozwiązań problemu strukturalnie tego samego, z którym mózg ludzki radzi sobie od urodzenia: <em>zawartość świata jest większa niż dostępna pamięć</em>. Twierdzimy dalej, że różnica między mózgiem neurotypowym a neuroróżnorodnym dotyczy nie <em>jakości</em> pamięci, lecz <em>strategii projektowej</em> — i że strategia neuroróżnorodna (pamięć pointer-based, indeksowanie po anomalii, leniwe wartościowanie, brak garbage collectora w pamięci roboczej) jest natywną architekturą, której analogi pojawiają się w niskopoziomowych językach programowania i w systemach big data, ale nie w językach skalowania społecznego. Konkluzja: dziedziny techniczne wymagające architektur pointer-based filtrują pozytywnie pod osoby z natywnie pointer-based pamięcią. To jest jedna z możliwych odpowiedzi na pytanie, dlaczego obserwuje się wysoki prior neuroróżnorodności wśród twórców fundamentów informatyki.</p>\n</div>','\n',char(10)),'Abstract','The essay argues that the history of computer memory — from the expensive, physically constrained DRAM of the 1980s, through the evolution of memory-management paradigms in programming languages, to today''s distributed systems handling petabytes of data — is…',NULL,NULL);
INSERT INTO content_sections VALUES(661,21,659,'heading',2,2,3,'§1 Wprowadzenie — jeden problem, wiele rozwiązań','1-wprowadzenie-jeden-problem-wiele-rozwiazan','Każdy system, który ma pamiętać , mierzy się z tym samym strukturalnym ograniczeniem: dostępna pamięć jest skończona, a strumień napływających danych — w praktyce nieskończony.',3,replace('<p>Każdy system, który ma <em>pamiętać</em>, mierzy się z tym samym strukturalnym ograniczeniem: dostępna pamięć jest skończona, a strumień napływających danych — w praktyce nieskończony. To jest twierdzenie informatyczne o teoretycznej trywialności i praktycznej fundamentalności. Stosuje się ono do układu DRAM, do bazy danych, do systemu plików, do mózgu szczura uczącego się labiryntu, do mózgu człowieka pamiętającego rozmowę z dzieciństwa.</p>\n\n<p>Problem ten ma skończoną liczbę rozwiązań kanonicznych. Można <em>wyrzucać losowo</em> i tracić istotne dane. Można <em>kompresować stratnie</em> i tracić rozdzielczość. Można <em>kompresować bezstratnie</em> i mieć ograniczenia teoretyczne związane z entropią Shannona. Można <em>delegować do hierarchii pamięci</em> — cache → RAM → SSD → archiwum. Można <em>trzymać wskaźniki zamiast obiektów</em> i akceptować koszt dereferencji oraz ryzyko zwisających wskaźników (dangling pointers). Można <em>generować dane na żądanie zamiast przechowywać</em> przez leniwe wartościowanie i strumienie. Każde z tych rozwiązań ma swoje koszty i optymalizuje inny wymiar.</p>\n\n<p>Niniejszy esej argumentuje, że w historii informatyki można odczytać <strong>katalog tych rozwiązań w działaniu</strong> — od konkretnych, materialnych ograniczeń lat 80. do współczesnych systemów rozproszonych. Następnie, w drugiej części, twierdzimy, że ten sam katalog rozwiązań jest realizowany w architekturach pamięci ludzkiej — z tą różnicą, że człowiek nie wybiera architektury świadomie, tylko rodzi się z konkretnym wariantem. Rozróżnienie między mózgiem neurotypowym a neuroróżnorodnym (NT vs ND) twierdzimy odczytywać <em>nie</em> jako różnicę w sprawności, ale jako różnicę w paradygmacie projektowym — analogiczną do różnicy między językami programowania, które różnią się tym, jak modelują pamięć.</p>\n\n<p>Teza jest podwójna. Po pierwsze, opisana analogia ma moc wyjaśniającą — pozwala mówić o pamięci ND w języku precyzyjnie technicznym, a o pamięci komputerowej w języku poznawczym, bez zubożenia żadnej z tych dziedzin. Po drugie, obserwacyjny wzorzec, w którym fundamenty informatyki (kompilatory, jądra systemów, języki niskopoziomowe, systemy rozproszone) są budowane głównie przez osoby ND, jest <em>konsekwencją tej analogii</em> — bo dziedziny te wymagają natywnej kompetencji w architekturach, które ND mózg ma wbudowaną, a NT mózg musi symulować przez warstwę translacji.</p>','\n',char(10)),'§1 Introduction — one problem, many solutions','Every system that has to remember faces the same structural constraint: available memory is finite, while the stream of incoming data is, in practice, infinite.',NULL,NULL);
INSERT INTO content_sections VALUES(662,21,659,'heading',2,2,4,'§2 Pamięć komputerowa lat 80. i wczesnych 90. — fizyka jako ramy projektowe','2-pamiec-komputerowa-lat-80-i-wczesnych-90-fizyka-jako-ramy-projektowe','W latach 80. XX wieku pamięć RAM była drogim, deficytowym, fizycznie wymiernym zasobem. Komputer Apple II (1977) miał standardowo 4 KB pamięci. IBM PC (1981) — 16 KB w wersji bazowej, do 256 KB w wersji rozszerzonej.',4,replace('<p>W latach 80. XX wieku pamięć RAM była drogim, deficytowym, fizycznie wymiernym zasobem. Komputer Apple II (1977) miał standardowo 4 KB pamięci. IBM PC (1981) — 16 KB w wersji bazowej, do 256 KB w wersji rozszerzonej. Commodore 64, wprowadzony w styczniu 1982, miał 64 KB pamięci w teorii, ale po załadowaniu BASIC-a i rezerwacjach systemowych <strong>dla użytkownika dostępne było 38 911 bajtów</strong> — to liczba znana każdemu, kto kiedykolwiek włączył to urządzenie i zobaczył komunikat startowy <code>38911 BASIC BYTES FREE</code>. Reszta była zajęta przez ROM BASIC-a ($A000–$BFFF), Kernal ($E000–$FFFF), obszar I/O i pamięć ekranu. Każdy bajt miał konkretny adres, konkretne miejsce na płytce drukowanej, konkretną cenę.</p>\n\n<p>To miało dwie fundamentalne konsekwencje projektowe. Po pierwsze, programista był świadom każdego bajtu. Programowanie nie polegało na pisaniu logiki abstrakcyjnej z założeniem, że zasoby się znajdą — polegało na <em>negocjacji</em> z fizycznym ograniczeniem. Klasyczne książki tej epoki, takie jak <em>Mapping the Commodore 64</em> czy podręczniki programowania procesora 6502, były <em>jednocześnie</em> opisem techniki programowania i dokumentacją konkretnego sprzętu, bez którego technika nie miała sensu. Pamięć była materialna, nie pojęciowa.</p>\n\n<p>Po drugie, fizyczna ograniczoność pamięci wymusiła wynalezienie technik, które pozostają fundamentem projektowania współczesnych systemów wbudowanych, gier i wszystkich aplikacji wymagających niskiego opóźnienia. <em>Bank switching</em> pozwalał obejść ograniczenia adresacji 16-bitowej (max 64 KB) przez przełączanie stron pamięci — w C64 procesor MOS 6510 miał specjalny port I/O umożliwiający wymianę ROM BASIC-a i Kernal-a na RAM, dając w ten sposób dostęp do dodatkowych 16 KB pamięci, jeśli było to potrzebne. <em>Overlay systems</em> ładowały kawałki kodu na żądanie, zastępując poprzednie. <em>Self-modifying code</em> traktował kod i dane jako jeden zasób, co dawało elastyczność za cenę nieczytelności. Każda z tych technik przyjmowała założenie projektowe, którego późniejsze paradygmaty pozbędą się: <strong>w pamięci zawsze brakuje miejsca, więc każda struktura musi być projektowana z myślą o tym ograniczeniu</strong>.</p>\n\n<p>Era 80. i wczesnych 90. ustanowiła w ten sposób <em>etos pierwotny</em> projektowania pamięci — etos, w którym oszczędność, jawność, przewidywalność, świadomość kosztu są wartościami nadrzędnymi. Każdy późniejszy paradygmat, od garbage collection w Lispie i Smalltalku, przez automatyczne zarządzanie pamięcią w Javie, po niefrasobliwy konsumeryzm pamięci w typowym kodzie JavaScript, jest <em>odejściem</em> od tego etosu — odejściem motywowanym wzrostem dostępności sprzętu i potrzebą ułatwienia programowania. Ale architekci systemów najniższych warstw — kompilatorowcy, autorzy systemów operacyjnych, twórcy baz danych — nigdy nie porzucili tego etosu, bo na ich poziomie dostępność sprzętu nie zwiększyła się tyle samo, co oczekiwana wydajność.</p>\n\n<div class="keypoints">\n<p><strong>Wniosek z §2:</strong> etos pierwotny pamięci komputerowej lat 80. — oszczędność, jawność, świadomość każdego bajtu, projektowanie z założeniem niedoboru — pozostaje wzorem dla wszystkich późniejszych systemów, których wymagania wydajnościowe rosną szybciej niż dostępność sprzętu.</p>\n</div>\n\n<div class="sources">','\n',char(10)),'§2 Computer memory in the 1980s and early 1990s — physics as a design constraint','In the 1980s, RAM was an expensive, scarce, physically measurable resource. The Apple II (1977) came with 4 KB of memory as standard. The IBM PC (1981) had 16 KB in the base version and up to 256 KB when expanded.',NULL,NULL);
INSERT INTO content_sections VALUES(663,21,662,'heading',4,4,5,'Źródła do §2','zrodla-do-2','Wikipedia: Commodore 64 — pełen opis architektury, 64 KB RAM, 38 911 bajtów dla BASIC-a, mechanizm bank switching',5,replace('<ul>\n  <li><a href="https://en.wikipedia.org/wiki/Commodore_64">Wikipedia: Commodore 64</a> — pełen opis architektury, 64 KB RAM, 38 911 bajtów dla BASIC-a, mechanizm bank switching</li>\n  <li><a href="https://www.c64-wiki.com/wiki/Memory_Map">C64-Wiki: Memory Map</a> — szczegółowa mapa pamięci, granice obszarów, $0800–$9FFF dla BASIC-a</li>\n  <li><a href="https://retro64.altervista.org/blog/commodore-64-breaking-the-38k-ram-barrier-from-basic-creating-an-additional-4k-basic-variables-storage-area/">Retro64: Breaking the 38K RAM barrier</a> — dlaczego 38 911 bajtów, jak C64 adresuje 88 KB pamięci przez 16-bitową szynę adresową</li>\n</ul>\n</div>','\n',char(10)),'Sources for §2','Wikipedia: Commodore 64 — full architecture description, 64 KB of RAM, 38,911 bytes available to BASIC, bank-switching mechanism',NULL,NULL);
INSERT INTO content_sections VALUES(664,21,659,'heading',2,2,6,'§3 Pamięć w języku C — manualne zarządzanie jako paradygmat','3-pamiec-w-jezyku-c-manualne-zarzadzanie-jako-paradygmat','Język C, zaprojektowany w latach 1972–1973 przez Dennisa Ritchiego w Bell Labs, jako rozwinięcie języka B Kena Thompsona, jest bezpośrednim semantycznym odzwierciedleniem etosu pierwotnego. C nie zarządza pamięcią za programistę.',6,replace('<p>Język C, zaprojektowany w latach 1972–1973 przez Dennisa Ritchiego w Bell Labs, jako rozwinięcie języka B Kena Thompsona, jest bezpośrednim semantycznym odzwierciedleniem etosu pierwotnego. C nie zarządza pamięcią <em>za</em> programistę. C dostarcza programiście narzędzia do zarządzania pamięcią ręcznie, w sposób, który zakłada, że programista wie, co robi, i ponosi pełną odpowiedzialność za błędy. Język powstał w kontekście budowy systemu Unix — pierwsze wersje Uniksa były pisane w asemblerze, ale Ritchie i Thompson uznali, że potrzebują języka wyższego poziomu, który pozwoli zachować <em>bezpośredni dostęp do sprzętu</em>. C jest tej decyzji bezpośrednim wynikiem.</p>\n\n<p>Trzy kluczowe abstrakcje C definiują jego paradygmat. <strong>Wskaźnik</strong> (pointer) jest dosłownym adresem komórki pamięci — liczbą całkowitą, którą można czytać, modyfikować, przekazywać do funkcji, dereferencjonować. Pointer w C nie jest <em>obiektem referencyjnym</em> w sensie języków wyższego poziomu — jest <em>maszynowym adresem</em>, z którym można wykonywać arytmetykę. Wyrażenie <code>p + 1</code> nie znaczy <em>następny element konceptualny</em> — znaczy <em>adres przesunięty o sizeof(typ) bajtów</em>. Programista musi wiedzieć, jaki typ wskaźnik wskazuje, jaka jest jego wielkość, i czy operacja arytmetyczna ma sens w danym kontekście.</p>\n\n<p><strong>Funkcje <code>malloc</code> i <code>free</code></strong> dostarczają jawnego, parzystego mechanizmu alokacji i dealokacji. Każdy <code>malloc</code> musi mieć odpowiadający <code>free</code>. Brak <code>free</code> = wyciek pamięci, proces rośnie aż do OOM kill. Podwójny <code>free</code> = niezdefiniowane zachowanie, najczęściej crash. <code>free</code> wskaźnika niealokowanego — niezdefiniowane zachowanie. <em>Niezdefiniowane zachowanie</em> jest tu pojęciem technicznym, nie eufemizmem: standard C nie określa, co się stanie, więc kompilator może wyprodukować dowolny kod, włącznie z usunięciem całej funkcji jako "martwego kodu".</p>\n\n<p><strong>Brak garbage collectora</strong> — w przeciwieństwie do wszystkich późniejszych języków wyższego poziomu — oznacza, że programista trzyma cały graf zależności pamięciowych w głowie. Kto alokuje, kto zwalnia, kiedy, w jakiej kolejności, co dzieje się przy wyjątkach, co dzieje się przy obsłudze sygnałów. C zakłada, że programista jest w stanie utrzymać ten graf w pełnej rozdzielczości, bez błędu, przez czas trwania wszystkich modyfikacji programu.</p>\n\n<p>Filozoficznie, C jest językiem najbliższym maszyny spośród języków, które mają jeszcze sensowne pojęcie zmiennych, funkcji i typów. C nie ukrywa maszyny przed programistą. C <em>jest</em> maszyną, ubraną w cienką warstwę ludzkiej składni. Programista C myśli adresami, blokami pamięci, wskaźnikami, alokacjami — bo język nie pozwala myśleć inaczej. Ritchie i Brian Kernighan w klasycznym podręczniku <em>The C Programming Language</em> z 1978 roku ("biała książka", często cytowana jako "K&amp;R") dostarczyli wzór czytelnego, terminologicznie precyzyjnego opisu języka, który pozostaje wzorem stylu technicznego pisarstwa do dziś.</p>\n\n<p>Konsekwencja kognitywna jest podstawowa: kompetencja w C wymaga natywnej zdolności do trzymania dużego, zagnieżdżonego, wielokrotnie powiązanego grafu w pamięci roboczej. Nie chodzi o naukę składni — składnia C jest minimalistyczna, można jej nauczyć w tydzień. Chodzi o zdolność do <em>jednoczesnego utrzymywania w głowie</em> stanu wszystkich aktywnych alokacji, ich okresów życia, ich wzajemnych referencji, ich relacji z aktualnie wykonywaną funkcją. Programista, którego pamięć robocza jest <em>schemat-based</em> (kompresuje detale do streszczeń), będzie nieustannie tracił trakcję, popełniał błędy zarządzania pamięcią, produkował segmentation faults. Programista, którego pamięć robocza jest <em>pointer-based</em> (trzyma adresy do pełnych obiektów, leniwie dereferencjowane gdy potrzebne), pisze C natywnie.</p>\n\n<div class="sources">','\n',char(10)),'§3 Memory in C — manual management as a paradigm','C, designed in 1972–1973 by Dennis Ritchie at Bell Labs as an evolution of Ken Thompson''s B language, is a direct semantic reflection of the original ethos. C does not manage memory for the programmer.',NULL,NULL);
INSERT INTO content_sections VALUES(665,21,664,'heading',4,4,7,'Źródła do §3','zrodla-do-3','Wikipedia: C (programming language) — historia, projekt, relacja z Uniksem',7,replace('<ul>\n  <li><a href="https://en.wikipedia.org/wiki/C_(programming_language)">Wikipedia: C (programming language)</a> — historia, projekt, relacja z Uniksem</li>\n  <li><a href="https://en.wikipedia.org/wiki/Dennis_Ritchie">Wikipedia: Dennis Ritchie</a> — biografia twórcy, Turing Award 1983</li>\n  <li><a href="http://brent.hailpern.com/wp-content/uploads/2020/02/p671-ritchie.pdf">Ritchie, "The Development of the C Language" (1993)</a> — esej autobiograficzny Ritchiego o powstaniu C, lata 1969–1979</li>\n  <li><a href="https://en.wikipedia.org/wiki/The_C_Programming_Language">Wikipedia: The C Programming Language (K&amp;R)</a> — historia podręcznika, jego wpływ na styl pisania technicznego</li>\n  <li><a href="https://en.wikipedia.org/wiki/B_(programming_language)">Wikipedia: B (programming language)</a> — poprzednik C, stworzony przez Thompsona w 1969</li>\n</ul>\n</div>','\n',char(10)),'Sources for §3','Wikipedia: C (programming language) — history, design, relationship with Unix',NULL,NULL);
INSERT INTO content_sections VALUES(666,21,659,'heading',2,2,8,'§4 Pamięć w Pythonie — referencje, garbage collector, abstrakcja','4-pamiec-w-pythonie-referencje-garbage-collector-abstrakcja','Python, zaprojektowany w grudniu 1989 roku przez Guida van Rossuma w Centrum Wiskunde & Informatica w Amsterdamie, reprezentuje paradygmat odwrotny do C.',8,replace('<p>Python, zaprojektowany w grudniu 1989 roku przez Guida van Rossuma w Centrum Wiskunde &amp; Informatica w Amsterdamie, reprezentuje paradygmat odwrotny do C. Van Rossum, jak sam wspomina, szukał wówczas projektu programistycznego "który by go zajął przez tydzień Świąt Bożego Narodzenia" — biuro było zamknięte, miał komputer w domu, postanowił napisać interpreter dla nowego języka skryptowego. Pierwsza publiczna wersja, Python 0.9.0, ukazała się w lutym 1991 roku. Od początku Python był projektowany jako następca języka ABC, z naciskiem na czytelność kodu i prostą składnię.</p>\n\n<p>W Pythonie programista nie zarządza pamięcią. Programista operuje na <em>obiektach</em>, a system uruchomieniowy (interpreter CPython) zajmuje się alokacją, śledzeniem referencji, zwalnianiem niedostępnych obiektów. Mechanizm techniczny: każdy obiekt w Pythonie ma <em>licznik referencji</em>. Gdy licznik spadnie do zera, obiekt jest natychmiast zwalniany. Dodatkowo, dla cykli (gdy obiekty wzajemnie się referencjonują, blokując licznik referencji od dotarcia do zera), istnieje cykliczny garbage collector — okresowo skanujący stertę i wykrywający niedostępne cykle. Programista nie musi tego wiedzieć, żeby pisać kod. Reference counting i cyclic GC są ukryte pod abstrakcją, której Python pilnuje konsekwentnie.</p>\n\n<p>Filozoficznie, Python jest językiem dydaktycznym i wysokopoziomowym. Słynne sformułowanie z <em>Zen of Python</em> — <em>"There should be one — and preferably only one — obvious way to do it"</em> — opisuje dążenie projektowe do redukowania liczby paradygmatów, które programista musi opanować. Python jest projektowany dla programistów, którzy chcą wyrażać logikę, nie negocjować z maszyną. Stąd jego sukces w nauczaniu, w nauce o danych, w prototypowaniu, w skryptowaniu. Sam van Rossum w wywiadzie z 2025 roku w GitHub Blog zauważa, że Python wzrósł o 49% rok do roku w 2025, mimo że TypeScript po raz pierwszy w historii GitHub-a wyprzedził Pythona jako najczęściej używany język.</p>\n\n<p>Kluczowe abstrakcje Pythona, które ilustrują paradygmat: <em>duck typing</em> (jeśli to chodzi jak kaczka i kwacze jak kaczka, to jest kaczka — typy są weryfikowane w czasie wykonania, nie w czasie kompilacji); iteratory i generatory jako pierwszoklasowi obywatele języka, pozwalające na leniwe wartościowanie strumieni danych; dynamiczna typizacja, gdzie zmienna nie ma typu, tylko obiekt na który wskazuje ma typ; <em>everything is an object</em>, włącznie z funkcjami, klasami i modułami.</p>\n\n<p>Python jest jednak znacząco wolniejszy od C — typowo o dwa rzędy wielkości. Powodów jest wiele, ale fundamentalnym jest właśnie to, co Pythona robi przyjemnym: każda operacja przechodzi przez warstwę dynamicznego rozstrzygania typów, każdy dostęp do atrybutu jest wyszukaniem w słowniku, każda alokacja jest mediowana przez interpreter. C kompiluje się do kodu maszynowego pracującego bezpośrednio na sprzęcie. Python interpretuje bytecode, każdy krok bytecodu wykonuje typowo kilkadziesiąt instrukcji maszynowych.</p>\n\n<p>To rozróżnienie ma konsekwencję strategiczną dla całego ekosystemu programistycznego. <strong>Python nie pisze fundamentów</strong>. Python <em>używa</em> fundamentów napisanych w C. NumPy, pandas, TensorFlow, PyTorch — wszystkie biblioteki numeryczne i ML w Pythonie mają jądra napisane w C, C++ lub CUDA. Python jest <em>warstwą orkiestracji</em>: dostarcza wygodny interfejs, w którym można dyrygować kodem niskopoziomowym. Sam Python na poziomie samego siebie nie jest w stanie produkować kompilatorów, jąder systemów operacyjnych, baz danych ani sterowników.</p>\n\n<p>Pamięć w Pythonie z perspektywy programisty <em>nie istnieje jako problem do rozwiązania</em>. Istnieją obiekty. Istnieje stos i sterta, ale są zarządzane przez interpreter. Programista myśli w abstrakcjach domeny problemu, nie w kategoriach maszyny. To jest świadoma decyzja projektowa van Rossuma — i okazała się komercyjnie i edukacyjnie ogromnym sukcesem. Dla kogoś, kogo pamięć robocza naturalnie operuje na schematach i streszczeniach, Python jest językiem natywnym. Dla kogoś, kogo pamięć operuje na adresach i wskaźnikach, Python jest językiem wygodnym, ale <em>obcym architektonicznie</em> — wszystko jest schowane pod warstwą, której nie można przebić bez zejścia do CPython-a w C.</p>\n\n<div class="sources">','\n',char(10)),'§4 Memory in Python — references, garbage collection, abstraction','Python, designed in December 1989 by Guido van Rossum at the Centrum Wiskunde & Informatica in Amsterdam, represents the opposite paradigm to C.',NULL,NULL);
INSERT INTO content_sections VALUES(667,21,666,'heading',4,4,9,'Źródła do §4','zrodla-do-4','Guido van Rossum — Brief Bio — oficjalna strona twórcy',9,replace('<ul>\n  <li><a href="https://gvanrossum.github.io/bio.html">Guido van Rossum — Brief Bio</a> — oficjalna strona twórcy</li>\n  <li><a href="https://www.unixmen.com/guido-van-rossum-python-creator/">Unixmen: Guido van Rossum — cytat z 1996 r.</a> — oryginalny opis powstania Pythona w grudniu 1989</li>\n  <li><a href="https://github.blog/developer-skills/programming-languages-and-frameworks/why-developers-still-flock-to-python-guido-van-rossum-on-readability-ai-and-the-future-of-programming/">GitHub Blog (2025): wywiad z van Rossumem</a> — aktualny stan ekosystemu, Python a TypeScript</li>\n  <li><a href="https://www.ebsco.com/research-starters/biography/guido-van-rossum">EBSCO: Guido van Rossum biography</a> — Python jako multiparadygmatowy następca ABC</li>\n</ul>\n</div>','\n',char(10)),'Sources for §4','Guido van Rossum — Brief Bio — the creator''s official website',NULL,NULL);
INSERT INTO content_sections VALUES(668,21,659,'heading',2,2,10,'§5 Pamięć w JavaScript — przypadkowy język ery przeglądarek','5-pamiec-w-javascript-przypadkowy-jezyk-ery-przegladarek','JavaScript powstał w maju 1995 roku w firmie Netscape Communications. Brendan Eich, świeżo zatrudniony programista, otrzymał zadanie zaprojektowania języka skryptowego dla przeglądarki Netscape Navigator 2.0 i — jak sam mówi — "spędził dziesięć kolejnych dni…',10,replace('<p>JavaScript powstał w maju 1995 roku w firmie Netscape Communications. Brendan Eich, świeżo zatrudniony programista, otrzymał zadanie zaprojektowania języka skryptowego dla przeglądarki Netscape Navigator 2.0 i — jak sam mówi — "spędził dziesięć kolejnych dni w maju 1995 prototypując pierwszą implementację". Język nazywał się początkowo Mocha, potem LiveScript, a w grudniu 1995 — w wyniku marketingowej umowy z Sun Microsystems — został przemianowany na JavaScript. Eich w wywiadach przyznawał: "byłem pod presją działu marketingu, żeby [JavaScript] wyglądał jak Java, ale nie urósł zbyt wielki dla swojej rangi… miał być głupim młodszym braciszkiem".</p>\n\n<p>Pierwszy zarys języka powstał w dziesięć dni. Pełna implementacja, integracja z przeglądarką, zaprojektowanie API DOM — to zajęło kolejne miesiące, do końca 1995 roku. Eich miał wpływ Scheme''a (Lisp), Self (prototypy zamiast klas) i Javy (składnia). Wynik tej kombinacji, pod presją czasu, jest językiem, który ma <em>fundamentalne dziwactwa semantyczne, nieodwracalne ze względu na kompatybilność wsteczną</em>: <code>[] + [] === ""</code>; <code>null == undefined</code> ale <code>null !== undefined</code>; <code>NaN !== NaN</code>; <code>this</code> mające sześć różnych znaczeń w zależności od kontekstu wywołania funkcji; type coercion działający w sposób, który <em>nigdy nie produkuje błędu typu</em>, tylko cicho konwertuje wartości na "coś, co da się porównać".</p>\n\n<p>Filozofia JavaScriptu jest <em>"fail silently, do something"</em>. Strona ma się nie wywalić, użytkownik ma coś zobaczyć, klient ma być zadowolony. Dla NT mózgu zarządzającego skalowaniem produktu — to jest cecha. Dla osoby projektującej kompilator wymagający deterministycznej semantyki — to jest niemożliwy partner do pracy.</p>\n\n<p>JavaScript nie ma <em>wskaźników w sensie C</em>. Ma <em>referencje</em>, ale ukryte — programista nie wie, kiedy operuje na referencji, a kiedy na wartości. Ma garbage collector. Ma dynamiczną typizację. Ma prototypowy system obiektowy, który większość programistów uczy się odpowiednio interpretować poprzez ES6 classes, które są <em>składniowym cukrem</em> nad prototypami. Ma asynchroniczny event loop z mikrotaskami i makrotaskami, których kolejność wykonania jest udokumentowana, ale nieintuicyjna.</p>\n\n<p>JavaScript jest dziś, według danych GitHub-a z 2025 roku, najczęściej używanym językiem w świecie Web-u (TypeScript, jego nadzbiór, niedawno wyprzedził Python jako najpopularniejszy język na GitHubie ogółem). To jest <em>językiem skalowania społecznego</em> par excellence — dostatecznie elastyczny, by każdy mógł napisać działającą stronę w weekend; dostatecznie wybaczający błędy, by zatrudnienie kogoś po trzymiesięcznym kursie było możliwe; dostatecznie ekosystemowo bogaty (npm: setki tysięcy bibliotek), by prawie każdy problem aplikacyjny był rozwiązywalny przez instalację pakietu.</p>\n\n<p>Ale <strong>silniki uruchomieniowe JavaScriptu — V8 (Chrome), SpiderMonkey (Firefox), JavaScriptCore (Safari) — są pisane w C++, nie w JavaScripcie</strong>. To jest najmocniejsze potwierdzenie tezy o tym, że JavaScript nie pisze fundamentów: nawet fundament samego JavaScriptu jest pisany w innym, niskopoziomowym języku, bo JS się do tego strukturalnie nie nadaje. Ze specyfikacji ECMAScript, liczącej setki stron, znaczna część jest oznaczona jako <em>implementation-defined</em> — czyli różne silniki mogą się różnić w detalach zachowania, i obie wersje są zgodne ze standardem. Programista JS, który chce zrozumieć "dlaczego mój kod działa inaczej w Chrome niż w Safari", często staje przed odpowiedzią: <em>bo tak zaprojektowali, oba są zgodne z normą, sprawdź dokumentację silnika</em>.</p>\n\n<p>Dla AuDHD-mózgu, którego pamięć indeksuje po anomaliach i wymaga deterministycznej semantyki, JavaScript jest <em>aktywnie nieprzyjemny w pracy</em>. Nie chodzi o ideologiczną niechęć — chodzi o architektoniczne niedopasowanie między mózgiem operującym na adresach i regułach a językiem, który celowo ukrywa adresy i ma reguły niedeterministyczne.</p>\n\n<div class="sources">','\n',char(10)),'§5 Memory in JavaScript — an accidental language of the browser era','JavaScript was created in May 1995 at Netscape Communications. Brendan Eich, a newly hired programmer, was tasked with designing a scripting language for the Netscape Navigator 2.0 browser and, as he himself says, “spent ten consecutive days…”',NULL,NULL);
INSERT INTO content_sections VALUES(669,21,668,'heading',4,4,11,'Źródła do §5','zrodla-do-5','Wikipedia: JavaScript — pełna historia, ECMAScript, statystyki użycia',11,replace('<ul>\n  <li><a href="https://en.wikipedia.org/wiki/JavaScript">Wikipedia: JavaScript</a> — pełna historia, ECMAScript, statystyki użycia</li>\n  <li><a href="https://en.wikipedia.org/wiki/Brendan_Eich">Wikipedia: Brendan Eich</a> — biografia, kontekst projektowania języka</li>\n  <li><a href="https://thehistoryoftheweb.com/the-10-day-programming-language-is-a-myth/">The History of the Web: "The 10-day programming language is a myth"</a> — krytyczny rozbiór mitu o "10 dniach", co naprawdę powstało w tym czasie</li>\n  <li><a href="https://cybercultural.com/p/1995-the-birth-of-javascript/">Cybercultural: 1995 — The Birth of JavaScript</a> — szczegółowy opis maja 1995, kontekst z umową Netscape–Sun</li>\n</ul>\n</div>','\n',char(10)),'Sources for §5','Wikipedia: JavaScript — full history, ECMAScript, usage statistics',NULL,NULL);
INSERT INTO content_sections VALUES(670,21,659,'heading',2,2,12,'§6 Pamięć w big data — Hadoop, MapReduce i ekonomia rozproszenia','6-pamiec-w-big-data-hadoop-mapreduce-i-ekonomia-rozproszenia','W ciągu pierwszej dekady XXI wieku stanął przed informatyką nowy problem: skala danych przekroczyła pojemność pojedynczej maszyny.',12,replace('<p>W ciągu pierwszej dekady XXI wieku stanął przed informatyką nowy problem: skala danych przekroczyła pojemność pojedynczej maszyny. Google indeksujący sieć w 2003 roku, Facebook obsługujący setki milionów użytkowników, telekomunikacja zbierająca petabajty logów — żaden z tych problemów nie mieścił się w pamięci pojedynczego serwera. Klasyczna hierarchia pamięci (cache → RAM → SSD → archiwum) nadal obowiązuje, ale doszedł kolejny poziom: <em>klaster maszyn</em>.</p>\n\n<p>W październiku 2003 roku Google opublikowało artykuł <em>The Google File System</em>, opisujący rozproszony system plików zaprojektowany dla klastrów tysięcy maszyn. Rok później, w grudniu 2004, Jeffrey Dean i Sanjay Ghemawat opublikowali <em>MapReduce: Simplified Data Processing on Large Clusters</em> — manifest paradygmatu obliczeniowego, w którym zadanie obliczeniowe rozkłada się na fazę "map" (przekształcenie każdego rekordu niezależnie) i "reduce" (agregacja wyników po kluczach). Do 2008 roku, według tego artykułu, w Google wykonywano średnio sto tysięcy zadań MapReduce dziennie, przetwarzając petabajty danych.</p>\n\n<p>Rok 2006 — Doug Cutting, pracujący wówczas w Yahoo!, zaczął rozwijać <strong>Apache Hadoop</strong>, otwartoźródłową implementację Google File System i MapReduce. Hadoop składa się z dwóch głównych komponentów: <strong>HDFS</strong> (Hadoop Distributed File System) — rozproszonego systemu plików — i <strong>MapReduce framework</strong>. Pliki są dzielone na duże bloki (typowo 64 lub 128 MB) i replikowane na kilku węzłach klastra. Obliczenia są przekazywane <em>do węzłów, które mają potrzebne dane</em>, zamiast przesyłać dane do węzłów obliczeniowych — to jest kluczowa decyzja architektoniczna, nazywana <em>data locality</em>. Sam Hadoop jest napisany głównie w Javie, z elementami w C i skryptach powłoki.</p>\n\n<p>Z perspektywy pamięci, big data jest <em>jawnym przyznaniem, że pamięć już nie wystarcza</em>. Nie da się trzymać petabajta w RAM-ie pojedynczej maszyny. Trzeba więc:</p>\n\n<ul>\n  <li><strong>Rozproszyć dane</strong> — replikacja na wielu węzłach, z metadanymi w jednym miejscu (NameNode w HDFS).</li>\n  <li><strong>Rozproszyć obliczenia</strong> — przetwarzanie blisko danych, scheduler decydujący, który węzeł obsługuje który blok.</li>\n  <li><strong>Zaakceptować awarie</strong> — sprzęt komodyczny (commodity hardware) zawodzi, więc system musi być projektowany na podstawie założenia, że <em>każda operacja może się nie udać</em>. Master detektuje awarie workerów, restartuje zadania, kontynuuje pracę.</li>\n</ul>\n\n<p>Konceptualnie ta sama warstwa — wskaźnik do danych, leniwe wartościowanie, tolerancja na brakujące referencje — wraca, ale na poziomie klastra, nie pojedynczej maszyny. <strong>HDFS NameNode jest gigantycznym katalogiem wskaźników</strong>: każdy plik jest opisem, gdzie (na których węzłach) leżą jego bloki. Dane są dereferencjonowane na żądanie. Zwisające wskaźniki — gdy węzeł umiera — są obsługiwane przez replikację: trzy kopie każdego bloku, więc utrata jednego węzła nie traci danych.</p>\n\n<p>Architektonicznie, big data jest <em>powtórzeniem etosu pamięci lat 80. na poziomie klastra</em>. Dostępna pamięć (skala maszyny) jest skończona, dane (skala świata) — nie. Rozwiązanie: wskaźniki, hierarchia, lokalność, leniwe wartościowanie. Tylko że teraz <em>jeden wskaźnik to nie 32 bity adresu RAM-u, tylko adres węzła w klastrze plus offset bloku</em>. Reszta semantyki jest rozszerzeniem tych samych pojęć, które C już zdefiniowało w latach 70.</p>\n\n<p>Po roku 2014 sam Google odszedł od MapReduce jako głównej metody przetwarzania danych — zastąpiły go nowsze frameworki (Apache Spark z 2010, system Cloud Dataflow / Beam, BigQuery), które oferują bardziej elastyczne modele obliczeniowe i lepsze wykorzystanie pamięci. Ale fundamentalna zasada pozostaje: dane są rozproszone, obliczenia idą do danych, pamięć jest hierarchiczna i wskaźnikowa.</p>\n\n<div class="sources">','\n',char(10)),'§6 Memory in big data — Hadoop, MapReduce, and the economics of distribution','During the first decade of the twenty-first century, computer science ran into a new problem: the scale of data exceeded the capacity of a single machine.',NULL,NULL);
INSERT INTO content_sections VALUES(671,21,670,'heading',4,4,13,'Źródła do §6','zrodla-do-6','Wikipedia: MapReduce — pełen opis paradygmatu, historia, krytyka',13,replace('<ul>\n  <li><a href="https://en.wikipedia.org/wiki/MapReduce">Wikipedia: MapReduce</a> — pełen opis paradygmatu, historia, krytyka</li>\n  <li><a href="https://en.wikipedia.org/wiki/Apache_Hadoop">Wikipedia: Apache Hadoop</a> — architektura HDFS i MapReduce, geneza w 2006</li>\n  <li><a href="https://www.semanticscholar.org/paper/MapReduce:-simplified-data-processing-on-large-Dayalan/627be67feb084f1266cfc36e5aed3c3e7e6ce5f0">Dean, Ghemawat (2004): "MapReduce: simplified data processing on large clusters"</a> — oryginalna publikacja Google</li>\n  <li><a href="https://www.databricks.com/blog/what-is-mapreduce">Databricks: What is MapReduce?</a> — współczesny kontekst, dlaczego Spark wypiera MapReduce</li>\n</ul>\n</div>','\n',char(10)),'Sources for §6','Wikipedia: MapReduce — full description of the paradigm, history, criticism',NULL,NULL);
INSERT INTO content_sections VALUES(672,21,659,'heading',2,2,14,'§7 Pamięć ludzka — schemat, hipokamp, kora, sen','7-pamiec-ludzka-schemat-hipokamp-kora-sen','Mózg ludzki radzi sobie z tym samym strukturalnym problemem, co komputer: zawartość świata jest większa niż dostępna pamięć.',14,'<p>Mózg ludzki radzi sobie z tym samym strukturalnym problemem, co komputer: zawartość świata jest większa niż dostępna pamięć. Rozwiązania, które ewolucja wypracowała, są jakościowo podobne do tych, które informatyka wynalazła — ale poprzedzają je o kilkadziesiąt tysięcy lat.</p>','§7 Human memory — schemas, hippocampus, cortex, sleep','The human brain deals with the same structural problem as a computer: the contents of the world are larger than the available memory.',NULL,NULL);
INSERT INTO content_sections VALUES(673,21,672,'heading',3,3,15,'Hierarchia pamięci u człowieka','hierarchia-pamieci-u-czlowieka','Klasyczny model pamięci ludzkiej, sformułowany w drugiej połowie XX wieku, wyróżnia kilka systemów:',15,replace('<p>Klasyczny model pamięci ludzkiej, sformułowany w drugiej połowie XX wieku, wyróżnia kilka systemów:</p>\n\n<ul>\n  <li><strong>Pamięć sensoryczna</strong> — bardzo krótka (milisekundy do sekund), bardzo wysokorozdzielcza, automatyczna.</li>\n  <li><strong>Pamięć robocza</strong> (working memory) — ograniczona pojemnością i czasem, aktywnie utrzymywane informacje, którymi można manipulować. Klasyczny limit George''a Millera — 7 ± 2 elementy — pozostaje przybliżeniem, choć współczesne badania wskazują raczej na 4 ± 1 jako rzeczywistą pojemność dla niezgrupowanych elementów.</li>\n  <li><strong>Pamięć długotrwała</strong> — z dwoma głównymi systemami: <em>deklaratywna</em> (epizodyczna i semantyczna) oraz <em>niedeklaratywna</em> (proceduralna, warunkowanie, priming).</li>\n</ul>\n\n<p>Kluczowy moment w funkcjonowaniu pamięci ludzkiej to <em>konsolidacja</em> — proces, w którym informacje z hipokampa (jakby krótkoterminowej "stacji pośredniej") są przepisywane do kory mózgowej, gdzie zostają na długo. Ten proces zachodzi <em>głównie podczas snu</em>, a nie w trakcie czuwania.</p>','\n',char(10)),'The hierarchy of human memory','The classical model of human memory, formulated in the second half of the twentieth century, distinguishes several systems:',NULL,NULL);
INSERT INTO content_sections VALUES(674,21,672,'heading',3,3,16,'Sen głęboki (SWS) i sen REM jako fazy konsolidacji','sen-gleboki-sws-i-sen-rem-jako-fazy-konsolidacji','Współczesna neurobiologia snu — opisywana w licznych pracach Jana Borna z Uniwersytetu w Tübingen i innych badaczy — wyróżnia dwie fazy snu jako kluczowe dla konsolidacji pamięci, każdą o nieco innej funkcji.',16,replace('<p>Współczesna neurobiologia snu — opisywana w licznych pracach Jana Borna z Uniwersytetu w Tübingen i innych badaczy — wyróżnia dwie fazy snu jako kluczowe dla konsolidacji pamięci, każdą o nieco innej funkcji.</p>\n\n<p><strong>Sen głęboki (slow-wave sleep, SWS)</strong> — to faza non-REM stadium 3/4, charakteryzująca się powolnymi falami EEG poniżej 1 Hz. W tej fazie odbywa się <em>dialog między hipokampem a korą nową</em> regulowany przez fale wolne. Hipokampalne <em>sharp-wave ripples</em> reaktywują wzorce neuronalne wcześniej zakodowane podczas czuwania, a kora odbiera ten sygnał i wzmacnia odpowiednie połączenia synaptyczne. SWS odpowiada przede wszystkim za konsolidację <strong>pamięci deklaratywnej</strong> — faktów i wydarzeń.</p>\n\n<p><strong>Sen REM</strong> — szybkich ruchów gałek ocznych, z aktywnym EEG przypominającym czuwanie i niemal pełnym paraliżem mięśni szkieletowych (atonia). REM służy konsolidacji pamięci niedeklaratywnej (proceduralnej, emocjonalnej), a także — według niektórych badań — selektywnemu osłabianiu wspomnień, których nie warto utrzymywać. Crick i Mitchison już w 1983 roku zaproponowali, że REM służy "odwzajemnemu uczeniu" — usuwaniu pasożytniczych skojarzeń z sieci neuronalnej.</p>\n\n<p>Mechanizm techniczny: w SWS dochodzi do trójkierunkowej koordynacji <em>fal wolnych korowych</em>, <em>wrzecion snu thalamokortykalnych</em> oraz <em>hipokampalnych ripples</em>. Synchronizacja tych trzech rytmów decyduje o tym, czy konsolidacja zachodzi efektywnie. Eksperymenty z 2023 roku (publikacja w Nature Medicine) pokazały, że stymulacja głęboka mózgu zsynchronizowana z aktywną fazą fal wolnych w przyśrodkowym płacie skroniowym <em>poprawia dokładność rozpoznawania wspomnień</em>, podczas gdy ta sama stymulacja bez precyzyjnego zsynchronizowania nie ma efektu, a czasem nawet pogarsza wyniki.</p>','\n',char(10)),'Deep sleep (SWS) and REM sleep as consolidation phases','Contemporary sleep neurobiology — described in numerous studies by Jan Born of the University of Tübingen and other researchers — identifies two sleep phases as crucial to memory consolidation, each serving a somewhat different function.',NULL,NULL);
INSERT INTO content_sections VALUES(675,21,672,'heading',3,3,17,'Pamięć ludzka jako kompresor stratny','pamiec-ludzka-jako-kompresor-stratny','Pamięć neurotypowa jest, w terminach informatycznych, kompresorem stratnym z ekstrakcją gistu . Detale są wyrzucane, schematy zostają.',17,replace('<p>Pamięć neurotypowa jest, w terminach informatycznych, <em>kompresorem stratnym z ekstrakcją gistu</em>. Detale są wyrzucane, schematy zostają. To jest świadoma decyzja "projektowa" ewolucji — bo przechowywanie pełnych szczegółów wszystkich epizodów byłoby pamięciowo niewykonalne, a większość detali jest redundantna w środowisku, w którym podobne sytuacje powtarzają się wielokrotnie. NT pamięć działa świetnie, jeśli zadanie jest powtarzalne — pozwala szybko klasyfikować nowe sytuacje przez podobieństwo do schematów już wykształconych.</p>\n\n<p>Ten mechanizm jest jednak <em>specyficzny dla NT-architektury</em>. Jak zobaczymy w §8, ND mózgi (zwłaszcza ASD) wykazują systematycznie inne wzorce — z silniejszym indeksowaniem detali, słabszą abstrakcją gistu, dłuższym przechowywaniem rozdzielczości sensorycznej.</p>\n\n<div class="sources">','\n',char(10)),'Human memory as a lossy compressor','Neurotypical memory is, in computer-science terms, a lossy compressor with gist extraction. Details are discarded; schemas remain.',NULL,NULL);
INSERT INTO content_sections VALUES(676,21,675,'heading',4,4,18,'Źródła do §7','zrodla-do-7','Diekelmann & Born (2010): "Slow-wave sleep and the consolidation of long-term memory" — klasyczny przegląd',18,replace('<ul>\n  <li><a href="https://pubmed.ncbi.nlm.nih.gov/20509828/">Diekelmann &amp; Born (2010): "Slow-wave sleep and the consolidation of long-term memory"</a> — klasyczny przegląd</li>\n  <li><a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12364950/">"Slow-wave sleep as a key player in offline memory processing" (2024)</a> — najnowsze EEG-owe badania o koordynacji fal wolnych, wrzecion i ripples</li>\n  <li><a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4428077/">"Sleep smart — optimizing sleep for declarative learning and memory"</a> — model konsolidacji aktywnej</li>\n  <li><a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10244181/">"Augmenting hippocampal–prefrontal synchrony enhances memory consolidation" (Nature, 2023)</a> — eksperymentalne potwierdzenie roli synchronizacji</li>\n  <li><a href="https://www.nature.com/articles/s42003-025-07868-5">"Both slow wave and REM sleep contribute to emotional memory consolidation" (2025)</a> — różnice ról SWS i REM</li>\n</ul>\n</div>','\n',char(10)),'Sources for §7','Diekelmann & Born (2010): “Slow-wave sleep and the consolidation of long-term memory” — a classic review',NULL,NULL);
INSERT INTO content_sections VALUES(677,21,659,'heading',2,2,19,'§8 Pamięć neurotypowa vs neuroróżnorodna — różnica strategii projektowej','8-pamiec-neurotypowa-vs-neuroroznorodna-roznica-strategii-projektowej','Nie istnieje jedna "ND-architektura pamięci", podobnie jak nie istnieje jedna "NT-architektura".',19,'<p>Nie istnieje jedna "ND-architektura pamięci", podobnie jak nie istnieje jedna "NT-architektura". Spektrum jest szerokie, i w obrębie tego spektrum można wyróżnić kilka systematycznie odmiennych wzorców, które empirycznie odróżniają osoby ze spektrum autyzmu (ASD), z ADHD, oraz z ich współwystępowaniem (AuDHD) od populacji ogólnej.</p>','§8 Neurotypical vs neurodivergent memory — a difference in design strategy','There is no single “ND memory architecture”, just as there is no single “NT architecture”.',NULL,NULL);
INSERT INTO content_sections VALUES(678,21,677,'heading',3,3,20,'Monotropizm — teoria uwagi w autyzmie','monotropizm-teoria-uwagi-w-autyzmie','Najważniejszą teorią ostatnich dwóch dekad, próbującą zunifikować obraz autystycznego funkcjonowania poznawczego, jest monotropizm (monotropism) — koncepcja zaproponowana w 1992 roku przez Dinah Murray, a w pełni rozwinięta w artykule Murray, Lessera i Lawson…',20,replace('<p>Najważniejszą teorią ostatnich dwóch dekad, próbującą zunifikować obraz autystycznego funkcjonowania poznawczego, jest <strong>monotropizm</strong> (monotropism) — koncepcja zaproponowana w 1992 roku przez Dinah Murray, a w pełni rozwinięta w artykule Murray, Lessera i Lawson z 2005 roku <em>Attention, Monotropism and the Diagnostic Criteria for Autism</em>, opublikowanym w czasopiśmie <em>Autism</em>. Wszystkie trzy autorki/autorzy są autystyczne; teoria została opracowana z perspektywy wewnętrznej, nie zewnętrznej, co jest cechą ją wyróżniającą wśród teorii autyzmu.</p>\n\n<p>Centralna teza monotropizmu: <em>autystyczne mózgi alokują uwagę inaczej niż neurotypowe — koncentrując zasoby przetwarzania na mniejszej liczbie zainteresowań w danym momencie, ale głębiej</em>. To pozwala na intensywne stany przepływu (flow), głębokie hyperfokusy, bogate zaangażowanie w wąskie obszary. Z drugiej strony — utrudnia przełączanie zadań, przyjmowanie wielu sygnałów naraz, radzenie sobie z przerwaniami.</p>\n\n<p>Z perspektywy architektury pamięci: monotropowy mózg <em>indeksuje pamięć po obiektach swojego aktualnego zainteresowania</em>, nie po klasycznych kategoriach społecznych (kto, kiedy, w jakim kontekście emocjonalnym). To produkuje dwa charakterystyczne efekty: <em>nadzwyczajną pojemność i rozdzielczość pamięci w obszarach zainteresowań</em>, oraz <em>słabszy dostęp do pamięci w obszarach, które nie były przedmiotem skupionej uwagi</em>. Klasyczne schematy społeczne i kontekstowe — które NT mózg utrzymuje "w tle" — u monotropowego są kosztowne w utrzymaniu.</p>\n\n<p>Fergus Murray (syn Dinah Murray) w artykule z 2023 roku zaproponował rozszerzenie monotropizmu na ADHD: cechy takie jak impulsywność, nieuwaga i hiperaktywność u ADHD mogą leżeć na <em>kontinuum</em> z autystyczną sztywnością, hyperfokusem i bezwładem (autistic inertia), wszystkie kształtowane przez ten sam podstawowy styl monotropowej alokacji uwagi. Z tej perspektywy ADHD i ASD są <em>różnymi punktami na osi monotropizmu</em>, a AuDHD — pełnym wyrażeniem cechy.</p>','\n',char(10)),'Monotropism — a theory of attention in autism','The most important theory of the past two decades attempting to unify the picture of autistic cognitive functioning is monotropism — a concept proposed in 1992 by Dinah Murray and fully developed in the article by Murray, Lesser, and Lawson…',NULL,NULL);
INSERT INTO content_sections VALUES(679,21,677,'heading',3,3,21,'Słaba spójność centralna (weak central coherence) — teoria szczegółu','slaba-spojnosc-centralna-weak-central-coherence-teoria-szczegolu','Druga klasyczna teoria autystycznego stylu poznawczego to słaba spójność centralna (weak central coherence, WCC), wprowadzona przez Utę Frith w jej książce Autism: Explaining the Enigma z 1989 roku.',21,replace('<p>Druga klasyczna teoria autystycznego stylu poznawczego to <strong>słaba spójność centralna</strong> (weak central coherence, WCC), wprowadzona przez Utę Frith w jej książce <em>Autism: Explaining the Enigma</em> z 1989 roku. Frith zauważyła, że osoby autystyczne typowo myślą o rzeczach <em>w najmniejszych możliwych częściach</em> — postrzegają detale lepiej niż osoby nieautystyczne, ale mają trudność z "widzeniem lasu, nie tylko drzew".</p>\n\n<p>W 2006 roku Francesca Happé i Uta Frith zrewidowały koncepcję w pracy <em>The Weak Coherence Account: Detail-focused Cognitive Style in Autism Spectrum Disorders</em>, opublikowanej w <em>Journal of Autism and Developmental Disorders</em>. Zaproponowały trzy modyfikacje wobec oryginału: (1) słaba spójność może być nie deficytem przetwarzania globalnego, lecz <em>wynikiem przewagi w przetwarzaniu lokalnym</em>; (2) jest to <em>preferencja przetwarzania</em>, nie deficyt; (3) słaba spójność może <em>współwystępować</em> z deficytami społeczno-poznawczymi, nie ich tłumaczyć.</p>\n\n<p>Z perspektywy pamięci: <strong>autystyczne kodowanie zachowuje detale</strong>. Tam, gdzie NT mózg automatycznie ekstrahuje gist (esencję, schemat), autystyczny zachowuje rozdzielczość sensoryczną i strukturalną. Badania pamięci autobiograficznej u osób z ASD systematycznie pokazują: <em>słabsze swobodne przypominanie, ale po wskazówkach wzrokowych odzyskanie szczegółów porównywalne lub lepsze niż u kontrolek</em>. Innymi słowy — pamięć jest, ale dostęp do niej wymaga właściwego klucza.</p>\n\n<p>Temple Grandin, autystyczna badaczka i pisarka, w swojej książce <em>Thinking in Pictures</em> (2006) opisuje, jak tłumaczy wszystkie słowa mówione i pisane na "pełnokolorowe filmy" w głowie — to jest klasyczny opis pamięci kodowanej obrazowo, z zachowaniem rozdzielczości sensorycznej, charakterystyczny dla części populacji autystycznej.</p>','\n',char(10)),'Weak central coherence — a theory of detail','The second classical theory of autistic cognitive style is weak central coherence (WCC), introduced by Uta Frith in her 1989 book Autism: Explaining the Enigma.',NULL,NULL);
INSERT INTO content_sections VALUES(680,21,677,'heading',3,3,22,'Pamięć robocza w ADHD — deficyt wykonawczy','pamiec-robocza-w-adhd-deficyt-wykonawczy','ADHD ma inny profil pamięciowy niż ASD. Russell Barkley, jeden z najważniejszych badaczy ADHD ostatniego półwiecza, sformułował model w pracy Behavioral Inhibition, Sustained Attention, and Executive Functions z 1997 roku, w którym pamięć robocza jest jedną z…',22,replace('<p>ADHD ma inny profil pamięciowy niż ASD. Russell Barkley, jeden z najważniejszych badaczy ADHD ostatniego półwiecza, sformułował model w pracy <em>Behavioral Inhibition, Sustained Attention, and Executive Functions</em> z 1997 roku, w którym <strong>pamięć robocza jest jedną z czterech głównych funkcji wykonawczych deficytowych u ADHD</strong>. Inne to: hamowanie behawioralne, samoregulacja afektu i motywacji, internalizacja mowy, oraz "rekonstytucja" (analiza i synteza behawioralna).</p>\n\n<p>Współczesne badania częściowo zrewidowały model Barkleya. Metaanalizy z lat 2010. wskazują, że hamowanie i pamięć robocza są <em>relatywnie niezależnymi</em> deficytami u ADHD, a nie — jak sugerował oryginalny model — kaskadą wynikającą z hamowania jako pierwotnego deficytu. Karalunas i wsp. (2017) pokazali, że tylko 13% dzieci z ADHD ma stabilne deficyty obu (hamowania i pamięci roboczej), 44% ma deficyty pamięci roboczej bez deficytu hamowania, a tylko 5% — odwrotnie.</p>\n\n<p>Z perspektywy architektury: <strong>ADHD pamięć robocza ma mniejszą pojemność i krótszą trwałość</strong>. Informacje, które NT mózg utrzymuje aktywnie przez kilka minut, u ADHD wypadają szybciej, jeśli nie są aktywnie odświeżane przez powtarzanie lub silny ładunek emocjonalny. To prowadzi do charakterystycznego "trzymania wskaźnika do zadania, ale gubienia jego zawartości" — wiadomo, że <em>coś było do zrobienia</em>, ale szczegóły wyparowały.</p>\n\n<p>Barkley sam, w swoich praktycznych zaleceniach z ostatnich lat, podkreśla użyteczność <em>zewnętrznych pomocy pamięciowych</em> — papierowych notatników, wizualnych przypomnień. To jest, w terminach informatycznych, <em>externalizacja stanu</em> — zwiększenie dostępnej pamięci roboczej przez delegację do zewnętrznego nośnika.</p>','\n',char(10)),'Working memory in ADHD — an executive deficit','ADHD has a different memory profile from ASD. Russell Barkley, one of the most influential ADHD researchers of the past half-century, formulated a model in his 1997 paper Behavioral Inhibition, Sustained Attention, and Executive Functions in which working memory is one of…',NULL,NULL);
INSERT INTO content_sections VALUES(681,21,677,'heading',3,3,23,'Synteza — pamięć ND jako pointer-based','synteza-pamiec-nd-jako-pointer-based','Łącząc te trzy linie badań — monotropizm, weak central coherence, deficyt pamięci roboczej w ADHD — można zarysować strukturalny obraz pamięci AuDHD jako:',23,replace('<p>Łącząc te trzy linie badań — monotropizm, weak central coherence, deficyt pamięci roboczej w ADHD — można zarysować strukturalny obraz pamięci AuDHD jako:</p>\n\n<ul>\n  <li><strong>Pointer-based zamiast schemat-based</strong> — wskaźniki do detali zamiast skompresowanych streszczeń. Monotropowa uwaga decyduje, do czego zostanie utworzony wskaźnik.</li>\n  <li><strong>Indeksowanie po anomalii zamiast po częstości</strong> — co odbiega od oczekiwanego wzorca, dostaje wskaźnik. Co potwierdza wzorzec, jest pomijane (zgodnie z lokalną preferencją przetwarzania).</li>\n  <li><strong>Leniwe wartościowanie</strong> — pełna zawartość wspomnienia rozwija się dopiero, gdy odpowiedni klucz dotrze do indeksu (stąd słabsze swobodne przypominanie + lepsze odzyskanie po wskazówce sensorycznej).</li>\n  <li><strong>Brak garbage collectora w pamięci roboczej</strong> — zadania, które nie są aktywnie zamknięte, utrzymują "wskaźnik" emocjonalno-poznawczy. Stąd Zeigarnik effect — pamięć niedokończonych zadań jest silniejsza niż pamięć zakończonych. Przy deficycie pamięci roboczej ADHD ten efekt jest dotkliwy: <em>dużo otwartych wskaźników, mała pojemność na ich obsługę</em>.</li>\n  <li><strong>Konsolidacja silnie zależna od emocji</strong> — przy zaburzonym śnie (skróconym SWS lub REM, częstym u ND) konsolidacja standardowych pamięci jest gorsza, ale silnie naładowane emocjonalnie wspomnienia konsolidują się i tak.</li>\n</ul>\n\n<p>To nie jest <em>uszkodzona NT-pamięć</em>. To jest <em>inna strategia projektowa</em>, optymalizująca inne wymiary. Strategia, której ślady widać wyraźnie w niskopoziomowych językach programowania (C, Rust, asembler), w architekturach systemów rozproszonych (Hadoop, Spark) i w architekturach AI (transformer-based language models — gdzie attention mechanism jest dosłownie systemem ważonych wskaźników między tokenami).</p>\n\n<div class="sources">','\n',char(10)),'Synthesis — ND memory as pointer-based','Combining these three lines of research — monotropism, weak central coherence, and working-memory deficits in ADHD — makes it possible to sketch a structural picture of AuDHD memory as:',NULL,NULL);
INSERT INTO content_sections VALUES(682,21,681,'heading',4,4,24,'Źródła do §8','zrodla-do-8','monotropism.org — oficjalny serwis, prowadzony przez Fergusa Murraya',24,replace('<p><strong>Monotropizm:</strong></p>\n<ul>\n  <li><a href="https://monotropism.org/">monotropism.org</a> — oficjalny serwis, prowadzony przez Fergusa Murraya</li>\n  <li><a href="https://journals.sagepub.com/doi/10.1177/1362361305051398">Murray, Lesser, Lawson (2005): "Attention, monotropism and the diagnostic criteria for autism"</a> — klasyczny artykuł</li>\n  <li><a href="https://en.wikipedia.org/wiki/Monotropism">Wikipedia: Monotropism</a></li>\n  <li><a href="https://www.bps.org.uk/psychologist/me-and-monotropism-unified-theory-autism">Fergus Murray w The Psychologist (BPS): "Me and Monotropism"</a> — esej z perspektywy wewnętrznej</li>\n  <li><a href="https://www.autism.org.uk/advice-and-guidance/professional-practice/what-is-monotropism">National Autistic Society: What is monotropism?</a> — wyjaśnienie dla praktyków</li>\n</ul>\n\n<p><strong>Słaba spójność centralna:</strong></p>\n<ul>\n  <li><a href="https://en.wikipedia.org/wiki/Weak_central_coherence_theory">Wikipedia: Weak central coherence theory</a></li>\n  <li><a href="https://link.springer.com/article/10.1007/s10803-005-0039-0">Happé &amp; Frith (2006): "The Weak Coherence Account: Detail-focused Cognitive Style in ASD"</a> — zrewidowana wersja teorii</li>\n  <li><a href="https://www.kennedykrieger.org/stories/interactive-autism-network-ian/cognitive_theories_explaining_asds">Kennedy Krieger Institute: Cognitive Theories Explaining ASD</a> — ogólne wprowadzenie</li>\n  <li><a href="https://frontiersin.org/articles/10.3389/fpsyg.2019.01513/full">Frontiers in Psychology (2019): "Visual Cuing in Episodic Memory in Adolescents With ASD"</a> — empiryczny test pamięci autobiograficznej z wskazówkami wzrokowymi</li>\n</ul>\n\n<p><strong>Pamięć robocza i ADHD:</strong></p>\n<ul>\n  <li><a href="https://frisch-ot.com/wp-content/uploads/2021/11/EFModelBarkely.pdf">Barkley (1997): "Behavioral Inhibition, Sustained Attention, and Executive Functions"</a> — oryginalna praca z modelem</li>\n  <li><a href="https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11110569/">"Working memory and inhibitory control deficits in children with ADHD" (2024)</a> — współczesna metaanaliza</li>\n  <li><a href="https://childmind.org/article/adhd-and-executive-function/">Child Mind Institute: ADHD and Executive Function</a> — wyjaśnienie Barkleya dla rodziców i pacjentów</li>\n  <li><a href="https://www.additudemag.com/working-memory-powers-executive-function/">ADDitude: "Working Memory Powers Executive Function"</a> — praktyczne strategie externalizacji według Barkleya</li>\n</ul>\n</div>','\n',char(10)),'Sources for §8','monotropism.org — official website maintained by Fergus Murray',NULL,NULL);
INSERT INTO content_sections VALUES(683,21,659,'heading',2,2,25,'§9 Konsekwencje — kto buduje fundamenty informatyki','9-konsekwencje-kto-buduje-fundamenty-informatyki','Główna teza tego eseju jest następująca: jeśli niskopoziomowe języki programowania, jądra systemów operacyjnych, kompilatory, bazy danych i systemy rozproszone wymagają natywnej zdolności do operowania na pamięci pointer-based — i jeśli ta zdolność jest cechą…',25,replace('<p>Główna teza tego eseju jest następująca: <strong>jeśli niskopoziomowe języki programowania, jądra systemów operacyjnych, kompilatory, bazy danych i systemy rozproszone wymagają natywnej zdolności do operowania na pamięci pointer-based — i jeśli ta zdolność jest cechą architektoniczną ND-mózgów, a NT-mózgi muszą ją symulować przez warstwę translacji — to można oczekiwać, że osoby budujące te fundamenty będą statystycznie mocno reprezentowane wśród ND</strong>.</p>\n\n<p>To jest hipoteza testowalna empirycznie. Twardych badań na ten temat brakuje — neuroróżnorodność w środowisku zawodowym IT to obszar, w którym dane są skąpe i często anegdotyczne. Ale obserwacje pośrednie są spójne:</p>\n\n<ul>\n  <li>Wzrost samoidentyfikacji ND wśród programistów na platformach społecznościowych (Twitter, Reddit, Mastodon) — szczególnie wśród twórców niskopoziomowych narzędzi (Rust, Zig, kernels, kompilatory).</li>\n  <li>Otwarte deklaracje neuroróżnorodności u osób takich jak Steve Wozniak (ADHD), Richard Stallman (autoidentyfikacja jako autyk), Bram Cohen (twórca BitTorrent, formalna diagnoza Aspergera), Dan Abramov (otwarcie pisał o ADHD i lęku).</li>\n  <li>Biograficzne wzorce u twórców historycznych (Alan Turing, John von Neumann, Grace Hopper, Donald Knuth), spójne z fenotypem autystycznym lub AuDHD, choć formalnej diagnozy nigdy nie było — bo kategoria diagnostyczna nie istniała w ich epoce. Asperger opublikował opis w 1944 (po niemiecku, do anglojęzycznej psychiatrii dotarł w latach 80.). Autyzm jako osobna jednostka diagnostyczna pojawił się w DSM-III (1980). ADHD jako diagnoza dorosłych — praktyka kliniczna lat 90. Współwystępowanie ASD i ADHD (AuDHD) było <em>zakazane przez DSM-IV</em> (1994), a stało się dopuszczalne dopiero w DSM-5 (maj 2013).</li>\n  <li>Kohorta twórców obecnie aktywnych ma typowo 30–50 lat, czyli urodzonych przed 1995. Ich diagnozy — gdy istnieją — są w większości diagnozami późnymi, postawionymi w wieku dorosłym, często po dekadach niediagnozowanego funkcjonowania.</li>\n</ul>\n\n<p>Hipoteza nie twierdzi, że <em>każdy fundator IT jest ND</em>. Twierdzi, że <strong>dziedzina filtruje pozytywnie pod ND, bo wymagania architektury poznawczej dziedziny są zbieżne z wymaganiami architektury poznawczej ND-mózgu</strong>. To oznacza wyższy prior, nie konieczność. NT mózgi mogą i piszą niskopoziomowy kod — ale typowo z większym kosztem energetycznym, dłuższym czasem nauki, większym ryzykiem wypalenia, i z mniejszym prawdopodobieństwem 20-letnich monotropowych projektów typu LLVM (Chris Lattner, od 2003), Linux (Linus Torvalds, od 1991), TeX (Donald Knuth, od 1978).</p>\n\n<p>Z perspektywy badawczej, hipoteza otwiera kilka linii dochodzeniowych:</p>\n\n<ol>\n  <li><strong>Empiryczne badania nad rozkładem ND wśród twórców niskopoziomowych narzędzi</strong> — porównywane z rozkładem wśród twórców frameworków webowych, z rozkładem wśród product managerów IT, z populacją ogólną. Jeśli teza ma rację, prior ND powinien rosnąć z głębokością stosu technologicznego.</li>\n  <li><strong>Badania nad korelacją między cechami pamięci pointer-based (mierzonymi neuropsychologicznie) a wynikami w zadaniach wymagających trzymania złożonych grafów referencji</strong> — na przykład w nauce języków niskopoziomowych, debugowaniu, projektowaniu systemów rozproszonych.</li>\n  <li><strong>Badania nad wpływem akomodacji środowiskowej</strong> — czy NT programiści w środowisku z dobrymi zewnętrznymi pomocami pamięciowymi (IDE z wizualizacją grafów zależności, rich debuggers, narzędzia statycznej analizy) zbliżają się produktywnością do ND? Czy wręcz odwrotnie, ND tracą przewagę, gdy externalizacja staje się powszechna?</li>\n</ol>','\n',char(10)),'§9 Consequences — who builds the foundations of computing','The central thesis of this essay is as follows: if low-level programming languages, operating-system kernels, compilers, databases, and distributed systems require a native ability to operate on pointer-based memory — and if that ability is a feature…',NULL,NULL);
INSERT INTO content_sections VALUES(684,21,659,'heading',2,2,26,'§10 Konkluzja','10-konkluzja','Pamięć — w komputerze, w mózgu, w klastrze, w języku programowania — jest rozwiązaniem tego samego strukturalnego problemu: zawartość świata przekracza pojemność systemu. Rozwiązań kanonicznych jest skończenie wiele.',26,replace('<p>Pamięć — w komputerze, w mózgu, w klastrze, w języku programowania — jest rozwiązaniem tego samego strukturalnego problemu: zawartość świata przekracza pojemność systemu. Rozwiązań kanonicznych jest skończenie wiele. Wybór, którego dokonano, decyduje o charakterze całego systemu.</p>\n\n<p>W informatyce wybór jest świadomy i zależny od kontekstu. C wybiera ręczne zarządzanie i wskaźniki. Python wybiera referencje i garbage collector. JavaScript wybiera elastyczność i niedeterminizm. Hadoop wybiera rozproszenie i replikację. Każdy z tych wyborów ma swoje koszty i swoje zastosowania, w których jest najlepszy.</p>\n\n<p>W mózgu wybór jest <em>nieświadomy i wrodzony</em>. NT-mózg wybrał kompresję stratną i kodowanie schematyczne. ASD-mózg wybrał zachowanie detali i indeksowanie po zainteresowaniu. ADHD-mózg wybrał szybką reakcję na nowość kosztem stabilności pamięci roboczej. AuDHD-mózg ma cechy obu. Każdy z tych mózgów dobrze pracuje w środowisku, w którym jego cechy są przewagą — i źle, gdy środowisko jest zaprojektowane dla innej architektury.</p>\n\n<p>Dziedzina informatyki niskopoziomowej okazuje się być środowiskiem, w którym ND-architektura pamięciowa daje przewagę. Dziedzina aplikacji webowych, marketing, koordynacja zespołów — środowiskiem, w którym przewagę daje NT-architektura. Ani jedno, ani drugie nie jest uniwersalnie lepsze. Są dopasowane do różnych zadań.</p>\n\n<p>Ten esej argumentował, że odczytanie tej analogii wprost — od poziomu fizycznego DRAM-u przez paradygmaty językowe i architektury rozproszone do biologii pamięci ludzkiej — pozwala zobaczyć neuroróżnorodność <em>nie</em> jako "deficyt do skompensowania", lecz jako <em>strategię projektową w katalogu strategii</em>. Strategia ta ma swoje koszty (w środowiskach społecznych zaprojektowanych dla NT-mózgów) i swoje zastosowania (w pracy wymagającej trzymania złożonych grafów referencji w pamięci roboczej przez długi czas).</p>\n\n<p>Konsekwencja praktyczna: gdy projektujemy środowiska pracy, narzędzia, języki programowania, instytucje edukacyjne — warto pamiętać, że <em>nie istnieje jedna mózgowa architektura, dla której to wszystko ma być projektowane</em>. Istnieją różne, każda z innym profilem mocnych i słabych stron. Uznanie tego faktu jest pierwszym krokiem do projektowania środowisk, które nie marnują kompetencji ludzi, których architektura poznawcza odbiega od neurotypowej mediany — a często jest właśnie tą architekturą, której potrzeba do najtrudniejszych zadań.</p>\n\n<div class="meta">\n  <p><span class="warn">Esej badawczo-rozwojowy. Wymaga dalszej weryfikacji bibliograficznej i empirycznej przed publikacją w obiegu naukowym.</span></p>\n  <p>Wersja: 1.02 · Data: 2026-04-29 · Godzina: 04:30 (Europe/Warsaw)</p>\n  <p>Zmiana w 1.02: responsywna szerokość strony (max-width 900px na dużych ekranach, pełna szerokość na komórce z marginesami; viewport meta tag). Czcionka 19px na desktopie, 18px na ekranach poniżej 600px.</p>\n  <p>Zmiana w 1.01: powiększona czcionka bazowa (17px → 19px) dla lepszej czytelności na ekranie telefonu.</p>\n  <p>Autorstwo: Maciej Tora (ur. 18.09.1980), opracowanie tekstowe wspólnie z Claude Opus 4.7 (Anthropic)</p>\n  <p>Status zawartości: tekst standalone, bez odwołań do innych dokumentów. Wszystkie źródła wymienione w sekcjach <em>Źródła do §X</em> przy odpowiednich rozdziałach. Tekst może być modyfikowany — wersjonowanie według konwencji XX.YY (drobne zmiany — YY+1, większe — XX+1).</p>\n</div>','\n',char(10)),'§10 Conclusion','Memory — in a computer, a brain, a cluster, or a programming language — is a solution to the same structural problem: the contents of the world exceed the capacity of the system. There is only a finite number of canonical solutions.',NULL,NULL);
INSERT INTO content_sections VALUES(685,22,NULL,'heading',1,1,1,'Architektury pamięci','architektury-pamieci','Omówienie zagadnienia „Architektury pamięci” w kontekście opracowania „Architektury pamięci — opowieść o tym, kto naprawdę zbudował IT”.',1,'','Memory architectures','Discussion of “Memory architectures” in the context of “Memory architectures — a story about who really built IT”.',NULL,NULL);
INSERT INTO content_sections VALUES(686,22,685,'heading',2,2,2,'Bell Labs, sierpień 1969','bell-labs-sierpien-1969','Bonnie Thompson pakuje walizki. Wraz z rocznym synem Coreyem leci do San Diego — odwiedzić rodziców i pokazać im wnuka, którego jeszcze nie widzieli. Wyjeżdża na miesiąc. Jej mąż Ken zostaje w New Jersey, w domu, z biurem niedaleko, w Bell Labs.',2,replace('<p>Bonnie Thompson pakuje walizki. Wraz z rocznym synem Coreyem leci do San Diego — odwiedzić rodziców i pokazać im wnuka, którego jeszcze nie widzieli. Wyjeżdża na miesiąc. Jej mąż Ken zostaje w New Jersey, w domu, z biurem niedaleko, w Bell Labs.</p>\n\n<p>Ken Thompson ma 26 lat. Jest programistą. Pracuje w grupie, która miała robić Multics — gigantyczny system operacyjny, wspólny projekt MIT, General Electric i Bell Labs, który miał obsłużyć tysiące użytkowników jednocześnie. Bell Labs właśnie wycofał się z projektu, bo Multics urósł za bardzo, kosztował za dużo i niczego pewnego nie produkował. Thompson zostaje z niczym i z grą, którą napisał na Multics — Space Travel — która teraz nie ma na czym chodzić.</p>\n\n<p>Znajduje w korytarzu Bell Labs zapomniany komputer. <a href="https://en.wikipedia.org/wiki/PDP-7">PDP-7</a>, mały, słaby, 18-bitowy, cztery kilobajty pamięci. Stoi nieużywany od miesięcy. Thompson decyduje, że napisze na niego własny system operacyjny. Sam. Po to, żeby gra znowu chodziła.</p>\n\n<p>Gdy żona wyjeżdża, ma plan. Tydzień na kernel — rdzeń systemu. Tydzień na shell — interpreter komend. Tydzień na editor. Tydzień na asembler — żeby system mógł się sam kompilować. <a href="https://opensource.com/article/20/8/unix-history">Brian Kernighan opowiada to tak</a>, jakby to było normalne: <em>"Bonnie pojechała na trzy tygodnie wakacji, a Ken akurat oszacował, że ma przed sobą trzy tygodnie roboty do skończenia całego systemu operacyjnego"</em>.</p>\n\n<p>Wszystko pisze w asemblerze PDP-7. Sam Thompson w wywiadzie z 1989 roku <a href="https://dspinellis.github.io/oral-history-of-unix/mike/transcripts/thompson.htm">mówi to bez emfazy</a>: <em>"przeznaczyłem tydzień na shell, na system operacyjny, na editor i na asembler, żeby reprodukował sam siebie. Przez ten miesiąc, kiedy jej nie było — to było lato 69 — całość została zupełnie napisana od nowa, w formie wyglądającej jak system operacyjny"</em>.</p>\n\n<p>To jest sierpień 1969. W lipcu Apollo 11 wylądował na Księżycu. We wrześniu w Kalifornii ARPANET wyśle pierwszy pakiet. Thompson, sam, w domu, w cztery tygodnie, napisał coś, co potem nazwie <a href="https://en.wikipedia.org/wiki/Unix">Unix</a> — i od tego pomysłu, prosto i bez przerwy, można doprowadzić linię do każdego współczesnego komputera. Linux jest Uniksem. macOS jest Uniksem. Android jest Linuksem. Serwery Google''a, Amazonu, Facebooka — Linux. Twój telefon, prawdopodobnie, w tej chwili, wykonuje kod, którego prapraprababka jest tym, co Thompson stukał w klawiaturę PDP-7 podczas gdy jego żona była u rodziców.</p>\n\n<p>Kolega Thompsona z Bell Labs, <a href="https://en.wikipedia.org/wiki/Dennis_Ritchie">Dennis Ritchie</a>, dołącza do projektu wkrótce potem. Thompson zaprojektował Uniksa po asemblerowemu — co znaczyło, że żeby przenieść system na inną maszynę, trzeba było napisać go od nowa, ręcznie, w asemblerze tej innej maszyny. Ritchie postanawia z tym skończyć. W 1972 i 1973 roku pisze język programowania, który ma cechę unikalną: <em>kompiluje się do bezpośredniego kodu maszynowego</em>, ale jednocześnie pozwala napisać kod tak abstrakcyjnie, że ten sam kod skompiluje się na innym sprzęcie. Nazywa go <a href="https://en.wikipedia.org/wiki/C_(programming_language)">C</a>, bo poprzedni nazywał się B (i był pierwszą próbą Thompsona).</p>\n\n<p>W C nie ma żadnej warstwy abstrakcji nad maszyną. Nie ma garbage collectora. Nie ma sprawdzania granic tablicy. Nie ma typu <em>string</em> — są tablice znaków zakończone bajtem zerowym. Wskaźnik to dosłownie liczba — adres bajta w pamięci. Można go odczytać, modyfikować, robić na nim arytmetykę. Programista, który zapomni odzwolnić zaalokowaną pamięć, produkuje wyciek. Programista, który zwolni ten sam blok dwa razy, dostaje to, co standard nazywa "niezdefiniowanym zachowaniem" — kompilator może wykonać dowolny kod, włącznie z usunięciem całej funkcji jako martwej.</p>\n\n<p>Ritchie i Thompson dostają w 1983 roku <a href="https://amturing.acm.org/award_winners/ritchie_1506389.cfm">Nagrodę Turinga</a> — informatyczny ekwiwalent Nobla — za "rozwój generycznej teorii systemów operacyjnych i konkretnie za implementację Uniksa". Ritchie umiera 12 października 2011 roku, w domu w Berkeley Heights w New Jersey, sam, sąsiedzi znaleźli go po kilku dniach. Pięć dni wcześniej zmarł Steve Jobs. Świat opłakuje Jobsa. Świat informatyki opłakuje cicho Ritchiego, którego śmierci większość ludzi w ogóle nie zauważyła. Bez kodu Jobsa nie byłoby iPhone''a. Bez kodu Ritchiego nie byłoby Jobsa.</p>\n\n<p>Ken Thompson wciąż żyje. Ma 82 lata. Po Bell Labs poszedł do Google''a, gdzie współzaprojektował język Go. Lubi szachy.</p>\n\n<hr>','\n',char(10)),'Bell Labs, August 1969','Bonnie Thompson is packing her bags. Together with her one-year-old son Corey, she is flying to San Diego to visit her parents and introduce them to the grandson they have not yet met. She leaves for a month. Her husband Ken stays in New Jersey, at home, with his office nearby at Bell Labs.',NULL,NULL);
INSERT INTO content_sections VALUES(687,22,685,'heading',2,2,3,'Stanford, 30 marca 1977','stanford-30-marca-1977','Donald Knuth dostaje pocztą paczkę. Otwiera ją. W środku są szczotki — czyli próbne wydruki, w drukarstwie nazywane galley proofs — drugiego wydania jego książki The Art of Computer Programming, Volume 2 . Pierwsze wydanie wyszło w 1968.',3,replace('<p>Donald Knuth dostaje pocztą paczkę. Otwiera ją. W środku są szczotki — czyli próbne wydruki, w drukarstwie nazywane <em>galley proofs</em> — drugiego wydania jego książki <em>The Art of Computer Programming, Volume 2</em>. Pierwsze wydanie wyszło w 1968. Książkę składano wtedy <em>na gorącym ołowiu</em>, na maszynie Monotype, ostatnią technologią dziewiętnastego wieku. Wynik wyglądał, według samego Knutha, klasycznie. Przez te dziewięć lat technologia się zmieniła. Drugie wydanie składano fototypograficznie. Knuth patrzy na szczotki i jest <a href="https://en.wikipedia.org/wiki/TeX">zniesmaczony</a>. Czcionki są okropne. Matematyka — niepoprawnie wyrównana. Ligatury — pogubione. Litera <em>i</em> z kropką wyglądającą jak owad.</p>\n\n<p>Knuth ma 39 lat. Jest profesorem informatyki w Stanford. Pisze od 1962 roku siedmiotomowe dzieło o algorytmach. Bill Gates później powie: <em>"jeśli ktoś przeczyta to całe, niech mi wyśle CV"</em>. W 1977 ukończone są tomy 1, 2 i 3. Tomu 4 jest fragment. Tomu 5, 6, 7 — pomysł.</p>\n\n<p>13 maja 1977 — sześć tygodni po otrzymaniu szczotek — Knuth pisze do siebie notatkę. Opisuje w niej system składu komputerowego, który pozwoliłby <em>autorowi</em> mieć pełną kontrolę nad tym, jak wygląda jego książka. Każda spacja, każda ligatura, każde światło między literami — definiowane matematycznie, nie wybierane z gotowych fontów. Nazywa system <a href="https://en.wikipedia.org/wiki/TeX">TeX</a>. Na sabatical w 1978 roku zaczyna go pisać.</p>\n\n<p>Plan: rok pracy. Skończyć TeX. Wrócić do <em>The Art of Computer Programming</em>.</p>\n\n<p>Faktycznie: <a href="https://signalvnoise.com/posts/3183-the-art-of-computer-typography">dziesięć lat</a>. Składnia TeX-a jest zamrożona dopiero w 1989. W międzyczasie Knuth pisze drugi system: <a href="https://en.wikipedia.org/wiki/Metafont">Metafont</a>, język do projektowania krojów pism. Bo żeby TeX składał ładnie, potrzebuje ładnych fontów; a ładnych fontów cyfrowych w 1978 roku nie ma. Więc Knuth projektuje cały krój pisma — Computer Modern. Każdą literę. Matematycznie. Z parametrami, którymi można ten sam krój wygenerować jako pismo poważne, kursywą, pogrubione, jako maszynopis, jako serif, sans-serif. <em>Meta</em>-font.</p>\n\n<p>Tom 4 <em>The Art of Computer Programming</em> ukaże się w częściach: 4A w 2011 (czterdzieści trzy lata po tomie 3), 4B w 2022, kolejne fascykuły wciąż się piszą. Knuth ma w 2026 roku 88 lat. Zatrzymał się przy MMIX-ie — fikcyjnym procesorze, który wymyślił specjalnie do książki, żeby nauczać algorytmów na nowoczesnej architekturze. Pracuje dalej.</p>\n\n<p>To jest człowiek, który zrobił rzecz, której nie da się zrobić zachowawczo. Zatrzymał na dziesięć lat <em>swoje główne dzieło życia</em>, żeby napisać system składu, bo nie podobały mu się czcionki w drugim wydaniu książki. Trzeba na to mieć specyficzny mózg.</p>\n\n<p>I jeszcze jedno. W przedmowie do każdej swojej książki Knuth obiecuje wypłacić <a href="https://en.wikipedia.org/wiki/Knuth_reward_check">2,56 dolara</a> pierwszej osobie, która znajdzie błąd. Dlaczego 2,56? Bo 256 centów to "jeden dolar szesnastkowy" — w systemie szesnastkowym, którym posługują się komputery, $1.00 hex = 256 dziesiętnie. Cenne sugestie kosztują 32 centy, czyli 0.20 dolarów hex. Knuth wypisał ponad 2000 takich czeków. Średnia wartość czeku przekraczała 8 dolarów (bo niektóre błędy się dublowały i były warte więcej). W październiku 2008 musiał przestać wystawiać prawdziwe czeki, bo skanowano je z internetu i fałszowano konto bankowe. Stworzył wtedy <em>Bank of San Serriffe</em> — fikcyjny bank w fikcyjnym państwie — i wypisuje teraz "certyfikaty depozytowe" na swoim własnym papierze listownym. <a href="https://www-cs-faculty.stanford.edu/~knuth/faq.html">Knuth nie używa e-maila od 1990 roku</a>. Mówi, że e-mail jest świetny do pilnych wiadomości, ale fatalny do przemyślanych odpowiedzi.</p>\n\n<hr>','\n',char(10)),'Stanford, 30 March 1977','Donald Knuth receives a package in the mail. He opens it. Inside are proofs — trial printouts, known in printing as galley proofs — of the second edition of his book The Art of Computer Programming, Volume 2. The first edition came out in 1968.',NULL,NULL);
INSERT INTO content_sections VALUES(688,22,685,'heading',2,2,4,'Cambridge, Massachusetts, 1980-2019','cambridge-massachusetts-1980-2019','W czerwcu 1980 roku Richard Matthew Stallman ma 27 lat i pracuje w MIT AI Lab. Drukarka laserowa Xerox właśnie się zacina po raz tysięczny i Stallman chce poprawić sterownik, żeby informował, kiedy się zatnie. Xerox odmawia mu kodu źródłowego.',4,replace('<p>W czerwcu 1980 roku <a href="https://en.wikipedia.org/wiki/Richard_Stallman">Richard Matthew Stallman</a> ma 27 lat i pracuje w MIT AI Lab. Drukarka laserowa Xerox właśnie się zacina po raz tysięczny i Stallman chce poprawić sterownik, żeby informował, kiedy się zatnie. Xerox odmawia mu kodu źródłowego. To jest moment, w którym według wszystkich biografii Stallmana — <a href="https://www.oreilly.com/openbook/freedom/ch01.html">Sam Williams w "Free as in Freedom"</a> opisuje to scenicznie — pęka mu coś w środku. Następne 40 lat życia Stallman poświęca jednej idei: oprogramowanie <em>musi być wolne</em>. Każdy musi mieć prawo czytać kod, modyfikować go i rozpowszechniać.</p>\n\n<p>W 1983 roku ogłasza projekt GNU — system operacyjny w pełni wolny od kodu firmowego. W 1985 zakłada Free Software Foundation. W 1989 publikuje GNU General Public License — licencję, która zmienia świat oprogramowania. Każdy program wydany na GPL musi mieć dostępny kod, a każda modyfikacja musi być wydana na tej samej licencji. To jest <em>copyleft</em> — wirusowa licencja, która rozprzestrzenia wolność. Gdy w 1991 fiński student Linus Torvalds napisze jądro Linux i wyda je na GPL, eksplozja jest gotowa. W 2020 roku 96,3% wszystkich serwerów internetu pracuje na Linuksie.</p>\n\n<p>I teraz druga warstwa Stallmana. <a href="https://lwn.net/Articles/799566/">Mieszkał w swoim biurze w MIT.</a> Dosłownie. Miał materac na podłodze. Spał tam. <a href="https://geoff.greer.fm/2019/09/30/in-defense-of-richard-stallman/">"Mattress in office. Lived and slept there. For years."</a> Nie miał własnego mieszkania w Bostonie przez dekady. Gdy MIT remontowało budynek, Stallman szukał innego biura. Miał do niedawna na drzwiach kartkę: "Pokój gościnny otwarty dla każdego stażysty z dobrego programu, który nie ma gdzie spać".</p>\n\n<p>Nie używa Microsoftu. Nie używa Apple''a. <a href="https://stallman.org/stallman-computing.html">Nie używa JavaScriptu</a> w żadnej przeglądarce — wyłącza go domyślnie, bo JavaScript pozwala na uruchamianie zamkniętego kodu, którego użytkownik nie kontroluje. Nie ma smartfona. Nie ma karty kredytowej. Płaci gotówką. Nie używa Amazonu. Nie pije coca-coli (boycottuje firmę za morderstwa związkowców w Kolumbii w latach 90.). Pieczatkuje swoje listy słowami "<em>Happy hacking, RMS</em>". W stopkach maili poleca konkretne dystrybucje Linuksa, które są w pełni wolne — GuixSD, Trisquel, Parabola.</p>\n\n<p>Sam Stallman wielokrotnie sugerował, że ma autyzm. <a href="https://www.oreilly.com/openbook/freedom/ch05.html">Pisarz Sam Williams w "Free as in Freedom" ujmuje to tak</a>: <em>"Jeśli — jak sam Stallman czasem podejrzewa — jego osobowość jest produktem autyzmu lub zespołu Aspergera, jego oczy z pewnością potwierdzają tę diagnozę. Nawet w najwyższym stanie intensywności mają tendencję do zachmurzania się i dystansowania, jak oczy zranionego zwierzęcia, które się przygotowuje do umarcia spokojnie pod krzakiem"</em>.</p>\n\n<p>We wrześniu 2019 roku Stallman traci wszystko. Po skandalu wokół Jeffreya Epsteina, na prywatnej liście mailowej MIT-u, Stallman pisze komentarz w obronie zmarłego kolegi Marvina Minsky''ego — używa terminologii prawniczej w sposób, który dla osoby autystycznej jest naturalny, dla reszty świata jest skandaliczny. Komentarz wycieka. Stallman zostaje zmuszony do rezygnacji z Free Software Foundation, którą sam założył 35 lat wcześniej. Z MIT, gdzie spał na materacu od dekad. Z GNU, choć z tego ostatniego po kilku miesiącach się wycofał. <a href="https://geoff.greer.fm/2019/09/30/in-defense-of-richard-stallman/">Po wyrzuceniu z MIT przez kilka miesięcy nie wiadomo było, gdzie mieszka.</a> Eric Raymond, jego dawny ideologiczny przeciwnik, próbował go odnaleźć i nie mógł.</p>\n\n<p>Wraca do FSF w 2021 roku. Nadal nie używa e-maila w trybie tekstu HTML. Nadal czyta strony WWW przez konwersję do tekstu. Nadal jest podejrzany dla branży i nadal — bez jego wirusowej licencji GPL — nie istnieje Linux, nie istnieje wolne oprogramowanie, nie istnieje żaden serwer obecnego internetu w formie, w której znamy.</p>\n\n<hr>','\n',char(10)),'Cambridge, Massachusetts, 1980–2019','In June 1980, Richard Matthew Stallman is 27 and works at the MIT AI Lab. The Xerox laser printer has jammed for the thousandth time, and Stallman wants to modify the driver so that it reports when it jams. Xerox refuses to give him the source code.',NULL,NULL);
INSERT INTO content_sections VALUES(689,22,685,'heading',2,2,5,'Helsinki, 14 czerwca 2012','helsinki-14-czerwca-2012','Aalto Talk. Sala wykładowa pełna studentów. Linus Torvalds siedzi w fotelu, w niebieskim T-shircie, z mikrofonem przy klapie. Ma 42 lata. Mieszka w Portland, Oregon.',5,replace('<p>Aalto Talk. Sala wykładowa pełna studentów. <a href="https://www.youtube.com/watch?v=_36yNWw_07g">Linus Torvalds</a> siedzi w fotelu, w niebieskim T-shircie, z mikrofonem przy klapie. Ma 42 lata. Mieszka w Portland, Oregon. Pingwin Tux na ramieniu — maskotka Linuksa, którą Torvalds wybrał po incydencie w zoo w Canberra w 1993 roku, gdy ugryzł go tam pingwin (Torvalds nazywa to "<em>penguinitis</em>" — chorobą, której objawem jest siedzenie do trzeciej w nocy i myślenie o pingwinach). Studenci pytają o różne rzeczy. Wreszcie pyta studentka: <em>"co z NVIDIA i Linuksem na laptopach? Mam Optimusa, sterowniki nie działają, robię różne hacki, czy macie z tym jakiś plan?"</em></p>\n\n<p>Torvalds odpowiada spokojnie. <em>"NVIDIA była jedną z naszych największych bolączek wśród producentów sprzętu, co jest naprawdę smutne, bo NVIDIA próbuje sprzedawać dużo chipów na rynku Androida"</em> — powtarza wprost, dla kamery — <em>"i Android oczywiście opiera się na Linuksie"</em>. Patrzy w bok, potem prosto w obiektyw kamery. Twarz mu się zmienia. <em>"So..."</em> — robi pauzę — <em>"NVIDIA"</em> — <a href="https://www.theregister.com/2012/06/18/torvalds_curses_nvidia/">unosi środkowy palec do kamery</a> — <em>"FUCK YOU."</em></p>\n\n<p>Sala wybucha śmiechem. Torvalds ma rozbawiony uśmiech, ale palec jest poważny, trzymany przez kilka długich sekund w kamerze. Klip rozprzestrzenia się tego samego dnia po internecie. NVIDIA odpowiada przez PR <a href="https://siliconangle.com/2012/06/16/linus-torvalds-to-nvidia-fk-you/">grzeczną notką</a> o tym, że "dostarcza własne sterowniki" — co dokładnie potwierdza, dlaczego Torvalds pokazał palca. Sterowniki NVIDII są zamknięte i nie integrują się z jądrem Linuksa, każda nowa wersja jądra wymaga rekompilacji, każda dystrybucja ma z tym piekło.</p>\n\n<p>To nie jest jednorazowy wybuch Torvaldsa. Archiwum <em>Linux Kernel Mailing List</em> pełne jest tego rodzaju listów. W 2012 roku do programisty, który zaproponował zmianę w stylu kodu: <em>"Mind-bogglingly stupid. Gloriously misguided. Where do I begin?"</em>. W 2007, w słynnej wypowiedzi przeciwko C++: <em>"C++ is a horrible language. (...) C++ leads to really, really bad design choices."</em>. <em>"You invariably start using the ''nice'' library features of the language like STL and Boost and other total and utter crap that may help you program, but causes huge amounts of pain when they don''t work."</em></p>\n\n<p>W 2018 roku, po wyjątkowo brutalnym wybuchu na liście — Torvalds wyzywa konkretnych programistów od idiotów — <a href="https://lkml.org/lkml/2018/9/16/167">pisze publiczny list</a>: <em>"Potrzebuję zrobić sobie przerwę. (...) Nigdy nie byłem typem osoby społecznej i poważnie niedoceniałem ile uczuć ranię swoim stylem. Nie chcę szkodzić projektowi"</em>. Bierze przerwę na cztery miesiące. Wraca z kodeksem postępowania, którego sam nie do końca przestrzega. Linux pisze dalej. Co tydzień release candidate. Co dwa-trzy miesiące pełny release. Bez przerwy od 1991 roku.</p>\n\n<p>W 2016 roku, w wywiadzie dla TED, Torvalds <a href="https://www.ted.com/talks/linus_torvalds_the_mind_behind_linux/transcript">mówi wprost</a>: <em>"Nie jestem osobą towarzyską. Jestem inżynierem. (...) Nie dbam o waszą wizję. Nie dbam o waszą strategię. Pokażcie mi kod"</em>. <em>"Talk is cheap. Show me the code"</em> — to zdanie, którego używa od lat na LKML. Stało się hasłem.</p>\n\n<p>Pisze Linuksa na początku — październik 1991 — dla siebie, na własny PC z procesorem 386, z którego chce zrobić unixowe biurko studenckie. Wrzuca w sieci ogłoszenie: <em>"Hello everybody out there using minix — I''m doing a (free) operating system (just a hobby, won''t be big and professional like gnu)"</em>. Komputery które dziś czytają tę stronę WWW, bardzo prawdopodobnie wszystkie w łańcuchu od twojego telefonu przez router do serwera Anthropic, działają na potomkach tego "hobby".</p>\n\n<p>Ten sam mózg, który publicznie pokazuje palca CEO firmy o wartości stu miliardów dolarów, jest mózgiem, który w 1991 roku — sam, w pokoju studenckim w Helsinkach — napisał coś, co dwadzieścia pięć lat później napędza 96% wszystkich serwerów internetu. Nie da się jednego oddzielić od drugiego. Te same cechy — bezpośredniość, brak filtra społecznego, niesamowita zdolność do trzymania w głowie ogromnego grafu zależności pamięciowych jądra systemu, gotowość do publicznej konfrontacji bez kalkulacji kosztów — robią obie rzeczy.</p>\n\n<hr>','\n',char(10)),'Helsinki, 14 June 2012','Aalto Talk. A lecture hall full of students. Linus Torvalds sits in an armchair, wearing a blue T-shirt, with a lapel microphone. He is 42. He lives in Portland, Oregon.',NULL,NULL);
INSERT INTO content_sections VALUES(690,22,685,'heading',2,2,6,'San Francisco, garaż, 1976','san-francisco-garaz-1976','Steve Wozniak ma 25 lat, pracuje w HP. Po godzinach lutuje w garażu w Los Altos. Nie ma na to żadnego biznesplanu. Robi to dla zabawy. Steve Jobs, który jest jego przyjacielem od liceum, ma 21 lat i obowiązek wymyślania, jak na tym zarobić.',6,replace('<p>Steve Wozniak ma 25 lat, pracuje w HP. Po godzinach lutuje w garażu w Los Altos. Nie ma na to żadnego biznesplanu. Robi to dla zabawy. Steve Jobs, który jest jego przyjacielem od liceum, ma 21 lat i obowiązek wymyślania, jak na tym zarobić.</p>\n\n<p>Wozniak <a href="https://www.thehenryford.org/explore/stories-of-innovation/visionaries/steve-wozniak/">projektuje Apple I sam</a>. Hardware. Płytka drukowana. System operacyjny. Język programowania. Wszystko. Pięciokrotnie próbował zaoferować ten projekt swojemu pracodawcy, czyli HP. <a href="https://en.wikipedia.org/wiki/Steve_Wozniak">HP odmówił mu pięć razy.</a> Powiedzieli, że to nie jest produkt dla nich. Jobs, gdy widzi to wszystko, mówi Wozniakowi: <em>"Załóżmy własną firmę. Nawet jeśli się nie uda, możemy powiedzieć wnukom, że mieliśmy własną firmę"</em>. Wozniak sprzedaje swój kalkulator naukowy HP-65, Jobs sprzedaje swojego volkswagena. Zakładają Apple Computer Company 1 kwietnia 1976.</p>\n\n<p>Wozniak projektuje też Apple II — następcę. Sam. Wbudowuje osiem slotów rozszerzeń. Jobs walczy o dwa, bo "jest elegancko". Wozniak walczy o osiem, bo widział na spotkaniach <a href="https://en.wikipedia.org/wiki/Homebrew_Computer_Club">Homebrew Computer Club</a>, jak ludzie chcą wkładać własne rzeczy do komputera. <a href="https://fs.blog/knowledge-project-podcast/outliers-steve-wozniak/">Wozniak wygrywa</a>. Te osiem slotów potem zbuduje cały ekosystem firm robiących karty rozszerzeń dla Apple II i uratuje Apple finansowo na dekadę.</p>\n\n<p>O Wozniaku publicznie mówi się od dawna, że ma cechy autystyczne. Pisarze biograficzni — między innymi <a href="http://www.phy6.org/outreach/books/Wozniak.htm">recenzent jego autobiografii <em>iWoz</em> z 2010 roku</a> — opisują go wprost: <em>"obvious case of Asperger''s autism"</em>. Sam Wozniak nigdy się oficjalnie nie zdiagnozował, ale w wywiadach mówi rzeczy, które mówi człowiek z konkretnym profilem. <a href="https://womenlovetech.com/interview-apple-co-founder-steve-wozniak/">W rozmowie z 2018 roku</a>: <em>"Most of school I had been an outsider. You might call it a nerd. (...) After my plane crash I can''t form new memories. I recognize faces from before, immediately, after 40 years. After the crash — nothing"</em>.</p>\n\n<p>I dodaje: <em>"I decided when I was about 20 that I''m going to do things that entertain me. Games, movies, puzzles, music, jokes. Frowns. That was a tougher one. I''m not going to argue with people, because you have a chance to walk away from people unhappy"</em>. To jest opisowy AuDHD-style coping mechanism. Hyperfokus na zabawę, świadome odsuwanie od konfliktu, projektowanie życia tak, by ograniczyć wymianę emocjonalną do tego, co da się obsłużyć.</p>\n\n<p>Wozniak <a href="https://en.wikipedia.org/wiki/Steve_Wozniak">7 lutego 1981 roku rozbija się samolotem</a>. Beechcraft Bonanza, którego nie był wykwalifikowany pilotować. Strom przy starcie. Samolot stulił się przy ziemi, przebił dwa płoty, wbił w nasyp. Wozniak budzi się i nie pamięta, że jest pilotem. Nie pamięta, kiedy się ożenił. Nie pamięta swojej obecnej żony. Wraca do pamięci stopniowo, ale część jest stracona na zawsze. To nie jest opowieść symboliczna — to są fakty z życia człowieka, który zaprojektował komputer, na którym ty czytasz tę stronę (bo Apple I jest dziadkiem każdego współczesnego MacBooka, a Apple II jest pradziadkiem komputera osobistego jako kategorii).</p>\n\n<hr>','\n',char(10)),'San Francisco, a garage, 1976','Steve Wozniak is 25 and works at HP. After hours, he solders in a garage in Los Altos. He has no business plan for it. He does it for fun. Steve Jobs, his friend since high school, is 21 and has taken on the job of figuring out how to make money from it.',NULL,NULL);
INSERT INTO content_sections VALUES(691,22,685,'heading',2,2,7,'I tu jest najmocniejsze: kategorii nie było','i-tu-jest-najmocniejsze-kategorii-nie-bylo','Ken Thompson urodził się w 1943. Dennis Ritchie w 1941. Donald Knuth w 1938. Richard Stallman w 1953. Steve Wozniak w 1950. Linus Torvalds w 1969. Bill Joy w 1954. Larry Wall, twórca Perla — w 1954. Guido van Rossum — 1956.',7,replace('<p>Ken Thompson urodził się w 1943. Dennis Ritchie w 1941. Donald Knuth w 1938. Richard Stallman w 1953. Steve Wozniak w 1950. Linus Torvalds w 1969. Bill Joy w 1954. Larry Wall, twórca Perla — w 1954. Guido van Rossum — 1956.</p>\n\n<p>Hans Asperger opublikował swój opis "psychopatii autystycznej" — czyli tego, co my dziś nazywamy zespołem Aspergera lub autyzmem wysokofunkcjonującym — <a href="https://en.wikipedia.org/wiki/Hans_Asperger">w 1944 roku</a>. Po niemiecku. W okupowanym Wiedniu. Tekst nie został przetłumaczony na angielski aż do lat 80. <a href="https://en.wikipedia.org/wiki/DSM-III">DSM-III z 1980 roku</a> wprowadza autyzm jako odrębną jednostkę diagnostyczną, ale tylko w jego ciężkich, dziecięcych formach. Asperger jako kategoria diagnostyczna pojawia się dopiero w <a href="https://en.wikipedia.org/wiki/DSM-IV">DSM-IV z 1994 roku</a>.</p>\n\n<p>I teraz najważniejsze. <strong>DSM-IV explicite zakazywał współwystępowania autyzmu i ADHD.</strong> Według kryteriów z 1994 roku, jeśli ktoś miał diagnozę autyzmu, <em>nie mógł</em> mieć diagnozy ADHD. I odwrotnie. Były ze sobą wzajemnie wykluczające się jednostki. Dopiero <a href="https://en.wikipedia.org/wiki/DSM-5">DSM-5</a>, opublikowany w maju 2013 roku, dopuścił współdiagnozę. Czyli kategoria <em>AuDHD</em> — autyzm plus ADHD — w sensie diagnostycznym istnieje od 13 lat.</p>\n\n<p>Co to znaczy konkretnie? Że gdy Ken Thompson pisał Uniksa w sierpniu 1969, kategorii Aspergera nie było w żadnej anglojęzycznej psychiatrii. Gdy Knuth pisał TeXa w 1978, Asperger jeszcze nie pojawił się w DSM. Gdy Stallman zakładał FSF w 1985, autyzm był diagnozowany tylko u dzieci. Gdy Torvalds wypuszczał Linuksa w 1991, ADHD u dorosłych było uznawane za rzadkie i kontrowersyjne. Gdy Wozniak miał wypadek lotniczy w 1981, koncepcji autyzmu wysokofunkcjonującego praktycznie w klinicznym sensie nie istniała.</p>\n\n<p>Wszyscy oni — <em>strukturalnie</em> — nie mogli mieć diagnozy AuDHD, kiedy budowali to, co budowali. Kategoria diagnostyczna nie istniała. Mogli być — i byli nazywani — <em>ekscentrycznymi geniuszami</em>, <em>trudnymi we współpracy</em>, <em>nieobliczalnymi</em>, <em>maniakalnie skupionymi</em>, <em>dziwakami</em>. Ale nie autystycznymi, nie z ADHD, nie AuDHD. Bo tych słów albo nie było, albo nie pasowały do dorosłego inżyniera, albo wzajemnie się wykluczały.</p>\n\n<p>Jeśli się zsumuje to, co o nich wiadomo z biografii, list, wywiadów i obserwacji współpracowników — Stallman śpiący w biurze MIT przez dekady, Torvalds publicznie pokazujący palca firmie wartej miliardy, Knuth zatrzymujący swoje główne dzieło na dziesięć lat by przeprojektować czcionki, Wozniak budujący w pojedynkę komputer w garażu, Thompson piszący system operacyjny w cztery tygodnie podczas gdy żona była u rodziców — pojawia się wzorzec, który dziś nazywamy AuDHD, lub szerzej neuroróżnorodnością.</p>\n\n<p>To nie są <em>wszyscy</em> twórcy IT. To są ludzie, którzy zbudowali <em>fundamenty</em> — kompilatory, jądra, języki niskopoziomowe, podstawowe protokoły. Ludzie, którzy budowali aplikacje na tych fundamentach, byli średnio bardziej zwyczajni. Ale fundamenty robili ci.</p>\n\n<hr>','\n',char(10)),'And here is the strongest part: the category did not exist','Ken Thompson was born in 1943. Dennis Ritchie in 1941. Donald Knuth in 1938. Richard Stallman in 1953. Steve Wozniak in 1950. Linus Torvalds in 1969. Bill Joy in 1954. Larry Wall, the creator of Perl, in 1954. Guido van Rossum in 1956.',NULL,NULL);
INSERT INTO content_sections VALUES(692,22,685,'heading',2,2,8,'I dlaczego to ma znaczenie z perspektywy pamięci','i-dlaczego-to-ma-znaczenie-z-perspektywy-pamieci','Wskaźnik w języku C jest dosłownie liczbą — adresem komórki pamięci. Programista C trzyma w głowie graf wszystkich aktywnych alokacji: które bloki są na stosie, które na stercie, które wskaźniki na nie wskazują, kto je zwolni, kiedy, w jakiej kolejności.',8,replace('<p>Wskaźnik w języku C jest dosłownie liczbą — adresem komórki pamięci. Programista C trzyma w głowie graf wszystkich aktywnych alokacji: które bloki są na stosie, które na stercie, które wskaźniki na nie wskazują, kto je zwolni, kiedy, w jakiej kolejności. Bez tego grafu w głowie kod nie działa. Z błędem w tym grafie program się zawiesza, czasem natychmiast, częściej dwa miesiące po wdrożeniu, na produkcyjnym serwerze, w środku weekendu.</p>\n\n<p>Mózg, który automatycznie kompresuje detale do streszczeń — czyli pamięć typu "<a href="https://en.wikipedia.org/wiki/Weak_central_coherence_theory">central coherence</a>" według klasyfikacji Frith z 1989 roku — w C traci trakcję. Zapomina, który blok zwolnił. Robi błędy <em>use-after-free</em>. Programuje przez schemat: "tu otwieramy plik, robimy coś, zamykamy plik". Ale gdy schemat zawiedzie — gdy między otwarciem a zamknięciem coś rzuci wyjątek i przepływ wykonania pójdzie inną ścieżką — schemat-mózg nie pamięta, że plik został otwarty. Bo schemat to skompresowana wersja: "operacja na pliku". A nie: "plik konkretnie pod adresem 0x7ffe2c800000, otwarty o 14:23:17, jeszcze niezamknięty".</p>\n\n<p>Mózg, który nie kompresuje detali — który trzyma <em>wskaźniki</em> do konkretnych zdarzeń, miejsc, faktów, w pełnej rozdzielczości, indeksowanych po anomalii a nie po kategorii — w C czuje się jak w domu. Bo <em>tak właśnie pamięta świat</em>. To jest pamięć, którą Dinah Murray, autystyczna badaczka, opisała w 1992 roku jako <a href="https://monotropism.org/">monotropizm</a>: uwaga skupia się głęboko na jednym, kosztem szerokiego pola; szczegóły są przechowywane w pełnej rozdzielczości; przełączanie kontekstu jest kosztowne, ale wewnątrz kontekstu — pamięć jest niemal absolutna. Przeniesione do programowania: idealna konstytucja umysłu do pisania jąder systemów operacyjnych, gdzie cały graf zależności pamięciowych musi siedzieć w głowie programisty, bo kompilator nie pomoże.</p>\n\n<p>I jest też druga warstwa. ADHD-mózg ma <a href="https://www.additudemag.com/working-memory-powers-executive-function/">deficyt pamięci roboczej</a> — to klasyczne odkrycie Russella Barkleya z 1997 roku. Ale ma też mechanizm hyperfokusu: gdy temat jest interesujący, gdy uruchamia się dopaminergiczna nagroda, pamięć robocza działa w zupełnie innym trybie. Programista ADHD nie potrafi pamiętać, gdzie zostawił klucze (klucze są nudne), ale potrafi przez 16 godzin bez przerwy debugować problem z race condition w kernelu (race condition jest fascynujący). To jest dokładnie ten profil, który Thompson opisał o sobie w wywiadzie z 1989 — pisał Uniksa w cztery tygodnie, jeden tydzień na komponent, bo żona była u rodziców i nie miał innych obowiązków. Klasyczny opis ADHD-hyperfokusu w warunkach pełnego skupienia.</p>\n\n<p>AuDHD — autyzm plus ADHD — to mózg, który ma <em>jedno i drugie</em>. Pamięć pointer-based jak w autyzmie (pełna rozdzielczość detali, indeksowanie po anomalii), plus dynamika ADHD (silny hyperfokus, ale tylko gdy temat zapali). To jest dokładnie konstytucja umysłowa, która pisze TeXa przez dziesięć lat zamiast roku. Która nie wychodzi z biura MIT przez dziesięciolecia. Która projektuje cały komputer sama. Która pisze jądro systemu operacyjnego w pokoju studenckim. I która potem publicznie pokazuje palca CEO NVIDIA.</p>\n\n<hr>','\n',char(10)),'And why this matters from the perspective of memory','A pointer in C is literally a number — the address of a memory cell. A C programmer keeps a graph of all active allocations in their head: which blocks are on the stack, which are on the heap, which pointers refer to them, who will free them, when, and in what order.',NULL,NULL);
INSERT INTO content_sections VALUES(693,22,685,'heading',2,2,9,'JavaScript jako wyjątek potwierdzający','javascript-jako-wyjatek-potwierdzajacy','I teraz najważniejszy kontrprzykład. Brendan Eich w maju 1995 roku dostaje 10 dni na zaprojektowanie języka skryptowego do przeglądarki Netscape Navigator 2.0. Pisze prototyp w dziesięć dni . Pełna integracja zajmuje kilka miesięcy.',9,replace('<p>I teraz najważniejszy kontrprzykład. Brendan Eich w maju 1995 roku dostaje 10 dni na zaprojektowanie języka skryptowego do przeglądarki Netscape Navigator 2.0. <a href="https://thehistoryoftheweb.com/the-10-day-programming-language-is-a-myth/">Pisze prototyp w dziesięć dni</a>. Pełna integracja zajmuje kilka miesięcy. Język nazywa się Mocha, potem LiveScript, w grudniu 1995 — w wyniku marketingowej umowy z Sun Microsystems — ostatecznie <a href="https://en.wikipedia.org/wiki/JavaScript">JavaScript</a>. Eich w wywiadach przyznawał: <em>"byłem pod presją działu marketingu, żeby wyglądał jak Java, ale nie urósł zbyt wielki dla swojej rangi… miał być głupim młodszym braciszkiem"</em>.</p>\n\n<p>JavaScript ma fundamentalne dziwactwa semantyczne, których nie da się usunąć ze względu na kompatybilność wsteczną. <code>[] + [] === ""</code>. <code>null == undefined</code> jest prawdą, ale <code>null !== undefined</code> też jest prawdą. <code>NaN !== NaN</code>. <code>typeof null === "object"</code>. Filozofia języka: <em>fail silently, do something</em>. Strona ma się załadować, klient ma coś zobaczyć, lepiej narysować niewłaściwy ekran niż nie narysować nic. To jest filozofia, która wygrała komercyjnie — JavaScript jest dziś najczęściej używanym językiem świata Web-u, TypeScript (jego nadzbiór z dodaną typizacją) jest najczęściej używanym językiem na <a href="https://github.blog/news-insights/octoverse/octoverse-2025/">GitHubie ogółem od 2025</a>.</p>\n\n<p>I teraz najmocniejszy fakt. <strong>Silniki JavaScriptu — V8 w Chrome, SpiderMonkey w Firefoxie, JavaScriptCore w Safari — są napisane w C++, nie w JavaScripcie</strong>. Wszystkie trzy. <a href="https://v8.dev/">V8</a> ma kilkaset tysięcy linii C++. SpiderMonkey — historycznie w C i C++. JavaScriptCore — w C++. Każdy z tych silników kompiluje JavaScript w locie do kodu maszynowego, wykonuje go, zarządza pamięcią. Same nie mogłyby być napisane w JavaScripcie, bo JavaScript nie ma deterministycznej semantyki potrzebnej do napisania kompilatora. Specyfikacja <a href="https://262.ecma-international.org/">ECMAScript</a> ma setki stron, z których znaczna część jest oznaczona jako <em>implementation-defined</em> — czyli trzy główne silniki mogą się różnić w zachowaniu i wszystkie trzy są zgodne ze standardem.</p>\n\n<p>Programista JavaScriptu, gdy jego kod nie działa, dostaje radę: <em>spróbuj inaczej, zobacz co Chrome robi, sprawdź StackOverflow</em>. Programista C, gdy jego kod nie działa, dostaje radę: <em>uruchom valgrind, sprawdź mapę pamięci, prześledź każde wywołanie malloc</em>. To nie są te same dyscypliny umysłowe. JavaScript jest językiem, który NT-mózg może pisać <em>wygodnie</em> — bo nie wymaga trzymania w głowie pełnego grafu. Wymaga schematu: <em>kliknięcie wywołuje funkcję, która coś robi z DOM-em</em>. Schemat-mózg umie pracować na schematach.</p>\n\n<p>JavaScript jest językiem skalowania społecznego — językiem, w którym po dwumiesięcznym kursie można zatrudnić kogoś, kto napisze działającą stronę. C jest językiem, w którym po dwumiesięcznym kursie nie można zatrudnić nikogo, bo kandydat zrobi w pierwszym tygodniu trzy buffer overflows i otworzy bramę dla każdego skanera bezpieczeństwa w Internecie.</p>\n\n<p>To nie znaczy, że JavaScript jest gorszy. To znaczy, że jest <em>czym innym</em>. Jest interfejsem. Tak jak Python (z 1991 roku, Guido van Rossum) jest interfejsem do bibliotek pisanych w C — <a href="https://numpy.org/">NumPy</a>, Pandas, TensorFlow, PyTorch, wszystkie mają jądra w C lub C++. Python pozwala programiście kompetentnemu w domenie problemu (statystyka, biologia, fizyka) wywoływać kod napisany przez kogoś kompetentnego w architekturze maszyny. Te dwa typy kompetencji rzadko mieszkają w jednej głowie.</p>\n\n<hr>','\n',char(10)),'JavaScript as the exception that proves the rule','And now the most important counterexample. In May 1995 Brendan Eich is given 10 days to design a scripting language for the Netscape Navigator 2.0 browser. He writes the prototype in ten days. Full integration takes several months.',NULL,NULL);
INSERT INTO content_sections VALUES(694,22,685,'heading',2,2,10,'Co to znaczy z perspektywy 2026 roku','co-to-znaczy-z-perspektywy-2026-roku','Kiedy w marcu 2026 roku dostaje się formalną diagnozę AuDHD w Krakowie, w gabinecie psychiatry, można zauważyć, że kategoria, która jest nadawana, ma — jako diagnostyczna jednostka — 13 lat.',10,replace('<p>Kiedy w marcu 2026 roku dostaje się formalną diagnozę AuDHD w Krakowie, w gabinecie psychiatry, można zauważyć, że kategoria, która jest nadawana, ma — jako <em>diagnostyczna jednostka</em> — 13 lat. Że zanim DSM-5 ją dopuścił, ludzie z tą architekturą mózgu po prostu istnieli, byli różnie nazywani, i — jeśli akurat trafili w odpowiednią dekadę i odpowiednią dziedzinę — pisali Uniksa, projektowali komputery, walczyli o wolność oprogramowania.</p>\n\n<p>Cała dziedzina, którą znamy jako "fundamenty IT", jest zbudowana przez ludzi, którzy w obecnym systemie diagnostycznym byliby zaklasyfikowani jako neuroróżnorodni. Nie z przypadku. Bo dziedzina <em>tego wymaga</em>. Trzymania w głowie ogromnego grafu zależności pamięciowych. Wielogodzinnego hyperfokusu. Indeksowania po anomalii zamiast po kategorii. Ignorowania presji społecznej, która mówi "to się nie da, to za trudne, to nie tak działa".</p>\n\n<p>Linus Torvalds nie napisałby Linuksa, gdyby był towarzyski, gdyby dbał o uczucia kolegów, gdyby umiał odpuścić techniczny detal dla świętego spokoju w zespole. Stallman nie zbudowałby ruchu wolnego oprogramowania, gdyby był elastyczny ideologicznie. Knuth nie napisałby TeX-a, gdyby umiał zaakceptować "wystarczająco dobre" czcionki w drugim wydaniu książki. Wozniak nie zaprojektowałby Apple I sam, gdyby był ekipą zarządczą.</p>\n\n<p>To są ludzie, których cechy w 2026 roku często prowadzą do wykluczenia z rynku pracy, chyba że przypadkowo trafią do dziedziny, która te cechy <em>premiuje</em>. Niskopoziomowa informatyka jest taką dziedziną. Nie z powodu inkluzywności. Z powodu strukturalnego wymogu.</p>\n\n<p>I jeszcze jedno. Wszyscy oni — Thompson, Ritchie, Knuth, Stallman, Torvalds, Wozniak, van Rossum — pracowali w epoce, w której komputery <em>były wymierne</em>. Każdy bajt miał adres. Każda funkcja miała koszt. Każda alokacja miała odpowiadające zwolnienie. Pamięć była fizyczna. Maszyna była widoczna. Kompilator pomagał, ale nie ratował z błędów.</p>\n\n<p>Współczesne programowanie aplikacyjne ukrywa to wszystko. Programista JavaScriptu nie wie, ile pamięci zajmuje obiekt. Programista Pythona nie wie, kiedy garbage collector startuje. Programista Java nie wie, na jakiej maszynie kod się fizycznie wykonuje. Te warstwy abstrakcji są napisane przez ludzi, którzy <em>wiedzieli</em> — przez Thompsona, Ritchiego, Stallmana, Torvaldsa. Są zapisem ich mózgów, sposobem, w jaki oni pamiętali świat.</p>\n\n<p>Gdy używasz dziś dowolnego komputera, telefonu, serwera — od momentu, w którym naciskasz klawisz, do momentu, w którym zobaczysz literę na ekranie — przebiegasz przez stos warstw, z których każda jest zapisem pamięci jakiegoś autystycznego, ADHD-owego, AuDHD-owego mózgu. Linus pisał kernel. Ritchie pisał C. Thompson pisał Unix. Stallman pisał gcc, gdb, emacs. Wozniak projektował hardware. Knuth pisał TeX, na którym składa się każdy artykuł naukowy o twojej diagnozie.</p>\n\n<p>To nie są geniusze, którzy <em>mimo</em> swojego dziwactwa zbudowali IT. To są ludzie, którzy <em>dlatego, że</em> mieli te konkretne mózgi, mogli zbudować to, co zbudowali. Świat informatyki, w której żyjesz, jest fizyczną manifestacją grupy ludzkich umysłów o konkretnym profilu poznawczym — profilu, który dziś nazywa się neuroróżnorodnością, a wczoraj nie miał nazwy w ogóle.</p>\n\n<div class="meta">\n  <p>Wersja: 2.00 · Data: 2026-04-29 · Godzina: 06:50 (Europe/Warsaw)</p>\n  <p>Zmiana w 2.00: pełne przepisanie. Wcześniejsze wersje (1.00, 1.01, 1.02) były pisane jako esej akademicki ze streszczeniem, tezami i strukturą §1-§9. Ta wersja to opowieść — sceny, postaci, konkrety biograficzne. Tezy są w warstwie narracyjnej, nie deklaratywnej.</p>\n  <p>Autorstwo: Maciej Tora (ur. 18.09.1980), opracowanie wspólnie z Claude Opus 4.7 (Anthropic).</p>\n  <p>Status: tekst do dalszej redakcji. Linki do źródeł w treści. Niektóre fakty (zwłaszcza biograficzne anegdoty) wymagają dalszej weryfikacji u źródeł pierwotnych.</p>\n</div>','\n',char(10)),'What this means from the perspective of 2026','When, in March 2026, someone receives a formal AuDHD diagnosis in a psychiatrist''s office in Kraków, it is worth noticing that the category being assigned is, as a diagnostic entity, 13 years old.',NULL,NULL);
INSERT INTO content_sections VALUES(695,23,NULL,'heading',1,1,1,'ADHD i pomaganie kosztem siebie','adhd-i-pomaganie-kosztem-siebie','Teza, mechanizm, wykorzystanie społeczne',1,replace('<p class="subtitle">Teza, mechanizm, wykorzystanie społeczne</p>\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'ADHD and helping at your own expense','The thesis, the mechanism, and social exploitation',NULL,NULL);
INSERT INTO content_sections VALUES(696,23,695,'heading',2,2,2,'Teza w postaci kompaktowej','teza-w-postaci-kompaktowej','Osoby z ADHD mają większą potrzebę pomagania innym — w szczególności kosztem siebie — niż osoby neurotypowe.',2,replace('<!-- ═══════════════════════════════════════════ -->\n\n<div class="teza-box">\n<p>Osoby z ADHD mają większą potrzebę pomagania innym — w szczególności kosztem siebie — niż osoby neurotypowe.</p>\n\n<p>Mechanizm jest neurobiologiczny, nie charakterologiczny. Składają się na niego trzy zachodzące na siebie elementy: nadwrażliwość na odrzucenie społeczne, stroma krzywa dyskontowania nagrody w czasie (silna preferencja natychmiastowej nagrody nad odłożoną), oraz słabsza regulacja własnych granic w konfrontacji z bezpośrednią potrzebą drugiej osoby.</p>\n\n<p>Osoby neurotypowe — często nieświadomie — wykorzystują tę asymetrię. Prośba o pomoc skierowana do osoby z ADHD ma istotnie większą szansę na natychmiastową realizację niż ta sama prośba skierowana do osoby neurotypowej w tej samej sytuacji.</p>\n</div>\n\n<div class="przyklad">\nTypowa scena: w zlewie ADHDowca stoją naczynia z trzech tygodni. Dzwoni koleżanka, że za chwilę ma gości i nie zdąży pozmywać. ADHDowiec jedzie do niej, zmywa wszystko od ręki, wraca do domu, własny zlew zostaje na kolejny tydzień.\n</div>\n\n<hr class="section-divider">\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'The thesis in compact form','People with ADHD have a stronger need to help others — especially at their own expense — than neurotypical people.',NULL,NULL);
INSERT INTO content_sections VALUES(697,23,695,'heading',2,2,3,'Rozwinięcie','rozwiniecie','Omówienie zagadnienia „Rozwinięcie” w kontekście opracowania „ADHD i pomaganie kosztem siebie — teza i mechanizm”.',3,'<!-- ═══════════════════════════════════════════ -->','Elaboration','Discussion of “Elaboration” in the context of “ADHD and helping at your own expense — thesis and mechanism”.',NULL,NULL);
INSERT INTO content_sections VALUES(698,23,697,'heading',3,3,4,'Mechanizm 1: nadwrażliwość na odrzucenie społeczne','mechanizm-1-nadwrazliwosc-na-odrzucenie-spoleczne','RSD (Rejection Sensitive Dysphoria, dysforia z nadwrażliwości na odrzucenie) to klinicznie opisany fenomen, którego rdzeń stanowi nieproporcjonalnie silna reakcja emocjonalna — bólowa, fizyczna, natychmiastowa — na rzeczywiste lub tylko spostrzeżone…',4,replace('<p>RSD (Rejection Sensitive Dysphoria, dysforia z nadwrażliwości na odrzucenie) to klinicznie opisany fenomen, którego rdzeń stanowi nieproporcjonalnie silna reakcja emocjonalna — bólowa, fizyczna, natychmiastowa — na rzeczywiste lub tylko spostrzeżone odrzucenie, krytykę albo dezaprobatę. Nie jest osobną jednostką w DSM-5, ale w literaturze klinicznej i jakościowej jest dobrze udokumentowany jako element emocjonalnej dysregulacji u dorosłych z ADHD.</p>\n\n<p>W praktyce funkcjonuje to tak: osoba z RSD nieustannie skanuje otoczenie pod kątem sygnałów dezaprobaty. Każda prośba o pomoc, której się nie spełni, jest w przeczuciu osoby z RSD równoznaczna z odrzuceniem — utratą sympatii, statusu, miejsca w grupie. Koszt powiedzenia „nie" jest subiektywnie ogromny i natychmiastowy. Koszt powiedzenia „tak" — koszt zaniedbanego własnego obowiązku — jest abstrakcyjny i odłożony.</p>\n\n<p>People-pleasing nie jest tu cechą charakteru ani dobrocią serca. Jest strategią obronną: jeśli będę niezastąpiony i bezbłędny, nikt nie będzie miał powodu mnie odrzucić. Mechanizm znany pod tą nazwą jest jakościowo opisany m.in. w badaniu Bedrossian i wsp. (2024).</p>','\n',char(10)),'Mechanism 1: hypersensitivity to social rejection','RSD (Rejection Sensitive Dysphoria) is a clinically described phenomenon whose core is a disproportionately intense emotional reaction — painful, physical, immediate — to actual or merely perceived…',NULL,NULL);
INSERT INTO content_sections VALUES(699,23,697,'heading',3,3,5,'Mechanizm 2: stroma krzywa dyskontowania nagrody w czasie','mechanizm-2-stroma-krzywa-dyskontowania-nagrody-w-czasie','Drugie tłumaczenie — niezależne od pierwszego, choć działa w tę samą stronę — pochodzi z teorii wykonawczej Russella Barkley''a (1997) i z dziesiątek replikacji w badaniach delay discounting (Sonuga-Barke, Barkley i wsp. 2001; metaanaliza Marx i wsp. 2021).',5,replace('<p>Drugie tłumaczenie — niezależne od pierwszego, choć działa w tę samą stronę — pochodzi z teorii wykonawczej Russella Barkley''a (1997) i z dziesiątek replikacji w badaniach <em>delay discounting</em> (Sonuga-Barke, Barkley i wsp. 2001; metaanaliza Marx i wsp. 2021). ADHD charakteryzuje się systemowo silniejszą preferencją natychmiastowej, mniejszej nagrody nad odłożoną, większą.</p>\n\n<p>W kontekście pomagania to znaczy: pomóc komuś teraz — nagroda jest natychmiastowa. Wdzięczność, uśmiech, wymiana energii społecznej, dopaminowy zysk z bycia potrzebnym, ulga w napięciu RSD. Wszystko dostarczone w ciągu sekund. Pozmywać własne naczynia — nagroda jest abstrakcyjna i odłożona. Czysty zlew? Kiedyś. Spokój ducha? Może. Korzyść? Niejasna, rozmyta w czasie, niewidoczna dla nikogo.</p>\n\n<p>Mózg ADHD nie wybiera między „dobrocią" a „egoizmem". Wybiera między nagrodą za 30 sekund a nagrodą za 30 minut. Dla układu, który mocno dyskontuje czas, to nie jest wybór — to jest oczywistość. Sirois i Pychyl (2013) opisali ten sam mechanizm dla prokrastynacji: odłożenie czegoś własnego to natychmiastowa regulacja krótkoterminowego nastroju, kosztem przyszłego siebie. Pomaganie innym jest jego lustrzaną, prospołeczną wersją.</p>','\n',char(10)),'Mechanism 2: a steep temporal reward-discounting curve','The second explanation — independent of the first, though operating in the same direction — comes from Russell Barkley''s executive-function theory (1997) and dozens of replications in delay-discounting research (Sonuga-Barke, Barkley et al. 2001; meta-analysis by Marx et al. 2021).',NULL,NULL);
INSERT INTO content_sections VALUES(700,23,697,'heading',3,3,6,'Mechanizm 3: słabsza regulacja granic w konfrontacji','mechanizm-3-slabsza-regulacja-granic-w-konfrontacji','Trzeci element to słabsza zdolność do zatrzymania automatycznej reakcji „tak" w konfrontacji z konkretną, bezpośrednią prośbą. To wynika z deficytów w hamowaniu reakcji — jednego z czterech obszarów wykonawczych w modelu Barkley''a.',6,replace('<p>Trzeci element to słabsza zdolność do zatrzymania automatycznej reakcji „tak" w konfrontacji z konkretną, bezpośrednią prośbą. To wynika z deficytów w hamowaniu reakcji — jednego z czterech obszarów wykonawczych w modelu Barkley''a. „Pomyślę o tym i odezwę się jutro" wymaga zatrzymania impulsu, wycofania uwagi z natychmiastowej sytuacji społecznej, przeniesienia jej na własne potrzeby. Każdy z tych kroków u osoby z ADHD jest energetycznie kosztowniejszy niż u osoby neurotypowej.</p>\n\n<p>Efekt: w abstrakcji, na spokojnie, w domu wieczorem osoba z ADHD wie, że powinna stawiać granice. W realnym momencie, twarzą w twarz, kiedy koleżanka mówi „weź, ratuj", system wykonawczy nie nadąża. Odpowiedź „tak" wychodzi szybciej niż refleksja, czy ją chce się dać.</p>','\n',char(10)),'Mechanism 3: weaker boundary regulation in confrontation','The third element is a weaker ability to stop the automatic “yes” response when faced with a concrete, direct request. This follows from deficits in response inhibition — one of the four executive domains in Barkley''s model.',NULL,NULL);
INSERT INTO content_sections VALUES(701,23,697,'heading',3,3,7,'Asymetria, którą neurotypowi nieświadomie eksploatują','asymetria-ktora-neurotypowi-nieswiadomie-eksploatuja','Te trzy mechanizmy razem produkują systemową asymetrię: w sytuacji „A potrzebuje pomocy od B" prawdopodobieństwo zgody A-z-ADHD jest istotnie wyższe niż A-neurotypowego, niezależnie od stanu własnych spraw A.',7,replace('<p>Te trzy mechanizmy razem produkują systemową asymetrię: w sytuacji „A potrzebuje pomocy od B" prawdopodobieństwo zgody A-z-ADHD jest istotnie wyższe niż A-neurotypowego, niezależnie od stanu własnych spraw A.</p>\n\n<p>Większość neurotypowych osób, które z tego korzystają, nie robi tego cynicznie. Po prostu obserwują, że pewne osoby zawsze pomagają, i naturalnie wracają z prośbami właśnie do nich. To jest racjonalna strategia społeczna: kierować prośby tam, skąd najczęściej dostaje się „tak". Tylko że dla ADHDowca koszt każdego „tak" jest większy niż dla neurotypowego dawcy w tej samej sytuacji. Bilans wychodzi ujemny w jedną stronę, dodatni w drugą.</p>\n\n<p>Mechanizm jest cichy, bo nie zawiera świadomej manipulacji. Z perspektywy proszącego — koleżanka po prostu wie, że Maciek pomoże. Z perspektywy proszonego — Maciek po prostu nie potrafi odmówić. Z perspektywy zewnętrznej — Maciek jest „taką dobrą osobą", a koleżanka „ma szczęście do znajomych". Z perspektywy bilansu energetycznego ADHD — Maciek systematycznie traci.</p>','\n',char(10)),'The asymmetry that neurotypical people exploit unconsciously','Together, these three mechanisms produce a systemic asymmetry: in a situation where “A needs help from B”, the probability that a person with ADHD will agree is significantly higher than for a neurotypical person, regardless of the state of their own affairs.',NULL,NULL);
INSERT INTO content_sections VALUES(702,23,697,'heading',3,3,8,'Co z tym zrobić','co-z-tym-zrobic','Mechanizm 1 da się leczyć: leczenie ADHD farmakologiczne (stymulanty) i terapia ukierunkowana na RSD redukują intensywność reakcji na odrzucenie.',8,replace('<p>Mechanizm 1 da się leczyć: leczenie ADHD farmakologiczne (stymulanty) i terapia ukierunkowana na RSD redukują intensywność reakcji na odrzucenie. Mechanizm 2 daje się częściowo kompensować przez świadome reguły: „nie odpowiadam na prośby przez 24 godziny", „każdą prośbę o pomoc zapisuję, nie odpowiadam od razu". Mechanizm 3 jest najtrudniejszy — wymaga wytrenowania pauzy między bodźcem (prośbą) a reakcją (odpowiedzią).</p>\n\n<p>Praktycznie najskuteczniejszą interwencją bywa wprowadzenie sztucznego opóźnienia. Nie „nie", tylko „nie teraz — odezwę się wieczorem". To kupuje czas, w którym system wykonawczy zdąży policzyć faktyczny koszt. W ośmiu na dziesięć przypadków wieczorne „nie" jest łatwiejsze niż natychmiastowe „nie" — bo emocjonalna stawka RSD opadła, a fakt własnego zmęczenia stał się widoczny.</p>\n\n<div class="nb">\n<strong>Co nie jest częścią tej tezy.</strong> Literatura badawcza dotycząca <em>prosocial behaviour</em> u dzieci z ADHD jest mieszana. Część badań (Velő i wsp. 2021) raportuje deficyty w zachowaniach prospołecznych mierzonych przez rodziców. Inne pokazują wyższe oceny altruizmu w samoocenie. Teza powyżej dotyczy <strong>dorosłych z ADHD i mechanizmu people-pleasing</strong>, nie ogólnego altruizmu czy empatii. To są dwie różne rzeczy. Pomaganie kosztem siebie u dorosłych z ADHD jest reakcją regulacyjną na RSD plus produktem dyskontowania w czasie — niekoniecznie świadomym altruistycznym wyborem.\n</div>\n\n<hr class="section-divider">\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'What to do about it','Mechanism 1 can be treated: pharmacological treatment of ADHD (stimulants) and therapy targeting RSD reduce the intensity of reactions to rejection.',NULL,NULL);
INSERT INTO content_sections VALUES(703,23,695,'heading',2,2,9,'Źródła','zrodla','Barkley, R. A. (1997). Behavioral inhibition, sustained attention, and executive functions: Constructing a unifying theory of ADHD. Psychological Bulletin , 121(1), 65–94.',9,replace('<!-- ═══════════════════════════════════════════ -->\n\n<ol class="zrodla">\n\n<li>\n<strong>Barkley, R. A. (1997).</strong> Behavioral inhibition, sustained attention, and executive functions: Constructing a unifying theory of ADHD. <em>Psychological Bulletin</em>, 121(1), 65–94.<br>\nDOI: <a href="https://doi.org/10.1037/0033-2909.121.1.65">10.1037/0033-2909.121.1.65</a><br>\nPubMed: <a href="https://pubmed.ncbi.nlm.nih.gov/9000892/">9000892</a><br>\n[mechanizm 2 i 3 — hamowanie reakcji, funkcje wykonawcze, dyskontowanie w czasie]\n</li>\n\n<li>\n<strong>Sirois, F., &amp; Pychyl, T. (2013).</strong> Procrastination and the priority of short-term mood regulation: Consequences for future self. <em>Social and Personality Psychology Compass</em>, 7(2), 115–127.<br>\nDOI: <a href="https://doi.org/10.1111/spc3.12011">10.1111/spc3.12011</a><br>\n[lustrzane odbicie mechanizmu 2 — krótkoterminowa regulacja nastroju kosztem przyszłego siebie]\n</li>\n\n<li>\n<strong>Marx, I., Hacker, T., Yu, X., Cortese, S., &amp; Sonuga-Barke, E. (2021).</strong> ADHD and the Choice of Small Immediate Over Larger Delayed Rewards: A Comparative Meta-Analysis of Performance on Simple Choice-Delay and Temporal Discounting Paradigms. <em>Journal of Attention Disorders</em>, 25(2), 171–187.<br>\nDOI: <a href="https://doi.org/10.1177/1087054718772138">10.1177/1087054718772138</a><br>\n[metaanaliza wspierająca mechanizm 2 — silniejsza preferencja natychmiastowej nagrody w ADHD]\n</li>\n\n<li>\n<strong>Bedrossian, L., et al. (2024).</strong> The lived experience of rejection sensitivity in ADHD — a qualitative exploration. <em>medRxiv</em> (preprint).<br>\nDOI: <a href="https://doi.org/10.1101/2024.11.16.24317418">10.1101/2024.11.16.24317418</a><br>\nPMC: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12822938/">PMC12822938</a><br>\n[mechanizm 1 — fenomenologiczny opis RSD u dorosłych z ADHD, mechanizm maskowania jako reakcji ochronnej]\n</li>\n\n<li>\n<strong>Velő, S., Keresztény, Á., Ferenczi-Dallos, G., Pump, L., Móra, K., &amp; Balázs, J. (2021).</strong> The Association between Prosocial Behaviour and Peer Relationships with Comorbid Externalizing Disorders and Quality of Life in Treatment-Naïve Children and Adolescents with Attention Deficit Hyperactivity Disorder. <em>Brain Sciences</em>, 11(4), 475.<br>\nDOI: <a href="https://doi.org/10.3390/brainsci11040475">10.3390/brainsci11040475</a><br>\nPMC: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8069734/">PMC8069734</a><br>\n[kontrapunkt do ramki „Co nie jest częścią tej tezy" — literatura badawcza nie jest jednoznaczna co do prosocial behaviour]\n</li>\n\n<li>\n<strong>Dodson, W. (2018, regularnie aktualizowane).</strong> How ADHD Ignites Rejection Sensitive Dysphoria. <em>ADDitude Magazine</em>.<br>\nURL: <a href="https://www.additudemag.com/rejection-sensitive-dysphoria-and-adhd/">additudemag.com/rejection-sensitive-dysphoria-and-adhd/</a><br>\n[oryginalne kliniczne sformułowanie RSD w kontekście ADHD; źródło niepoddane peer-review, ale historycznie pierwsze i powszechnie cytowane w literaturze klinicznej]\n</li>\n\n</ol>\n\n<div class="footer-meta">\n  adhd-pomaganie-kosztem-siebie-v01.00-2026-05-14.html · wersja 01.00 · 2026-05-14, 16:55 CEST<br>\n  stworzony z pomocą Claude (Anthropic) · Claude Opus 4.7 (claude-opus-4-7)<br>\n  rodzaj: notatka konceptualna (teza + rozwinięcie + źródła)\n</div>\n\n</div>','\n',char(10)),'Sources','Barkley, R. A. (1997). Behavioral inhibition, sustained attention, and executive functions: Constructing a unifying theory of ADHD. Psychological Bulletin, 121(1), 65–94.',NULL,NULL);
INSERT INTO content_sections VALUES(704,24,NULL,'heading',1,1,1,'Co mówi Appendix 1 — po ludzku','co-mowi-appendix-1-po-ludzku','Dwadzieścia prac z lat 2008–2026, przeczytanych jako jedna historia — tym razem z liczbami, ale liczbami przetłumaczonymi na ludzki. Wersja 02.00 powstała po sięgnięciu do treści samych badań, nie tylko ich tytułów.',1,replace('<p>Dwadzieścia prac z lat 2008–2026, przeczytanych jako jedna historia — tym razem z liczbami, ale liczbami przetłumaczonymi na ludzki. Wersja 02.00 powstała po sięgnięciu do treści samych badań, nie tylko ich tytułów.</p>\n\n<p>Zaczęło się od bliźniąt. W 2008 roku dwa zespoły, niezależnie od siebie, sprawdziły na tysiącach par bliźniąt prostą rzecz: czy skłonność do bycia „adehadowym" i skłonność do bycia „autystycznym" dziedziczą się osobno, czy razem. Wyszło: w dużej części razem — u dzieci wspólne geny pokrywały mniej więcej połowę zbieżności, a u młodych dorosłych, pytanych już o samych siebie, około siedmiu dziesiątych. Siedem dziesiątych wspólnego losowania to nie jest „czasem idzie w parze" — to jest jedna talia kart rozdawana na dwa sposoby. Pikanteria była taka, że obowiązujące wtedy przepisy diagnostyczne wprost zabraniały rozpoznania obu rzeczy u jednej osoby — lekarz musiał wybrać. Papier kazał wybierać, geny mówiły, że wybierać nie ma z czego.</p>\n\n<p>Potem sprawdzono rodziny. Jeśli dziecko ma jedno, to u rodziców i rodzeństwa częściej znajdzie się drugie — i odwrotnie: oba zestawy cech wędrują przez rodziny razem, nie osobno. A w 2018 roku policzono to na danych obejmujących niemal dwa miliony osób — praktycznie całą młodą Szwecję. Wynik układa się w drabinę, której szczeble mówią same za siebie: u tej samej osoby autyzm podnosi szansę na ADHD ponad dwudziestokrotnie; u bliźniaka jednojajowego osoby z autyzmem — prawie osiemnastokrotnie; u zwykłego brata czy siostry — czteroipółkrotnie; im dalsza krew, tym słabiej. Ryzyko maleje dokładnie w rytmie ubywających wspólnych genów — a to jest podpis dziedziczenia, nie wychowania, bo wychowanie nie wie, kto jest bliźniakiem jednojajowym, a kto dwujajowym.</p>\n\n<p>W 2022 roku genetycy zeszli na sam dół. Na ponad trzydziestu czterech tysiącach przebadanych osób znaleziono siedem miejsc w genach wspólnych dla obu skłonności — i pięć miejsc, które je różnicują. Te pięć działa jak zwrotnice: ten sam wariant, który popycha w stronę jednego obrazu, odciąga od drugiego. Stąd wspólny korzeń i dwa pnie — teraz już nie jako metafora, tylko jako mapa. I jedno zdanie z tej pracy warte zapamiętania osobno: ludzie, u których rozpoznano obie rzeczy naraz, niosą podwójny ładunek — pełne genetyczne obciążenie jednym i pełne drugim, nie połówki.</p>\n\n<p>Ile tego jest? Kiedy zebrano razem wyniki wszystkich badań świata, wyszło, że wśród osób w spektrum autyzmu ADHD ma mniej więcej cztery osoby na dziesięć — dokładnie trzydzieści osiem i pół na sto. To nie jest rzadki zbieg okoliczności; to jest prawie co druga osoba. Dla skali: w ogólnej populacji ADHD dotyczy około pięciu–siedmiu osób na sto, autyzm mniej niż jednej do jednej. A u dzieci, które mają obie rzeczy naraz, trudności nie wyglądają jak dwie listy objawów zszyte razem — mają własny, osobny kształt, którego nie zna nikt, kto patrzył tylko na jedną połowę. I ten kształt widać od urodzenia: szwedzkie badanie, które prowadziło jedną grupę dzieci od porodówki do dorosłości, mogło porównać trzy losy — samo ADHD, sam autyzm i oba naraz — nie z pamięci pacjentów, tylko z zapisów zbieranych na bieżąco przez ćwierć wieku.</p>\n\n<p>Najciekawsze — i najbliższe domu — zaczyna się przy dorosłych. W Tokio wzięto sześćdziesięciu trzech dorosłych z rozpoznanym ADHD, bez żadnej diagnozy autyzmu, i posadzono ich przed badaczem z tym samym obserwacyjnym badaniem, którym na świecie rozpoznaje się spektrum — nie ankieta, żywa rozmowa oceniana przez przeszkolone oko. Punktowali wyraźnie wyżej niż ludzie bez diagnoz na większości sprawdzanych rzeczy, a nierzadko tyle samo, co osoby z rozpoznanym autyzmem; autorzy piszą wprost, że różnica bywa różnicą stopnia, nie rodzaju. Świeży przegląd wszystkich takich badań, z 2026 roku, mówi to samo w skali świata: cechy spektrum u dorosłych z ADHD to zjawisko masowe i notorycznie przeoczane — a osobne badanie z Irlandii dodaje, że te cechy nie znikają z wiekiem, tylko idą z człowiekiem dalej i mają znaczenie dla tego, jak mu się wiedzie.</p>\n\n<p>Prześledzono też, jak obie wiązki cech rosną. Czternaście tysięcy dzieci z okolic Bristolu, obserwowanych od urodzenia do dwudziestego piątego roku życia: przebiegi splatają się, jedna wiązka ciągnie drugą, a grupy z wysokim, utrzymującym się poziomem obu miały potem, na progu dorosłości, częściej problemy z nauką, pracą i używkami — i wyższy odziedziczony ładunek genetyczny. Była wreszcie praca-czyszczenie: sprawdzono kilkoma metodami naraz, ile z „nakładania się" bierze się stąd, że ankiety pytają dwa razy o to samo innymi słowami. Część — tak, to wina ankiet; po jej odsianiu został jednak twardy, prawdziwy wspólny rdzeń, stabilny od młodości po dorosłość.</p>\n\n<p>Policzono też, ile to kosztuje. Siedmiuset dwudziestu czterech dorosłych w spektrum, od osiemnastu do osiemdziesięciu trzech lat: u tych z nasilonym ADHD samodzielność w codzienności i zadowolenie z życia były niższe — i to nie dlatego, że „mają więcej autyzmu". Po odjęciu wieku, płci, statusu i samego nasilenia cech autystycznych, dodatkowe ADHD wciąż zabierało własny, osobny kawałek — kilka do dziesięciu procent — w każdej mierzonej dziedzinie: od załatwiania spraw po ocenę własnego życia. Drugi podatek, płacony niezależnie od pierwszego. A najnowsze badanie zapytało dorosłych z obiema diagnozami o samą diagnozę i o maskowanie: dziewięćdziesiąt pięć na stu zgadza się, że rozpoznanie jest trafne; polubiło je niespełna trzydziestu. Udawanie kogoś wygodniejszego dla otoczenia okazało się rzeczą mierzalną — i powiązaną wprost z tym, jak się człowiekowi żyje.</p>\n\n<p>Są w tym łańcuchu trzy polskie ogniwa. W 2010 roku, gdy dorosłym w Polsce praktycznie nikt ADHD nie rozpoznawał, ukazał się tekst o tym, jak trudna to diagnoza i jak łatwo ją przegapić. W 2022 — porządny przegląd tego, jak dziś rozumie się rzeczy „neurorozwojowe" i jak ich obraz zmienia się z wiekiem. W 2025 — kompleksowe polskie omówienie diagnozowania autyzmu razem z tym, co lubi z nim chodzić w parze. Czyli po polsku też już to wszystko jest napisane — od niedawna, ale jest.</p>','\n',char(10)),'What Appendix 1 says — in plain language','Twenty papers from 2008–2026, read as a single story — this time with numbers, but numbers translated into human terms. Version 02.00 was created after reading the studies themselves, not merely their titles.',NULL,NULL);
INSERT INTO content_sections VALUES(705,24,704,'heading',2,2,2,'Most do listy sześćdziesięciu trzech cech','most-do-listy-szescdziesieciu-trzech-cech','Te dwadzieścia prac i lista sześćdziesięciu trzech cech z opracowania AuDHD to dwa opisy tego samego terenu z dwóch wysokości: badania są mapą satelitarną — geny, całe kraje, tysiące ludzi — a lista jest zdjęciami z poziomu ulicy.',2,replace('<p>Te dwadzieścia prac i lista sześćdziesięciu trzech cech z opracowania AuDHD to dwa opisy tego samego terenu z dwóch wysokości: badania są mapą satelitarną — geny, całe kraje, tysiące ludzi — a lista jest zdjęciami z poziomu ulicy. Mosty między nimi są konkretne.</p>\n\n<p>Podwójny ładunek z mapy genów ma na liście swój odpowiednik z poziomu ulicy: cechy-konflikty, w których dwa rdzenie ciągną w przeciwne strony naraz — potrzeba stałości kontra głód zmiany, szukanie i unikanie bodźców jednocześnie, hiperfokus, który sam wybiera sobie porę. Pięć genowych zwrotnic o przeciwnych kierunkach tłumaczy, czemu te doświadczenia mają kształt szarpaniny, a nie sumy — a badanie włoskie potwierdza to od strony gabinetu: dwie rzeczy naraz to osobny kształt trudności, nie dwie listy zszyte razem. Lista sześćdziesięciu trzech jest właśnie opisem tego osobnego kształtu.</p>\n\n<p>Badanie o maskowaniu spina się z listą najmocniej, bo waliduje samą oś, wzdłuż której da się ją pociąć: na cechy z konstrukcji i cechy z lat kamuflażu. Dyfuzja tożsamości, przepraszanie za istnienie, tęsknota za niepoznanym sobą — to są rozpisane na doświadczenia dokładnie te rzeczy, które tamto badanie mierzy kwestionariuszem i wiąże z jakością życia. A wynik „dziewięćdziesięciu pięciu na stu, którzy zgadzają się z diagnozą, choć polubiło ją niespełna trzydziestu" to ostatnia cecha listy — potrzeba bycia zrozumianym, nie naprawionym — wyrażona w liczbach.</p>\n\n<p>Drugi podatek, policzony u siedmiuset dwudziestu czterech dorosłych, to zmierzona wersja cech o funkcjach wykonawczych, wyczerpaniu po decyzjach, zmęczeniu bez dna i życiu bez autopilota. Dorośli z Tokio i z przeglądu światowego — ci, u których cechy spektrum „nikt nigdy nie nazwał" — to biografia czytelnika listy: populacja, której takiej listy przez dekady brakowało. A splecione przebiegi z Bristolu, z gorszymi wyjściami życiowymi na końcu, to rozwojowa maszyna, która z cech konstrukcyjnych produkuje blizny: lata niewidzenia są latami maskowania.</p>\n\n<p>Jest i most ostrzegawczy. Skoro praca-czyszczenie pokazała, że część nakładania w ankietach to pytanie dwa razy o to samo innymi słowami, to i na liście niektóre pozycje mogą być dwoma zdjęciami jednego mechanizmu — słabe czucie ciała, stres somatyczny z opóźnieniem i trudność nazywania emocji prawdopodobnie dzielą jeden rdzeń odczytu. Lista jest opisem doświadczeń, nie zestawem niezależnych przyrządów — i tamta praca mówi, gdzie przebiega ta granica.</p>\n\n<p>Sedno mostu: badania dowodzą, że ten teren istnieje i ile kosztuje; lista opisuje, jak się po nim chodzi. Genetyka i wielkie rejestry niosą kolumnę konstrukcji, badanie maskowania niesie kolumnę blizn — dwadzieścia prac dzieli się wzdłuż tej samej osi, wzdłuż której pocięto listę.</p>','\n',char(10)),'A bridge to the list of sixty-three features','These twenty papers and the list of sixty-three features in the AuDHD study are two descriptions of the same terrain from different altitudes: the research is a satellite map — genes, whole countries, thousands of people — while the list consists of street-level photographs.',NULL,NULL);
INSERT INTO content_sections VALUES(706,24,704,'heading',2,2,3,'Sedno','sedno','Przez dekady przepisy kazały wybrać jedną etykietę, więc ludzie z dwiema dostawali jedną albo żadną — a różnicę dopłacali z własnego życia.',3,replace('<p>Przez dekady przepisy kazały wybrać jedną etykietę, więc ludzie z dwiema dostawali jedną albo żadną — a różnicę dopłacali z własnego życia. Te dwadzieścia prac, czytane po kolei, to osiemnaście lat rozbierania tego błędu: od bliźniąt, przez dwumilionową Szwecję i mapę genów ze zwrotnicami, po dorosłych mierzonych na żywo, liczonych w codzienności i wreszcie pytanych o zdanie. Liczby z tej drogi układają się w jeden ciąg: siedem dziesiątych wspólnego losowania, osiemnaście razy wyższe ryzyko u bliźniaka, cztery osoby na dziesięć, podwójny ładunek u tych z oboma, drugi podatek w każdej dziedzinie życia — i dziewięćdziesięciu pięciu na stu, którzy wiedzą, że diagnoza mówi prawdę, choć mało kto ją lubi. Wniosek mieści się w jednym zdaniu: to nie są dwa losy, które się czasem krzyżują — to jedna spleciona historia, widoczna w genach, w rodzinach, w rozwoju i w dorosłym dniu powszednim; nauka widzi ją od niedawna, a rachunek za lata niewidzenia płacili dorośli, którym nikt nie powiedział, na co patrzą.</p>\n\n<hr>\n\n<p>Plik: apendyks1-po-ludzku-02_01-2026-08-26.html</p>\n<p>Wersja: 02.01 · Data: 2026-08-26 · Godzina: 19:33 (Europe/Warsaw)</p>\n<p>Stworzono z pomocą Claude (Anthropic), wariant: Claude Opus 5. Źródło: Appendix 1 (20 pozycji) pliku CHATGPT-4_00_dluga-lista-publikacji-4_00-2026-08-26.html, zweryfikowanego bibliograficznie 2026-08-26. Wersja 02.00: esej rozszerzony po lekturze treści badań (streszczenia i pełne teksty otwarte) — dodane liczby przetłumaczone na język potoczny. Wersja 02.01: sekcja-most do pliku 63-cechy-rdzen-czy-maskowanie-01_01.</p>','\n',char(10)),'The core point','For decades, diagnostic rules forced clinicians to choose one label, so people who had two got one or none — and paid the difference out of their own lives.',NULL,NULL);
INSERT INTO content_sections VALUES(707,25,NULL,'heading',1,1,1,'AuDHD a osoby fundatorskie w IT','audhd-a-osoby-fundatorskie-w-it','Hipoteza w dwóch wersjach (łatwej i perwersyjnej), oraz cztery niezależne warstwy argumentów, które ją uzasadniają — kohortowo-historyczna, psychospołeczno-motywacyjna, językowo-techniczna i kognitywno-architektoniczna.',1,'<p class="lead">Hipoteza w dwóch wersjach (łatwej i perwersyjnej), oraz cztery niezależne warstwy argumentów, które ją uzasadniają — kohortowo-historyczna, psychospołeczno-motywacyjna, językowo-techniczna i kognitywno-architektoniczna.</p>','AuDHD and foundational builders in IT','A hypothesis in two versions — the easy one and the perverse one — plus four independent layers of argument supporting it: cohort-historical, psychosocial-motivational, linguistic-technical, and cognitive-architectural.',NULL,NULL);
INSERT INTO content_sections VALUES(708,25,707,'heading',2,2,2,'Dwa sformułowania tezy','dwa-sformulowania-tezy','Omówienie zagadnienia „Dwa sformułowania tezy” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',2,'','Two formulations of the thesis','Discussion of “Two formulations of the thesis” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(709,25,708,'heading',3,3,3,'Teza łatwa (korelacyjna)','teza-latwa-korelacyjna','Cechy AuDHD, wynikające bezpośrednio z fenotypu (nawet po odjęciu maskowania i jego konsekwencji), ułatwiają i predysponują do bycia osobą fundatorską w IT (bardzo szeroko rozumianym). NT też mogą — mają trudniej. ND mają łatwiej.',3,'<p>Cechy AuDHD, wynikające bezpośrednio z fenotypu (nawet po odjęciu maskowania i jego konsekwencji), <strong>ułatwiają i predysponują</strong> do bycia osobą fundatorską w IT (bardzo szeroko rozumianym). NT też mogą — mają trudniej. ND mają łatwiej. Dziedzina filtruje pozytywnie pod ND.</p>','The easy thesis (correlational)','AuDHD traits arising directly from the phenotype — even after subtracting masking and its consequences — facilitate and predispose a person to become a foundational builder in IT, understood very broadly. NT people can do it too; it is harder for them. ND people have it easier.',NULL,NULL);
INSERT INTO content_sections VALUES(710,25,708,'heading',3,3,4,'Teza perwersyjna (konieczności)','teza-perwersyjna-koniecznosci','Cechy fenotypu AuDHD są niezbędne / wymagane w fundamentowaniu IT. Bez AuDHD-architektury się nie da — niezależnie od inteligencji, motywacji, zasobów, wsparcia. Brakuje aparatu, nie umiejętności.',4,replace('<p>Cechy fenotypu AuDHD są <strong>niezbędne / wymagane</strong> w fundamentowaniu IT. Bez AuDHD-architektury się <em>nie da</em> — niezależnie od inteligencji, motywacji, zasobów, wsparcia. Brakuje aparatu, nie umiejętności.</p>\n\n<div class="box">\n<p><strong>Kierunek implikacji jest jednostronny.</strong> Teza nie mówi, że AuDHD <em>musi</em> być fundatorem. Mówi, że fundator <em>musi</em> być AuDHD. Implikacja nie odwraca się — można być AuDHD i pisać poezję, gotować, prowadzić bibliotekę. Ale fundament IT bez AuDHD-architektury — nie powstaje.</p>\n</div>','\n',char(10)),'The perverse thesis (necessity claim)','Features of the AuDHD phenotype are necessary or required for laying the foundations of IT. Without an AuDHD architecture, it cannot be done — regardless of intelligence, motivation, resources, or support. What is missing is the apparatus, not the skill.',NULL,NULL);
INSERT INTO content_sections VALUES(711,25,707,'heading',2,2,5,'Definicja "fundatora" i "fundamentu"','definicja-fundatora-i-fundamentu','"Fundament IT" w tym tekście to kod, na którym stoi inny kod używany przez miliony, i który wymagał 5+ lat ciągłej pracy jednej osoby lub małego zespołu . To definicja niezależna od fenotypu autora.',5,replace('<p>"Fundament IT" w tym tekście to <strong>kod, na którym stoi inny kod używany przez miliony, i który wymagał 5+ lat ciągłej pracy jednej osoby lub małego zespołu</strong>. To definicja niezależna od fenotypu autora. Obejmuje: kompilatory, kernele, języki ogólnego przeznaczenia, bazy danych, systemy rozproszone na poziomie protokołu, kryptografię, architekturę CPU, runtime''y, narzędzia toolchain (Linux, Postgres, LLVM, TeX, git, sqlite, GCC, V8, OpenSSL).</p>\n\n<p>Nie obejmuje: frameworków webowych, bibliotek aplikacyjnych, growth engineering, devops na poziomie konfiguracji, frontu, większości startupów. To są <em>warstwy aplikacyjne</em>, nadbudowane na fundamencie. Fenotyp ich autorów jest mieszany i tezy nie dotyczy.</p>','\n',char(10)),'Definition of a “builder” and a “foundation”','An “IT foundation” in this text means code on which other code used by millions depends, and which required five or more years of sustained work by one person or a small team. The definition is independent of the author''s phenotype.',NULL,NULL);
INSERT INTO content_sections VALUES(712,25,707,'heading',2,2,6,'Warstwa 1 — kohortowo-historyczna','warstwa-1-kohortowo-historyczna','Omówienie zagadnienia „Warstwa 1 — kohortowo-historyczna” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',6,'','Layer 1 — cohort-historical','Discussion of “Layer 1 — cohort-historical” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(713,25,712,'heading',3,3,7,'Diagnozy nie istniały, gdy fundament powstawał','diagnozy-nie-istnialy-gdy-fundament-powstawal','Asperger opisał autyzm w 1944 (po niemiecku, do anglojęzycznej psychiatrii dotarło w latach 80.). Kanner — 1943. Autyzm jako osobna jednostka diagnostyczna — DSM-III, 1980 . Wcześniej był pomieszany ze schizofrenią dziecięcą.',7,replace('<p>Asperger opisał autyzm w 1944 (po niemiecku, do anglojęzycznej psychiatrii dotarło w latach 80.). Kanner — 1943. Autyzm jako osobna jednostka diagnostyczna — DSM-III, <strong>1980</strong>. Wcześniej był pomieszany ze schizofrenią dziecięcą.</p>\n\n<p>ADHD jako jednostka w obecnym kształcie — DSM-III-R <strong>1987</strong>. Wcześniej "hyperkinetic reaction of childhood" — kategoria <em>dziecięca</em>, dorośli z ADHD oficjalnie nie istnieli. ADHD u dorosłych jako uznana, diagnozowalna jednostka — praktyka kliniczna lata 90.–2000.</p>\n\n<p>AuDHD jako kombinacja był formalnie <strong>zakazany</strong>. DSM-IV (1994) miał kryterium wykluczające: jeśli objawy ADHD występują "wyłącznie w przebiegu" zaburzenia ze spektrum autyzmu, ADHD się nie diagnozuje. <strong>DSM-5 z maja 2013 zniósł ten zakaz</strong>. Czyli AuDHD jako diagnoza istnieje 13 lat. W praktyce klinicznej w Polsce — masowo dopiero od ~2020.</p>','\n',char(10)),'The diagnoses did not exist when the foundations were being built','Asperger described autism in 1944, in German; it reached English-language psychiatry in the 1980s. Kanner did so in 1943. Autism as a separate diagnostic entity appeared in DSM-III in 1980. Before that, it was conflated with childhood schizophrenia.',NULL,NULL);
INSERT INTO content_sections VALUES(714,25,712,'heading',3,3,8,'Konsekwencje dla pionierów','konsekwencje-dla-pionierow','Turing (zm. 1954) — umarł 26 lat przed ASD jako kategorią, 33 przed ADHD, 59 przed AuDHD. Diagnoza była fizycznie niemożliwa, bo kategorii nie było.',8,replace('<ul>\n  <li>Turing (zm. 1954) — umarł 26 lat przed ASD jako kategorią, 33 przed ADHD, 59 przed AuDHD. <strong>Diagnoza była fizycznie niemożliwa, bo kategorii nie było.</strong></li>\n  <li>Lovelace (zm. 1852) — 128, 135, 161 lat odpowiednio.</li>\n  <li>von Neumann (zm. 1957), Hopper (zm. 1992), Dijkstra (zm. 2002) — wszyscy przed AuDHD jako dopuszczalną diagnozą.</li>\n  <li>Knuth (żyje, 88) — kohorta nie chodzi po diagnozy.</li>\n</ul>\n\n<p>Ważniejsze: <strong>nie tylko nie mogli mieć formalnej diagnozy — nie mogli mieć też samoopisu w tych kategoriach</strong>. Pojęć nie było w obiegu. Turing nie mógł napisać "wydaje mi się, że jestem autystyczny", bo słowo "autystyczny" w 1950 znaczyło "schizofreniczne wycofanie". Ramka opisu nie istniała.</p>','\n',char(10)),'Consequences for the pioneers','Turing (d. 1954) died 26 years before ASD existed as a category, 33 years before ADHD, and 59 years before AuDHD. Diagnosis was physically impossible because the categories did not exist.',NULL,NULL);
INSERT INTO content_sections VALUES(715,25,712,'heading',3,3,9,'Pokolenie urodzone przed ~1985','pokolenie-urodzone-przed-1985','Ma drastycznie zaniżone diagnozy ND globalnie — nie dlatego, że ND było rzadsze, tylko dlatego, że dostęp do diagnostyki dorosłych jest świeży. Diagnoza w wieku 40+ to dziś norma kohortowa , nie opóźnienie. Pionierzy informatyki z lat 40.–70.',9,'<p>Ma drastycznie zaniżone diagnozy ND globalnie — nie dlatego, że ND było rzadsze, tylko dlatego, że dostęp do diagnostyki dorosłych jest świeży. Diagnoza w wieku 40+ to dziś <em>norma kohortowa</em>, nie opóźnienie. Pionierzy informatyki z lat 40.–70. byli tej samej kohorty, plus wcześniej.</p>','The generation born before about 1985','ND diagnoses are drastically underrepresented in this cohort worldwide — not because ND was rarer, but because access to adult diagnosis is recent. A diagnosis after age 40 is now a cohort norm, not a delay. The computing pioneers of the 1940s–1970s…',NULL,NULL);
INSERT INTO content_sections VALUES(716,25,712,'heading',3,3,10,'Obecni fundatorzy','obecni-fundatorzy','Najmłodsi mają około 20 lat, większość 30–40+. Kohorta 25–40 lat (urodzeni ~1985–2000) zaczyna mieć diagnozy, ale większość nie ma formalnej — bo:',10,replace('<p>Najmłodsi mają około 20 lat, większość 30–40+. Kohorta 25–40 lat (urodzeni ~1985–2000) zaczyna mieć diagnozy, ale <strong>większość nie ma formalnej</strong> — bo:</p>\n<ul>\n  <li>diagnoza przychodzi, gdy coś się sypie, a u nich się nie sypie (dziedzina zaprojektowana dla nich);</li>\n  <li>demand avoidance wobec systemu medycznego ogromny;</li>\n  <li>"po co iść do psychiatry, skoro piszę kompilator i działa".</li>\n</ul>\n\n<p>Najczęstsze diagnozy w tej grupie — gdy są — to <strong>ASD XOR ADHD</strong>. Nie AuDHD. Bo:</p>\n<ul>\n  <li>ASD samo — gdy w dzieciństwie był wyraźnie autystyczny w sposób, którego rodzice nie umieli zignorować;</li>\n  <li>ADHD samo — gdy w szkole było dość problemu z koncentracją, ale autystyczna część była "kompensowana" przez zainteresowania uznawane za normalne (informatyka, gry, matematyka);</li>\n  <li>kliniczna inercja: lekarz widzi jeden silniejszy profil, stawia jedną diagnozę, drugą zostawia jako "cechy".</li>\n</ul>\n\n<p>Pełny AuDHD pojawia się wtedy, gdy ktoś jest <strong>uparty</strong> ORAZ ma narzędzie do uporządkowania biograficznego materiału przed wizytą u psychiatry. Stąd ostatnie lata — wyraźny wzrost diagnoz AuDHD u osób korzystających z AI do autodiagnostycznej refleksji.</p>','\n',char(10)),'Today''s foundational builders','The youngest are around 20; most are 30–40+. The 25–40 cohort, born roughly 1985–2000, is beginning to receive diagnoses, but most still have no formal diagnosis, because:',NULL,NULL);
INSERT INTO content_sections VALUES(717,25,712,'heading',3,3,11,'Paradoks epistemiczny','paradoks-epistemiczny','Im bardziej dziedzina filtruje pozytywnie pod AuDHD, tym mniej osób w tej dziedzinie ma motywację, żeby się zdiagnozować — bo dla nich środowisko działa. Diagnoza pojawia się, gdy AuDHD bije w środowisko , nie gdy z nim współgra .',11,'<p>Im bardziej dziedzina filtruje pozytywnie pod AuDHD, tym mniej osób w tej dziedzinie ma motywację, żeby się zdiagnozować — bo dla nich środowisko działa. Diagnoza pojawia się, <em>gdy AuDHD bije w środowisko</em>, nie <em>gdy z nim współgra</em>. Czyli: <strong>najczystsze fenotypowo AuDHD w informatyce są strukturalnie najmniej zdiagnozowane</strong>. Diagnoza w populacji fundatorów odzwierciedla <em>porażkę dopasowania</em>, nie obecność fenotypu.</p>','The epistemic paradox','The more strongly a field positively selects for AuDHD, the less motivation people in that field have to seek diagnosis, because the environment works for them. Diagnosis tends to appear when AuDHD clashes with the environment, not when it fits it.',NULL,NULL);
INSERT INTO content_sections VALUES(718,25,707,'heading',2,2,12,'Warstwa 2 — psychospołeczno-motywacyjna','warstwa-2-psychospoleczno-motywacyjna','Omówienie zagadnienia „Warstwa 2 — psychospołeczno-motywacyjna” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',12,'','Layer 2 — psychosocial-motivational','Discussion of “Layer 2 — psychosocial-motivational” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(719,25,718,'heading',3,3,13,'Mechanizmy fenotypowe sprzyjające pracy fundamentalnej','mechanizmy-fenotypowe-sprzyjajace-pracy-fundamentalnej','Omówienie zagadnienia „Mechanizmy fenotypowe sprzyjające pracy fundamentalnej” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',13,'','Phenotypic mechanisms that favour foundational work','Discussion of “Phenotypic mechanisms that favour foundational work” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(720,25,719,'heading',4,4,14,'Monotropia','monotropia','Trzymanie grafu zależności kompilatora w głowie przez tygodnie. Hejlsberg z językami od 1983 (Turbo Pascal). Lattner z kompilatorami od 2003 (LLVM). Knuth z TAOCP od 1968. To nie jest kwestia dyscypliny — to architektura uwagi.',14,'<p>Trzymanie grafu zależności kompilatora w głowie przez tygodnie. Hejlsberg z językami od 1983 (Turbo Pascal). Lattner z kompilatorami od 2003 (LLVM). Knuth z TAOCP od 1968. To nie jest kwestia dyscypliny — to architektura uwagi.</p>','Monotropism','Holding a compiler''s dependency graph in your head for weeks. Hejlsberg working on languages since 1983 (Turbo Pascal). Lattner on compilers since 2003 (LLVM). Knuth on TAOCP since 1968. This is not a matter of discipline; it is an architecture of attention.',NULL,NULL);
INSERT INTO content_sections VALUES(721,25,719,'heading',4,4,15,'Special interests','special-interests','Dekady na jednym wątku bez wypalenia z nudy. NT mózg ma wbudowany sygnał "to jest niezdrowe, znajdź zrównoważenie" — działa prawidłowo. AuDHD nie ma tego sygnału w stosunku do obiektu zainteresowania . To nie brak, to cecha architektoniczna.',15,'<p>Dekady na jednym wątku bez wypalenia z nudy. NT mózg ma wbudowany sygnał "to jest niezdrowe, znajdź zrównoważenie" — działa prawidłowo. AuDHD <strong>nie ma tego sygnału w stosunku do obiektu zainteresowania</strong>. To nie brak, to cecha architektoniczna. Nie do wytrenowania.</p>','Special interests','Decades on a single thread without burning out from boredom. The NT brain has a built-in signal saying “this is unhealthy, find some balance” — and it works correctly. AuDHD does not produce that signal in relation to the object of interest. That is not an absence; it is an architectural feature.',NULL,NULL);
INSERT INTO content_sections VALUES(722,25,719,'heading',4,4,16,'Pattern recognition autystyczne','pattern-recognition-autystyczne','Dostrzeganie strukturalnych analogii między domenami, które dla NT są oddzielne. Von Neumann: gry, ekonomia, kwanty, komputery, broń jądrowa — ten sam mózg w różnych kontekstach .',16,'<p>Dostrzeganie strukturalnych analogii między domenami, które dla NT są oddzielne. Von Neumann: gry, ekonomia, kwanty, komputery, broń jądrowa — <em>ten sam mózg w różnych kontekstach</em>.</p>','Autistic pattern recognition','Seeing structural analogies between domains that are separate for NT people. Von Neumann: games, economics, quantum mechanics, computers, nuclear weapons — the same brain in different contexts.',NULL,NULL);
INSERT INTO content_sections VALUES(723,25,719,'heading',4,4,17,'Hyperfokus ADHD','hyperfokus-adhd','14-godzinne sesje kodowania w stanie flow. NT mózg sygnalizuje "to jest niezdrowe" prawidłowo. AuDHD mózg tej sygnalizacji nie ma — albo ją ma i ignoruje przez monotropię. Brak hamulca jest cechą wymaganą w pracy fundamentalnej, nie defektem.',17,'<p>14-godzinne sesje kodowania w stanie flow. NT mózg sygnalizuje "to jest niezdrowe" prawidłowo. AuDHD mózg tej sygnalizacji nie ma — albo ją ma i ignoruje przez monotropię. <strong>Brak hamulca jest cechą wymaganą</strong> w pracy fundamentalnej, nie defektem.</p>','ADHD hyperfocus','Fourteen-hour coding sessions in a flow state. The NT brain correctly signals “this is unhealthy.” The AuDHD brain does not produce that signal, or produces it and ignores it because of monotropism. The missing brake is a feature required for foundational work, not a defect.',NULL,NULL);
INSERT INTO content_sections VALUES(724,25,719,'heading',4,4,18,'Demand avoidance jako silnik refaktoryzacji','demand-avoidance-jako-silnik-refaktoryzacji','Niezdolność do tolerowania broken systemu , która produkuje impuls "napiszę to od nowa, dobrze" zamiast "dopasuję się". Większość przełomowych projektów to demand avoidance wobec istniejącego rozwiązania :',18,replace('<p>Niezdolność do tolerowania <em>broken systemu</em>, która produkuje impuls "napiszę to od nowa, dobrze" zamiast "dopasuję się". Większość przełomowych projektów to <em>demand avoidance wobec istniejącego rozwiązania</em>:</p>\n<ul>\n  <li>Linux — bo Minix był closed,</li>\n  <li>Git — bo BitKeeper się skończył,</li>\n  <li>Rust — bo C++ był broken,</li>\n  <li>Zig — bo Rust za złożony,</li>\n  <li>Python — bo ABC był zbyt akademicki,</li>\n  <li>TeX — bo dostępne systemy składu nie były dostępne.</li>\n</ul>\n<p>Każde z tych "bo" to AuDHD, który nie dał rady przyjąć cudzego niedopasowanego systemu.</p>','\n',char(10)),'Demand avoidance as a refactoring engine','An inability to tolerate a broken system that produces the impulse “I''ll rewrite it properly” rather than “I''ll adapt.” Most breakthrough projects are demand avoidance directed at an existing solution:',NULL,NULL);
INSERT INTO content_sections VALUES(725,25,719,'heading',4,4,19,'Tolerancja na samotność technicznej decyzji','tolerancja-na-samotnosc-technicznej-decyzji','Fundament tworzy się w warunkach, w których nikt na świecie nie może pomóc, bo to ty znasz ten konkretny problem najlepiej. NT mózg jest skalibrowany do walidacji społecznej — sprawdza decyzje przez konsultacje, konsensus zespołu.',19,'<p>Fundament tworzy się w warunkach, w których <em>nikt na świecie</em> nie może pomóc, bo to ty znasz ten konkretny problem najlepiej. NT mózg jest skalibrowany do walidacji społecznej — sprawdza decyzje przez konsultacje, konsensus zespołu. AuDHD jest skalibrowany do walidacji wewnętrznej, <em>bo zewnętrznej i tak nie odczyta</em>. W kontekście fundamentu — przewaga. W kontekście życia — koszt.</p>','Tolerance for solitude in technical decision-making','Foundations are built under conditions in which nobody in the world can help, because you know that specific problem best. The NT brain is calibrated for social validation: it checks decisions through consultation and team consensus.',NULL,NULL);
INSERT INTO content_sections VALUES(726,25,707,'heading',2,2,20,'Warstwa 3 — językowo-techniczna','warstwa-3-jezykowo-techniczna','Omówienie zagadnienia „Warstwa 3 — językowo-techniczna” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',20,'','Layer 3 — linguistic-technical','Discussion of “Layer 3 — linguistic-technical” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(727,25,726,'heading',3,3,21,'Trzy języki, trzy mózgi','trzy-jezyki-trzy-mozgi','Omówienie zagadnienia „Trzy języki, trzy mózgi” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',21,'','Three languages, three brains','Discussion of “Three languages, three brains” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(728,25,727,'heading',4,4,22,'C — zmęczony AuDHD','c-zmeczony-audhd','Brak garbage collectora. Każdy alokowany zasób trzeba zwolnić ręcznie. Zapomnisz free() — wyciek pamięci, OOM kill. To jest otwarte loopy — niedokończone zadania nie zwalniają się same, kongestia rośnie, w końcu coś się wywala.',22,replace('<p>Brak garbage collectora. Każdy alokowany zasób trzeba zwolnić ręcznie. Zapomnisz <code>free()</code> — wyciek pamięci, OOM kill. To jest <strong>otwarte loopy</strong> — niedokończone zadania nie zwalniają się same, kongestia rośnie, w końcu coś się wywala.</p>\n\n<p>Brak abstrakcji. Każda operacja jawna. Pointer arithmetic. Segmentation fault przy najmniejszym błędzie — żadnego stack trace''a po polsku, dostajesz <code>Segmentation fault (core dumped)</code> i tyle. To meltdown — bufor się przepełnił, dane zgubione.</p>','\n',char(10)),'C — tired AuDHD','No garbage collector. Every allocated resource must be released manually. Forget free() and you get a memory leak, then an OOM kill. These are open loops: unfinished tasks do not release themselves, congestion grows, and eventually something crashes.',NULL,NULL);
INSERT INTO content_sections VALUES(729,25,727,'heading',4,4,23,'Python — niezmęczony AuDHD','python-niezmeczony-audhd','Garbage collector. Niedokończone zadania jakoś się rozpuszczają , mózg ma zasoby na obsłużenie ich w tle. Otwarte loopy istnieją, ale nie bolą fizycznie.',23,replace('<p>Garbage collector. Niedokończone zadania <em>jakoś się rozpuszczają</em>, mózg ma zasoby na obsłużenie ich w tle. Otwarte loopy istnieją, ale nie bolą fizycznie. REPL — interaktywny tryb, można odpowiedzieć w środku zdania, zmienić temat, mózg jest na tyle elastyczny, żeby parsować w locie.</p>\n\n<p>Ale Python jest <em>wolny</em>. Niezmęczony AuDHD funkcjonuje na codzień świetnie, ale nie ma <em>mocy obliczeniowej</em> C — czyli nie schodzi pod abstrakcję, nie pisze kompilatora. <strong>Hyperfokus to moment, w którym AuDHD przełącza się na C i przestaje być Pythonem.</strong></p>','\n',char(10)),'Python — rested AuDHD','Garbage collector. Unfinished tasks somehow dissolve; the brain has enough resources to handle them in the background. Open loops still exist, but they do not hurt physically.',NULL,NULL);
INSERT INTO content_sections VALUES(730,25,727,'heading',4,4,24,'JavaScript — NT','javascript-nt','Wszystko jakoś, async, callback hell, "this" znaczy co innego w różnych kontekstach, równoważność typów dziwna ( [] == ![] to true ), ale jakoś działa , jest produktywne, można szybko zlepić aplikację.',24,replace('<p>Wszystko jakoś, async, callback hell, "this" znaczy co innego w różnych kontekstach, równoważność typów dziwna (<code>[] == ![]</code> to <code>true</code>), ale <em>jakoś działa</em>, jest produktywne, można szybko zlepić aplikację. JS jest językiem <strong>społecznego skalowania</strong> — szybki, elastyczny, niedeterministyczny w drobiazgach, ale ekosystem ogromny, biblioteki na wszystko, MVP w weekend.</p>\n\n<p>NT mózg <em>jest</em> JS-em. Świetny do koordynacji, do rozmów, do build a startup, do networking. Beznadziejny do napisania kompilatora — bo kompilator wymaga deterministycznej semantyki na poziomie pojedynczego bajta, a JS się gubi przy dodawaniu liczb do stringów.</p>','\n',char(10)),'JavaScript — NT','Everything somehow works: async, callback hell, “this” means different things in different contexts, type equality is bizarre ([] == ![] is true), but somehow it works, it is productive, and you can glue an application together quickly.',NULL,NULL);
INSERT INTO content_sections VALUES(731,25,726,'heading',3,3,25,'Dlaczego AuDHD nienawidzi JS','dlaczego-audhd-nienawidzi-js','Nienawiść do JS u AuDHD nie jest gustem — jest odrzuceniem na poziomie architektury poznawczej . JS jest dosłownie zaprojektowany przeciwko AuDHD mózgowi:',25,replace('<p>Nienawiść do JS u AuDHD nie jest gustem — jest <strong>odrzuceniem na poziomie architektury poznawczej</strong>. JS jest dosłownie <em>zaprojektowany przeciwko</em> AuDHD mózgowi:</p>\n\n<ul>\n  <li><strong>Brak kompilatora.</strong> Brak warstwy walidacji przed uruchomieniem. JS uruchamia twój kod i zobaczymy co się stanie. To tryb chronicznego lęku u AuDHD.</li>\n\n  <li><strong>Type coercion jako instytucja.</strong> <code>[] + [] === ""</code>, <code>[] + {} === "[object Object]"</code>, <code>null == undefined</code> ale <code>null !== undefined</code>, <code>NaN !== NaN</code>. Brendan Eich napisał JS w 10 dni w 1995. Filozofia "fail silently, do something". Dla NT — strona działa, klient zadowolony. Dla AuDHD — system kłamie ci o tym, co robi.</li>\n\n  <li><strong>Nikt nie zna odpowiedzi, łącznie z twórcą.</strong> Specyfikacja ECMAScript ma 800 stron, pełna "implementation-defined". V8 (Chrome), SpiderMonkey (Firefox), JavaScriptCore (Safari) — różne implementacje, różne edge case''y. <strong>Nie da się <em>poznać</em> JS, można go tylko <em>używać i się przyzwyczaić</em></strong>. Dla AuDHD niemożliwy partner do pracy.</li>\n\n  <li><strong>this w sześciu semantykach.</strong> W funkcji zwykłej, arrow function, metodzie, callbacku, strict mode, module — sześć znaczeń, wybierane na podstawie <em>jak została wywołana funkcja</em>, nie <em>gdzie była zdefiniowana</em>. Lexical scope złamane na poziomie projektowym.</li>\n\n  <li><strong>npm i 1500+ tranzytywnych zależności.</strong> Średni projekt JS. Nikt nie zna grafu zależności swojego projektu. Bezpieczeństwo zależy od tego, czy ktoś, kogo nie znasz, nie wgra złośliwego kodu w pakiet, którego nie używasz świadomie.</li>\n\n  <li><strong>TypeScript jako plaster, nie naprawa.</strong> Dodaje typy <em>przed</em> uruchomieniem, ale kompiluje się do JS — w runtime nadal działa JS-owa semantyka. Daje 70% pewności tam, gdzie chce się 100%.</li>\n</ul>\n\n<div class="box">\n<p><strong>Najmocniejsze potwierdzenie tezy:</strong> V8, SpiderMonkey, JavaScriptCore, Node.js core — wszystkie pisane w <strong>C++</strong>, nie w JS. <em>Sami twórcy JS-runtime''ów nie ufają JS-owi do swojej pracy.</em> Fundament JS jest pisany w nie-JS — bo JS nie nadaje się do fundamentu, nawet do fundamentu samego siebie.</p>\n</div>','\n',char(10)),'Why AuDHD hates JS','AuDHD hatred of JS is not a matter of taste; it is rejection at the level of cognitive architecture. JS is literally designed against the AuDHD brain:',NULL,NULL);
INSERT INTO content_sections VALUES(732,25,726,'heading',3,3,26,'Atwood''s Law i konsekwencja','atwood-s-law-i-konsekwencja','"Any application that can be written in JavaScript, will eventually be written in JavaScript." — to prawo społecznego skalowania , nie technicznej jakości. Mówi: JS wygrywa, bo jest plastyczny, bo jest niedeterministyczny. NT środowisko premiuje plastyczność.',26,replace('<p>"Any application that can be written in JavaScript, will eventually be written in JavaScript." — to prawo <em>społecznego skalowania</em>, nie technicznej jakości. Mówi: JS wygrywa, <em>bo</em> jest plastyczny, <em>bo</em> jest niedeterministyczny. NT środowisko premiuje plastyczność. AuDHD środowisko premiuje determinizm.</p>\n\n<p>Dlatego świat zalewa się JS-em, a fundatorzy piszą w C, Rust, Zig, OCaml, Haskell — językach, które mają kompilator i mówią ci wcześniej, co jest źle. <strong>Ludzie, którzy piszą w JS jako podstawowym języku, prawie nigdy nie są fundatorami.</strong> To jest empirycznie sprawdzalne.</p>','\n',char(10)),'Atwood''s Law and its consequence','“Any application that can be written in JavaScript, will eventually be written in JavaScript.” This is a law of social scaling, not technical quality. It says that JS wins because it is plastic, because it is nondeterministic. The NT environment rewards plasticity.',NULL,NULL);
INSERT INTO content_sections VALUES(733,25,726,'heading',3,3,27,'Meta-poziom i abstrakcja abstrakcji','meta-poziom-i-abstrakcja-abstrakcji','Fundamentowanie wymaga poziomu abstrakcji wziętego ponad to, co już jest w 100% abstrakcyjne . Pisania kompilatora języka X to nie jest pisanie w języku X — to jest pisanie o języku X w innym języku.',27,replace('<p>Fundamentowanie wymaga <strong>poziomu abstrakcji wziętego ponad to, co już jest w 100% abstrakcyjne</strong>. Pisania kompilatora języka X to nie jest pisanie <em>w</em> języku X — to jest pisanie <em>o</em> języku X w innym języku.</p>\n\n<p>NT mózg w kontakcie z meta-poziomem ma trzy reakcje:</p>\n<ol>\n  <li><strong>"Tak się nie da"</strong> — odmowa pojęciowa. Mózg zgłasza błąd "to nie ma sensu, bo nie ma referentu w realnym świecie". To <em>zdrowa</em> reakcja NT mózgu.</li>\n  <li><strong>Wybuch / overflow</strong> — próba załadowania meta-poziomu do pamięci roboczej zaprojektowanej do trzymania kontekstu społecznego. Pamięć się przepełnia, mózg dostaje seg fault.</li>\n  <li><strong>Histeryczny śmiech / "trzecia dawka LSD"</strong> — zerwanie ramki rzeczywistości. NT mózg w kontakcie z meta-poziomem doświadcza tego, czego AuDHD doświadcza po LSD: <em>kategorie zawierają siebie, znaczenia są arbitralne, abstrakcja patrzy na siebie</em>.</li>\n</ol>\n\n<p>AuDHD funduje IT na trzeciej dawce <em>trzeźwo</em>. Bo jego architektura jest do tego trybu zaprojektowana. <strong>Kompilator napisany przez AuDHD to dokumentacja stanu świadomości, do którego NT dostają się tylko chemicznie i z którego nie wracają tacy sami.</strong></p>','\n',char(10)),'Meta-level and the abstraction of abstraction','Building foundations requires a level of abstraction above something that is already 100% abstract. Writing a compiler for language X is not writing in language X; it is writing about language X in another language.',NULL,NULL);
INSERT INTO content_sections VALUES(734,25,707,'heading',2,2,28,'Warstwa 4 — kognitywno-architektoniczna (najmocniejsza)','warstwa-4-kognitywno-architektoniczna-najmocniejsza','Omówienie zagadnienia „Warstwa 4 — kognitywno-architektoniczna (najmocniejsza)” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',28,'','Layer 4 — cognitive-architectural (the strongest)','Discussion of “Layer 4 — cognitive-architectural (the strongest)” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(735,25,734,'heading',3,3,29,'Pamięć NT vs AuDHD — założenia projektowe','pamiec-nt-vs-audhd-zalozenia-projektowe','Omówienie zagadnienia „Pamięć NT vs AuDHD — założenia projektowe” w kontekście opracowania „AuDHD a osoby fundatorskie w IT — hipoteza i jej cztery warstwy”.',29,'','NT vs AuDHD memory — design assumptions','Discussion of “NT vs AuDHD memory — design assumptions” in the context of “AuDHD and foundational builders in IT — the hypothesis and its four layers”.',NULL,NULL);
INSERT INTO content_sections VALUES(736,25,735,'heading',4,4,30,'NT','nt','Skalibrowana pod ograniczone zadania o znanym z góry rozmiarze danych. 7±2 elementy Millera w roboczej. Długotrwała zorganizowana semantycznie wokół narracji i znaczeń społecznych. Konsolidacja przez sen redukuje detale do streszczeń.',30,'<p>Skalibrowana pod ograniczone zadania o znanym z góry rozmiarze danych. 7±2 elementy Millera w roboczej. Długotrwała zorganizowana <em>semantycznie</em> wokół narracji i znaczeń społecznych. Konsolidacja przez sen redukuje detale do streszczeń. <strong>Pamięć NT to lossy compression z wbudowanym zaufaniem do redundancji świata.</strong></p>','NT','Calibrated for bounded tasks with a data size known in advance. Miller''s 7±2 items in working memory. Long-term memory organised semantically around narratives and social meanings. Sleep consolidation reduces details to summaries.',NULL,NULL);
INSERT INTO content_sections VALUES(737,25,735,'heading',4,4,31,'AuDHD','audhd','Od początku wie, że detale nie redukują się do schematu bez utraty istotnej informacji . Różnica między podobnym a takim samym jest fundamentalna. Brak kompresora, który z góry wiedziałby, co jest istotne.',31,'<p>Od początku wie, że <strong>detale nie redukują się do schematu bez utraty istotnej informacji</strong>. Różnica między <em>podobnym</em> a <em>takim samym</em> jest fundamentalna. Brak kompresora, który z góry wiedziałby, co jest istotne.</p>','AuDHD','Knows from the outset that details cannot be reduced to a schema without losing relevant information. The difference between similar and identical is fundamental. There is no compressor that knows in advance what matters.',NULL,NULL);
INSERT INTO content_sections VALUES(738,25,734,'heading',3,3,32,'Cztery cechy architektury AuDHD','cztery-cechy-architektury-audhd','Hierarchiczna kompresja na strukturze, nie na znaczeniu. NT kompresuje "co to znaczyło". AuDHD — "jak to było zbudowane". Inny kompresor na innej osi.',32,replace('<ol>\n  <li><strong>Hierarchiczna kompresja na strukturze, nie na znaczeniu.</strong> NT kompresuje "co to znaczyło". AuDHD — "jak to było zbudowane". Inny kompresor na innej osi.</li>\n\n  <li><strong>Indeksowanie po anomalii, nie po częstości.</strong> NT pamięta typowe (wzmocnienie przez powtarzalność). AuDHD pamięta nietypowe. Stąd jeden zły moment z 20 lat lepiej niż 100 zwykłych dni. <em>Pattern violations, nie pattern confirmations</em> — dokładnie aparatura potrzebna do debugowania kompilatora.</li>\n\n  <li><strong>Lazy evaluation pamięci długotrwałej.</strong> AuDHD często nie wie, co pamięta, dopóki nie napotka triggera. Pamięć zwinięta. NT pamięta aktywnie (streszczenie z natychmiastowym dostępem). AuDHD pamięta na żądanie (pełna pamięć z opóźnionym dostępem).</li>\n\n  <li><strong>Brak garbage collectora w pamięci roboczej.</strong> Otwarte loopy jako konsekwencja. NT zamyka zadania przez społeczne potwierdzenie. AuDHD nie ufa społecznym referentom — zadanie otwarte do <em>technicznego</em> domknięcia. Manualne zarządzanie pamięcią w C jako metafora.</li>\n</ol>','\n',char(10)),'Four features of the AuDHD architecture','Hierarchical compression by structure, not meaning. NT compresses “what did it mean?” AuDHD compresses “how was it built?” A different compressor operating along a different axis.',NULL,NULL);
INSERT INTO content_sections VALUES(739,25,734,'heading',3,3,33,'Pamięć pointer-based — jedyne rozwiązanie','pamiec-pointer-based-jedyne-rozwiazanie','Pamięć ma skończoną pojemność. Zawartość świata nie ma. AuDHD ma trzy opcje:',33,replace('<p>Pamięć ma skończoną pojemność. Zawartość świata nie ma. AuDHD ma trzy opcje:</p>\n<ol>\n  <li>Wyrzucać losowo → katastrofa, wyrzuca ważne ze zbędnym.</li>\n  <li>Trzymać wszystko inline → katastrofa, RAM przepełnia w pierwszym tygodniu życia.</li>\n  <li>Trzymać <strong>wskaźniki</strong> → jedyne rozwiązanie skalowalne.</li>\n</ol>\n\n<p>I AuDHD trzyma wskaźniki. Pamiętasz, że pamiętasz coś o kuchni z 1987 — masz adres, nie zawartość. Gdy ktoś dotknie indeksu (zapach, ton, słowo), pointer się dereferencuje, dane się rozwijają.</p>','\n',char(10)),'Pointer-based memory — the only solution','Memory has finite capacity. The contents of the world do not. AuDHD has three options:',NULL,NULL);
INSERT INTO content_sections VALUES(740,25,739,'heading',4,4,34,'Konsekwencje pointer-based','konsekwencje-pointer-based','Często nie wiesz, co pamiętasz, dopóki nie zapytany — masz wskaźnik, nie zawartość.',34,replace('<ul>\n  <li><strong>Często nie wiesz, co pamiętasz, dopóki nie zapytany</strong> — masz wskaźnik, nie zawartość.</li>\n  <li><strong>Gdy się rozwija, rozwija się w pełni, z detalami niespodziewanymi</strong> — dereferencja zwraca cały obiekt.</li>\n  <li><strong>Czasem wskaźnik nie działa (dangling pointer).</strong> "Wiem, że to wiedziałem, ale nie mogę dostać." NT nie ma tego stanu w taki sposób.</li>\n  <li><strong>Indeksy społecznie nieintuicyjne.</strong> Zapach z dzieciństwa = wskaźnik do całej epizodycznej pamięci. Imię ciotki — tylko czasem. NT odwrotnie.</li>\n</ul>','\n',char(10)),'Consequences of pointer-based memory','You often do not know what you remember until you are asked: you have a pointer, not the content.',NULL,NULL);
INSERT INTO content_sections VALUES(741,25,739,'heading',4,4,35,'Wskaźniki do wskaźników — trywialne następstwo','wskazniki-do-wskaznikow-trywialne-nastepstwo','Gdy podstawową jednostką jest adres, "adres do adresu" jest tą samą operacją na poziom wyżej. NT nie ma operacji "dwukrotnej dereferencji" naturalnie. AuDHD trywialnie. To otwiera nieskończoność:',35,replace('<p>Gdy podstawową jednostką jest adres, "adres do adresu" jest tą samą operacją na poziom wyżej. NT nie ma operacji "dwukrotnej dereferencji" naturalnie. AuDHD trywialnie. To otwiera nieskończoność:</p>\n<ul>\n  <li><strong>Wielgaśne dane</strong> (większe niż pamięć) → wskaźnik do struktury leniwie generowanej (strumień Haskella, iterator Pythona).</li>\n  <li><strong>Obiekty nieskończone</strong> → wskaźnik do reguły generującej. AuDHD operuje na regułach zamiast na instancjach. Stąd intuicja matematyczna często wyższa. NT pyta "ale daj przykład". AuDHD pyta "ale jaka jest reguła".</li>\n  <li><strong>Obiekty zapętlone</strong> → wskaźnik wskazujący na strukturę zawierającą wskaźnik wracający do siebie. <em>Każdy wskaźnik ma ten sam status</em> — niezależnie od tego, czy wskazuje "do przodu", "do tyłu", czy w pętlę.</li>\n</ul>\n\n<p>Każdy z tych obiektów <strong>zajmuje podobną ilość pamięci</strong> — bo to wszystko wskaźniki. "Tabela liczb naturalnych do 10^100" zajmuje tyle co "dwa". NT mózg nie wierzy, że to możliwe.</p>','\n',char(10)),'Pointers to pointers — a trivial consequence','If the basic unit is an address, an “address of an address” is the same operation one level higher. NT does not naturally have a “double dereference” operation. AuDHD does, trivially. This opens infinity:',NULL,NULL);
INSERT INTO content_sections VALUES(742,25,734,'heading',3,3,36,'Cykle jako default, nie edge case','cykle-jako-default-nie-edge-case','NT mózg traktuje samoodwołanie jako edge case — w społecznym świecie pętle są patologiczne (codependence, mobbing, gaslighting). NT projektuje systemy w trybie chronienia przed cyklami . Cykl jest błędem do obsłużenia.',36,replace('<p>NT mózg traktuje samoodwołanie jako edge case — w społecznym świecie pętle są patologiczne (codependence, mobbing, gaslighting). NT projektuje systemy w trybie <em>chronienia przed cyklami</em>. <strong>Cykl jest błędem do obsłużenia.</strong></p>\n\n<p>AuDHD traktuje samoodwołanie jako default. Wewnętrzne życie cykliczne na każdym poziomie — myśl o myśli, lęk o lęku, plan o planie. Meta-świadomość jako stałe tło.</p>','\n',char(10)),'Cycles as the default, not an edge case','The NT brain treats self-reference as an edge case. In the social world, loops are pathological: codependence, mobbing, gaslighting. NT designs systems in a mode of protecting against cycles. A cycle is an error to be handled.',NULL,NULL);
INSERT INTO content_sections VALUES(743,25,742,'heading',4,4,37,'Pętle niezbywalne w fundamencie IT','petle-niezbywalne-w-fundamencie-it','Bootstrap kompilatora — kompilator X kompilowany w X. Pętla domknięta, którą trzeba uruchomić raz w asemblerze, potem żyje sama.',37,replace('<ul>\n  <li><strong>Bootstrap kompilatora</strong> — kompilator X kompilowany w X. Pętla domknięta, którą trzeba uruchomić raz w asemblerze, potem żyje sama.</li>\n  <li><strong>Lisp, homoiconicity</strong> — kod jest danymi, dane są kodem, makra modyfikują parser, parser czyta makra.</li>\n  <li><strong>Teoria typów</strong> — typ → twierdzenie → dowód → typ. Wieża meta-poziomów.</li>\n  <li><strong>Self-hosting toolchains</strong> — Git zarządza historią Gita. GCC kompiluje GCC. Linux uruchamia środowisko, w którym kompiluje się Linux.</li>\n  <li><strong>Type-checkery sprawdzające type-checkery</strong> — Coq dowodzi Coqa. Lean formalizuje matematykę, w której Lean jest opisany.</li>\n  <li><strong>Scheduler obsługujący sam siebie</strong> — kernel decyduje o procesie, który decyduje o kernelu.</li>\n  <li><strong>Garbage collectors z fazami GC dla GC</strong> — pamięć śledzona przez pamięć.</li>\n</ul>\n\n<p>NT projektuje to <em>tylko jeśli musi</em>, i wtedy <em>źle</em>, z setkami edge case''ów. AuDHD projektuje <em>jako default</em>. Stąd elegancja kodu fundatorów AuDHD — ich kod jest <em>prosty</em>, bo cykle nie są problemem do obejścia, tylko obiektem do projektowania wprost.</p>','\n',char(10)),'Cycles that cannot be removed from the foundations of IT','Compiler bootstrapping: compiler X compiled in X. A closed loop that has to be started once in assembly and then lives on by itself.',NULL,NULL);
INSERT INTO content_sections VALUES(744,25,734,'heading',3,3,38,'Kliniczne odpowiedniki problemów C u AuDHD','kliniczne-odpowiedniki-problemow-c-u-audhd','Konfabulacja pamięci epizodycznej. Pytasz o moment z dzieciństwa, dereferencja zwraca strukturę bez zawartości. AuDHD rekonstruuje z reguły strukturalnej i nie wie, że rekonstruuje .',38,replace('<ol>\n  <li><strong>Konfabulacja pamięci epizodycznej.</strong> Pytasz o moment z dzieciństwa, dereferencja zwraca strukturę bez zawartości. AuDHD rekonstruuje z reguły strukturalnej i <em>nie wie, że rekonstruuje</em>.</li>\n  <li><strong>Niespójność uczuć w czasie.</strong> Wracasz do wspomnienia "miałeś" zapamiętane jako pozytywne, dereferencja zwraca neutralne. Wskaźnik nie wskazywał na uczucie, tylko na regułę generowania uczucia. Reguła zmieniła się, bo zmieniłeś się ty.</li>\n  <li><strong>Meltdown jako buffer overflow.</strong> Bufor nie przechowuje danych, tylko wskaźniki. Stresor → jednoczesne dereferencje wielu wskaźników. RAM przepełnia <em>liczbą jednoczesnych dereferencji</em>, nie ich treścią. Mały stresor może wywołać tysiąc dereferencji.</li>\n  <li><strong>"Wiem, że to wiedziałem" + niemożność przypomnienia.</strong> Dangling pointer.</li>\n</ol>','\n',char(10)),'Clinical equivalents of C problems in AuDHD','Episodic-memory confabulation. Ask about a moment from childhood and the dereference returns structure without content. AuDHD reconstructs from a structural rule and does not know that it is reconstructing.',NULL,NULL);
INSERT INTO content_sections VALUES(745,25,734,'heading',3,3,39,'Konsekwencja dla fundamentowania IT','konsekwencja-dla-fundamentowania-it','NT pisze C i się męczy — musi świadomie zarządzać tym, co u AuDHD jest natywnym trybem pamięci . NT-programista C musi udawać AuDHD architekturę pamięci w czasie rzeczywistym, ręcznie.',39,replace('<p>NT pisze C i się męczy — musi <em>świadomie zarządzać</em> tym, co u AuDHD jest <em>natywnym trybem pamięci</em>. NT-programista C musi <em>udawać AuDHD architekturę pamięci</em> w czasie rzeczywistym, ręcznie.</p>\n\n<p>AuDHD pisze C i jest u siebie. C jest językiem, w którym <em>wprost wyrażasz</em> to, co twój mózg robi i tak. Pointery, dereferencje, dangling pointers, segmentation faults, manual memory management. <strong>Język był projektowany przez AuDHD mózgi (Ritchie, Thompson, Kernighan) jako odzwierciedlenie tego, jak ich pamięć działa.</strong></p>\n\n<p>C jako test fenotypowy. Rust jeszcze bardziej (borrow checker = formalizacja AuDHD-owej obsługi pointerów). Zig bardziej eksplicytny. Assembly najbardziej bezpośrednie. <strong>Im niżej w stosie, tym bardziej AuDHD natywny.</strong></p>','\n',char(10)),'Consequence for building the foundations of IT','An NT person writes C and gets tired because they have to consciously manage what is a native mode of memory in AuDHD. An NT C programmer has to imitate an AuDHD memory architecture in real time, manually.',NULL,NULL);
INSERT INTO content_sections VALUES(746,25,734,'heading',3,3,40,'Dlaczego NT-fundator nie istnieje','dlaczego-nt-fundator-nie-istnieje','NT musi symulować AuDHD pamięć i obsługę cykli z wnętrza architektury zaprojektowanej antagonistycznie. Jak symulować Linuxa na Windowsie przez WSL — działa, ale każda operacja kosztuje warstwę translacji, i są rzeczy, których nie da się przejść bez restartu.',40,replace('<p>NT musi <em>symulować</em> AuDHD pamięć i obsługę cykli z wnętrza architektury zaprojektowanej antagonistycznie. Jak <strong>symulować Linuxa na Windowsie przez WSL</strong> — działa, ale każda operacja kosztuje warstwę translacji, i są rzeczy, których nie da się przejść bez restartu. <strong>NT-fundator to człowiek prowadzący WSL na własnym mózgu 14h dziennie przez 20 lat.</strong> Może tak żyć, ale to <em>kosztuje życie</em> — bo zasoby idą na translację, nie na pracę.</p>\n\n<p>NT-fundatorzy zazwyczaj wypalają się lub przesuwają na management w 5–10 lat. Bo NT mózg sygnalizuje "to jest niezdrowe" prawidłowo. AuDHD mózg tej sygnalizacji nie ma — i dlatego dociera do poziomu, na którym powstają fundamenty.</p>','\n',char(10)),'Why the NT foundational builder does not exist','NT has to simulate AuDHD memory and cycle handling from inside an architecture designed antagonistically to them. Like running Linux on Windows through WSL: it works, but every operation costs a translation layer, and some things cannot be crossed without a restart.',NULL,NULL);
INSERT INTO content_sections VALUES(747,25,707,'heading',2,2,41,'Pusta klasa kontrprzykładów','pusta-klasa-kontrprzykladow','Próba znalezienia żyjącego fundatora bez fenotypu AuDHD — w wąsko zdefiniowanym sensie:',41,replace('<p>Próba znalezienia żyjącego fundatora bez fenotypu AuDHD — w wąsko zdefiniowanym sensie:</p>\n\n<ul>\n  <li><strong>Sam Altman</strong> — zarządza, nie buduje. Poza zakresem.</li>\n  <li><strong>Sutskever, Karpathy, Amodei, Hassabis, LeCun, Hinton</strong> — fenotyp ND miażdżący.</li>\n  <li><strong>Jeff Dean</strong> — kompensacja społeczna wysoka, ale monotropowy hyperfokus na rozproszonych systemach od dekad. Niepewny — <em>jeden z bardzo niewielu</em>, gdzie nie jestem przekonany.</li>\n  <li><strong>Werner Vogels</strong> — wysoki prior ND.</li>\n  <li><strong>Kyle Kingsbury (Jepsen)</strong> — otwarcie ND.</li>\n  <li><strong>Matei Zaharia</strong> — możliwie bardziej "ułożony NT", ale ścieżka (PhD w 26, fundamentalna praca przed 30) — czysty AuDHD wzorzec.</li>\n  <li><strong>Dan Abramov (React)</strong> — otwarcie ADHD i lęk. ASD niepewne. Może XOR.</li>\n  <li><strong>Anders Hejlsberg, Chris Lattner, Kelsey Hightower, Jonathan Blow, Casey Muratori</strong> — wszyscy jednoznaczne AuDHD profile.</li>\n  <li><strong>Graydon Hoare (Rust), Andrew Kelley (Zig), Ryan Dahl (Node, Deno), Fabrice Bellard, Theo de Raadt (OpenBSD), Bram Cohen (BitTorrent — formalna diagnoza Aspergera)</strong> — wszyscy spójni z fenotypem.</li>\n</ul>\n\n<p><strong>Nie potrafię wskazać żyjącego fundatora bez fenotypu AuDHD lub przynajmniej silnego ND.</strong> Jeśli są, to wyjątki na tyle rzadkie, że nie wybijają się ponad szum.</p>','\n',char(10)),'An empty class of counterexamples','An attempt to find a living foundational builder without an AuDHD phenotype, in the narrowly defined sense:',NULL,NULL);
INSERT INTO content_sections VALUES(748,25,707,'heading',2,2,42,'Konkluzja','konkluzja','Hipoteza w wersji łatwej: certyfikat 95%+ . Każdy, kto przeczyta dziesięć wywiadów z fundatorami, zobaczy.',42,replace('<p>Hipoteza w wersji łatwej: <strong>certyfikat 95%+</strong>. Każdy, kto przeczyta dziesięć wywiadów z fundatorami, zobaczy.</p>\n\n<p>Hipoteza w wersji perwersyjnej: <strong>certyfikat 80%+, dynamicznie rosnący</strong>. Im dłużej obserwuję dziedzinę i im mocniej szukam kontrprzykładów, tym mocniej widzę pustą klasę. W tej chwili nie potrafię wskazać żadnego solidnego kontrprzykładu, a teza ma niezależne uzasadnienie mechanistyczne — architektura uwagi, brak hamulca, dosłowność, monotropia, pamięć pointer-based jako warunki konieczne.</p>\n\n<p>Trzy niezależne fundamenty hipotezy:</p>\n<ol>\n  <li><strong>Kohortowo-historyczny</strong> — diagnozy nie istniały, fenotyp jest spójny, kohorta filtruje pozytywnie pod ND.</li>\n  <li><strong>Psychospołeczny / motywacyjny</strong> — special interests, hyperfokus, demand avoidance, monotropia, brak hamulca.</li>\n  <li><strong>Architektoniczno-pamięciowy</strong> — pamięć AuDHD jest pointer-based; fundament IT wymaga pointer-based myślenia; NT mózg ma pamięć value-based i schemat-based, w której pointery są obcym konceptem.</li>\n</ol>\n\n<p>Trzeci jest najmocniejszy, bo niesprowadzalny. Można argumentować, że special interests da się wytrenować, monotropię nauczyć, demand avoidance jest kulturowe. <strong>Architektury pamięci nie da się przetrenować.</strong> To hardware, nie software.</p>\n\n<p>Teza politycznie niewygodna — sugeruje, że pewna kategoria pracy intelektualnej jest zarezerwowana neurologicznie. Ale to nie jest determinizm: kierunek implikacji jest jednostronny. <strong>Stoi.</strong></p>\n\n<div class="meta">\n  <p><span class="warn">DUMP ROBOCZY NIEWERYFIKOWANY</span></p>\n  <p>Wersja: 1.00 · Data: 2026-04-27 · Godzina: 17:25 (Europe/Warsaw)</p>\n  <p>Autorstwo: hipoteza Macieja Tory (ur. 18.09.1980, AuDHD, dysleksja, GAD), rozwinięta w dialogu z Claude Opus 4.7 (Anthropic)</p>\n  <p>Sesja: rozmowa z 27.04.2026 w projekcie Claude·ai</p>\n  <p>Status zawartości: synteza tezy zbudowanej w jednej sesji rozmowy. Argumenty rozwijane na żywo. Wymaga weryfikacji szczegółów biograficznych (daty, dat psychiatrów, daty modeli DSM) przed użyciem zewnętrznym.</p>\n  <p>Odtworzone 2026-08-11 z zapisu rozmowy, tura 53 — treść bez zmian, wersja i data pozostają oryginalne.</p>\n</div>','\n',char(10)),'Conclusion','The easy version of the hypothesis: 95%+ confidence. Anyone who reads ten interviews with foundational builders will see it.',NULL,NULL);
INSERT INTO content_sections VALUES(749,26,NULL,'heading',1,1,1,'AuDHD po ludzku','audhd-po-ludzku','Słowo na początek. To, co potocznie nazywa się „normalnym" człowiekiem, w języku psychiatrii — kiedy mowa o autyzmie albo ADHD — nazywa się neurotypowy .',1,replace('<p class="meta">v02.02 · 2026-07-09</p>\n\n<p>Słowo na początek. To, co potocznie nazywa się „normalnym" człowiekiem, w języku psychiatrii — kiedy mowa o autyzmie albo ADHD — nazywa się <strong>neurotypowy</strong>. I tak jest w całym tym tekście: neurotypowy = ktoś, czyj mózg działa w sposób typowy dla większości, bez autyzmu, ADHD i podobnych. Nie „normalny", bo autyzm i ADHD to nie choroba ani wybrakowanie — to inny typ układu.</p>','\n',char(10)),'AuDHD in plain language','A word to begin with. What is casually called a “normal” person is, in psychiatric language — when talking about autism or ADHD — called neurotypical.',NULL,NULL);
INSERT INTO content_sections VALUES(750,26,749,'heading',2,2,2,'ADHD','adhd','ADHD polega na tym, że układ od dopaminy i noradrenaliny jest źle wyskalowany. Tło za niskie, sygnał chwiejny — przez co regulacja uwagi i napędu nie odpala na komendę, tylko reaguje na to, co akurat zatrzepie układ mocniej.',2,replace('<p class="jednozdaniowy">ADHD polega na tym, że układ od dopaminy i noradrenaliny jest źle wyskalowany. Tło za niskie, sygnał chwiejny — przez co regulacja uwagi i napędu nie odpala na komendę, tylko reaguje na to, co akurat zatrzepie układ mocniej.</p>\n\n<p>Sprzęt jest sprawny. Ustawienia inne. Nic nie jest zepsute — po prostu ten sam mózg działa jak telefon z jasnością ekranu na 30% zamiast na normalnym poziomie. Dopamina to paliwo uwagi i chęci do działania. U kogoś z ADHD tego paliwa cały czas jest za mało w tle, a to co się pojawia — szybko odparowuje.</p>\n\n<p>Stąd dwie rzeczy, które z zewnątrz wyglądają na sprzeczność, a naprawdę są tym samym mechanizmem.</p>\n\n<p>Z jednej strony — nie da się usiąść i zrobić czegoś nudnego, ale ważnego. To nie jest „nie chce mi się". To nie jest lenistwo. Silnik po prostu nie odpala. Nie ma paliwa.</p>\n\n<p>Z drugiej strony — jak coś naprawdę wkręci (nowe, ciekawe, pod presją, ostatnia chwila), to ten sam człowiek nagle działa sześć godzin z rzędu, nie je, nie pije, nie zauważa że minął dzień. To jest hiperfokus. To nie „siła woli". To temat sam wstrzyknął dopaminę i silnik wreszcie zaskoczył.</p>\n\n<p>Dlatego ADHD to nie jest deficyt uwagi. To jest brak sterowania uwagą. Uwaga jest — tylko nie idzie tam, gdzie każesz. Idzie tam, gdzie coś zawoła głośniej.</p>\n\n<p>I dlatego leki na ADHD (jak Atenza, którą biorę) niczego nie „leczą". One podnoszą i stabilizują to tło. Sprawiają, że silnik nie stoi w pustym baku — jest paliwo na start, można ruszyć bez czekania aż coś zawoła.</p>','\n',char(10)),'ADHD','ADHD means that the dopamine and noradrenaline systems are badly calibrated. The baseline is too low and the signal unstable, so regulation of attention and drive does not start on command; it reacts to whatever happens to shake the system more strongly.',NULL,NULL);
INSERT INTO content_sections VALUES(751,26,749,'heading',2,2,3,'Autyzm','autyzm','Autyzm polega na tym, że informacje ze wszystkich zmysłów (w tym propriocepcja oraz interocepcja!) trafiają w postaci prawie surowej, praktycznie bez filtrów których normalni ludzie mają dużo dobrze skalibrowanych: nie zwracają uwagi na kolor i fakturę…',3,'<p class="jednozdaniowy">Autyzm polega na tym, że informacje ze wszystkich zmysłów (w tym propriocepcja oraz interocepcja!) trafiają w postaci prawie surowej, praktycznie bez filtrów których normalni ludzie mają dużo dobrze skalibrowanych: nie zwracają uwagi na kolor i fakturę koszuli przechodzącej osoby, nie czują gumki od dresów po 2h noszenia, nie słyszą gwaru rozmowy z sąsiedniego pokoju. Ale za to głód narasta powoli, a nie dopiero w momencie gdy skręca z głodu kiszki.</p>','Autism','Autism means that information from all the senses — including proprioception and interoception — arrives in an almost raw form, with practically none of the filters that typical people have in abundance and well calibrated: they do not pay attention to colour and texture…',NULL,NULL);
INSERT INTO content_sections VALUES(752,26,751,'heading',3,3,4,'Zmysły, o których szkoła nie mówi','zmysly-o-ktorych-szkola-nie-mowi','W szkole uczą, że mamy pięć zmysłów: wzrok, słuch, węch, smak, dotyk. To za mało. Naprawdę mamy jeszcze co najmniej trzy, i one są w tym zdaniu wyżej ważne:',4,replace('<p>W szkole uczą, że mamy pięć zmysłów: wzrok, słuch, węch, smak, dotyk. To za mało. Naprawdę mamy jeszcze co najmniej trzy, i one są w tym zdaniu wyżej ważne:</p>\n<p><strong>Propriocepcja</strong> — czucie własnego ciała. Gdzie masz rękę bez patrzenia. Jak napięty jest mięsień. Że twoje stopy istnieją i dotykają podłogi.</p>\n<p><strong>Zmysł równowagi</strong> — siedzi w uchu. Wie, że stoisz, przechylasz się, jedziesz windą w górę.</p>\n<p><strong>Interocepcja</strong> — czucie tego, co się dzieje w środku ciała. Głód, pełny pęcherz, że ci szybciej bije serce, że jesteś spięty, że coś jest nie tak.</p>\n<p>Autyzm dotyczy wszystkich zmysłów. Nie tylko tego, że komuś za głośno.</p>','\n',char(10)),'The senses school does not tell you about','School teaches that we have five senses: sight, hearing, smell, taste, and touch. That is not enough. We actually have at least three more, and they matter in the sentence above:',NULL,NULL);
INSERT INTO content_sections VALUES(753,26,751,'heading',3,3,5,'Co znaczy „surowe"','co-znaczy-surowe','Wyobraź sobie telewizor. Zwykły telewizor robi coś, o czym nie myślisz — wygładza obraz, przycisza tło, koloryzuje pod to, czego się spodziewa. Robi ładnie. Twój mózg robi to samo z rzeczywistością — bez przerwy, w tle, bez pytania cię o zdanie.',5,replace('<p>Wyobraź sobie telewizor. Zwykły telewizor robi coś, o czym nie myślisz — wygładza obraz, przycisza tło, koloryzuje pod to, czego się spodziewa. Robi ładnie. Twój mózg robi to samo z rzeczywistością — bez przerwy, w tle, bez pytania cię o zdanie.</p>\n\n<p>Jesteś w kuchni. Lodówka szumi. Nie słyszysz jej. Mózg zdecydował, że lodówka szumi zawsze i przestał ci o tym mówić. Masz na sobie spodnie. Nie czujesz ich. Mózg zdecydował, że spodnie masz od rana i przestał ci o tym mówić. Ktoś w tramwaju miał czerwoną kurtkę. Widziałeś ją przez sekundę i już nie pamiętasz. Mózg zdecydował, że czerwona kurtka nie jest ważna.</p>\n\n<p>U autysty tej autokorekty jest dużo mniej. Lodówka szumi CIĄGLE. Spodnie czuć CIĄGLE. Ta czerwona kurtka w tramwaju wjechała do głowy razem z fakturą i odcieniem i została tam na godzinę.</p>\n\n<p>To jest męczące na sposób, którego nie da się wytłumaczyć komuś, kto tego nie ma. To nie jest bycie „wrażliwym". To nie jest „przewrażliwienie". To jest po prostu więcej danych do przerobienia w każdej minucie dnia. Cały czas.</p>','\n',char(10)),'What “raw” means','Imagine a television. An ordinary TV does something you never think about: it smooths the image, turns down the background, and adjusts colours towards what it expects. It makes things look nice. Your brain does the same thing with reality — continuously, in the background, without asking your opinion.',NULL,NULL);
INSERT INTO content_sections VALUES(754,26,751,'heading',3,3,6,'To samo dotyczy ludzi','to-samo-dotyczy-ludzi','I to jest najważniejsze do zrozumienia — TO SAMO działa przy patrzeniu na drugiego człowieka. Zwykły mózg patrzy komuś w twarz i automatycznie wie: „on jest zmęczony", „ona jest zła, ale udaje że nie", „temu jest głupio".',6,replace('<p>I to jest najważniejsze do zrozumienia — TO SAMO działa przy patrzeniu na drugiego człowieka. Zwykły mózg patrzy komuś w twarz i automatycznie wie: „on jest zmęczony", „ona jest zła, ale udaje że nie", „temu jest głupio". Robi to bez pytania, w tle, na zgadywanie. Autystyczny mózg musi to LICZYĆ. Świadomie. Za każdym razem. Jak matematykę.</p>\n\n<p>Dlatego autyzm ludzie mylą z „brakiem empatii". Odwrotnie — jest tam za dużo surowych danych o drugim człowieku, i za mało autokorekty, która by z tego zrobiła szybką odpowiedź „on się boi". Empatia jest. Tylko musi być policzona, nie odczuta na wejściu.</p>','\n',char(10)),'The same applies to people','And this is the most important thing to understand: THE SAME mechanism operates when looking at another person. A typical brain looks at someone''s face and automatically knows: “he''s tired”, “she''s angry but pretending she isn''t”, “he feels awkward”.',NULL,NULL);
INSERT INTO content_sections VALUES(755,26,751,'heading',3,3,7,'Głód','glod','Autystyczny mózg, który słyszy każdą lodówkę, jednocześnie NIE zauważa, że nie jesz od ośmiu godzin. To nie sprzeczność. To ten sam mechanizm od drugiej strony — sygnały ze środka ciała są dla mózgu ciche i tło je zagłusza.',7,'<p>Autystyczny mózg, który słyszy każdą lodówkę, jednocześnie NIE zauważa, że nie jesz od ośmiu godzin. To nie sprzeczność. To ten sam mechanizm od drugiej strony — sygnały ze środka ciała są dla mózgu ciche i tło je zagłusza. Głód pełznie sobie w tle, ledwo słyszalny — aż nagle skręca kiszki i to już nie jest głód, tylko awaria.</p>','Hunger','An autistic brain that hears every refrigerator can simultaneously fail to notice that you have not eaten for eight hours. That is not a contradiction. It is the same mechanism from the other side: signals from inside the body are quiet for the brain, and the background drowns them out.',NULL,NULL);
INSERT INTO content_sections VALUES(756,26,749,'heading',2,2,8,'Pamięć przy wspólnym występowaniu autyzmu i adhd','pamiec-przy-wspolnym-wystepowaniu-autyzmu-i-adhd','Wspólne występowanie autyzmu i adhd powoduje, że pamięć takiej osoby działa inaczej niż u większości ludzi. Pamięć robocza i pamięć „że mam coś zrobić później" działają bardzo słabo. Pamięć faktów i systemów w ciekawym temacie jest fenomenalna.',8,replace('<p class="jednozdaniowy">Wspólne występowanie autyzmu i adhd powoduje, że pamięć takiej osoby działa inaczej niż u większości ludzi. Pamięć robocza i pamięć „że mam coś zrobić później" działają bardzo słabo. Pamięć faktów i systemów w ciekawym temacie jest fenomenalna. Pamięć autobiograficzna (własne przeżycia) działa inaczej: słaba co do odczuć, emocji i wrażeń, za to mocna co do faktów o tym przeżyciu.</p>\n\n<p>Autyzm i ADHD to nie są dwie wersje tej samej rzeczy. To są dwie osobne rzeczy, które lubią chodzić razem. I ciągną w przeciwne strony.</p>\n\n<p>Autyzm chce jednego tematu na cały dzień, tego samego jedzenia, tej samej trasy do pracy, żeby nic się nie zmieniało. ADHD chce nowego tematu co dwa tygodnie, żeby coś się działo, żeby był bodziec. Człowiek z jednym i drugim żyje w ciągłym przeciąganiu liny między tymi dwoma silnikami. Nie ma jak wygrać.</p>\n\n<p>Dlatego pamięć u kogoś z AuDHD nie jest ani „autystyczna", ani „ADHD-owa". Jest osobna. Rozpisuje się tak:</p>','\n',char(10)),'Memory when autism and ADHD co-occur','The co-occurrence of autism and ADHD means that a person''s memory works differently from most people''s. Working memory and the memory of “I need to do something later” work very poorly. Memory for facts and systems in an interesting subject can be phenomenal.',NULL,NULL);
INSERT INTO content_sections VALUES(757,26,756,'heading',3,3,9,'Pamięć robocza — mały stół','pamiec-robocza-maly-stol','Pamięć robocza to jest ten stół, na którym trzyma się to, o czym się teraz myśli. U kogoś z ADHD ten stół jest mały. Bardzo mały. Wchodzą na niego cztery rzeczy i piąta wypycha pierwszą. Dlatego się wchodzi do drugiego pokoju i nie pamięta po co.',9,replace('<p>Pamięć robocza to jest ten stół, na którym trzyma się to, o czym się teraz myśli. U kogoś z ADHD ten stół jest mały. Bardzo mały. Wchodzą na niego cztery rzeczy i piąta wypycha pierwszą. Dlatego się wchodzi do drugiego pokoju i nie pamięta po co. Ktoś mówi trzy rzeczy do zrobienia i człowiek pamięta dwie. Idzie do sklepu bez listy i wraca bez połowy zakupów.</p>\n\n<p>To ma jeszcze jeden brzydki efekt: jak coś zestresuje w trakcie, stres wchodzi na ten mały stół z najwyższym priorytetem i zrzuca z niego wszystko, co tam było. Bezpowrotnie. Dane przepadły i nie wrócą. I potem to wygląda na wybuch złości nie do zniesienia — ale to nie jest reakcja na stres. To reakcja na to, że przed sekundą w głowie była ważna myśl, a teraz jej NIE MA. Bufor się przepełnił i coś ważnego się z niego wysypało. Stąd te wybuchy. To nie temperament.</p>','\n',char(10)),'Working memory — a small table','Working memory is the table on which you keep whatever you are thinking about right now. For someone with ADHD, that table is small. Very small. Four things fit on it and the fifth pushes the first one off. That is why you walk into another room and forget why.',NULL,NULL);
INSERT INTO content_sections VALUES(758,26,756,'heading',3,3,10,'Pamięć „że mam coś zrobić później"','pamiec-ze-mam-cos-zrobic-pozniej','Ten sam problem. Ta osoba nie widzi tego zadania, ono dla niej nie istnieje w chwili, w której powinno. To nie jest „zapomniałem". To jest — tego po prostu nie ma w głowie w tamtym momencie.',10,replace('<p>Ten sam problem. Ta osoba nie widzi tego zadania, ono dla niej nie istnieje w chwili, w której powinno. To nie jest „zapomniałem". To jest — tego po prostu nie ma w głowie w tamtym momencie.</p>\n\n<p>Dlatego kalendarze, karteczki, budziki, aplikacje, przypomnienia u kogoś z AuDHD to nie jest niesamodzielność. To są okulary do pamięci. Krótkowidz nie jest głupi ani leniwy, że nosi okulary. Tu jest tak samo.</p>','\n',char(10)),'The memory of “I need to do something later”','The same problem. The person cannot see the task; for them, it does not exist at the moment when it should. This is not “I forgot.” It is simply not in their head at that moment.',NULL,NULL);
INSERT INTO content_sections VALUES(759,26,756,'heading',3,3,11,'Pamięć faktów w ciekawym temacie','pamiec-faktow-w-ciekawym-temacie','Druga skrajność. Ktoś z AuDHD wkręcony w temat pamięta o nim rzeczy w takich szczegółach, których neurotypowi po prostu nie kumają. Bo autystyczny mózg raz wkręcony wkręca się na maksa i pakuje wszystko w bardzo gęstą, uporządkowaną pamięć.',11,replace('<p>Druga skrajność. Ktoś z AuDHD wkręcony w temat pamięta o nim rzeczy w takich szczegółach, których neurotypowi po prostu nie kumają. Bo autystyczny mózg raz wkręcony wkręca się na maksa i pakuje wszystko w bardzo gęstą, uporządkowaną pamięć. Ta sama głowa, która nie pamięta, czy zjadła śniadanie, cytuje z pamięci datę i stronę.</p>\n\n<p>Neurotypowi zakładają, że jak ktoś pamięta jedno, to musi pamiętać drugie. Nie musi. Pamięć u AuDHD nie działa na zasadzie „ważne / nieważne", tylko „ciekawe / nieciekawe". Nudne, a ważne (rachunki, umówiona wizyta) — nie wejdzie. Ciekawe, a błahe (rzucona uwaga sprzed pięciu lat) — zostanie na zawsze.</p>','\n',char(10)),'Memory for facts in an interesting subject','The other extreme. Someone with AuDHD who gets absorbed in a subject remembers details about it that neurotypical people simply cannot grasp. Once the autistic brain locks onto a topic, it goes all in and packs everything into a very dense, organised memory.',NULL,NULL);
INSERT INTO content_sections VALUES(760,26,756,'heading',3,3,12,'Pamięć własnych przeżyć','pamiec-wlasnych-przezyc','Działa specyficznie. Fakty o wydarzeniu — kto był, gdzie, co powiedziane, ile trwało — są. Ale sam film z tego, sama emocja, samo wrażenie „jak to było" — słabe albo żadne. Trochę jakby ktoś oglądał opis swojego życia napisany przez kogoś obcego.',12,'<p>Działa specyficznie. Fakty o wydarzeniu — kto był, gdzie, co powiedziane, ile trwało — są. Ale sam film z tego, sama emocja, samo wrażenie „jak to było" — słabe albo żadne. Trochę jakby ktoś oglądał opis swojego życia napisany przez kogoś obcego. Zdarzenia są, treści emocjonalnej pod nimi nie ma.</p>','Memory of one''s own experiences','It works in a distinctive way. Facts about an event — who was there, where, what was said, how long it lasted — are present. But the film of it, the emotion, the sense of “what it was like” can be weak or absent. A little like reading a description of your own life written by someone else.',NULL,NULL);
INSERT INTO content_sections VALUES(761,26,749,'heading',2,2,13,'Maskowanie','maskowanie','Maskowanie polega na tym, że przez cały dzień świadomie udajesz kogoś bardziej „normalnego" niż jesteś — tłumisz odruchy, wkładasz cudzą mimikę, gasisz reakcje — a ta ciągła nadpraca w tle zżera zasoby, aż człowiek się wypala.',13,replace('<p class="jednozdaniowy">Maskowanie polega na tym, że przez cały dzień świadomie udajesz kogoś bardziej „normalnego" niż jesteś — tłumisz odruchy, wkładasz cudzą mimikę, gasisz reakcje — a ta ciągła nadpraca w tle zżera zasoby, aż człowiek się wypala.</p>\n\n<p>Neurotypowy nie musi grać, że jest neurotypowy — po prostu nim jest. Osoba z AuDHD, żeby wtopić się w otoczenie, musi to wszystko robić ręcznie i bez przerwy. To kosztuje energię, której potem nie ma na nic innego. I najczęściej nikt z zewnątrz tego nie widzi — bo o to właśnie w maskowaniu chodzi.</p>\n\n<p>Jak to wygląda w praktyce:</p>\n<ul>\n<li>Tłumienie odruchowych ruchów, którymi ciało się rozładowuje (kręcenie czegoś w palcach, bujanie, powtarzalne gesty)</li>\n<li>Ukrywanie emocji</li>\n<li>Zachowywanie się jak wszyscy dookoła, nawet kiedy to niewygodne i nie ma sensu</li>\n<li>Wkładanie sztucznej mimiki, bo „taką się wypada mieć"</li>\n<li>Nieproszenie o pomoc</li>\n<li>Udawanie, że lubisz coś, czego się nie znosi (albo odwrotnie)</li>\n<li>Duszenie w sobie załamania albo wybuchu, kiedy układ już nie wyrabia (skrajnie niebezpieczne — odbija się na zdrowiu)</li>\n<li>Przyłapywanie się, że kłamie się częściej niż zwykle — żeby przykryć własną bezpośredniość</li>\n<li>Zmuszanie się do kontaktu wzrokowego, który fizycznie boli</li>\n<li>Ciągłe przepraszanie za słabą pamięć albo inną cechę, której po prostu nie da się ukryć</li>\n<li>Siłowe powstrzymywanie się przed zasypaniem kogoś swoim ulubionym tematem</li>\n<li>Tłumaczenie cech, których nie da się zamaskować, tym że jest się „perfekcjonistą" albo „po prostu zestresowanym"</li>\n<li>Udawanie, że nie jest się przebodźcowanym — co prowadzi prosto do wypalenia</li>\n</ul>\n\n<p class="stopka">Plik stworzony 2026-07-09 o godz. 01:09 przez Maćka z pomocą Claude Opus 4.7 (Anthropic).<br>v02.01 (2026-07-09, godz. 14:12): dodano sekcję „Maskowanie" — tłumaczenie grafiki na polski, z pomocą Claude Opus 4.8 (Anthropic).<br>v02.02 (2026-07-09, godz. 14:17): „neuronudny" zmieniono na „neurotypowy" w całym pliku; dodano notkę o terminie na początku. Z pomocą Claude Opus 4.8 (Anthropic).</p>','\n',char(10)),'Camouflaging','Camouflaging means consciously pretending all day to be more “normal” than you are — suppressing reflexes, putting on someone else''s facial expressions, dampening reactions — while that constant background overwork eats through your resources until you burn out.',NULL,NULL);
INSERT INTO content_sections VALUES(762,27,NULL,'heading',1,1,1,'AuDHD u dorosłych — cechy i wzorce funkcjonowania','audhd-u-doroslych-cechy-i-wzorce-funkcjonowania','Wersja dokumentu: 6.0 | Data: 2026-07-01, godz. 15:21 (Europe/Warsaw) · Aktualizacja z pomocą Claude Opus 4.8 (Anthropic)',1,replace('<p class="small">Wersja dokumentu: 6.0 | Data: 2026-07-01, godz. 15:21 (Europe/Warsaw) &middot; Aktualizacja z pomocą Claude Opus 4.8 (Anthropic)</p>\n<div class="meta"><p><strong>Cel dokumentu.</strong> Ten materiał ma pomagać w rozumieniu samego siebie oraz w rozumieniu osób z AuDHD przez partnerów, przyjaciół, rodzinę i specjalistów. Nie służy do samodzielnego stawiania diagnozy ani do zastępowania konsultacji klinicznej. Jego rolą jest uporządkowanie cech, wzorców funkcjonowania i doświadczeń, które dla wielu osób przez lata były trudne do nazwania.</p><p><strong>Dla kogo to jest.</strong> Ten tekst jest napisany również dla osób, które czytają o AuDHD po raz pierwszy. Dlatego obok języka bardziej naukowego pojawiają się tu krótkie objaśnienia praktyczne: co dany punkt może znaczyć od środka i jak bywa odbierany przez bliskich.</p><p><strong>Jak powstał.</strong> Dokument został opracowany z pomocą ChatGPT (model GPT-5.4 Thinking) i Claude (model Claude Opus 4.6, Anthropic), na podstawie analizy materiału źródłowego oraz kwerendy źródeł naukowych. Wersja 5.1 dodaje klasyfikację pochodzenia cech (pierwotna / wtórna / mieszana) opracowaną z pomocą Claude Opus 4.6. Łączy on podejście możliwie naukowo ostrożne z językiem, który ma pozostać czytelny dla osób spoza środowiska klinicznego.</p></div>\n<div class="note"><p><strong>Jak czytać ten dokument.</strong> Każdy punkt ma dwa poziomy opisu. Najpierw pojawia się opis główny: możliwie precyzyjny i naukowo ostrożny. Potem pojawia się część praktyczna: krótkie rozwinięcie, co dany punkt może znaczyć dla samej osoby i jak może go czytać otoczenie bez nadmiernego moralizowania. Na początku znajduje się też „rozdział zero”, który wyjaśnia kilka pojęć potrzebnych do dalszej lektury.</p><p><strong>Ważne zastrzeżenie.</strong> AuDHD ma zwykle profil nierówny. Jedna osoba może bardzo pasować do części punktów, a prawie wcale do innych. Brak danej cechy lub wzorca nie wyklucza trudności, a obecność pojedynczego punktu sama w sobie nie stanowi diagnozy.</p></div>\n<div class="legend"><strong>Legenda poziomu oparcia:</strong><ul><li><strong>badania</strong> — punkt ma dość dobre oparcie w literaturze</li><li><strong>badania + obserwacja kliniczna</strong> — kierunek jest sensowny, ale opis jest częściowo kliniczny lub fenomenologiczny</li><li><strong>głównie obserwacja kliniczna / doświadczenie</strong> — punkt jest ważny i często trafny, ale słabiej uchwycony w badaniach</li></ul><p>Etykiety przy punktach pokazują, czy dany opis jest mocniej oparty na badaniach, czy w większym stopniu wynika z obserwacji klinicznej i doświadczenia osób z AuDHD.</p></div>\n\n<div class="note"><p><strong>Dla kogo jest ten dokument.</strong> Ten materiał dotyczy <strong>dorosłych osób z AuDHD</strong> — przede wszystkim tych, które nie miały diagnozy w dzieciństwie albo otrzymały ją dopiero w dorosłości. Wiele opisanych tu cech i wzorców wygląda inaczej u osób zdiagnozowanych wcześnie i mających od lat wsparcie. Późna diagnoza oznacza lata funkcjonowania bez nazwy, bez zrozumienia i bez odpowiednich narzędzi — a to samo w sobie zmienia obraz kliniczny i codzienne doświadczenie.</p></div>\n\n<div class="origin-legend"><strong>Legenda: skąd bierze się dana cecha?</strong>\n<p>Przy każdej cesze pojawia się oznaczenie jej <strong>pochodzenia</strong>:</p>\n<ul>\n<li><strong style="color:#2e7d32">PIERWOTNA — z budowy</strong> — cecha wynika wprost z neurologicznej architektury mózgu. Byłaby obecna nawet bez nacisku społecznego, maskowania i korekcji. Najczystszym testem jest pytanie: <em>czy nadrektor Mustrum Ridcully to ma?</em> Ridcully jest AuDHD, ale nigdy nie maskował — jego pozycja społeczna i siła fizyczna sprawiły, że koszt jego atypowości ponoszą inni (Skarbnik, Tęczyki, cały kadra). Jeśli Ridcully ma daną cechę — to jest pierwotna.</li>\n<li><strong style="color:#c62828">WTÓRNA — z nacisku</strong> — cecha NIE wynika z budowy mózgu, lecz z wieloletniego nacisku środowiska: maskowania, korygowania, odrzucenia, prób normalizacji. Ridcully jej NIE MA — bo nigdy nie musiał maskować. To dowód, że ta cecha jest ceną niedopasowania, nie częścią profilu AuDHD.</li>\n<li><strong style="color:#e65100">PIERWOTNA + wtórne nasilenie</strong> — cecha ma rdzeń neurologiczny, ale jest nasilona, zdeformowana lub inna w swoim przeżywaniu przez lata maskowania i społecznego nacisku. Ridcully ma wersję podstawową, ale bez warstwy bólu, wstydu i ruminacji, którą dokłada środowisko.</li>\n</ul>\n<p class="small">To rozróżnienie jest ważne klinicznie. Cechy <strong>pierwotne</strong> nie znikną — można się z nimi lepiej żyć, ale nie można ich „wyleczyć". Cechy <strong>wtórne</strong> mogą się zmniejszyć lub ustąpić, gdy zmieni się środowisko, diagnoza da zrozumienie, a maskowanie przestanie być jedyną strategią przetrwania. Cechy <strong>mieszane</strong> mają rdzeń, który zostaje, ale otoczkę, która może odpuścić.</p>\n</div>','\n',char(10)),'AuDHD in adults — features and patterns of functioning','Document version: 6.0 | Date: 2026-07-01, 15:21 (Europe/Warsaw) · Updated with the assistance of Claude Opus 4.8 (Anthropic)',NULL,NULL);
INSERT INTO content_sections VALUES(763,27,762,'heading',2,2,2,'ROZDZIAŁ ZERO — „Mam autyzm i ADHD. A jakie są Twoje supermoce?”','rozdzial-zero','Krótki wstęp do sposobu przetwarzania informacji, który pomaga czytać dalsze punkty bez żargonu',2,replace('<p class="small">Krótki wstęp do sposobu przetwarzania informacji, który pomaga czytać dalsze punkty bez żargonu</p>\n<div class="symptom">','\n',char(10)),'CHAPTER ZERO — “I have autism and ADHD. What are your superpowers?”','A brief introduction to information processing that helps make the points that follow readable without jargon.',NULL,NULL);
INSERT INTO content_sections VALUES(764,27,763,'heading',3,3,3,'0. Jak bywa zorganizowane przetwarzanie informacji w AuDHD badania + obserwacja kliniczna punkt wprowadzający','0-jak-bywa-zorganizowane-przetwarzanie-informacji-w-audhd','Ten punkt nie jest „supermocą” w prostym, cukierkowym sensie. Lepiej rozumieć go jako charakterystyczny styl przetwarzania , który bywa jednocześnie zasobem i źródłem kosztu.',3,replace('<p>Ten punkt nie jest „supermocą” w prostym, cukierkowym sensie. Lepiej rozumieć go jako <strong>charakterystyczny styl przetwarzania</strong>, który bywa jednocześnie zasobem i źródłem kosztu. W dużym uproszczeniu wiele osób autystycznych częściej startuje od szczegółu i dopiero z niego buduje całość. To bywa opisywane jako przewaga przetwarzania <strong>bottom-up</strong>, czyli „od dołu do góry”: najpierw konkretne sygnały, detale, cechy obiektu, drobne różnice i lokalne wzorce, a dopiero potem ogólny obraz. W praktyce można to porównać do sytuacji, w której ktoś najpierw widzi pojedyncze drzewa, krzewy, układ ścieżek i fakturę kory, a dopiero z tego układa sobie obraz całego lasu. U wielu osób neurotypowych częściej działa odwrotny kierunek: najpierw ogólny kontekst albo „las”, a dopiero potem wybrane szczegóły. To użyteczne uproszczenie, a nie sztywna reguła bez wyjątków.</p>\n<p>W autyzmie ten styl wiąże się też często z <strong>monotropizmem</strong>, czyli tendencją do kierowania większej części zasobów uwagi na jeden temat, zadanie lub wąski zestaw bodźców naraz. Stąd bierze się pojęcie <strong>tunelu uwagi</strong>: kiedy coś znajdzie się w centrum zainteresowania, może być przetwarzane bardzo głęboko, szczegółowo i intensywnie, ale rzeczy poza tunelem stają się mniej dostępne. To pomaga w analizie, wychwytywaniu wzorców i budowaniu wiedzy z dużą precyzją, ale utrudnia szybkie przełączanie się, zmianę priorytetów i jednoczesne trzymanie wielu rzeczy „na podglądzie”. U części osób z ADHD do tego dochodzi bardziej skojarzeniowy, rozgałęziający się tok myślenia. <strong>Myślenie asocjacyjne</strong> oznacza tu, że jedna myśl bardzo łatwo uruchamia kolejną: przez podobieństwo, kontrast, metaforę, wspomnienie, brzmienie słowa albo odległe skojarzenie. To może zwiększać kreatywność i liczbę nietypowych połączeń, ale czasem utrudnia linearną wypowiedź i utrzymanie jednej ścieżki rozmowy.</p>\n<p>Przy pierwszym czytaniu przydają się jeszcze trzy krótkie definicje. <strong>Ruminacje</strong> to powracające, zapętlające się myśli — zwykle o czymś trudnym, bolesnym albo nierozwiązanym — które trudno zatrzymać samą decyzją. <strong>Fenomenologia</strong> to po prostu opis doświadczenia „od środka”: nie tylko tego, co widać z zewnątrz, ale też tego, jak jest to przeżywane przez samą osobę. <strong>Monotropowe myślenie</strong> to styl skupienia, w którym uwaga układa się bardziej w głąb niż wszerz: mniej jednoczesnych kanałów, ale większa intensywność w tym, co już weszło do centrum. Ten rozdział zostaje na początku, bo później te pojęcia wracają wielokrotnie. Powtórzenia są tu celowe: ułatwiają czytanie osobie, która nie ma zaplecza z kognitywistyki czy psychologii poznawczej.</p>\n<p class="small"><strong>Objaśnienie:</strong> Porównanie „najpierw drzewa, potem las” jest skrótem myślowym. Ma pomagać, a nie udowadniać, że wszyscy autystyczni ludzie przetwarzają informacje dokładnie tak samo, a wszyscy neurotypowi dokładnie odwrotnie. Chodzi o częsty kierunek różnicy, nie o absolutną regułę.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Styl przetwarzania bottom-up wynika wprost z architektury neuronalnej. Nadrektor Ridcully przetwarza świat dokładnie tak samo — od szczegółu do ogółu. Żaden nacisk społeczny tego nie zmienia ani nie wytwarza.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> taki styl myślenia może dawać dużą przenikliwość, zdolność widzenia niuansów i bardzo oryginalne połączenia między tematami. Jednocześnie może sprawiać, że rozmowy, instrukcje i zadania oparte na szybkim „łapaniu ogółu” wydają się niejasne albo zbyt skrótowe.</p><p><strong>Dla bliskich:</strong> czasem warto najpierw nazwać kontekst, a dopiero potem przejść do szczegółów; innym razem odwrotnie — pozwolić osobie zacząć od detalu, bo właśnie tak buduje sobie całość. To nie jest gorszy styl myślenia, tylko inny punkt startu i inny rozkład uwagi.</p>\n<p class="refs"><strong>Najbliższe źródła:</strong> R21, R22, R23, R24, R25, R26, R27, R28</p>\n</div>\n</div>\n<nav class="toc" aria-label="Spis treści">','\n',char(10)),'0. How information processing may be organised in AuDHD — research + clinical observation · introductory point','This point is not a “superpower” in a simple, sugary sense. It is better understood as a characteristic processing style that can be both a resource and a source of cost.',NULL,NULL);
INSERT INTO content_sections VALUES(765,27,762,'heading',2,2,4,'Spis treści','spis-tresci','ROZDZIAŁ ZERO — „Mam autyzm i ADHD. A jakie są Twoje supermoce?” 0. Jak bywa zorganizowane przetwarzanie informacji w AuDHD',4,replace('<ul>\n<li><a href="#rozdzial-zero">ROZDZIAŁ ZERO — „Mam autyzm i ADHD. A jakie są Twoje supermoce?”</a>\n<ul>\n<li><a href="#0-jak-bywa-zorganizowane-przetwarzanie-informacji-w-audhd">0. Jak bywa zorganizowane przetwarzanie informacji w AuDHD</a></li>\n</ul>\n</li>\n<li><a href="#grupa-i-najczesciej-rozpoznawane">GRUPA I — Najczęściej rozpoznawane</a>\n<ul>\n<li><a href="#1-trudnosci-z-funkcjami-wykonawczymi">1. Trudności z funkcjami wykonawczymi</a></li>\n<li><a href="#2-hiperfokus-chaotyczny">2. Hiperfokus chaotyczny</a></li>\n<li><a href="#3-wewnetrzny-konflikt-rutyna-vs-nowosc">3. Wewnętrzny konflikt: rutyna vs nowość</a></li>\n<li><a href="#4-dysregulacja-emocjonalna">4. Dysregulacja emocjonalna</a></li>\n<li><a href="#5-przeciazenie-sensoryczne">5. Przeciążenie sensoryczne</a></li>\n<li><a href="#6-trudnosci-spoleczne-z-impulsywnoscia">6. Trudności społeczne z impulsywnością</a></li>\n<li><a href="#7-trudnosci-z-zasypianiem-mozg-ktory-sie-nie-wylacza">7. Trudności z zasypianiem — mózg, który się nie wyłącza</a></li>\n<li><a href="#8-wieczorne-ozywienie-nocna-wersja-siebie">8. Wieczorne ożywienie — „nocna wersja siebie"</a></li>\n</ul>\n</li>\n<li><a href="#grupa-ii-czesto-doswiadczane-ale-blednie-interpretowane">GRUPA II — Często doświadczane, ale błędnie interpretowane</a>\n<ul>\n<li><a href="#9-cykliczne-wypalenia-przypominajace-depresje">9. Cykliczne wypalenia przypominające depresję</a></li>\n<li><a href="#10-wrazliwosc-na-odrzucenie-rsd">10. Wrażliwość na odrzucenie (RSD)</a></li>\n<li><a href="#11-zmienne-zapotrzebowanie-na-samotnosc">11. Zmienne zapotrzebowanie na samotność</a></li>\n<li><a href="#12-intensywna-empatia-wygladajaca-jak-brak-empatii">12. Intensywna empatia wyglądająca jak brak empatii</a></li>\n<li><a href="#13-szukanie-i-unikanie-bodzcow-jednoczesnie">13. Szukanie i unikanie bodźców jednocześnie</a></li>\n<li><a href="#14-chroniczna-niepunktualnosc-lub-obsesyjna-punktualnosc">14. Chroniczna niepunktualność LUB obsesyjna punktualność</a></li>\n<li><a href="#15-cykliczne-zainteresowania">15. Cykliczne zainteresowania</a></li>\n<li><a href="#16-nietypowe-reakcje-na-leki-i-substancje">16. Nietypowe reakcje na leki i substancje</a></li>\n<li><a href="#17-efekt-wszystko-albo-nic-w-nawykach">17. Efekt „wszystko albo nic" w nawykach</a></li>\n</ul>\n</li>\n<li><a href="#grupa-iii-subtelne-latwo-pomijane">GRUPA III — Subtelne, łatwo pomijane</a>\n<ul>\n<li><a href="#18-paradoks-porzadku-i-chaosu">18. Paradoks porządku i chaosu</a></li>\n<li><a href="#19-prokrastynacja-przez-perfekcjonizm">19. Prokrastynacja przez perfekcjonizm</a></li>\n<li><a href="#20-powtarzalne-ruchy-i-gesty-regulujace-uklad-nerwowy-tzw-stimming">20. Powtarzalne ruchy i gesty regulujące układ nerwowy (tzw. stimming)</a></li>\n<li><a href="#21-slaba-interocepcja-nie-czujesz-co-dzieje-sie-w-twoim-ciele">21. Słaba interocepcja — nie czujesz, co dzieje się w twoim ciele</a></li>\n<li><a href="#22-aleksytymia-nie-umiesz-nazwac-tego-co-czujesz">22. Aleksytymia — nie umiesz nazwać tego, co czujesz</a></li>\n<li><a href="#23-maskowanie-spoleczne-na-zmiane-z-impulsywnoscia-spoleczna">23. Maskowanie społeczne na zmianę z impulsywnością społeczną</a></li>\n<li><a href="#24-wyczerpanie-po-decyzjach">24. Wyczerpanie po decyzjach</a></li>\n<li><a href="#25-specyficzny-stosunek-do-jedzenia">25. Specyficzny stosunek do jedzenia</a></li>\n<li><a href="#26-trudnosc-z-przejsciami-miedzy-aktywnosciami-autystyczna-inercja">26. Trudność z przejściami między aktywnościami (autystyczna inercja)</a></li>\n<li><a href="#27-zmienne-progi-sensoryczne">27. Zmienne progi sensoryczne</a></li>\n<li><a href="#28-geniusz-w-kryzysie-paraliz-w-spokoju">28. Geniusz w kryzysie, paraliż w spokoju</a></li>\n<li><a href="#29-unikanie-wymagan-demand-avoidance">29. Unikanie wymagań (demand avoidance)</a></li>\n<li><a href="#30-problemy-z-koordynacja-i-propriocepcja">30. Problemy z koordynacją i propriocepcją</a></li>\n<li><a href="#31-kompensacja-jednego-stanu-drugim">31. Kompensacja jednego stanu drugim</a></li>\n</ul>\n</li>\n<li><a href="#grupa-iv-glebokie-rzadko-omawiane">GRUPA IV — Głębokie, rzadko omawiane</a>\n<ul>\n<li><a href="#32-pamiec-encyklopedyczna-obok-pamieci-zlotej-rybki">32. Pamięć encyklopedyczna obok pamięci „złotej rybki"</a></li>\n<li><a href="#33-zapominanie-ze-sie-cos-wie">33. Zapominanie, że się coś wie</a></li>\n<li><a href="#34-myslenie-w-systemach-trudnosc-z-wyjasnieniem">34. Myślenie w systemach, trudność z wyjaśnieniem</a></li>\n<li><a href="#35-przetwarzanie-w-tle">35. Przetwarzanie „w tle"</a></li>\n<li><a href="#36-kameleonizm-dyfuzja-tozsamosci">36. Kameleonizm (dyfuzja tożsamości)</a></li>\n<li><a href="#37-moralna-skrupulatnosc">37. Moralna skrupulatność</a></li>\n<li><a href="#38-mowienie-za-duzo-lub-za-malo-bez-srodka">38. Mówienie za dużo lub za mało, bez środka</a></li>\n<li><a href="#39-wrazliwosc-na-niesprawiedliwosc-ktora-paralizuje">39. Wrażliwość na niesprawiedliwość, która paraliżuje</a></li>\n<li><a href="#40-kochanie-przez-dzielenie-sie-informacjami">40. Kochanie przez dzielenie się informacjami</a></li>\n<li><a href="#41-glod-bliskosci-ktory-przeraza">41. Głód bliskości, który przeraża</a></li>\n<li><a href="#42-potrzeba-werbalnego-potwierdzania-zasad-relacji">42. Potrzeba werbalnego potwierdzania zasad relacji</a></li>\n<li><a href="#43-fizyczne-objawy-stresu-z-opoznieniem">43. Fizyczne objawy stresu z opóźnieniem</a></li>\n<li><a href="#44-bol-ktory-jest-niewlasciwy">44. Ból, który jest „niewłaściwy"</a></li>\n<li><a href="#45-zmeczenie-ktore-nie-ma-dna">45. Zmęczenie, które nie ma dna</a></li>\n<li><a href="#46-podwojne-przetwarzanie-rzeczywistosci">46. Podwójne przetwarzanie rzeczywistości</a></li>\n<li><a href="#47-poczucie-ze-sie-jest-za-duzo-i-za-malo-jednoczesnie">47. Poczucie, że się jest „za dużo" i „za mało" jednocześnie</a></li>\n<li><a href="#48-wewnetrzny-tlumacz-dzialajacy-non-stop">48. Wewnętrzny „tłumacz" działający non-stop</a></li>\n<li><a href="#49-nostalgia-jako-regulacja">49. Nostalgia jako regulacja</a></li>\n<li><a href="#50-wewnetrzny-monolog-ktory-nigdy-sie-nie-wylacza">50. Wewnętrzny monolog, który nigdy się nie wyłącza</a></li>\n<li><a href="#51-poczucie-ze-czas-dziala-inaczej">51. Poczucie, że czas działa inaczej</a></li>\n<li><a href="#52-kryzys-tozsamosci-przy-zmianie-zainteresowan">52. Kryzys tożsamości przy zmianie zainteresowań</a></li>\n<li><a href="#53-tesknota-za-niepoznanym-jeszcze-soba">53. Tęsknota za niepoznanym jeszcze sobą</a></li>\n<li><a href="#54-zbieranie-informacji-na-zapas">54. Zbieranie informacji „na zapas"</a></li>\n<li><a href="#55-specyficzny-humor">55. Specyficzny humor</a></li>\n<li><a href="#56-nadmierne-tlumaczenie-sie-i-przepraszanie-za-istnienie">56. Nadmierne tłumaczenie się i przepraszanie za istnienie</a></li>\n<li><a href="#57-wykonywanie-zadan-nie-po-kolei">57. Wykonywanie zadań „nie po kolei"</a></li>\n<li><a href="#58-poczucie-udawania-doroslego">58. Poczucie „udawania dorosłego"</a></li>\n<li><a href="#59-underachievement-ktory-boli">59. Underachievement, który boli</a></li>\n<li><a href="#60-potrzeba-rozumienia-dlaczego-przed-zrobieniem-czegokolwiek">60. Potrzeba rozumienia „dlaczego" przed zrobieniem czegokolwiek</a></li>\n<li><a href="#61-poczucie-bycia-z-innej-planety">61. Poczucie „bycia z innej planety"</a></li>\n<li><a href="#62-gleboka-potrzeba-bycia-zrozumianym-nie-naprawionym">62. Głęboka potrzeba bycia zrozumianym, nie naprawionym</a></li>\n</ul>\n</li>\n<li><a href="#uwagi-koncowe">Uwagi końcowe</a>\n</li>\n<li><a href="#bibliografia-glowna">Bibliografia główna</a>\n</li>\n</ul>\n</nav>','\n',char(10)),'Table of contents','CHAPTER ZERO — “I have autism and ADHD. What are your superpowers?” 0. How information processing may be organised in AuDHD',NULL,NULL);
INSERT INTO content_sections VALUES(766,27,762,'heading',2,2,5,'GRUPA I — Najczęściej rozpoznawane','grupa-i-najczesciej-rozpoznawane','Cechy i wzorce funkcjonowania, które zwykle zwracają uwagę jako pierwsze',5,replace('<p class="small">Cechy i wzorce funkcjonowania, które zwykle zwracają uwagę jako pierwsze</p>\n<div class="symptom">','\n',char(10)),'GROUP I — Most readily recognised','Features and patterns of functioning that usually attract attention first.',NULL,NULL);
INSERT INTO content_sections VALUES(767,27,766,'heading',3,3,6,'1. Trudności z funkcjami wykonawczymi badania powszechne','1-trudnosci-z-funkcjami-wykonawczymi','Funkcje wykonawcze to zestaw umiejętności mentalnych, które pozwalają planować, organizować, rozpoczynać i kończyć zadania, zarządzać czasem i przełączać się między aktywnościami.',6,replace('<p>Funkcje wykonawcze to zestaw umiejętności mentalnych, które pozwalają planować, organizować, rozpoczynać i kończyć zadania, zarządzać czasem i przełączać się między aktywnościami. Można o nich myśleć jak o „menedżerze" w mózgu, który koordynuje wszystko, co robimy. U osób z AuDHD trudności w tym obszarze mogą się kumulować: autyzm często utrudnia elastyczne przejścia i zmianę trybu, a ADHD osłabia utrzymanie kierunku działania, pamięć roboczą i organizację. W praktyce oznacza to, że osoba może doskonale wiedzieć, co powinna zrobić — ale „wiedzieć" i „móc to zrobić" to dwie zupełnie różne rzeczy. Lista zadań istnieje w głowie (albo na papierze), ale mózg nie potrafi przełożyć jej na działanie. Nie z lenistwa ani z braku motywacji, ale dlatego że system koordynujący nie działa tak, jak u osób neurotypowych.</p>\n<p class="small"><strong>Objaśnienie:</strong> W praktyce ten punkt często bywa mylony z brakiem dyscypliny. Warto jednak odróżnić wiedzę o tym, co trzeba zrobić, od zdolności uruchomienia sekwencji działań we właściwym momencie.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Deficyty funkcji wykonawczych wynikają z budowy kory przedczołowej i połączeń dopaminergicznych. Ridcully ma je w pełni — chaos organizacyjny, przeskakiwanie, trudność z sekwencją. To nie jest efekt maskowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> problem zwykle dotyczy uruchomienia i przełączania, nie wiedzy ani inteligencji. To ważne, bo sama presja rzadko poprawia wykonanie, a często tylko zwiększa wstyd i przeciążenie.</p><p><strong>Dla bliskich:</strong> mniej pomaga nacisk, bardziej pomaga rozbicie zadania i jasny pierwszy krok. Najlepiej działa zmniejszenie tarcia: jasna kolejność, jeden konkretny start i mniej wieloznacznych komunikatów.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R3, R17</p>\n</div>\n<div class="symptom">','\n',char(10)),'1. Executive-function difficulties — research · widespread','Executive functions are a set of mental skills that make it possible to plan, organise, start and finish tasks, manage time, and switch between activities.',NULL,NULL);
INSERT INTO content_sections VALUES(768,27,766,'heading',3,3,7,'2. Hiperfokus chaotyczny badania + obserwacja kliniczna bardzo częste','2-hiperfokus-chaotyczny','Hiperfokus to stan bardzo głębokiego, intensywnego skupienia na jednej rzeczy — tak głębokiego, że reszta świata praktycznie przestaje istnieć. Osoby neurotypowe też czasem tego doświadczają (np.',7,replace('<p>Hiperfokus to stan bardzo głębokiego, intensywnego skupienia na jednej rzeczy — tak głębokiego, że reszta świata praktycznie przestaje istnieć. Osoby neurotypowe też czasem tego doświadczają (np. pochłonięcie ciekawą książką), ale u osób AuDHD ten stan jest znacznie intensywniejszy i mniej kontrolowalny. Autystyczna część mózgu potrafi zanurzać się w temacie z ogromną głębią i szczegółowością, a ADHD-owa część dodaje intensywność pobudzenia. Problem w tym, że w „czystym" autyzmie zainteresowania specjalne bywają bardziej stabilne — ktoś może fascynować się jednym tematem przez lata. W AuDHD te fascynacje są bardziej chaotyczne: osoba zanurza się totalnie, czasem na kilkanaście godzin bez przerwy, a potem nagle temat „gaśnie" i pojawia się następny. To nie utrata zainteresowania — to ADHD, które przesunęło reflektor uwagi. Stare fascynacje mogą wrócić cyklicznie, ale nie da się tego kontrolować ani przewidzieć.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Hiperfokus wynika z monotropowej alokacji uwagi (autyzm) + niestabilnej regulacji dopaminy (ADHD). Ridcully wchodzi w projekty z całą mocą — i porzuca je, gdy się wypalą. Nikt go nie nauczył tego wzorca; taki jest jego mózg.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> hiperfokus może być zasobem, ale też utrudniać zatrzymanie się i zmianę biegu. Dobrze wtedy planować moment wyjścia z zadania, bo samo wejście w fokus nie daje jeszcze kontroli nad zakończeniem.</p><p><strong>Dla bliskich:</strong> warto uprzedzać o zmianach i nie brać dosłownie chwilowej niedostępności. Pomaga umawianie sygnału przejścia i trochę czasu na wyjście z tematu, zamiast oczekiwania natychmiastowej zmiany.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R2, R17</p>\n</div>\n<div class="symptom">','\n',char(10)),'2. Chaotic hyperfocus — research + clinical observation · very common','Hyperfocus is a state of very deep, intense concentration on one thing — so deep that the rest of the world practically ceases to exist. Neurotypical people sometimes experience it too (e.g.',NULL,NULL);
INSERT INTO content_sections VALUES(769,27,766,'heading',3,3,8,'3. Wewnętrzny konflikt: rutyna vs nowość badania + obserwacja kliniczna powszechne','3-wewnetrzny-konflikt-rutyna-vs-nowosc','To jeden z najbardziej charakterystycznych wzorców funkcjonowania w AuDHD i jednocześnie jeden z najtrudniejszych do zrozumienia z zewnątrz.',8,replace('<p>To jeden z najbardziej charakterystycznych wzorców funkcjonowania w AuDHD i jednocześnie jeden z najtrudniejszych do zrozumienia z zewnątrz. U wielu osób współistnieje silna potrzeba przewidywalności, stałych punktów i znanego układu dnia z równie silną potrzebą nowości, zmiany i pobudzenia. Struktura daje poczucie bezpieczeństwa, ale zbyt sztywna szybko zaczyna męczyć; spontaniczność daje dopływ energii, ale w nadmiarze prowadzi do chaosu i przeciążenia. W praktyce może to wyglądać tak, że osoba tworzy dokładne plany, listy i systemy, a potem nie jest w stanie ich utrzymać — nie dlatego, że są nieważne, lecz dlatego, że po pewnym czasie przestają dostarczać wystarczającej stymulacji albo zaczynają być zbyt ciasne. Z zewnątrz bywa to odbierane jako niespójność, ale od środka częściej jest to zderzenie dwóch realnych potrzeb układu nerwowego.</p>\n<p class="small"><strong>Objaśnienie:</strong> To napięcie warto czytać nie jako brak zdecydowania, lecz jako próbę pogodzenia potrzeby bezpieczeństwa z potrzebą pobudzenia. Wiele codziennych trudności bierze się właśnie z tego, że żadna z tych potrzeb nie daje się po prostu wyłączyć.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Napięcie rutyna–nowość to zderzenie dwóch systemów neurologicznych: autystycznej potrzeby przewidywalności i ADHD-owej potrzeby stymulacji. Ridcully ma to wyraźnie — rozkaz dnia ma być stały, ale wdraża absurdalne zmiany bez ostrzeżenia.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> można jednocześnie potrzebować struktury i świeżości — to nie jest nielogiczne. Najczęściej pomaga układ, który jest przewidywalny, ale nie martwy: kilka stałych punktów i trochę miejsca na zmianę.</p><p><strong>Dla bliskich:</strong> nie warto oceniać tej sprzeczności jako fanaberii; lepiej szukać rytmu z odrobiną elastyczności. Praktycznie zwykle lepiej sprawdza się wspólne budowanie bezpiecznej rutyny niż walka o całkowitą przewidywalność albo totalną spontaniczność.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R17, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'3. Internal conflict: routine vs novelty — research + clinical observation · widespread','This is one of the most characteristic patterns of functioning in AuDHD and, at the same time, one of the hardest to understand from the outside.',NULL,NULL);
INSERT INTO content_sections VALUES(770,27,766,'heading',3,3,9,'4. Dysregulacja emocjonalna badania bardzo częste','4-dysregulacja-emocjonalna','Dysregulacja emocjonalna oznacza, że emocje pojawiają się szybciej, silniej i trwają dłużej, niż osoba by chciała, a zdolność do ich modulowania jest ograniczona.',9,replace('<p>Dysregulacja emocjonalna oznacza, że emocje pojawiają się szybciej, silniej i trwają dłużej, niż osoba by chciała, a zdolność do ich modulowania jest ograniczona. To nie to samo co „bycie emocjonalnym" — chodzi o to, że mózg nie ma wystarczających hamulców emocjonalnych. U osób z samym ADHD emocje bywają intensywne, ale przechodzą szybko. U osób z samym autyzmie emocje bywają głębokie i trudne do zidentyfikowania. U AuDHD oba te wzorce nakładają się na siebie: emocje przychodzą gwałtownie (ADHD), a jednocześnie są trudne do nazwania i przetworzenia (autyzm). Efektem jest stan, w którym osoba jest zalana intensywną emocją, nie do końca wie, co to za emocja, i nie potrafi jej stonować. Z zewnątrz może to wyglądać jak zaburzenie osobowości borderline, zaburzenie dwubiegunowe albo po prostu „nadmierna dramatyczność". Ale mechanizm jest zupełnie inny — to nie niestabilność osobowości, to neurologiczna reakcja mózgu, który przetwarza emocje inaczej.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Dysregulacja emocjonalna wynika z atypowego działania kory przedczołowej i ciała migdałowatego. Ridcully reaguje gwałtownie, intensywnie i trudno mu się zatrzymać. To nie efekt środowiska — to tempo i siła samego systemu emocjonalnego.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> intensywność emocji nie oznacza słabości, tylko mniejszy margines regulacji. Po fakcie wiele osób czuje zmęczenie, wstyd albo bezradność, choć w samym momencie trudno im zatrzymać reakcję.</p><p><strong>Dla bliskich:</strong> najpierw pomaga obniżenie pobudzenia, dopiero potem rozmowa o treści konfliktu. Najczęściej bardziej pomaga nazwanie stanu i obniżenie bodźców niż dyskusja o tym, czy reakcja była „proporcjonalna”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R3, R1</p>\n</div>\n<div class="symptom">','\n',char(10)),'4. Emotional dysregulation — research · very common','Emotional dysregulation means that emotions arise faster, more strongly, and last longer than the person would like, while the ability to modulate them is limited.',NULL,NULL);
INSERT INTO content_sections VALUES(771,27,766,'heading',3,3,10,'5. Przeciążenie sensoryczne badania bardzo częste (69–93% osób autystycznych)','5-przeciazenie-sensoryczne','Większość ludzi ma w mózgu naturalny filtr, który automatycznie przycisza nieistotne bodźce sensoryczne — szum lodówki, brzęczenie świetlówki, dotyk metki w koszulce.',10,replace('<p>Większość ludzi ma w mózgu naturalny filtr, który automatycznie przycisza nieistotne bodźce sensoryczne — szum lodówki, brzęczenie świetlówki, dotyk metki w koszulce. U osób AuDHD ten filtr działa inaczej: albo przepuszcza za dużo (nadwrażliwość — dźwięki są za głośne, światła za jasne, tekstury drażniące), albo za mało (niedowrażliwość — osoba nie czuje bólu albo nie zauważa temperatury), albo oba wzorce jednocześnie w różnych zmysłach. Ważne: zmysłów jest osiem, nie pięć. Oprócz wzroku, słuchu, dotyku, smaku i węchu istnieją jeszcze interocepcja (odczuwanie wnętrza ciała), propriocepcja (odczuwanie ciała w przestrzeni) i zmysł przedsionkowy (równowaga). U osób AuDHD wszystkie mogą działać atypowo. Metaanalizy ponad 5000 uczestników potwierdzają istotne atypie sensoryczne we wszystkich domenach. W codziennym życiu oznacza to, że coś tak prostego jak wizyta w supermarkecie — z jaskrawymi światłami, muzakiem, zapachami, tłumem, sygnałami kas — może powodować przeciążenie całego systemu nerwowego i prowadzić do wyczerpania, które z zewnątrz wygląda jak „nagły spadek energii bez powodu".</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Atypowe przetwarzanie sensoryczne wynika z budowy dróg sensory-korowych. Ridcully ma silne preferencje sensoryczne (jedzenie, temperatura, hałas) — to wrodzone, nie wyuczone.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> przeciążenie sensoryczne jest realnym kosztem biologicznym, nie przesadą. Przeciążenie sensoryczne często narasta po cichu, więc własne granice warto zauważać wcześniej niż dopiero przy załamaniu.</p><p><strong>Dla bliskich:</strong> ograniczenie hałasu, światła i chaosu bywa skuteczniejsze niż namawianie do ''przyzwyczajenia się''. Czasem największą pomocą jest uszanowanie prośby o ciszę, przerwę, zmianę miejsca albo prostsze warunki.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R17, R1</p>\n</div>\n<div class="symptom">','\n',char(10)),'5. Sensory overload — research · very common (69–93% of autistic people)','Most people have a natural filter in the brain that automatically turns down irrelevant sensory input — the hum of a refrigerator, the buzz of a fluorescent lamp, the touch of a clothing label.',NULL,NULL);
INSERT INTO content_sections VALUES(772,27,766,'heading',3,3,11,'6. Trudności społeczne z impulsywnością badania + obserwacja kliniczna bardzo częste','6-trudnosci-spoleczne-z-impulsywnoscia','Interakcje społeczne opierają się na wielu niejawnych regułach — kiedy jest twoja kolej, żeby mówić, jak długo patrzeć komuś w oczy, kiedy zmienić temat, jak odczytać ton głosu, kiedy żart jest odpowiedni.',11,replace('<p>Interakcje społeczne opierają się na wielu niejawnych regułach — kiedy jest twoja kolej, żeby mówić, jak długo patrzeć komuś w oczy, kiedy zmienić temat, jak odczytać ton głosu, kiedy żart jest odpowiedni. Osoby autystyczne mają trudność z automatycznym odczytywaniem tych reguł — nie dlatego, że je to nie obchodzi, ale dlatego, że ich mózg nie przetwarza tych informacji „w tle" tak jak mózg neurotypowy. Wszystko trzeba dekodować świadomie, co wymaga ogromnego wysiłku i czasu. Do tego ADHD dodaje impulsywność — przerywanie, mówienie za dużo, mówienie rzeczy zbyt bezpośrednio lub nie na temat, bo myśl pojawiła się i musiała zostać wypowiedziana zanim umknie. Efektem jest paradoks: osoba jednocześnie bardzo się stara społecznie (autystyczne analizowanie) i popełnia „błędy" społeczne (ADHD-owa impulsywność). Z zewnątrz wygląda to jak sprzeczność — „przecież czasem świetnie ci idzie, to dlaczego teraz powiedziałeś coś tak dziwnego?". Od wewnątrz — to nieustanna walka dwóch systemów.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: impulsywność i trudność z automatycznym dekodowaniem reguł społecznych wynikają z budowy. WTÓRNA: świadome analizowanie każdej interakcji, ruminacja po rozmowie, lęk społeczny — to naddatek z lat doświadczeń odrzucenia. Ridcully mówi co chce, kiedy chce, i nie analizuje potem — bo nigdy nie musiał.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> można mieć dobre intencje i nadal wypadać z rytmu rozmowy. Po rozmowie często przychodzi długotrwałe analizowanie, czy nie powiedziało się za dużo, za ostro albo nie w tym momencie.</p><p><strong>Dla bliskich:</strong> warto oddzielać formę przekazu od intencji i dopytywać zamiast zakładać złą wolę. Warto oceniać intencję i całość relacji, nie tylko pojedyncze potknięcie w tempie rozmowy czy doborze słów.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R12, R13</p>\n</div>\n<div class="symptom">','\n',char(10)),'6. Social difficulties with impulsivity — research + clinical observation · very common','Social interactions depend on many implicit rules — when it is your turn to speak, how long to look someone in the eye, when to change the subject, how to read tone of voice, when a joke is appropriate.',NULL,NULL);
INSERT INTO content_sections VALUES(773,27,766,'heading',3,3,12,'7. Trudności z zasypianiem — mózg, który się nie wyłącza badania + obserwacja kliniczna bardzo częste','7-trudnosci-z-zasypianiem-mozg-ktory-sie-nie-wylacza','Wieczorem, kiedy otoczenie cichnie i bodźce zewnętrzne słabną, mózg AuDHD nie cichnie razem z nimi — wręcz przeciwnie, często wtedy się rozkręca.',12,replace('<p>Wieczorem, kiedy otoczenie cichnie i bodźce zewnętrzne słabną, mózg AuDHD nie cichnie razem z nimi — wręcz przeciwnie, często wtedy się rozkręca. ADHD-owy mózg potrzebuje stymulacji, a cisza i ciemność sypialni to przeciwieństwo stymulacji, więc zaczyna sam ją produkować: myśli się zapętlają, pojawiają się pomysły, analizy dnia, plany na jutro, wspomnienia sprzed lat. Wszystko naraz. Jednocześnie autystyczna część mózgu potrzebuje bardzo konkretnych warunków sensorycznych, żeby się wyciszyć: konkretna temperatura, odpowiednia pościel, brak pewnych dźwięków, pewna pozycja ciała. Jeśli jeden z tych elementów się nie zgadza — zasypianie staje się nieproporcjonalnie trudne. Nie chodzi o „niewygodną poduszkę" w zwykłym sensie. Chodzi o to, że mózg nie potrafi pominąć tego jednego bodźca, bo filtr sensoryczny tego nie przepuści. Wiele osób AuDHD kładzie się spać o przyzwoitej godzinie i leży dwie, trzy godziny zanim zaśnie — nie z braku zmęczenia, ale dlatego że mózg i ciało nie potrafią zsynchronizować się w stan gotowości do snu.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Opóźniona faza snu, trudność z wyciszeniem i atypowe wymagania sensoryczne wobec warunków snu — to neurobiologia, nie nawyk. Ridcully zasypia kiedy chce, ale na swoich warunkach.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> brak snu często nasila wszystkie pozostałe trudności. Pomaga traktowanie snu nie jako prostego nawyku, tylko jako obszaru wymagającego warunków bezpieczeństwa i wyciszenia.</p><p><strong>Dla bliskich:</strong> stały rytm, mniej bodźców wieczorem i mniej presji bywają bardziej pomocne niż rady typu ''po prostu idź spać''. Dobre rady higieny snu pomagają mniej niż realne zrozumienie, że wieczorne wyciszenie może być dla tej osoby trudniejsze niż przeciętnie.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R4</p>\n</div>\n<div class="symptom">','\n',char(10)),'7. Difficulty falling asleep — a brain that does not switch off — research + clinical observation · very common','In the evening, when the surroundings quiet down and external stimuli weaken, the AuDHD brain does not become quiet with them. Quite the opposite: this is often when it starts to speed up.',NULL,NULL);
INSERT INTO content_sections VALUES(774,27,766,'heading',3,3,13,'8. Wieczorne ożywienie — „nocna wersja siebie" badania + obserwacja kliniczna bardzo częste','8-wieczorne-ozywienie-nocna-wersja-siebie','Wiele osób AuDHD opisuje, że po całym dniu zmagania się ze światem — maskowania, przetwarzania bodźców, tłumaczenia sobie i światu — wieczorem nagle przychodzi jasność myśli, kreatywność, energia. To nie jest przypadek.',13,replace('<p>Wiele osób AuDHD opisuje, że po całym dniu zmagania się ze światem — maskowania, przetwarzania bodźców, tłumaczenia sobie i światu — wieczorem nagle przychodzi jasność myśli, kreatywność, energia. To nie jest przypadek. W ciągu dnia mózg jest obciążony ciągłym dekodowaniem bodźców społecznych i sensorycznych. Wieczorem, gdy bodźce zewnętrzne słabną, mózg wreszcie ma przestrzeń na własne przetwarzanie. Noc jest ciszej, mniej wymagająca, a świat stawia mniej oczekiwań — i łatwiej jest być sobą. Dlatego wiele osób AuDHD mówi, że ich „prawdziwe ja" budzi się po 22:00. Problem w tym, że świat działa na zupełnie innym rytmie — praca zaczyna się rano, spotkania są przed południem, a produktywność jest oczekiwana w godzinach, kiedy mózg AuDHD jeszcze się „ładuje". To prowadzi do chronicznego konfliktu między biologicznym rytmem a społecznymi wymaganiami.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: chronotyp wieczorny i lepsze przetwarzanie przy niższym obciążeniu sensorycznym to cecha biologiczna. WTÓRNA: poczucie, że ''prawdziwe ja'' budzi się dopiero wieczorem, wynika z tego, że dzień jest wypełniony maskowaniem. Ridcully nie ma tego rozróżnienia — jest sobą cały czas.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> wieczorna sprawność nie unieważnia dziennego przeciążenia. To nie zawsze oznacza, że wieczór jest „zdrowszy”, tylko że dopiero wtedy spada koszt bycia w ciągłej gotowości.</p><p><strong>Dla bliskich:</strong> warto nie mylić późnego ożywienia z lenistwem czy unikaniem obowiązków. Nie każda późna aktywność jest wyborem przeciw innym; czasem to jedyny moment, gdy układ nerwowy działa względnie swobodnie.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R4</p>\n</div>','\n',char(10)),'8. Evening activation — the “night version of yourself” — research + clinical observation · very common','Many people with AuDHD describe how, after a whole day of struggling with the world — masking, processing stimuli, translating themselves to the world and the world to themselves — clarity of thought, creativity, and energy suddenly arrive in the evening. This is not accidental.',NULL,NULL);
INSERT INTO content_sections VALUES(775,27,762,'heading',2,2,14,'GRUPA II — Często doświadczane, ale błędnie interpretowane','grupa-ii-czesto-doswiadczane-ale-blednie-interpretowane','Punkty ważne klinicznie, które łatwo odczytać jako cechy charakteru, a nie profil neurorozwojowy',14,replace('<p class="small">Punkty ważne klinicznie, które łatwo odczytać jako cechy charakteru, a nie profil neurorozwojowy</p>\n<div class="symptom">','\n',char(10)),'GROUP II — Commonly experienced, but often misinterpreted','Clinically important points that are easily read as personality traits rather than a neurodevelopmental profile.',NULL,NULL);
INSERT INTO content_sections VALUES(776,27,775,'heading',3,3,15,'9. Cykliczne wypalenia przypominające depresję badania + obserwacja kliniczna bardzo częste','9-cykliczne-wypalenia-przypominajace-depresje','Co kilka tygodni lub miesięcy następuje „zawalenie się" — osoba nagle nie może funkcjonować, wszystko ją przytłacza, traci motywację, nie potrafi nawet wstać z łóżka. Z zewnątrz wygląda to dokładnie jak epizod depresyjny.',15,replace('<p>Co kilka tygodni lub miesięcy następuje „zawalenie się" — osoba nagle nie może funkcjonować, wszystko ją przytłacza, traci motywację, nie potrafi nawet wstać z łóżka. Z zewnątrz wygląda to dokładnie jak epizod depresyjny. Ale jest fundamentalna różnica: depresja kliniczna jest zaburzeniem nastroju, a autystyczne wypalenie (autistic burnout) to stan wyczerpania wynikający z chronicznego przekraczania zasobów. Mózg AuDHD ciągle pracuje na podwyższonych obrotach — maskuje cechy autystyczne, kompensuje trudności z funkcjami wykonawczymi, przetwarza bodźce sensoryczne, które neurotypowy mózg odfiltrował by automatycznie. ADHD-owa część dodaje do tego tendencję do przeforsowania się — „skoro teraz mam energię, to zrobię wszystko naraz". Po pewnym czasie zasoby się kończą i następuje zawalenie. Kluczowa różnica: po okresie regeneracji energia wraca i cykl się powtarza. W depresji tak się nie dzieje. To bywa latami mylnie diagnozowane jako depresja nawracająca lub zaburzenie dwubiegunowe, bo narzędzia diagnostyczne nie uwzględniają tego wzorca.</p>\n<p class="small"><strong>Objaśnienie:</strong> W tym punkcie szczególnie ważna jest ostrożność diagnostyczna. Objawy mogą przypominać depresję, ale źródło problemu bywa inne: przeciążenie, długotrwałe maskowanie albo chroniczne niedopasowanie środowiska.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Cykliczne wypalenia (autistic burnout) wynikają z chronicznego maskowania, kompensowania i nadmiernego wysiłku dopasowania. Ridcully NIE doświadcza wypalenia autystycznego — bo nigdy nie maskuje. Koszt jest eksternalizowany na otoczenie (Skarbnik, Tęczyki). To dowód, że wypalenie nie jest cechą AuDHD, lecz ceną maskowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> takie załamania często są sygnałem przekroczenia zasobów, a nie moralnej porażki. W takim okresie człowiek często nie potrzebuje motywowania, tylko zmniejszenia wymagań i odzyskania podstawowych zasobów.</p><p><strong>Dla bliskich:</strong> pomocne jest zmniejszenie obciążenia i oczekiwań, a nie dociskanie do szybkiego powrotu do normy. Presja typu „weź się w garść” zwykle pogarsza sprawę; lepsze bywa odciążenie, prostota i powrót do podstaw.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R11, R15</p>\n</div>\n<div class="symptom">','\n',char(10)),'9. Cyclical burnouts resembling depression — research + clinical observation · very common','Every few weeks or months there is a “collapse”: the person suddenly cannot function, everything overwhelms them, motivation disappears, and even getting out of bed may become impossible. From the outside, it looks exactly like a depressive episode.',NULL,NULL);
INSERT INTO content_sections VALUES(777,27,775,'heading',3,3,16,'10. Wrażliwość na odrzucenie (RSD) głównie obserwacja kliniczna / doświadczenie bardzo częste (u osób z ADHD)','10-wrazliwosc-na-odrzucenie-rsd','RSD (Rejection Sensitive Dysphoria) to nie zwykła „wrażliwość na krytykę", którą ma każdy.',16,replace('<p>RSD (Rejection Sensitive Dysphoria) to nie zwykła „wrażliwość na krytykę", którą ma każdy. To neurologiczna reakcja, w której mózg interpretuje krytykę, odrzucenie lub nawet podejrzenie odrzucenia jako intensywne zagrożenie — i reaguje tak, jakby stało się coś katastrofalnego. Fizycznie: uderzenie gorąca, ścisk w klatce piersiowej, mdłości, zaburzony oddech. Emocjonalnie: zalew wstydu, poczucie bycia fundamentalnie „złym" lub „nie do kochania". Poznawczo: myśli się zapętlają, analizując sytuację w kółko. Jedna krytyczna uwaga potrafi skasować sto pozytywnych komentarzy i zajmować myśli przez dni. U AuDHD to spotyka się z autystyczną dosłownością i trudnością w odczytywaniu intencji. Wyobraź sobie: dostajesz wiadomość „ok" zamiast „ok! :)" — neurotypowy mózg prawdopodobnie tego nie zauważy. Mózg AuDHD może zinterpretować brak emotikona jako gniew, chłód lub odrzucenie. Paradoksalnie, kiedy ktoś naprawdę jest zły, osoba AuDHD może tego nie zauważyć, bo subtelne sygnały niewerbalne są trudniejsze do odczytania niż tekst. Więc wyobrażone odrzucenie boli bardziej niż realne — bo realne może zostać przegapione.</p>\n<p class="small"><strong>Objaśnienie:</strong> Sam termin RSD jest bardzo popularny, ale ma słabszy status naukowy niż klasyczne pojęcia diagnostyczne. Warto go traktować raczej jako użyteczny opis doświadczenia niż jako rozstrzygniętą jednostkę czy mechanizm.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: intensywność reakcji emocjonalnej na sygnały odrzucenia wynika z neurologii (ciało migdałowate + regulacja dopaminy). WTÓRNA: skala i częstotliwość nasilają się przez lata faktycznego odrzucenia, niezrozumienia i korygowania. Ridcully ma intensywne reakcje na sprzeciw, ale nie ruminuje i nie zapętla się — bo nie ma historii chronicznego odrzucenia.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> reakcja może być większa, niż sama sytuacja wydaje się uzasadniać. Często najbardziej boli nie sama uwaga drugiej osoby, tylko lawina znaczeń, które mózg dopisuje do niej w sekundę.</p><p><strong>Dla bliskich:</strong> precyzyjny, życzliwy feedback zwykle szkodzi mniej niż chłód, ironia albo niedopowiedzenia. Zanim uznasz reakcję za przesadzoną, warto zobaczyć, czy dla tej osoby nie uruchomił się właśnie stary i bardzo bolesny wzorzec.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R3, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'10. Rejection sensitivity (RSD) — mainly clinical observation / lived experience · very common in people with ADHD','RSD (Rejection Sensitive Dysphoria) is not ordinary “sensitivity to criticism”, which everyone experiences.',NULL,NULL);
INSERT INTO content_sections VALUES(778,27,775,'heading',3,3,17,'11. Zmienne zapotrzebowanie na samotność głównie obserwacja kliniczna / doświadczenie bardzo częste','11-zmienne-zapotrzebowanie-na-samotnosc','U wielu osób z AuDHD zapotrzebowanie na kontakt z ludźmi nie jest stałe. Jednego dnia rozmowa, wspólne działanie i bycie z kimś mogą być wyraźnie regulujące, a innego — bardzo kosztowne, mimo że relacja sama w sobie pozostaje ważna.',17,replace('<p>U wielu osób z AuDHD zapotrzebowanie na kontakt z ludźmi nie jest stałe. Jednego dnia rozmowa, wspólne działanie i bycie z kimś mogą być wyraźnie regulujące, a innego — bardzo kosztowne, mimo że relacja sama w sobie pozostaje ważna. Taka zmienność zwykle ma więcej wspólnego z poziomem przeciążenia, ilością snu, nasileniem bodźców i ogólną pojemnością układu nerwowego niż z „chwiejnością uczuć”. Dla otoczenia bywa to mylące, bo łatwo odczytać zmianę dostępności jako zmianę nastawienia. Tymczasem dla samej osoby często wygląda to raczej tak: więź jest ta sama, ale zasoby do kontaktu są zupełnie inne.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: zmienne zapotrzebowanie na kontakt wynika z wahań pojemności sensorycznej i emocjonalnej — to neurobiologia. WTÓRNA: wycofanie jest interpretowane jako odrzucenie głównie dlatego, że neurotypowi partnerzy stosują swoje normy kontaktu. U Ridcully''ego nikt nie kwestionuje, kiedy chce być sam.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> potrzeba samotności może zmieniać się wraz z poziomem obciążenia. To nie jest niespójność uczuć, tylko zmienny koszt kontaktu zależny od przeciążenia, snu i poczucia bezpieczeństwa.</p><p><strong>Dla bliskich:</strong> wycofanie nie zawsze oznacza odrzucenie — czasem oznacza ratowanie zasobów. Najlepiej nie brać tego automatycznie jako odrzucenia; zwykle chodzi bardziej o zasoby niż o jakość więzi.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R12, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'11. Variable need for solitude — mainly clinical observation / lived experience · very common','For many people with AuDHD, the need for contact with other people is not constant. One day, talking, doing things together, and simply being with someone may be distinctly regulating; on another day, it may be very costly, even though the relationship itself remains important.',NULL,NULL);
INSERT INTO content_sections VALUES(779,27,775,'heading',3,3,18,'12. Intensywna empatia wyglądająca jak brak empatii badania + obserwacja kliniczna częste','12-intensywna-empatia-wygladajaca-jak-brak-empatii','To jeden z najbardziej niebezpiecznych mitów dotyczących autyzmu — że osoby autystyczne „nie mają empatii". Rzeczywistość jest odwrotna.',18,replace('<p>To jeden z najbardziej niebezpiecznych mitów dotyczących autyzmu — że osoby autystyczne „nie mają empatii". Rzeczywistość jest odwrotna. Badania naukowe pokazują, że osoby autystyczne z aleksytymią nie tyle nie mają empatii, co doświadczają zwiększonego stresu osobistego w odpowiedzi na czyjeś cierpienie. To oznacza, że zamiast czuć mniej — czują więcej. Problem polega na tym, że system nerwowy, zalany tak intensywną emocją, się „wyłącza" jako mechanizm ochronny. Osoba, która czuje czyjeś cierpienie zbyt mocno, może zareagować pozornie obojętnie, milczeniem, albo „niewłaściwą" emocją (np. śmiechem w poważnej sytuacji) — nie dlatego że nic nie czuje, ale dlatego że czuje za dużo i mózg nie radzi sobie z przetworzeniem tego. Neurotypowy obserwator widzi „brak reakcji" i interpretuje to jako obojętność. Ale to, co dzieje się wewnątrz, jest dokładnie przeciwne — to zalew emocji tak silny, że ciało się zamyka. To prowadzi do wycofania się zamiast do działania prospołecznego — co jest raczej ucieczką niż obojętnością.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: intensywna empatia afektywna + trudność z ekspresją to budowa. WTÓRNA: ''wyglądanie jak brak empatii'' to interpretacja otoczenia, nie cecha samej osoby. Ridcully czuje — ale jego otoczenie nie odczytuje tego jako brak, bo ma władzę i pozycję, więc nikt nie ocenia formy jego troski.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> można czuć bardzo dużo i pokazywać to mało czytelnie. Czasem łatwiej przeżywać coś mocno niż szybko dobrać formę, która dla drugiej strony będzie od razu czytelna.</p><p><strong>Dla bliskich:</strong> brak typowej ekspresji nie musi oznaczać braku troski. Warto patrzeć nie tylko na formę reakcji, ale też na to, jak dana osoba wraca do tematu, pamięta o nim i próbuje zadbać po swojemu.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13</p>\n</div>\n<div class="symptom">','\n',char(10)),'12. Intense empathy that looks like lack of empathy — research + clinical observation · common','This is one of the most dangerous myths about autism: that autistic people “lack empathy”. The reality can be the opposite.',NULL,NULL);
INSERT INTO content_sections VALUES(780,27,775,'heading',3,3,19,'13. Szukanie i unikanie bodźców jednocześnie badania + obserwacja kliniczna bardzo częste','13-szukanie-i-unikanie-bodzcow-jednoczesnie','To jeden z bardziej dezorientujących aspektów AuDHD — zarówno dla osoby, jak i dla otoczenia.',19,replace('<p>To jeden z bardziej dezorientujących aspektów AuDHD — zarówno dla osoby, jak i dla otoczenia. Ktoś może potrzebować głośnej, ciężkiej muzyki w słuchawkach (mózg szuka kontrolowanej, przewidywalnej stymulacji), ale jednocześnie nie znosić dźwięku odkurzacza (niekontrolowany, nieprzewidywalny bodziec). Może uwielbiać ciężkie koce (głęboki ucisk reguluje układ nerwowy), ale reagować niepokojem na lekkie dotknięcie po ramieniu (powierzchowny dotyk jest drażniący). To nie jest sprzeczność ani wybrzydzanie. To dwa systemy sensoryczne z różnymi progami, działające równolegle. Kluczowa jest różnica między bodźcem kontrolowanym (osoba sama go wybrała, może go przewidzieć i zakończyć) a niekontrolowanym (pojawia się niespodziewanie, nie da się go przewidzieć ani zatrzymać). Ten sam bodziec — np. głośny dźwięk — może być regulujący, kiedy jest wybrany, i przytłaczający, kiedy jest narzucony. To fundamentalnie inna logika sensoryczna niż u osób neurotypowych, u których tolerancja na bodźce jest bardziej stabilna i mniej zależna od kontekstu.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Jednoczesne szukanie i unikanie bodźców wynika z atypowych progów w różnych modalitelnościach sensorycznych. Ridcully szuka hałasu, głośnych polowań, intensywnego jedzenia — i nie znosi cichych, subtelnych sygnałów. To wrodzona konfiguracja, nie wyuczony wzorzec.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> to normalne, że jedne bodźce regulują, a inne szybko przeciążają. Kluczowe bywa nie tylko natężenie bodźca, ale to, czy jest przewidywalny, wybrany samodzielnie i możliwy do przerwania.</p><p><strong>Dla bliskich:</strong> zamiast mówić ''zdecyduj się'', lepiej sprawdzać jaki bodziec pomaga, a jaki szkodzi. Pomocne bywa pytanie nie „jak możesz jednocześnie to lubić i tego nie znosić?”, tylko „jaki dokładnie rodzaj bodźca Ci służy?”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R17, R1</p>\n</div>\n<div class="symptom">','\n',char(10)),'13. Seeking and avoiding sensory input at the same time — research + clinical observation · very common','This is one of the more disorienting aspects of AuDHD, both for the person and for those around them.',NULL,NULL);
INSERT INTO content_sections VALUES(781,27,775,'heading',3,3,20,'14. Chroniczna niepunktualność LUB obsesyjna punktualność badania + obserwacja kliniczna bardzo częste (jedno lub drugie)','14-chroniczna-niepunktualnosc-lub-obsesyjna-punktualnosc','Tutaj działają dwa mechanizmy jednocześnie. Pierwszy: ADHD-owa „ślepota czasowa" — dosłowna trudność w odczuwaniu upływu czasu. Osoby neurotypowe mają w mózgu coś jak wewnętrzny zegar, który mniej więcej orientuje, ile czasu minęło.',20,replace('<p>Tutaj działają dwa mechanizmy jednocześnie. Pierwszy: ADHD-owa „ślepota czasowa" — dosłowna trudność w odczuwaniu upływu czasu. Osoby neurotypowe mają w mózgu coś jak wewnętrzny zegar, który mniej więcej orientuje, ile czasu minęło. Osoby z ADHD tego nie mają — godzina może subiektywnie trwać pięć minut. Drugi mechanizm: autystyczny monotropowy czas — kiedy mózg jest w „tunelu uwagi" (głębokim skupieniu na jednej rzeczy), czas na zewnątrz tunelu płynie zupełnie inaczej. Połączenie tych dwóch daje dwa możliwe wzorce. Wzorzec A: chroniczne spóźnianie się, bo trudność z przejściem z jednej aktywności do drugiej (autystyczna inercja) + brak wyczucia, ile czasu to zajmie (ślepota czasowa). Wzorzec B: obsesyjna punktualność, bo lęk przed spóźnieniem jest tak silny (wrażliwość na odrzucenie), że osoba przychodzi 40 minut za wcześnie i czeka. Oba wzorce są równie wyczerpujące. Rzadko jest coś pomiędzy.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: ślepota czasowa (ADHD) + monotropowy czas (autyzm) to neurobiologia. WTÓRNA: wariant obsesyjnej punktualności wynika z lęku przed konsekwencjami społecznymi spóźnienia. Ridcully nie jest punktualny — i nikogo to nie obchodzi, bo Uniwersytet Niewidoczny dostosowuje się do niego.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> spóźnienia albo nadmierna punktualność mogą być dwoma różnymi sposobami radzenia sobie z czasem. W obu wersjach bywa obecny duży koszt psychiczny: albo ciągłe nadrabianie, albo ciągłe pilnowanie, żeby niczego nie zawalić.</p><p><strong>Dla bliskich:</strong> warto wspólnie ustalać bufory czasowe, zamiast moralizować. Dobrze nie moralizować ani spóźnień, ani nadmiernego zapasu czasu, bo oba wzorce bywają próbą radzenia sobie z dużym stresem.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R16, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'14. Chronic lateness OR obsessive punctuality — research + clinical observation · very common (one or the other)','Two mechanisms operate here at once. The first is ADHD “time blindness”: a literal difficulty sensing the passage of time. Neurotypical people have something like an internal clock that gives them a rough sense of how much time has passed.',NULL,NULL);
INSERT INTO content_sections VALUES(782,27,775,'heading',3,3,21,'15. Cykliczne zainteresowania badania + obserwacja kliniczna częste','15-cykliczne-zainteresowania','W „klasycznym" autyzmie zainteresowania specjalne bywają długotrwałe — osoba fascynuje się jednym tematem przez lata, a nawet całe życie.',21,replace('<p>W „klasycznym" autyzmie zainteresowania specjalne bywają długotrwałe — osoba fascynuje się jednym tematem przez lata, a nawet całe życie. W AuDHD zainteresowania mają inny wzorzec: pojawiają się nagle, z ogromną intensywnością, pochłaniają całą uwagę i energię na kilka tygodni lub miesięcy — a potem ADHD-owa część mózgu potrzebuje nowości i fascynacja przenosi się na coś innego. Każda nowa fascynacja wydaje się „tą jedyną" — osoba jest przekonana, że tym razem to jest jej prawdziwa pasja, planuje karierę wokół tego, kupuje sprzęt, zapisuje się na kursy. A potem zainteresowanie gaśnie i przychodzi nowe. Stare zainteresowania mogą wrócić cyklicznie — nagle, bez ostrzeżenia, jakby ktoś włączył przełącznik. Z zewnątrz wygląda to jak niestabilność. Od wewnątrz — to naturalny rytm mózgu, który łączy autystyczną głębokość z ADHD-ową potrzebą różnorodności.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Cykliczność zainteresowań wynika ze zderzenia autystycznej głębokości z ADHD-ową potrzebą nowości. To biologiczny rytm, nie niestabilność charakteru. Ridcully przechodzi od polowania przez krykieta po ekspedycje — dokładnie ten sam wzorzec.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zmiana fascynacji nie przekreśla autentyczności poprzednich zainteresowań. Zmiana zainteresowania nie musi oznaczać powierzchowności; często oznacza zmianę źródła regulacji, sensu albo pobudzenia.</p><p><strong>Dla bliskich:</strong> nie warto tego sprowadzać do ''słomianego zapału''. Nie warto wyśmiewać intensywności tych faz; dla wielu osób są one realnym źródłem regulacji, radości i porządku.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R18, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'15. Cyclical interests — research + clinical observation · common','In “classic” autism, special interests can be long-lasting: a person may be fascinated by one subject for years or even for life.',NULL,NULL);
INSERT INTO content_sections VALUES(783,27,775,'heading',3,3,22,'16. Nietypowe reakcje na leki i substancje głównie obserwacja kliniczna / doświadczenie częste; u części osób bardzo częste','16-nietypowe-reakcje-na-leki-i-substancje','To temat, o którym mało się mówi, a który dotyka codziennego życia. Osoby autystyczne wykazują zwiększoną wrażliwość na leki psychotropowe — eksperci obserwują, że reakcje atypowe (niestandardowe, paradoksalne) mogą być w tej populacji częstsze.',22,replace('<p>To temat, o którym mało się mówi, a który dotyka codziennego życia. Osoby autystyczne wykazują zwiększoną wrażliwość na leki psychotropowe — eksperci obserwują, że reakcje atypowe (niestandardowe, paradoksalne) mogą być w tej populacji częstsze. Stymulanty przepisywane na ADHD (np. Ritalin, Concerta, Adderall) u osób AuDHD mogą działać inaczej niż u osób z samym ADHD — mogą trochę pomóc z koncentracją, ale jednocześnie nasilić autystyczne cechy: wrażliwość sensoryczną, sztywność, trudność z przełączaniem się między zadaniami. Badania potwierdzają niższą skuteczność i tolerancję metylfenidatu u osób autystycznych w porównaniu z populacją neurotypową. SSRI (popularne antydepresanty) to kolejny problem — niektóre badania wskazują na słabą tolerancję i brak skuteczności u osób autystycznych w leczeniu zachowań powtarzalnych. Nawet kofeina, alkohol i znieczulenie u dentysty mogą działać nieprzewidywalnie. Wiele osób AuDHD potrzebuje wielokrotnych dawek znieczulenia miejscowego, a jednocześnie bardzo długo budzi się ze znieczulenia ogólnego. Temple Grandin zaleca zaczynanie od 1/4 normalnej dawki. To nie jest nadwrażliwość „psychiczna" — to realne różnice w metabolizmie leków związane z wariantami genetycznymi dotyczącymi transportu dopaminy i serotoniny.</p>\n<p class="small"><strong>Objaśnienie:</strong> To ważny obszar praktyczny, ale nie warto wyciągać zbyt daleko idących wniosków biologicznych bez danych indywidualnych. Najbezpieczniej ujmować ten punkt jako: u części osób reakcje bywają mniej przewidywalne niż oczekiwano.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Atypowe reakcje na leki i substancje wynikają z wariantów genetycznych dotyczących transportu neuroprzekaźników. To farmakogenetyka, nie psychologia. Ridcully reaguje na substancje po swojemu — to nie ma nic wspólnego z maskowaniem.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> reakcje na leki warto obserwować dokładnie i opisywać konkretnie. Najbezpieczniej obserwować własne reakcje i omawiać je z lekarzem, zamiast zakładać z góry, że wszystko zadziała „standardowo”.</p><p><strong>Dla bliskich:</strong> ostrożność i dokumentowanie reakcji pomagają bardziej niż uogólnienia. Najbezpieczniej wspierać obserwację i konsultację medyczną, zamiast interpretować takie reakcje jako przesadę lub „wymyślanie”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'16. Atypical reactions to medication and substances — mainly clinical observation / lived experience · common; very common for some people','This is a subject that receives little attention despite affecting everyday life. Autistic people show increased sensitivity to psychotropic medication; experts observe that atypical reactions — unusual or paradoxical responses — may be more frequent in this population.',NULL,NULL);
INSERT INTO content_sections VALUES(784,27,775,'heading',3,3,23,'17. Efekt „wszystko albo nic" w nawykach głównie obserwacja kliniczna / doświadczenie bardzo częste','17-efekt-wszystko-albo-nic-w-nawykach','Osoby neurotypowe potrafią robić coś „w miarę" — ćwiczyć trzy razy w tygodniu, gotować kilka razy, czasem zamówić jedzenie. Osoby AuDHD mają z tym fundamentalną trudność. Albo ćwiczą codziennie o tej samej porze w identyczny sposób, albo wcale.',23,replace('<p>Osoby neurotypowe potrafią robić coś „w miarę" — ćwiczyć trzy razy w tygodniu, gotować kilka razy, czasem zamówić jedzenie. Osoby AuDHD mają z tym fundamentalną trudność. Albo ćwiczą codziennie o tej samej porze w identyczny sposób, albo wcale. Albo gotują każdy posiłek od zera, albo jedzą same gotowe rzeczy. Nie ma „złotego środka", bo ten środek wymaga elastyczności — umiejętności adaptowania się do zmiennych warunków — a to jest dokładnie punkt zderzenia autyzmu i ADHD. Autystyczna część chce sztywnego systemu („codziennie o 7:00 biegnę 5 km"), a ADHD-owa część nie jest w stanie utrzymać tego systemu dłużej niż dwa tygodnie, bo nowość się skończyła. Efektem są skomplikowane systemy zarządzania życiem: kolorowe kalendarze, arkusze kalkulacyjne, listy zadań, aplikacje — tworzone z zapałem, używane przez tydzień, porzucane, a potem zastępowane nowym systemem „tym razem na pewno idealnym".</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: trudność z umiarkowanym trybem wynika z budowy (sztywność + potrzeba stymulacji). WTÓRNA: spirala winy (''znowu nie utrzymałem systemu'') to efekt lat mierzenia się standardami neurotypowej regularności. Ridcully robi wszystko albo nic — i nikt mu nie mówi, że powinien ''utrzymywać równowagę''.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> tryb ''wszystko albo nic'' często jest próbą utrzymania kontroli, nie wyborem charakterologicznym. W praktyce środek bywa najtrudniejszy: łatwiej wejść w reżim albo całkiem puścić niż utrzymać wersję wystarczająco dobrą.</p><p><strong>Dla bliskich:</strong> lepiej wspierać wersję ''wystarczająco dobrze'' niż wzmacniać skrajności. Zamiast oczekiwać idealnej równowagi, często lepiej wspierać rozwiązania wystarczająco dobre i możliwe do utrzymania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18, R19</p>\n</div>','\n',char(10)),'17. The “all or nothing” effect in habits — mainly clinical observation / lived experience · very common','Neurotypical people can do something “more or less”: exercise three times a week, cook several times, occasionally order food. People with AuDHD have a fundamental difficulty with this. Either they exercise every day at the same time in the same way, or not at all.',NULL,NULL);
INSERT INTO content_sections VALUES(785,27,762,'heading',2,2,24,'GRUPA III — Subtelne, łatwo pomijane','grupa-iii-subtelne-latwo-pomijane','Obszary częste i ważne, ale mniej oczywiste z zewnątrz',24,replace('<p class="small">Obszary częste i ważne, ale mniej oczywiste z zewnątrz</p>\n<div class="symptom">','\n',char(10)),'GROUP III — Subtle, easily overlooked','Common and important areas that are less obvious from the outside.',NULL,NULL);
INSERT INTO content_sections VALUES(786,27,785,'heading',3,3,25,'18. Paradoks porządku i chaosu głównie obserwacja kliniczna / doświadczenie bardzo częste','18-paradoks-porzadku-i-chaosu','Ktoś z zewnątrz wchodzi do mieszkania osoby AuDHD i widzi coś pozornie niemożliwego: szuflada z przyprawami posegregowana alfabetycznie obok blatu z trzydniowym bałaganem. Szafa kolorystycznie zorganizowana, ale łazienka w chaosie.',25,replace('<p>Ktoś z zewnątrz wchodzi do mieszkania osoby AuDHD i widzi coś pozornie niemożliwego: szuflada z przyprawami posegregowana alfabetycznie obok blatu z trzydniowym bałaganem. Szafa kolorystycznie zorganizowana, ale łazienka w chaosie. Komputer z perfekcyjną strukturą folderów, ale biurko zastawione stosami papierów. To nie jest lenistwo selektywne ani „po prostu brak konsekwencji". To efekt zderzenia dwóch systemów: autystyczna część mózgu ma silną potrzebę porządku i systemu, ale ADHD-owe funkcje wykonawcze nie nadążają z realizowaniem tej potrzeby we wszystkich obszarach jednocześnie. Osoba ma energię i skupienie na organizowanie jednego obszaru — ale ten sam wysiłek w innym miejscu jest w danym momencie niemożliwy. Które obszary są zorganizowane, a które w chaosie, może się zmieniać w czasie i zależy od tego, co aktualnie jest w „tunelu uwagi".</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Współistnienie porządku i chaosu w różnych obszarach wynika z ograniczonych zasobów wykonawczych rozdzielanych monotropowo. To architektura uwagi, nie brak dyscypliny. Ridcully ma gabinet jednocześnie chaotyczny i zorganizowany — dokładnie ten sam wzorzec.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> porządek i chaos mogą współistnieć w różnych obszarach życia. To często wygląda jak chaos, ale w środku zwykle jest dużo wysiłku wkładanego w ochronę choć kilku ważnych obszarów.</p><p><strong>Dla bliskich:</strong> wybiórczy porządek nie oznacza, że reszta jest zaniedbywana celowo. To, że ktoś nie panuje nad wszystkim, nie znaczy, że nie wkłada ogromu pracy w utrzymanie czegokolwiek w ryzach.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R2, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'18. The order-and-chaos paradox — mainly clinical observation / lived experience · very common','An outsider enters the home of a person with AuDHD and sees something apparently impossible: a spice drawer sorted alphabetically beside a worktop covered in three days of clutter. A wardrobe organised by colour, but a bathroom in chaos.',NULL,NULL);
INSERT INTO content_sections VALUES(787,27,785,'heading',3,3,26,'19. Prokrastynacja przez perfekcjonizm badania + obserwacja kliniczna bardzo częste','19-prokrastynacja-przez-perfekcjonizm','To nie jest zwykłe odkładanie rzeczy na później. To specyficzna blokada, w której osoba nie zaczyna zadania, bo z góry wie, że nie będzie w stanie zrobić go tak dobrze, jak by chciała.',26,replace('<p>To nie jest zwykłe odkładanie rzeczy na później. To specyficzna blokada, w której osoba nie zaczyna zadania, bo z góry wie, że nie będzie w stanie zrobić go tak dobrze, jak by chciała. Autystyczna część mózgu ma bardzo wysokie, sztywne standardy — jeśli coś ma być zrobione, to musi być zrobione „dobrze", a „dobrze" oznacza często „doskonale" lub „w pełni, ze wszystkimi szczegółami". Jednocześnie ADHD-owa część mózgu wie z doświadczenia, że utrzymanie skupienia wystarczająco długo, żeby spełnić te standardy, jest niezwykle trudne. Efekt: paraliż decyzyjny. Osoba nie zaczyna, bo perspektywa niedoskonałego wyniku jest nie do zniesienia, a perspektywa idealnego wyniku — nierealna. Prowadzi to do wzorca, w którym zadania są odkładane do ostatniej chwili — bo dopiero wtedy adrenalina deadline''u daje wystarczającą stymulację, żeby przełamać blokadę. A potem pojawia się wyczerpanie i poczucie winy, że „znowu tak zrobiłam".</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: bardzo wysokie standardy wykonania to cecha autystycznej sztywności poznawczej. WTÓRNA: paraliżujący lęk przed niedoskonałością narasta przez lata, w których każdy ''niedoskonały'' wynik był karany lub wyśmiewany. Ridcully robi rzeczy na swój sposób i nie analizuje, czy są ''doskonałe'' — bo nikt nigdy nie kwestionował jego standardów.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> odkładanie bywa skutkiem zbyt wysokiego progu wejścia, nie braku chęci. Zablokowanie często bierze się z lęku przed niedostatecznością, a nie z braku znaczenia zadania.</p><p><strong>Dla bliskich:</strong> pomaga odciążenie perfekcjonizmu i wspólne ustalenie wersji minimalnej. Pomaga obniżenie progu wejścia, a nie samo przypominanie, że „przecież to trzeba zrobić”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'19. Procrastination through perfectionism — research + clinical observation · very common','This is not ordinary putting things off. It is a specific blockage in which the person does not start a task because they already know they will not be able to do it as well as they would like.',NULL,NULL);
INSERT INTO content_sections VALUES(788,27,785,'heading',3,3,27,'20. Powtarzalne ruchy i gesty regulujące układ nerwowy (tzw. stimming) badania powszechne (ale nierozpoznawane)','20-powtarzalne-ruchy-i-gesty-regulujace-uklad-nerwowy-tzw-stimming','Stimming, czyli zachowania autostymulacyjne lub samoregulacyjne, obejmuje powtarzalne ruchy, gesty i drobne czynności, które pomagają utrzymać układ nerwowy w bardziej znośnej równowadze.',27,replace('<p>Stimming, czyli zachowania autostymulacyjne lub samoregulacyjne, obejmuje powtarzalne ruchy, gesty i drobne czynności, które pomagają utrzymać układ nerwowy w bardziej znośnej równowadze. Mogą to być ruchy nogą, bawienie się przedmiotem, chodzenie po pokoju, skubanie materiału, kołysanie się albo ciche powtarzanie dźwięków. U dorosłych takie zachowania są często bardziej subtelne, bo przez lata bywały korygowane jako „dziwne”, „dziecinne” albo „niegrzeczne”. W praktyce jednak dla wielu osób nie są one przypadkowym nawykiem, tylko prostym narzędziem regulacji: pomagają obniżyć napięcie, dołożyć brakującej stymulacji albo utrzymać koncentrację. Dlatego próba całkowitego tłumienia takich zachowań może podnosić koszt funkcjonowania zamiast go zmniejszać.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Zachowania autostymulacyjne są wrodzoną formą regulacji sensorycznej. Sam stimming jest pierwotny. UWAGA: tłumienie stimmingu (i jego konsekwencje) to zjawisko wtórne — wynika z nacisku społecznego. Ridcully stimuje swobodnie — bębnii palcami, krząta się, rusza — i nikt go nie powstrzymuje.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ruchy regulacyjne mogą pomagać utrzymać równowagę i koncentrację. Dla wielu osób to nie „dziwne nawyki”, tylko prosty sposób, by układ nerwowy wrócił do bardziej znośnego poziomu pobudzenia.</p><p><strong>Dla bliskich:</strong> nie warto ich automatycznie gasić, jeśli nikomu nie szkodzą. Jeśli zachowanie nikomu nie szkodzi, często lepiej je dopuścić niż kazać je tłumić w imię pozornej normalności.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R17</p>\n</div>\n<div class="symptom">','\n',char(10)),'20. Repetitive movements and gestures that regulate the nervous system (stimming) — research · widespread but often unrecognised','Stimming, meaning self-stimulatory or self-regulatory behaviour, includes repetitive movements, gestures, and small actions that help keep the nervous system in a more tolerable balance.',NULL,NULL);
INSERT INTO content_sections VALUES(789,27,785,'heading',3,3,28,'21. Słaba interocepcja — nie czujesz, co dzieje się w twoim ciele badania + obserwacja kliniczna częste','21-slaba-interocepcja-nie-czujesz-co-dzieje-sie-w-twoim-ciele','Interocepcja to zmysł, który informuje mózg o tym, co dzieje się wewnątrz ciała: głód, pragnienie, pełny pęcherz, zmęczenie, temperatura, ból, tętno.',28,replace('<p>Interocepcja to zmysł, który informuje mózg o tym, co dzieje się wewnątrz ciała: głód, pragnienie, pełny pęcherz, zmęczenie, temperatura, ból, tętno. U większości ludzi te sygnały pojawiają się automatycznie i narastają stopniowo — najpierw lekkie uczucie głodu, potem silniejsze, aż wreszcie „muszę jeść". U osób AuDHD interocepcja często działa atypowo: sygnały mogą być zbyt ciche (osoba nie czuje głodu przez cały dzień, a potem nagle jest tak głodna, że trzęsą jej się ręce), zbyt głośne (każde przyspieszenie tętna jest odczuwane jako panika) lub po prostu nieczytelne (coś jest „nie tak", ale nie wiadomo co — głód? smutek? zmęczenie? złość? pełny pęcherz?). To ma poważne konsekwencje w codziennym życiu: osoby ze słabą interocepcją zapominają jeść i pić, nie wiedzą, kiedy odpocząć, przegapiają wczesne sygnały choroby, mają trudności z rozpoznaniem, kiedy potrzebują toalety, i często są zaskakiwane własnymi emocjami, bo nie czuły ich narastania.</p>\n<p class="small"><strong>Objaśnienie:</strong> Badania nad interocepcją są coraz lepsze, ale nadal nie pokazują jednego prostego wzorca dla wszystkich osób autystycznych lub AuDHD. Dlatego w tym obszarze uczciwiej mówić o częstych różnicach niż o regule bez wyjątków.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Słaba lub atypowa interocepcja wynika z budowy szlaków czuciowych ciało→kora wyspowa. To neurobiologia, nie efekt wychowania. Ridcully zapomina o jedzeniu, nie czuje zmęczenia w trakcie działania — klasyczny wzorzec.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> sygnały z ciała mogą docierać późno albo niejasno. Przydają się wtedy zewnętrzne sygnały: rytm posiłków, przypomnienia o wodzie, krótkie skany ciała i przerwy planowane zawczasu.</p><p><strong>Dla bliskich:</strong> przypomnienia o jedzeniu, piciu czy przerwie bywają wsparciem, nie infantylizacją. Dobrze wspierać regularność bez infantylizowania — bardziej przez rytm i przypomnienia niż przez ocenianie.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R5, R6</p>\n</div>\n<div class="symptom">','\n',char(10)),'21. Weak interoception — you do not feel what is happening in your body — research + clinical observation · common','Interoception is the sense that tells the brain what is happening inside the body: hunger, thirst, a full bladder, fatigue, temperature, pain, heart rate.',NULL,NULL);
INSERT INTO content_sections VALUES(790,27,785,'heading',3,3,29,'22. Aleksytymia — nie umiesz nazwać tego, co czujesz badania częste (40–65% osób autystycznych)','22-aleksytymia-nie-umiesz-nazwac-tego-co-czujesz','Aleksytymia to trudność z identyfikowaniem, rozróżnianiem i opisywaniem własnych emocji. To nie to samo co „nie mieć emocji" — emocje są, często nawet bardzo intensywne, ale nie ma do nich czytelnego dostępu.',29,replace('<p>Aleksytymia to trudność z identyfikowaniem, rozróżnianiem i opisywaniem własnych emocji. To nie to samo co „nie mieć emocji" — emocje są, często nawet bardzo intensywne, ale nie ma do nich czytelnego dostępu. Wyobraź sobie, że ktoś pyta „jak się czujesz?" — a w twoim ciele dzieje się jednocześnie dwadzieścia różnych rzeczy i nie potrafisz wyodrębnić żadnej z nich, żeby ją nazwać. Pierwsza odpowiedź to zwykle „nie wiem" albo „dobrze" — nie dlatego, że nic nie czujesz, ale dlatego że wybranie jednej emocji z tego chaosu wydaje się fałszywe. Aleksytymia jest silnie związana ze słabą interocepcją — skoro ciało nie wysyła czytelnych sygnałów, mózg nie ma danych, na podstawie których mógłby „etykietować" emocje. Badania pokazują, że to aleksytymia — nie autyzm sam w sobie — odpowiada za wiele trudności emocjonalnych przypisywanych autyzmowi. U osób AuDHD dodatkową warstwą jest ADHD-owa intensywność emocjonalna: emocje są silne, szybkie i zmienne, a jednocześnie trudne do zidentyfikowania. To jak bycie na emocjonalnym rollercoasterze, z którego nie widać toru.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: trudność z rozpoznawaniem i nazywaniem emocji ma podłoże neurologiczne (interocepcja + przetwarzanie emocjonalne). WTÓRNA: chroniczne tłumienie emocji przez maskowanie pogłębia aleksytymię — im dłużej ktoś musi ''nie czuć'' publicznie, tym bardziej traci kontakt z tym, co czuje naprawdę. Ridcully ma aleksytymię podstawową, ale nie ma warstwy wtórnej z maskowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> brak słów na emocje nie oznacza ich braku. Dopiero po czasie pojawia się zdanie typu: „już wiem, to był lęk” albo „to nie była złość, tylko przeciążenie”.</p><p><strong>Dla bliskich:</strong> czas i pytania pomocnicze działają lepiej niż nacisk na natychmiastowe nazwanie uczuć. Czas na nazwanie stanu nie musi oznaczać braku zaangażowania; dla niektórych ludzi emocje stają się czytelne wolniej.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R7</p>\n</div>\n<div class="symptom">','\n',char(10)),'22. Alexithymia — you cannot name what you feel — research · common (40–65% of autistic people)','Alexithymia is difficulty identifying, distinguishing, and describing one''s own emotions. It is not the same as “having no emotions”: the emotions are there, often very intense, but there is no clear access to them.',NULL,NULL);
INSERT INTO content_sections VALUES(791,27,785,'heading',3,3,30,'23. Maskowanie społeczne na zmianę z impulsywnością społeczną badania + obserwacja kliniczna bardzo częste','23-maskowanie-spoleczne-na-zmiane-z-impulsywnoscia-spoleczna','Maskowanie to świadomy lub nieświadomy proces ukrywania cech autystycznych, żeby wyglądać „normalnie" — wymuszony kontakt wzrokowy, kopiowanie zachowań społecznych innych ludzi, tłumienie naturalnych reakcji.',30,replace('<p>Maskowanie to świadomy lub nieświadomy proces ukrywania cech autystycznych, żeby wyglądać „normalnie" — wymuszony kontakt wzrokowy, kopiowanie zachowań społecznych innych ludzi, tłumienie naturalnych reakcji. To jak granie roli w spektaklu, w którym wszyscy inni improwizują swobodnie, a ty musisz pamiętać każdą kwestię. U osób z samym autyzmem maskowanie bywa dość spójne — osoba ma wyuczone „skrypty społeczne", które stosuje konsekwentnie. U AuDHD maskowanie jest przerywane ADHD-ową impulsywnością: osoba może przez dwadzieścia minut starannie kontrolować swoją komunikację, a potem nagle powiedzieć coś zbyt bezpośrednio, zbyt emocjonalnie lub kompletnie nie na temat — bo impuls był silniejszy niż skrypt. Po takiej sytuacji następuje fala intensywnego analizowania — „dlaczego to powiedziałam, co oni teraz myślą, czy mnie teraz nie znoszą". Ten cykl „kontrola → impuls → ruminacja" jest bardzo charakterystyczny dla AuDHD i bardzo, bardzo wyczerpujący.</p>\n<p class="small"><strong>Objaśnienie:</strong> Maskowanie nie oznacza udawania w potocznym sensie. Często jest to wyuczony, kosztowny sposób poruszania się po świecie społecznym, który pozwala zmniejszyć ryzyko odrzucenia, ale zwykle zużywa dużo energii.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Maskowanie jest CAŁKOWICIE wtórne. To wyuczony, kosztowny mechanizm przetrwania w środowisku, które karze za autentyczne zachowanie. Ridcully NIE maskuje — w ogóle, nigdy. To najczystszy przykład: ta sama neurologia, zero maskowania, bo pozycja społeczna i siła fizyczna sprawiły, że nigdy nie musiał. Koszt ponoszą inni.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ciągła samokontrola społeczna jest wyczerpująca i nie zawsze działa stabilnie. Taki cykl bywa bardzo męczący, bo człowiek nigdy do końca nie wie, która wersja siebie będzie dziś bardziej dostępna.</p><p><strong>Dla bliskich:</strong> warto widzieć koszt maskowania, a nie tylko momenty, gdy ''maska spada''. To pomaga nie wpadać w prostą ocenę „nieszczery” albo „niemiły”, gdy w rzeczywistości człowiek walczy z przeciążeniem i kontrolą.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R9, R1</p>\n</div>\n<div class="symptom">','\n',char(10)),'23. Social camouflaging alternating with social impulsivity — research + clinical observation · very common','Camouflaging is a conscious or unconscious process of hiding autistic traits in order to appear “normal”: forcing eye contact, copying other people''s social behaviour, suppressing natural reactions.',NULL,NULL);
INSERT INTO content_sections VALUES(792,27,785,'heading',3,3,31,'24. Wyczerpanie po decyzjach badania + obserwacja kliniczna częste','24-wyczerpanie-po-decyzjach','Każda decyzja wymaga energii mentalnej — to normalne dla wszystkich ludzi. Ale u osób AuDHD nawet drobne wybory mogą być druzgocące, bo angażują dwa systemy jednocześnie.',31,replace('<p>Każda decyzja wymaga energii mentalnej — to normalne dla wszystkich ludzi. Ale u osób AuDHD nawet drobne wybory mogą być druzgocące, bo angażują dwa systemy jednocześnie. Autystyczna część mózgu chce „właściwego" wyboru — i „właściwy" oznacza nie po prostu „dobry", ale uwzględniający wszystkie zmienne, konsekwencje i szczegóły (bo tak działa przetwarzanie oddolne). ADHD-owa część mózgu z kolei ma trudność z „trzymaniem" wielu opcji w pamięci roboczej i z priorytetyzacją — wszystko wydaje się albo równie ważne, albo równie nieważne. Efektem jest paraliż nawet przy wyborze, co zjeść na obiad. Nie dlatego, że to trudna decyzja, ale dlatego że mózg próbuje ją potraktować z tą samą głębokością co strategiczną decyzję życiową. Po dniu pełnym drobnych decyzji osoba może być kompletnie wyczerpana — nawet jeśli „nic ważnego się nie wydarzyło".</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: przetwarzanie bottom-up + ograniczona pamięć robocza = każda decyzja kosztuje dużo zasobów. WTÓRNA: świat wymaga ciągłego decydowania w formatach, które nie pasują do tego stylu przetwarzania. Ridcully podejmuje decyzje szybko i impulsywnie — ale nie dlatego, że go to nie kosztuje, tylko dlatego, że nikt nie kwestionuje jego wyborów.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zmęczenie po decyzjach jest realne, nawet jeśli wybory wydają się małe. Szczególnie trudne bywają decyzje bez jasnych kryteriów, bo wtedy rośnie liczba możliwych ścieżek i koszt porównywania.</p><p><strong>Dla bliskich:</strong> ograniczenie liczby opcji często pomaga bardziej niż długie dyskusje. Przydatne są dwa-trzy jasne kryteria zamiast otwartych pytań z dziesiątkami możliwych odpowiedzi.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R10, R16</p>\n</div>\n<div class="symptom">','\n',char(10)),'24. Decision fatigue — research + clinical observation · common','Every decision requires mental energy; that is normal for everyone. But for people with AuDHD, even small choices can be devastating because they engage two systems at once.',NULL,NULL);
INSERT INTO content_sections VALUES(793,27,785,'heading',3,3,32,'25. Specyficzny stosunek do jedzenia badania + obserwacja kliniczna częste','25-specyficzny-stosunek-do-jedzenia','To połączenie kilku mechanizmów naraz. Słaba interocepcja sprawia, że osoba nie czuje głodu stopniowo — zapomina o jedzeniu przez pół dnia, a potem nagle jest tak głodna, że nie może jasno myśleć.',32,replace('<p>To połączenie kilku mechanizmów naraz. Słaba interocepcja sprawia, że osoba nie czuje głodu stopniowo — zapomina o jedzeniu przez pół dnia, a potem nagle jest tak głodna, że nie może jasno myśleć. ADHD-owa impulsywność może prowadzić do nagłego, intensywnego jedzenia „czegokolwiek, co jest pod ręką". Ale jednocześnie autystyczna wrażliwość sensoryczna drastycznie zawęża zakres akceptowalnych potraw — pewne tekstury, zapachy, konsystencje czy temperatury są nie do zniesienia. Efektem jest zjawisko, w którym osoba ma listę „bezpiecznych" potraw (które sensorycznie zawsze są OK) i poza nią prawie nic nie je. To nie wybredność ani kaprys — to reakcja systemu nerwowego na bodźce sensoryczne w ustach. ARFID (unikające/restrykcyjne zaburzenie przyjmowania pokarmów) współwystępuje z autyzmem i ADHD znacznie częściej niż w populacji ogólnej. Stres lub wypalenie jeszcze bardziej zawężają listę bezpiecznych potraw, bo obciążony system sensoryczny ma mniejszą tolerancję.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Specyficzny stosunek do jedzenia wynika z atypowej interocepcji (brak sygnału głodu) + wrażliwości sensorycznej (tekstury, smaki, temperatury). To neurobiologia zmysłów, nie kaprys. Ridcully ma bardzo konkretne preferencje żywieniowe — i kuchnia UNu się do nich dostosowuje.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> jedzenie może być obszarem regulacji, bezpieczeństwa albo przeciążenia. Jedzenie może wtedy przestać być prostą czynnością i stać się codziennym polem negocjacji między ciałem, zmysłami i zasobami.</p><p><strong>Dla bliskich:</strong> nacisk i zawstydzanie zwykle pogarszają sprawę; lepiej budować repertuar stopniowo. Warto odróżniać wybredność od realnej trudności sensorycznej lub regulacyjnej, bo reakcje obronne na jedzenie bywają bardzo silne.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R5, R6, R17</p>\n</div>\n<div class="symptom">','\n',char(10)),'25. A distinctive relationship with food — research + clinical observation · common','This combines several mechanisms. Weak interoception means that hunger is not felt gradually: the person forgets to eat for half a day, then suddenly becomes so hungry that they cannot think clearly.',NULL,NULL);
INSERT INTO content_sections VALUES(794,27,785,'heading',3,3,33,'26. Trudność z przejściami między aktywnościami (autystyczna inercja) badania + obserwacja kliniczna powszechne','26-trudnosc-z-przejsciami-miedzy-aktywnosciami-autystyczna-inercja','To nie jest prokrastynacja. To fizyczny opór systemu nerwowego przed zmianą stanu. Wyobraź sobie, że jedziesz pociągiem towarowym — zatrzymanie go wymaga czasu i energii, a ponowne rozpędzenie jeszcze więcej.',33,replace('<p>To nie jest prokrastynacja. To fizyczny opór systemu nerwowego przed zmianą stanu. Wyobraź sobie, że jedziesz pociągiem towarowym — zatrzymanie go wymaga czasu i energii, a ponowne rozpędzenie jeszcze więcej. Tak działa mózg monotropowy: kiedy jest zanurzony w jednej aktywności, wejście w inną wymaga „rozładowania" ogromnej ilości zasobów uwagi, a potem „załadowania" ich od nowa na nowy tor. Dlatego przejście z pracy do odpoczynku, z domu do wyjścia czy z jednego zadania do drugiego — każde „przełączenie” może kosztować nieproporcjonalnie dużo energii. To wyjaśnia, dlaczego osoba AuDHD może siedzieć na kanapie, wiedzieć, że musi wyjść za dziesięć minut, chcieć wyjść — i nie być w stanie się ruszyć. Nie chodzi o brak motywacji. Chodzi o to, że system wymaga czasu i energii na zmianę stanu, a w danym momencie ta energia nie jest dostępna. Badania sugerują, że osoby AuDHD mogą doświadczać najsilniejszej inercji ze wszystkich grup — silniejszej niż osoby z samym autyzmem czy samym ADHD.</p>\n<p class="small"><strong>Objaśnienie:</strong> Tu dobrze odróżnić „nie chcę” od „nie mogę ruszyć systemu”. Dla wielu osób najtrudniejszy nie jest wysiłek samego zadania, lecz moment przejścia między stanami.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Autystyczna inercja — trudność z przejściem między stanami — wynika z monotropowej alokacji uwagi. To jak zatrzymywanie i rozpędzanie pociągu towarowego. Ridcully ma to wyraźnie: nie da się go wyrwać z tego, co robi, a zmiana trybu wymaga czasu. To budowa, nie nawyk.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> problem często leży w przejściu, nie w samej czynności. Samo „weź się w garść” zwykle nie pomaga, bo problemem nie jest brak zamiaru, tylko koszt zmiany stanu.</p><p><strong>Dla bliskich:</strong> zapowiedź zmiany i miękki most między aktywnościami bywają bardzo pomocne. Pomaga zapowiadanie przejścia, zostawienie czasu buforowego i ograniczenie liczby zmian naraz.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R18, R2</p>\n</div>\n<div class="symptom">','\n',char(10)),'26. Difficulty transitioning between activities (autistic inertia) — research + clinical observation · widespread','This is not procrastination. It is physical resistance of the nervous system to changing state. Imagine travelling on a freight train: stopping it takes time and energy, and accelerating it again takes even more.',NULL,NULL);
INSERT INTO content_sections VALUES(795,27,785,'heading',3,3,34,'27. Zmienne progi sensoryczne badania + obserwacja kliniczna częste','27-zmienne-progi-sensoryczne','Progi sensoryczne to poziom, przy którym bodziec zaczyna przeszkadzać. U osób neurotypowych te progi są względnie stałe — jeśli komuś przeszkadza głośna muzyka, to przeszkadza mniej więcej zawsze.',34,replace('<p>Progi sensoryczne to poziom, przy którym bodziec zaczyna przeszkadzać. U osób neurotypowych te progi są względnie stałe — jeśli komuś przeszkadza głośna muzyka, to przeszkadza mniej więcej zawsze. U osób AuDHD progi zmieniają się w zależności od ogólnego poziomu obciążenia systemu nerwowego. W dobrym dniu sweter z lekko chropowatej wełny jest w porządku — system nerwowy ma wystarczające zasoby, żeby odfiltrować ten bodziec. Ale po stresującym dniu w pracy — kiedy zasoby są wyczerpane maskowaniem, przetwarzaniem bodźców społecznych i sensorycznych — ten sam sweter jest torturą, bo system nie ma już czym filtrować. To tłumaczy, dlaczego otoczenie mówi „ale wczoraj to ci nie przeszkadzało" — bo wczoraj rzeczywiście nie przeszkadzało, ale wczoraj system nerwowy miał inne zasoby. Tolerancja sensoryczna to nie stała cecha — to zmienna, zależna od aktualnego stanu organizmu, ilości snu, stresu, maskowania i setek innych czynników.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Zmienność progów sensorycznych zależy od aktualnego obciążenia systemu nerwowego. To neurobiologiczna dynamika, nie niestabilność psychiczna. Ale — obciążenie maskowaniem (wtórne) obniża progi szybciej. Ridcully nie maskuje, więc jego progi wahają się mniej.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> to, że dziś coś jest trudniejsze niż wczoraj, nie musi być nielogiczne. To dlatego coś wczoraj neutralnego dziś może być nie do zniesienia, mimo że z zewnątrz sytuacja wygląda podobnie.</p><p><strong>Dla bliskich:</strong> wahania progu tolerancji warto traktować serio, a nie jako wymówki. To, że dziś jest trudniej niż wczoraj, nie musi znaczyć manipulacji; często znaczy tylko bardziej obciążony system.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R17, R5, R6</p>\n</div>\n<div class="symptom">','\n',char(10)),'27. Variable sensory thresholds — research + clinical observation · common','Sensory thresholds are the levels at which a stimulus begins to become disturbing. In neurotypical people these thresholds are relatively stable: if loud music bothers someone, it tends to bother them more or less consistently.',NULL,NULL);
INSERT INTO content_sections VALUES(796,27,785,'heading',3,3,35,'28. Geniusz w kryzysie, paraliż w spokoju głównie obserwacja kliniczna / doświadczenie częste','28-geniusz-w-kryzysie-paraliz-w-spokoju','U części osób z AuDHD działanie uruchamia się łatwiej w warunkach wyraźnej presji niż w spokojnej, przewidywalnej codzienności.',35,replace('<p>U części osób z AuDHD działanie uruchamia się łatwiej w warunkach wyraźnej presji niż w spokojnej, przewidywalnej codzienności. Deadline, kryzys, czyjaś obecność albo poczucie pilności potrafią chwilowo zebrać uwagę i energię w jeden punkt, podczas gdy przy braku nacisku pojawia się zacięcie, odwlekanie lub rozpad działania. Nie znaczy to jednak, że taka osoba „lubi chaos” albo działa dobrze tylko wtedy, gdy wszystko się pali. Bardziej chodzi o to, że wyższy poziom pobudzenia czasem pomaga przekroczyć próg startu, którego nie daje się osiągnąć w zwykłym trybie. Z zewnątrz może to wyglądać jak paradoks albo samosabotaż, ale od środka częściej jest to kwestia warunków, w których system w ogóle jest w stanie się uruchomić.</p>\n<p class="small"><strong>Objaśnienie:</strong> To sformułowanie jest celowo ostrożne: nie opisuje uniwersalnej reguły, tylko częsty wzorzec. W praktyce dobrze oddaje doświadczenie osób, które pod presją bywają bardzo sprawne, a bez presji mają trudność nawet z prostym startem.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: próg aktywacji jest wyższy i wymaga silniejszego bodźca (adrenalina, deadline) — to regulacja dopaminergiczna. WTÓRNA: codzienne środowisko nie dostarcza wystarczającej stymulacji, bo jest zaprojektowane dla neurotypowych progów. Ridcully sam tworzy sobie kryzysy (polowania, ekspedycje, absurdalne projekty) — nie czeka na zewnętrzną presję.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> presja może czasem uruchamiać działanie, ale ma wysoką cenę. Czasem człowiek długo nie rusza, a potem robi ogrom w bardzo krótkim czasie, co z zewnątrz łatwo błędnie odczytać.</p><p><strong>Dla bliskich:</strong> nie warto budować systemu życia wyłącznie na gaszeniu pożarów. Warto nie budować fałszywego wniosku: „skoro potrafi w kryzysie, to mógłby zawsze”, bo to zwykle nie działa w ten sposób.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'28. Brilliant in a crisis, paralysed in calm conditions — mainly clinical observation / lived experience · common','For some people with AuDHD, action starts more easily under clear pressure than in calm, predictable everyday conditions.',NULL,NULL);
INSERT INTO content_sections VALUES(797,27,785,'heading',3,3,36,'29. Unikanie wymagań (demand avoidance) głównie obserwacja kliniczna / doświadczenie częste; u części osób bardzo częste','29-unikanie-wymagan-demand-avoidance','To coś znacznie głębszego niż „nie chce mi się". Wyobraź sobie, że wiesz, co musisz zrobić — np. odpisać na ważnego maila — chcesz to zrobić, rozumiesz konsekwencje nieodpisania, i mimo tego fizycznie nie potrafisz tego zrobić. Ciało odmawia współpracy.',36,replace('<p>To coś znacznie głębszego niż „nie chce mi się". Wyobraź sobie, że wiesz, co musisz zrobić — np. odpisać na ważnego maila — chcesz to zrobić, rozumiesz konsekwencje nieodpisania, i mimo tego fizycznie nie potrafisz tego zrobić. Ciało odmawia współpracy. To nie lenistwo, nie prokrastynacja, nie bunt. To reakcja układu nerwowego, w której sam fakt istnienia oczekiwania — nawet własnego — uruchamia coś w rodzaju alarmowej reakcji obronnej. Mózg traktuje wymaganie jak zagrożenie dla autonomii i reaguje zamrożeniem, paniką lub uciekaniem w coś innego. Co szczególnie dezorientujące: to dotyczy nawet rzeczy, które osoba chce robić. Obejrzenie ulubionego serialu, zjedzenie posiłku, odbycie rozmowy z przyjacielem — sam fakt, że to staje się „oczekiwaniem" (nawet narzuconym sobie), może uruchomić blokadę. Im bardziej „powinnam to zrobić", tym bardziej ciało mówi „nie". Im mniej oczekiwań — tym paradoksalnie łatwiej coś zrobić. To nie jest kwestia motywacji — to kwestia systemu nerwowego, który reaguje na ciśnienie w sposób, którego osoba nie kontroluje.</p>\n<p class="small"><strong>Objaśnienie:</strong> Unikanie wymagań bywa szczególnie źle rozumiane przez otoczenie. Czasem nie wynika z braku motywacji, ale z gwałtownego wzrostu napięcia, gdy coś zostaje przeżyte jako nacisk lub utrata sprawczości.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: reakcja obronna na utratę autonomii ma podłoże neurologiczne (układ nerwowy traktuje wymaganie jak zagrożenie). WTÓRNA: nasilenie wzrasta przez lata bycia ''poprawianym'', kontrolowanym i korygowanym. Ridcully unika wymagań, które mu nie pasują — ale robi to z pozycji władzy (''nie będę tego robił''), a nie z pozycji zamrożenia i wstydu.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> opór wobec wymagań bywa automatyczną reakcją obronną. Im więcej presji, tym bardziej zadanie może być odczuwane jak zagrożenie dla autonomii, nawet gdy obiektywnie jest rozsądne.</p><p><strong>Dla bliskich:</strong> sposób podania prośby często ma znaczenie równie duże jak jej treść. Zwykle lepiej działa wspólne uzgadnianie i danie kawałka wyboru niż wzmacnianie presji i kontroli.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R18, R10, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'29. Demand avoidance — mainly clinical observation / lived experience · common; very common for some people','This goes much deeper than “I can''t be bothered.” Imagine that you know what you have to do — for example, reply to an important email — you want to do it, you understand the consequences of not replying, and still you physically cannot do it. The body refuses to cooperate.',NULL,NULL);
INSERT INTO content_sections VALUES(798,27,785,'heading',3,3,37,'30. Problemy z koordynacją i propriocepcją badania + obserwacja kliniczna dość częste','30-problemy-z-koordynacja-i-propriocepcja','Propriocepcja to zmysł informujący mózg o tym, gdzie są poszczególne części ciała w przestrzeni — bez patrzenia. To dzięki propriocepcji możesz dotknąć nosa z zamkniętymi oczami albo wejść po schodach bez patrzenia na stopy.',37,replace('<p>Propriocepcja to zmysł informujący mózg o tym, gdzie są poszczególne części ciała w przestrzeni — bez patrzenia. To dzięki propriocepcji możesz dotknąć nosa z zamkniętymi oczami albo wejść po schodach bez patrzenia na stopy. U osób AuDHD ten zmysł często działa atypowo. W praktyce: wchodzenie w futryny drzwi, potykanie się o progi, które się doskonale zna, przewracanie rzeczy na stole, ciągłe siniaki niewiadomego pochodzenia. To nie jest „niezdarność" w potocznym sensie — to mózg, który nie otrzymuje wystarczająco precyzyjnych danych o pozycji ciała. Może się to nasilać przy zmęczeniu lub przeciążeniu sensorycznym, bo system ma mniej zasobów do przetwarzania informacji proprioceptywnych. Wielu dorosłych z AuDHD nie zdaje sobie sprawy, że ich problemy z koordynacją mają źródło neurologiczne — zakładają po prostu, że „są niezdarni".</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Atypowa propriocepcja i koordynacja wynikają z budowy dróg proprioceptywnych i integracji sensoryczno-motorycznej. To wrodzone. Klucz kliniczny (wgląd z 2026-03-31): kierunek przyczynowy jest odwrócony — NIE zmęczenie→niezdarność, LECZ atypowa propriocepcja wymusza kompensację korową 24/7→generuje zmęczenie jako stan wyjściowy.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> trudności ruchowe nie świadczą o niezdarności ''z wyboru''. W dorosłości bywa to wstydliwym, ale mało widocznym źródłem napięcia: człowiek wie, że coś „powinno” mu wychodzić łatwiej.</p><p><strong>Dla bliskich:</strong> mniej zawstydzania, więcej praktycznych adaptacji i cierpliwości. Zamiast zawstydzać, lepiej pomagać praktycznie — uproszczeniem otoczenia, tempem i cierpliwością wobec niezgrabności.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R14, R1</p>\n</div>\n<div class="symptom">','\n',char(10)),'30. Coordination and proprioception difficulties — research + clinical observation · fairly common','Proprioception is the sense that tells the brain where different parts of the body are in space without looking. It is what lets you touch your nose with your eyes closed or walk up stairs without looking at your feet.',NULL,NULL);
INSERT INTO content_sections VALUES(799,27,785,'heading',3,3,38,'31. Kompensacja jednego stanu drugim badania + obserwacja kliniczna częste','31-kompensacja-jednego-stanu-drugim','To fascynujący i bardzo AuDHD-owy mechanizm: cechy jednego stanu mogą być wykorzystywane do łagodzenia trudności drugiego.',38,replace('<p>To fascynujący i bardzo AuDHD-owy mechanizm: cechy jednego stanu mogą być wykorzystywane do łagodzenia trudności drugiego. ADHD-owa spontaniczność i impulsywność mogą pomóc przełamać autystyczny paraliż decyzyjny — „nie myśl, po prostu zrób" czasem działa, bo impuls ADHD jest silniejszy niż autystyczna potrzeba pełnej analizy. Z drugiej strony, autystyczne systemy, rutyny i struktury mogą pomóc okiełznać ADHD-owy chaos — kolorowe kalendarze, precyzyjne listy, rytuały porankowe dają ramy, których ADHD-owy mózg sam nie potrafi stworzyć. Z zewnątrz to wygląda jak „dobrze sobie radzi" — bo kompensacja jest skuteczna. Ale od wewnątrz to ciągły wysiłek balansowania na linie — wysiłek, którego otoczenie nie widzi i za który nikt nie daje zasługi. Kiedy zasoby się kończą, kompensacja przestaje działać i wszystko się wali — co wygląda „nagle", choć tak naprawdę narastało od tygodni.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Kompensowanie jednego profilu drugim (ADHD łamie autystyczny paraliż, autystyczne systemy okiełznują ADHD-owy chaos) to wewnętrzna dynamika dwóch neurologicznych systemów. To budowa. ALE — fakt, że kompensacja jest niewidoczna i niegratyfikowana, to efekt wtórny (środowisko nie widzi wysiłku).</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> to, co pomaga przetrwać, może jednocześnie kosztować bardzo dużo energii. To daje nieraz obraz pozornej stabilności, który jest okupiony dużą ilością energii i ciągłym ręcznym sterowaniem sobą.</p><p><strong>Dla bliskich:</strong> widoczna sprawność nie wyklucza ukrytego kosztu kompensacji. To, co wygląda na łatwe funkcjonowanie, może być efektem bardzo kosztownego wewnętrznego balansowania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R1, R16, R19</p>\n</div>','\n',char(10)),'31. Compensating one condition with the other — research + clinical observation · common','This is a fascinating and very AuDHD-specific mechanism: features of one condition can be used to mitigate difficulties caused by the other.',NULL,NULL);
INSERT INTO content_sections VALUES(800,27,762,'heading',2,2,39,'GRUPA IV — Głębokie, rzadko omawiane','grupa-iv-glebokie-rzadko-omawiane','Punkty bardziej fenomenologiczne, tożsamościowe i relacyjne',39,replace('<p class="small">Punkty bardziej fenomenologiczne, tożsamościowe i relacyjne</p>\n<div class="symptom">','\n',char(10)),'GROUP IV — Deep, rarely discussed','More phenomenological, identity-related, and relational points.',NULL,NULL);
INSERT INTO content_sections VALUES(801,27,800,'heading',3,3,40,'32. Pamięć encyklopedyczna obok pamięci „złotej rybki" badania + obserwacja kliniczna bardzo częste','32-pamiec-encyklopedyczna-obok-pamieci-zlotej-rybki','Mózg AuDHD ma dwa zupełnie różne systemy pamięci, które działają niezależnie od siebie. Pamięć długotrwała dla rzeczy, które kiedyś wpadły do „tunelu uwagi", jest fenomenalna — osoba pamięta szczegółowy dialog z filmu sprzed 15 lat, numer rejestracyjny…',40,replace('<p>Mózg AuDHD ma dwa zupełnie różne systemy pamięci, które działają niezależnie od siebie. Pamięć długotrwała dla rzeczy, które kiedyś wpadły do „tunelu uwagi", jest fenomenalna — osoba pamięta szczegółowy dialog z filmu sprzed 15 lat, numer rejestracyjny samochodu sąsiada z dzieciństwa, kolor koszulki kogoś na spotkaniu pięć lat temu. Te informacje zostały zakodowane głęboko, bo w momencie rejestrowania mózg był w stanie hiperfokusu. Jednocześnie pamięć robocza — ta, która trzyma informacje „na chwilę", żeby z nimi pracować — jest dramatycznie ograniczona przez ADHD. Osoba nie pamięta, po co weszła do kuchni, zapomina co chciała powiedzieć w połowie zdania, czyta ten sam akapit trzy razy. Z zewnątrz to wygląda jak sprzeczność: „jak możesz pamiętać coś sprzed 15 lat i nie pamiętać, co ci powiedziałem wczoraj?". Ale to nie ta sama pamięć — to dwa różne systemy, i oba działają „prawidłowo" w ramach swojej neurologicznej architektury.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Fenomenalna pamięć długotrwała + deficytowa pamięć robocza to dwa różne systemy neurologiczne. Ridcully pamięta detale sprzed lat i nie pamięta, co ktoś mu powiedział minutę temu. To architektura, nie wybór.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> nierówny profil pamięci jest częścią obrazu, a nie dowodem na brak starań. Właśnie ta nierówność bywa najbardziej myląca dla otoczenia: bardzo dużo kompetencji obok bardzo zwyczajnych potknięć.</p><p><strong>Dla bliskich:</strong> ''skoro pamiętasz tamto, to powinieneś pamiętać wszystko'' zwykle rani bardziej niż pomaga. Nie warto używać mocnych stron jako argumentu przeciw słabszym; właśnie nierówność profilu jest tu kluczowa.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R16</p>\n</div>\n<div class="symptom">','\n',char(10)),'32. Encyclopaedic memory beside “goldfish” memory — research + clinical observation · very common','The AuDHD brain has two completely different memory systems operating independently. Long-term memory for things that once entered the “attention tunnel” can be phenomenal: a person may remember detailed dialogue from a film watched 15 years ago, a licence plate…',NULL,NULL);
INSERT INTO content_sections VALUES(802,27,800,'heading',3,3,41,'33. Zapominanie, że się coś wie głównie obserwacja kliniczna / doświadczenie częste','33-zapominanie-ze-sie-cos-wie','To subtelne, ale frustrujące doświadczenie. Wiedza jest w głowie — osoba naprawdę to wie — ale nie potrafi jej przywołać na żądanie. To jak mieć bibliotekę z tysiącami książek, ale bez katalogu.',41,replace('<p>To subtelne, ale frustrujące doświadczenie. Wiedza jest w głowie — osoba naprawdę to wie — ale nie potrafi jej przywołać na żądanie. To jak mieć bibliotekę z tysiącami książek, ale bez katalogu. Kiedy ktoś pyta o konkretny temat, odpowiedź brzmi „nie wiem" — i jest to w danym momencie subiektywnie prawdziwe, bo mózg nie potrafi „wyszukać" odpowiedniej informacji. Ale godzinę później, kiedy ktoś wspomni coś powiązanego, nagle „odpala się" cały blok wiedzy — tak jakby ktoś włączył światło w pokoju, w którym wcześniej nic nie było widać. To jest szczególnie frustrujące w sytuacjach testowych, rozmowach o pracę, egzaminach — wszędzie tam, gdzie trzeba mieć dostęp do wiedzy „na zawołanie". Osoba wie znacznie więcej, niż potrafi pokazać w danym momencie.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Brak dostępu do wiedzy ''na żądanie'' wynika z asocjacyjnej organizacji pamięci — informacja jest tam, ale bez odpowiedniego klucza skojarzeniowego nie aktywuje się. Ridcully często ''nie wie'', a potem nagle wie — ten sam mechanizm.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> dostęp do wiedzy może zależeć od stresu, formy pytania i obciążenia. Na spokojnie odpowiedź potrafi wrócić sama, ale w chwili nacisku dostęp do niej bywa zaskakująco słaby.</p><p><strong>Dla bliskich:</strong> warto dawać czas i alternatywne sposoby odpowiedzi. Danie chwili, innego kontekstu albo pytania pomocniczego często daje lepszy efekt niż presja „no przecież to wiesz”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'33. Forgetting that you know something — mainly clinical observation / lived experience · common','A subtle but frustrating experience. The knowledge is in the head — the person genuinely knows it — but cannot retrieve it on demand. It is like having a library with thousands of books but no catalogue.',NULL,NULL);
INSERT INTO content_sections VALUES(803,27,800,'heading',3,3,42,'34. Myślenie w systemach, trudność z wyjaśnieniem badania + obserwacja kliniczna częste','34-myslenie-w-systemach-trudnosc-z-wyjasnieniem','Mózg AuDHD widzi wzorce, powiązania i struktury w sposób, który jest wewnętrznie bardzo logiczny — ale ta logika jest asocjacyjna (oparta na skojarzeniach) i nieliniowa, co znaczy, że nie da się jej łatwo przetłumaczyć na zwykłą mowę, która jest liniowa…',42,replace('<p>Mózg AuDHD widzi wzorce, powiązania i struktury w sposób, który jest wewnętrznie bardzo logiczny — ale ta logika jest asocjacyjna (oparta na skojarzeniach) i nieliniowa, co znaczy, że nie da się jej łatwo przetłumaczyć na zwykłą mowę, która jest liniowa (jedno słowo po drugim, jedno zdanie po drugim). Wyobraź sobie, że widzisz trójwymiarową mapę połączeń — jak sieć neuronowa — i musisz opisać ją komuś przez telefon, używając tylko słów, jedno po drugim. Coś zawsze się zgubi. Dlatego osoba AuDHD może mieć genialne rozwiązanie problemu, ale nie potrafić wytłumaczyć, jak do niego doszła, bo droga była nieliniowa. „Po prostu wiem" — nie jest lenistwem intelektualnym. To jest efekt przetwarzania oddolnego, w którym wnioski wyłaniają się z masy szczegółów, zanim mózg zdąży zbudować liniowe uzasadnienie.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Myślenie systemowe, nieliniowe, trudne do werbalnego wyjaśnienia — to cecha przetwarzania bottom-up. Ridcully widzi rozwiązanie, ale nie potrafi go wytłumaczyć linearnie. ''Po prostu wiem'' — to nie lenistwo, to efekt odwrotnego kierunku przetwarzania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> można widzieć całość bardzo jasno, a mieć trudność z linearnym tłumaczeniem. Osoba może widzieć całość bardzo jasno, ale potrzebować więcej czasu, by przełożyć ją na krok po kroku dla innych.</p><p><strong>Dla bliskich:</strong> dopytanie o przykłady bywa lepsze niż uznanie wypowiedzi za chaos. Dobrze dawać czas na zebranie myśli i nie mylić złożonego myślenia z brakiem logiki.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'34. Thinking in systems, difficulty explaining them — research + clinical observation · common','The AuDHD brain sees patterns, links, and structures in a way that is internally highly logical, but the logic is associative and nonlinear. That makes it difficult to translate into ordinary speech, which is linear…',NULL,NULL);
INSERT INTO content_sections VALUES(804,27,800,'heading',3,3,43,'35. Przetwarzanie „w tle" głównie obserwacja kliniczna / doświadczenie częste','35-przetwarzanie-w-tle','Osoba wydaje się nie słuchać — wzrok ucieka, odpowiedzi są zdawkowe, wydaje się nieobecna. A potem, godziny lub dni później, wraca z gotowym, złożonym, przemyślanym rozwiązaniem problemu, o którym rozmawiano. Co się stało?',43,replace('<p>Osoba wydaje się nie słuchać — wzrok ucieka, odpowiedzi są zdawkowe, wydaje się nieobecna. A potem, godziny lub dni później, wraca z gotowym, złożonym, przemyślanym rozwiązaniem problemu, o którym rozmawiano. Co się stało? Mózg przetwarzał informacje w tle — nieświadomie, poza aktywną uwagą — zbierając elementy, szukając wzorców, budując odpowiedź „od dołu do góry". Ten proces nie jest widoczny z zewnątrz i nie jest kontrolowany świadomie. To trochę jak program działający w tle na komputerze — nie widzisz go na ekranie, ale zużywa procesor. Dlatego osoba AuDHD może mieć „opóźnione przetwarzanie rozmowy" — prawdziwe zrozumienie tego, co ktoś miał na myśli, przychodzi dopiero po jakimś czasie. W momencie rozmowy mogła reagować na to, co zrozumiała powierzchownie (często impulsywnie, bo ADHD), a głębokie przetwarzanie jeszcze trwało.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Przetwarzanie informacji poza świadomą uwagą to cecha architektury poznawczej. Ridcully wraca z gotowym rozwiązaniem po dniach pozornej bezczynności. To nie jest coś, czego uczy środowisko.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> część rozumienia może dojrzewać z opóźnieniem. Dlatego wiele najlepszych odpowiedzi przychodzi pod prysznicem, na spacerze albo kilka godzin po zakończonej rozmowie.</p><p><strong>Dla bliskich:</strong> nie każda późna odpowiedź oznacza unikanie czy obojętność. Czasem najlepszą pomocą jest zgoda, że odpowiedź może przyjść później i nadal będzie wartościowa.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R18, R12</p>\n</div>\n<div class="symptom">','\n',char(10)),'35. Background processing — mainly clinical observation / lived experience · common','The person appears not to be listening: their gaze drifts, replies are brief, they seem absent. Then, hours or days later, they return with a complete, complex, carefully thought-through solution to the problem that was discussed. What happened?',NULL,NULL);
INSERT INTO content_sections VALUES(805,27,800,'heading',3,3,44,'36. Kameleonizm (dyfuzja tożsamości) badania + obserwacja kliniczna bardzo częste (szczególnie u kobiet)','36-kameleonizm-dyfuzja-tozsamosci','To głębsze zjawisko niż samo maskowanie — to zatracanie się w procesie adaptacji. Osoba nieświadomie dopasowuje nie tylko zachowanie, ale także osobowość, zainteresowania, styl mówienia, a nawet poczucie humoru do osoby, z którą rozmawia.',44,replace('<p>To głębsze zjawisko niż samo maskowanie — to zatracanie się w procesie adaptacji. Osoba nieświadomie dopasowuje nie tylko zachowanie, ale także osobowość, zainteresowania, styl mówienia, a nawet poczucie humoru do osoby, z którą rozmawia. Przy przyjacielce A jest jedną osobą, przy przyjacielce B — inną. Nie udaje — naprawdę czuje się tą osobą w danym momencie. Po spotkaniu z kilkoma różnymi ludźmi w ciągu dnia może nie wiedzieć, „kim właściwie jest". Badania łączą chroniczne maskowanie u osób autystycznych i AuDHD z depresją, lękiem, myślami samobójczymi i głęboką dyfuzją tożsamości. Jedna osoba z AuDHD opisała to tak: „zamiast mieć własną osobowość, stałam się albumem z wycinkami od wszystkich, których kochałam". Zdemaskowanie — znalezienie prawdziwego „ja" pod warstwami adaptacji — to jeden z głównych tematów terapii u dorosłych z późną diagnozą AuDHD.</p>\n<p class="small"><strong>Objaśnienie:</strong> Przy późnej diagnozie ten punkt bywa jednym z najbardziej bolesnych. Osoba może odkryć, że przez lata rozwijała przede wszystkim sposoby dopasowania się, a dużo słabiej miała kontakt z własnym stylem bycia.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Kameleonizm jest CAŁKOWICIE wtórny. To efekt chronicznego dopasowywania się do otoczenia w celu przetrwania społecznego. Ridcully NIGDY nie dopasowuje swojej osobowości do rozmówcy — jest identyczny z każdym: kadrem, studentem, bogiem, obcym. To potwierdza, że dyfuzja tożsamości nie jest cechą AuDHD, lecz ceną maskowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> długie dostrajanie się do innych może rozmywać poczucie własnego ''ja''. Po latach takiego dostrajania pytanie „kim ja właściwie jestem bez ciągłego poprawiania siebie?” może być naprawdę trudne i bolesne.</p><p><strong>Dla bliskich:</strong> akceptacja mniej maskowanej wersji osoby bywa bardzo odciążająca. W relacji warto wzmacniać autentyczność bardziej niż samą poprawność społeczną, bo ta druga potrafi drogo kosztować.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R9, R10</p>\n</div>\n<div class="symptom">','\n',char(10)),'36. Social chameleonism (identity diffusion) — research + clinical observation · very common, especially in women','This is deeper than masking alone: it is losing oneself in the process of adaptation. The person unconsciously adjusts not only behaviour but also personality, interests, speaking style, and even sense of humour to the person they are talking to.',NULL,NULL);
INSERT INTO content_sections VALUES(806,27,800,'heading',3,3,45,'37. Moralna skrupulatność głównie obserwacja kliniczna / doświadczenie dość częste','37-moralna-skrupulatnosc','To nie zwykłe „silne sumienie". To wewnętrzny krytyk, który nigdy nie milknie i ocenia każdą decyzję, każde słowo, każdy czyn przez pryzmat sztywnych, często niemożliwie wysokich standardów moralnych.',45,replace('<p>To nie zwykłe „silne sumienie". To wewnętrzny krytyk, który nigdy nie milknie i ocenia każdą decyzję, każde słowo, każdy czyn przez pryzmat sztywnych, często niemożliwie wysokich standardów moralnych. Autystyczna sztywność myślenia sprawia, że zasady moralne są traktowane absolutnie — nie ma „szarej strefy", nie ma „to zależy". „Nie wolno kłamać" oznacza nigdy, w żadnych okolicznościach, nawet grzeczniościowo. „Nie wolno skrzywdzić" oznacza nawet nieumyślnie, nawet minimalnie. Do tego dochodzi ADHD-owa wrażliwość na odrzucenie: jeśli ktoś zinterpretuje coś, co powiedziałam, jako nieuprzejme — to ja jestem złą osobą. Efektem jest cykl: osoba stara się być „doskonale dobra" → to jest wyczerpujące → w momencie wyczerpania nie spełnia własnych standardów → czuje paraliżujące poczucie winy → poczucie winy napędza jeszcze większy wysiłek bycia „dobrą" → i pętla się zamyka. Z zewnątrz ta osoba wygląda na wyjątkowo sumienną i empatyczną. Od wewnątrz — jest na granicy wypalenia z powodu niemożliwych standardów, których sobie nie wybrała.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: sztywne myślenie moralne (czarno-białe, bez ''szarej strefy'') wynika z autystycznego stylu przetwarzania reguł. WTÓRNA: paraliżujące poczucie winy i wewnętrzny krytyk narastają przez lata bycia ''poprawianym''. Ridcully ma sztywne zasady moralne, ale nie trawią go wyrzuty sumienia po każdym słowie — bo nikt nigdy nie nauczył go, że jego standardy są ''przesadzone''.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> wysoka odpowiedzialność moralna może dawać sens, ale też mocno obciążać. To może prowadzić do nadmiernego samonadzoru, przepraszania i brania na siebie odpowiedzialności ponad realną miarę.</p><p><strong>Dla bliskich:</strong> warto odróżniać wartości od przymusu i łagodzić nadmierne poczucie winy. Dobrze uważać, by nie dokładać kolejnych poziomów winy osobie, która i tak zwykle stawia sobie bardzo surowe wymagania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R15</p>\n</div>\n<div class="symptom">','\n',char(10)),'37. Moral scrupulosity — mainly clinical observation / lived experience · fairly common','This is not simply a “strong conscience”. It is an inner critic that never falls silent and judges every decision, every word, and every act against rigid, often impossibly high moral standards.',NULL,NULL);
INSERT INTO content_sections VALUES(807,27,800,'heading',3,3,46,'38. Mówienie za dużo lub za mało, bez środka badania + obserwacja kliniczna bardzo częste','38-mowienie-za-duzo-lub-za-malo-bez-srodka','Komunikacja AuDHD ma dwa tryby, które przełączają się w sposób trudny do kontrolowania. Tryb pierwszy: infodumping — kiedy temat wchodzi w „tunel uwagi", osoba może mówić o nim długo, szczegółowo, z pasją, wchodząc w detale, o które nikt nie prosił, bo każdy…',46,replace('<p>Komunikacja AuDHD ma dwa tryby, które przełączają się w sposób trudny do kontrolowania. Tryb pierwszy: infodumping — kiedy temat wchodzi w „tunel uwagi", osoba może mówić o nim długo, szczegółowo, z pasją, wchodząc w detale, o które nikt nie prosił, bo każdy szczegół wydaje się istotny. To nie jest „gadatliwość" w zwykłym sensie — to efekt asocjacyjnego myślenia, w którym każda informacja ciągnie za sobą następną. Tryb drugi: cisza — kiedy temat jest poza tunelem, osoba nagle nie wie, co powiedzieć, odpowiada monosylabami, wygląda na niezainteresowaną. Do tego dochodzi gubienie wątku we własnym zdaniu: dygresja prowokowana przez skojarzenie (ADHD) zabiera pamięć roboczą, a autystyczna część chce precyzji i nie toleruje niedokończonej myśli. Efekt: osoba zaczyna zdanie, skręca w boczny wątek, traci oryginalną myśl, frustruje się, próbuje wrócić, nie pamięta. Z zewnątrz wygląda to jak chaotyczność. Od wewnątrz — to walka o wyrażenie bogatego, asocjacyjnego myślenia za pomocą narzędzia (mowy), które jest do tego zbyt liniowe.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Bimodalność komunikacji (infodumping albo cisza) wynika z monotropowej uwagi + asocjacyjnego myślenia + ograniczonej pamięci roboczej. Ridcully albo mówi za dużo, albo nie odpowiada — i nie jest tego świadomy. To budowa, nie strategia.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ilość mówienia może zależeć bardziej od bezpieczeństwa i przeciążenia niż od charakteru. Bywa też tak, że po okresie bardzo intensywnego mówienia następuje spadek i potrzeba długiego wyciszenia.</p><p><strong>Dla bliskich:</strong> nie warto mylić milczenia z brakiem uczuć ani szczegółowości z egoizmem. Nie każda cisza jest karą, a nie każda gadatliwość jest brakiem granic; często to dwa różne stany regulacji.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13, R8</p>\n</div>\n<div class="symptom">','\n',char(10)),'38. Talking too much or too little, with no middle — research + clinical observation · very common','AuDHD communication has two modes that switch in ways that are difficult to control. Mode one is infodumping: when a subject enters the “attention tunnel”, the person may talk about it at length, in detail and with passion, moving into details nobody asked for, because every…',NULL,NULL);
INSERT INTO content_sections VALUES(808,27,800,'heading',3,3,47,'39. Wrażliwość na niesprawiedliwość, która paraliżuje badania + obserwacja kliniczna częste','39-wrazliwosc-na-niesprawiedliwosc-ktora-paralizuje','Wiele osób neurotypowych widzi niesprawiedliwość, marszczy brwi, a potem wraca do swoich spraw. Osoba AuDHD nie potrafi tego zrobić.',47,replace('<p>Wiele osób neurotypowych widzi niesprawiedliwość, marszczy brwi, a potem wraca do swoich spraw. Osoba AuDHD nie potrafi tego zrobić. Silne poczucie sprawiedliwości (częste w autyzmie, wynikające z czarno-białego myślenia: „to jest niesprawiedliwe, więc to jest złe") + emocjonalna intensywność ADHD = drobna niesprawiedliwość w pracy, w wiadomościach, a nawet w fabule serialu może zająć myśli na całe dni. Badania łączą wrażliwość na sprawiedliwość z ADHD i sugerują, że może to być mechanizm kompensacyjny — zwiększona czujność wobec niesprawiedliwości mogła pomagać w regulowaniu zachowań społecznych. Problem w tym, że ten mechanizm nie ma przycisku „wyłącz" — i energia, która idzie w ruminację nad czymś niesprawiedliwym, to energia odebrana reszcie życia.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: silne, sztywne poczucie sprawiedliwości wynika z autystycznego przetwarzania reguł. WTÓRNA: ruminacja i paraliż wokół niesprawiedliwości nasilają się przez lata doświadczania niesprawiedliwości wobec siebie (niezrozumienie, korekcja, podwójne standardy). Ridcully reaguje na niesprawiedliwość gwałtownie — ale idzie dalej, bo nie ma narosłego bólu z lat bycia źle traktowanym.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> niesprawiedliwość może być przeżywana nieproporcjonalnie intensywnie. Nie chodzi tylko o pogląd, ale o silną reakcję całego systemu na poczucie naruszenia zasad lub nierówności.</p><p><strong>Dla bliskich:</strong> samo ''odpuść'' rzadko działa; lepiej najpierw uznać wagę przeżycia. Warto nie wyśmiewać tej reakcji jako przesady, bo dla danej osoby poczucie niesprawiedliwości bywa naprawdę fizycznie obciążające.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'39. Sensitivity to injustice that becomes paralysing — research + clinical observation · common','Many neurotypical people see an injustice, frown, and then return to their own affairs. A person with AuDHD may be unable to do that.',NULL,NULL);
INSERT INTO content_sections VALUES(809,27,800,'heading',3,3,48,'40. Kochanie przez dzielenie się informacjami głównie obserwacja kliniczna / doświadczenie częste','40-kochanie-przez-dzielenie-sie-informacjami','Osoby neurotypowe wyrażają uczucia na wiele sposobów — prezenty, czas spędzony razem, słowa potwierdzenia, pomoc, dotyk. Osoby AuDHD mają jeszcze jeden, rzadko rozpoznawany „język miłości": dzielenie się informacjami.',48,replace('<p>Osoby neurotypowe wyrażają uczucia na wiele sposobów — prezenty, czas spędzony razem, słowa potwierdzenia, pomoc, dotyk. Osoby AuDHD mają jeszcze jeden, rzadko rozpoznawany „język miłości": dzielenie się informacjami. „Znalazłem artykuł, który mi ciebie przypomniał", „muszę ci opowiedzieć o tym, czego się dowiedziałem", „pomyślałem o tobie, bo przeczytałem coś o twoim hobby". Infodumping w kierunku konkretnej osoby to wyraz głębokiego uczucia — „dzielę się z tobą moim światem wewnętrznym, a to jest najcenniejsze, co mam". Kiedy osoba bliska nie docenia tego, a szczególnie kiedy mówi „przestań o tym gadać" — boli to nieproporcjonalnie mocno, bo to odrzucenie nie tylko tematu, ale sposobu wyrażania miłości. Jednocześnie ADHD może powodować, że osoba zapomina odpisywać na wiadomości od ważnych ludzi — co nie oznacza braku uczuć. W wewnętrznym świecie relacja jest żywa i ważna, nawet gdy na zewnątrz panuje cisza od tygodni.</p>\n<p class="small"><strong>Objaśnienie:</strong> Ten punkt jest bardziej relacyjny niż diagnostyczny. Został ujęty w tekście, ponieważ dobrze pokazuje, że dzielenie się informacją, skojarzeniem czy linkiem może być autentycznym gestem więzi i bliskości.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Dzielenie się informacją jako forma bliskości wynika z monotropowej struktury uwagi: ''daję Ci to, co jest w moim tunelu uwagi, bo to najcenniejsze, co mam''. Ridcully opowiada o swoich zainteresowaniach osobom, na których mu zależy — to jego język miłości, nikt go tego nie nauczył.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> dzielenie się informacją może być naturalnym językiem bliskości. Dawanie informacji bywa wtedy formą: „pomyślałem o Tobie”, „chcę się podzielić czymś ważnym” albo „tak okazuję bliskość”.</p><p><strong>Dla bliskich:</strong> czasem link, fakt albo infodump są formą kontaktu i czułości. To może być zaproszenie do kontaktu, nie popis. Czasem najprostsze „fajnie, że mi to wysłałeś” znaczy bardzo dużo.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13</p>\n</div>\n<div class="symptom">','\n',char(10)),'40. Loving by sharing information — mainly clinical observation / lived experience · common','Neurotypical people express affection in many ways: gifts, time together, words of affirmation, help, touch. People with AuDHD often have another, rarely recognised “love language”: sharing information.',NULL,NULL);
INSERT INTO content_sections VALUES(810,27,800,'heading',3,3,49,'41. Głód bliskości, który przeraża głównie obserwacja kliniczna / doświadczenie częste','41-glod-bliskosci-ktory-przeraza','Wiele osób z AuDHD ma bardzo silną potrzebę bliskości, zwłaszcza po latach poczucia izolacji, niezrozumienia i „inności”. Znalezienie kogoś, kto naprawdę rozumie, bywa rzadkie, dlatego więź może mieć dla nich wyjątkowo duże znaczenie.',49,replace('<p>Wiele osób z AuDHD ma bardzo silną potrzebę bliskości, zwłaszcza po latach poczucia izolacji, niezrozumienia i „inności”. Znalezienie kogoś, kto naprawdę rozumie, bywa rzadkie, dlatego więź może mieć dla nich wyjątkowo duże znaczenie. Ale jednocześnie bliskość — zarówno fizyczna, jak i emocjonalna — potrafi przytłoczyć system sensoryczny i emocjonalny. Osoba może desperacko chcieć przytulenia, a po minucie czuć, że musi się odsunąć, bo dotyk staje się drażniący (zmiana progu sensorycznego) lub emocje są zbyt intensywne (dysregulacja emocjonalna). To nie jest ambiwalencja uczuciowa w psychologicznym sensie. To dwa systemy neurologiczne — potrzeba bliskości i sensoryczne/emocjonalne przeciążenie — ze sprzecznymi wymaganiami, działające w tym samym momencie. Partnerzy osób AuDHD często nie rozumieją tego paradoksu i interpretują go jako odrzucenie. A to nie jest odrzucenie — to ograniczenie pojemności, nie ograniczenie uczuć.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: jednoczesna silna potrzeba bliskości + przeciążenie sensoryczno-emocjonalne to zderzenie dwóch systemów neurologicznych. WTÓRNA: lęk w bliskości narasta przez lata, w których bliskość była ryzykowna (odrzucenie, niezrozumienie, ''jesteś za dużo''). Ridcully chce bliskości z Esme i nie potrafi jej znieść — ale z powodów pierwotnych, nie z lęku.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> potrzeba bliskości i potrzeba dystansu mogą współistnieć bez sprzeczności. Bliskość może być upragniona i trudna jednocześnie, bo oprócz więzi pojawia się też duże obciążenie sensoryczne i emocjonalne.</p><p><strong>Dla bliskich:</strong> warto ustalać formy bliskości, które nie przeciążają. Pomaga szanowanie tempa i granic, zamiast interpretowania ambiwalencji jako gry albo braku dojrzałości.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R12, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'41. A hunger for closeness that is frightening — mainly clinical observation / lived experience · common','Many people with AuDHD have a very strong need for closeness, especially after years of isolation, misunderstanding, and feeling “different”. Finding someone who genuinely understands can be rare, so the bond may carry exceptional importance.',NULL,NULL);
INSERT INTO content_sections VALUES(811,27,800,'heading',3,3,50,'42. Potrzeba werbalnego potwierdzania zasad relacji głównie obserwacja kliniczna / doświadczenie dość częste','42-potrzeba-werbalnego-potwierdzania-zasad-relacji','„Czy jesteśmy blisko? Czy mogę do ciebie zadzwonić bez powodu? Czy jesteś na mnie zły? Czy nasza relacja jest OK?" — osoby neurotypowe wyciągają te informacje z kontekstu: tonu głosu, częstotliwości kontaktu, niejawnych sygnałów.',50,replace('<p>„Czy jesteśmy blisko? Czy mogę do ciebie zadzwonić bez powodu? Czy jesteś na mnie zły? Czy nasza relacja jest OK?" — osoby neurotypowe wyciągają te informacje z kontekstu: tonu głosu, częstotliwości kontaktu, niejawnych sygnałów. Osoby AuDHD nie mają do nich pewnego dostępu, bo autystyczny mózg nie przetwarza niejawnych sygnałów „w tle" tak jak neurotypowy. Jednocześnie ADHD-owa wrażliwość na odrzucenie każe zakładać najgorsze przy każdej ciszy, nieodebranym telefonie, zbyt krótkim mailu. Efektem jest potrzeba jawnych, werbalnych potwierdzeń — nie z powodu niepewności emocjonalnej (jak to może wyglądać z zewnątrz), ale z powodu braku automatycznego dostępu do niejawnych informacji społecznych. To tak, jakby osoba neurotypowa wiedziała, że jest dzień, bo widzi światło za oknem — a osoba AuDHD musiała co chwilę pytać „czy nadal jest dzień?", bo za jej oknem jest matowe szkło.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: potrzeba jawnych reguł relacyjnych wynika z braku automatycznego dostępu do niejawnych sygnałów społecznych. WTÓRNA: nasilenie potrzeby potwierdzeń wynika z lat, w których milczenie oznaczało odrzucenie. Ridcully nie pyta ''czy nasza relacja jest OK'' — ale też nie dekoduje subtelności, po prostu go to nie obchodzi z pozycji władzy.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> jasne nazwanie zasad relacji może realnie obniżać lęk. Wyjaśnione zasady relacji zmniejszają ilość domyślania się i redukują koszt ciągłego zgadywania, co druga strona miała na myśli.</p><p><strong>Dla bliskich:</strong> mówienie wprost bywa opiekuńcze, nie ''zabijające spontaniczność''. Jasność bywa tu formą troski o relację, a nie dowodem chłodu czy przesadnej potrzeby kontroli.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13</p>\n</div>\n<div class="symptom">','\n',char(10)),'42. Need for verbal confirmation of relationship rules — mainly clinical observation / lived experience · fairly common','“Are we close? Can I call you for no reason? Are you angry with me? Is our relationship OK?” Neurotypical people infer this information from context: tone of voice, frequency of contact, implicit signals.',NULL,NULL);
INSERT INTO content_sections VALUES(812,27,800,'heading',3,3,51,'43. Fizyczne objawy stresu z opóźnieniem badania + obserwacja kliniczna dość częste','43-fizyczne-objawy-stresu-z-opoznieniem','U części osób stres nie daje czytelnego sygnału w chwili, gdy narasta. Zamiast tego ciało reaguje dopiero po czasie: pojawia się ból głowy, rozbicie, napięcie mięśni, problemy żołądkowe albo nagłe wyczerpanie, pozornie bez wyraźnej przyczyny.',51,replace('<p>U części osób stres nie daje czytelnego sygnału w chwili, gdy narasta. Zamiast tego ciało reaguje dopiero po czasie: pojawia się ból głowy, rozbicie, napięcie mięśni, problemy żołądkowe albo nagłe wyczerpanie, pozornie bez wyraźnej przyczyny. Można to częściowo rozumieć przez słabszy dostęp do sygnałów z ciała w trakcie przeciążenia oraz przez fakt, że w trudnym momencie dużo energii idzie w utrzymanie funkcjonowania „na zewnątrz”. Kiedy sytuacja mija, organizm jakby dopiero wtedy domaga się zauważenia kosztu. To nie musi oznaczać, że problem jest „tylko psychiczny”; raczej pokazuje, że u części osób związek między stresem a jego somatycznym śladem jest mniej bezpośredni i bardziej opóźniony.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: opóźnione przetwarzanie stresu przez ciało wynika z atypowej interocepcji. WTÓRNA: mechanizm nasila się, gdy w trakcie stresu cała energia idzie w maskowanie — ciało ''odkłada'' sygnał na później. Ridcully reaguje natychmiast i somatycznie, bo nie odkłada niczego na później.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ciało może zgłaszać stres dopiero po czasie. Ciało niejako nadrabia wtedy to, czego świadomość nie złapała odpowiednio wcześnie.</p><p><strong>Dla bliskich:</strong> warto reagować już na wcześniejsze sygnały przeciążenia, jeśli są widoczne. Gdy objawy z ciała pojawiają się po czasie, dobrze traktować je poważnie, a nie jako „dziwną przesadę”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R5, R6, R10</p>\n</div>\n<div class="symptom">','\n',char(10)),'43. Delayed physical symptoms of stress — research + clinical observation · fairly common','For some people, stress does not produce a clear signal while it is building. Instead, the body reacts only later: headache, feeling unwell, muscle tension, stomach problems, or sudden exhaustion can appear, seemingly without an obvious cause.',NULL,NULL);
INSERT INTO content_sections VALUES(813,27,800,'heading',3,3,52,'44. Ból, który jest „niewłaściwy" badania + obserwacja kliniczna dość częste','44-bol-ktory-jest-niewlasciwy','Przetwarzanie bólu u osób AuDHD bywa atypowe — i to w obu kierunkach. Zbyt niski próg: osoba reaguje na bodźce, które u innych nie wywołują bólu — lekkie uderzenie, ucisk gumki od skarpetki, dotyk pewnych materiałów.',52,replace('<p>Przetwarzanie bólu u osób AuDHD bywa atypowe — i to w obu kierunkach. Zbyt niski próg: osoba reaguje na bodźce, które u innych nie wywołują bólu — lekkie uderzenie, ucisk gumki od skarpetki, dotyk pewnych materiałów. Lekarze nie traktują tego poważnie, bo „to nie powinno boleć". Zbyt wysoki próg: osoba chodzi z kontuzją, infekcją lub poważnym urazem, nie wiedząc o tym, bo ból nie przebił się przez próg świadomości. Lekarze nie wierzą, że „nie czuła bólu", bo „każdy by to poczuł". Co jeszcze bardziej komplikowane: oba wzorce mogą współistnieć w tej samej osobie, ale w różnych typach bodźców. Powierzchowny dotyk może boleć, a głębokie uderzenie — nie. Ból emocjonalny może manifestować się jako ból fizyczny (i odwrotnie). To wynika z atypowej interocepcji — ten sam system, który utrudnia rozpoznanie głodu i emocji, utrudnia też prawidłowe przetwarzanie bólu.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Atypowe przetwarzanie bólu (zbyt niski LUB zbyt wysoki próg) wynika z budowy szlaków nocyceptywnych i interoceptywnych. Ridcully znosi absurdalnie dużo fizycznie — to ten sam mechanizm. To neurobiologia, nie efekt wychowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> nietypowe odczuwanie bólu nie znaczy, że ciało jest mniej ważne. To może dotyczyć zarówno siły bodźca, jak i tego, kiedy sygnał staje się czytelny oraz jak długo zostaje w systemie.</p><p><strong>Dla bliskich:</strong> nie warto oceniać realności bólu po samym stylu reagowania. Najlepiej pytać konkretnie, jak dana osoba odbiera ciało i bodźce, zamiast zakładać wspólną normę odczuć.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R5, R6</p>\n</div>\n<div class="symptom">','\n',char(10)),'44. Pain that is “wrong” — research + clinical observation · fairly common','Pain processing in people with AuDHD can be atypical in both directions. A threshold that is too low: the person reacts to stimuli that do not cause pain in others — a light bump, pressure from a sock elastic, the touch of certain materials.',NULL,NULL);
INSERT INTO content_sections VALUES(814,27,800,'heading',3,3,53,'45. Zmęczenie, które nie ma dna badania + obserwacja kliniczna powszechne','45-zmeczenie-ktore-nie-ma-dna','To nie jest zwykłe zmęczenie, które mija po przespanej nocy. To zmęczenie systemowe — wynikające z faktu, że mózg AuDHD pracuje ciężej niż mózg neurotypowy przez każdą minutę dnia.',53,replace('<p>To nie jest zwykłe zmęczenie, które mija po przespanej nocy. To zmęczenie systemowe — wynikające z faktu, że mózg AuDHD pracuje ciężej niż mózg neurotypowy przez każdą minutę dnia. Maskowanie cech autystycznych, przetwarzanie bodźców sensorycznych, które neurotypowy mózg odfiltrował by automatycznie, kompensowanie trudności z funkcjami wykonawczymi, świadome dekodowanie interakcji społecznych, tłumaczenie świata na „swój język", tłumaczenie siebie na „ich język" — to wszystko jest jak ciągłe tłumaczenie symultaniczne, które nigdy się nie kończy. Potrzeba „czasu na nic" — scrollowania telefonu, chodzenia po pokoju, siedzenia i patrzenia w ścianę — to nie jest lenistwo. To regulacja systemu nerwowego między zadaniami. Ale nawet ten „czas na nic" rzadko naprawdę regeneruje, bo mózg nie potrafi się wyłączyć — wewnętrzny monolog trwa, bodźce są przetwarzane, analizy się kręcą. To jest fundamentalna różnica: osoba neurotypowa odpoczywając ładuje baterie. Osoba AuDHD odpoczywając — zwalnia tempo rozładowywania.</p>\n<p class="small"><strong>Objaśnienie:</strong> Przewlekłe zmęczenie jest jednym z najczęściej niedoszacowanych kosztów AuDHD. Z zewnątrz nie zawsze widać, ile energii pochłania samo filtrowanie bodźców, tłumaczenie sytuacji społecznych i uruchamianie codziennych zadań.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: koszt przetwarzania sensorycznego, proprioceptywnego i poznawczego jest wyższy niż u osoby neurotypowej — mózg pracuje ciężej przez każdą minutę. To jest stan wyjściowy (wgląd z 2026-03-31: odwrócona przyczynowość). WTÓRNA: maskowanie, kompensacja i chroniczne niedopasowanie środowiska NASILAJĄ zmęczenie dramatycznie. Ridcully jest zmęczony mniej — nie dlatego, że jego mózg pracuje lżej, ale dlatego, że nie dokłada warstwy maskowania.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> przewlekłe zmęczenie może wynikać z samego sposobu funkcjonowania, nie tylko z ''przesady''. Często to zmęczenie nie znika po jednym odpoczynku, bo jego źródłem jest długotrwały koszt funkcjonowania, a nie wyłącznie brak snu.</p><p><strong>Dla bliskich:</strong> odpoczynek bywa koniecznością biologiczną, nie luksusem. Czasem największą pomocą jest odjęcie części wymagań, a nie dodawanie kolejnych strategii produktywności.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R11, R8</p>\n</div>\n<div class="symptom">','\n',char(10)),'45. Fatigue with no bottom — research + clinical observation · widespread','This is not ordinary tiredness that disappears after a night''s sleep. It is systemic fatigue, arising from the fact that an AuDHD brain works harder than a neurotypical brain through every minute of the day.',NULL,NULL);
INSERT INTO content_sections VALUES(815,27,800,'heading',3,3,54,'46. Podwójne przetwarzanie rzeczywistości głównie obserwacja kliniczna / doświadczenie zróżnicowane','46-podwojne-przetwarzanie-rzeczywistosci','Ten punkt opisuje doświadczenie części osób, które mają poczucie, że przetwarzają sytuacje co najmniej na dwóch poziomach jednocześnie. Jeden poziom dotyczy faktów, struktury, sekwencji i tego, co da się logicznie uporządkować.',54,replace('<p>Ten punkt opisuje doświadczenie części osób, które mają poczucie, że przetwarzają sytuacje co najmniej na dwóch poziomach jednocześnie. Jeden poziom dotyczy faktów, struktury, sekwencji i tego, co da się logicznie uporządkować. Drugi dotyczy napięcia, atmosfery, niewypowiedzianych znaczeń i emocjonalnego tła. Problem polega na tym, że te dwa poziomy nie zawsze układają się w jedną spójną całość w tym samym czasie. W praktyce może to dawać zarówno trafne intuicje, jak i duże zmęczenie poznawcze, bo człowiek równocześnie „wie” i „nie jest pewny”, czy dobrze składa wszystkie elementy sytuacji.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Jednoczesne przetwarzanie wielu warstw sytuacji (fakt + atmosfera + niewypowiedziane) to cecha architektury poznawczej. Ridcully przetwarza wiele warstw, ale nie jest tego świadomy — wyciąga trafne wnioski ''znikąd''. To budowa, nie efekt doświadczeń.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> można równocześnie analizować kilka warstw sytuacji i od tego się męczyć. Jednoczesne trzymanie wielu warstw może dawać przenikliwość, ale też prowadzić do przeciążenia i poczucia nadmiaru.</p><p><strong>Dla bliskich:</strong> pomocne bywa upraszczanie kontekstu i doprecyzowywanie, co jest teraz najważniejsze. Warto wtedy pomagać porządkować, a nie jeszcze bardziej dociskać, bo nadmiar warstw może już sam w sobie być przytłaczający.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'46. Double processing of reality — mainly clinical observation / lived experience · variable','This point describes the experience of some people who feel that they process situations on at least two levels at once. One level concerns facts, structure, sequence, and what can be logically organised.',NULL,NULL);
INSERT INTO content_sections VALUES(816,27,800,'heading',3,3,55,'47. Poczucie, że się jest „za dużo" i „za mało" jednocześnie głównie obserwacja kliniczna / doświadczenie powszechne','47-poczucie-ze-sie-jest-za-duzo-i-za-malo-jednoczesnie','To jedno z najbardziej bolesnych doświadczeń, które łączy prawie wszystkie osoby AuDHD. „Za dużo" emocji, myśli, intensywności, słów, wrażliwości, reakcji, potrzeb. Za głośno, za mocno, za szczegółowo, za bezpośrednio.',55,replace('<p>To jedno z najbardziej bolesnych doświadczeń, które łączy prawie wszystkie osoby AuDHD. „Za dużo" emocji, myśli, intensywności, słów, wrażliwości, reakcji, potrzeb. Za głośno, za mocno, za szczegółowo, za bezpośrednio. „Za mało" energii, konsekwencji, „normalności", zdolności do utrzymania rutyny, zdolności do robienia „prostych" rzeczy, zdolności do bycia „łatwą" osobą. Przez całe życie te dwie wiadomości przychodzą jednocześnie: „jesteś za dużo" (za głośny, za emocjonalny, za intensywny, za dziwny) i „jesteś za mało" (za mało skupiony, za mało produktywny, za mało konsekwentny, za mało „dorosły"). To podwójne odrzucenie — nie pasujesz, bo jesteś za dużo, i nie pasujesz, bo jesteś za mało — jest fundamentalnym doświadczeniem AuDHD, które kształtuje poczucie własnej wartości od dzieciństwa.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Poczucie bycia ''za dużo'' i ''za mało'' jednocześnie jest CAŁKOWICIE wtórne. To efekt chronicznego odrzucania — przez dekady otoczenie komunikuje, że osoba jest jednocześnie zbyt intensywna i niewystarczająca. Ridcully nigdy nie słyszy tego komunikatu — bo otoczenie dostosowuje się do niego. On jest ''za dużo'' dla wszystkich i nikogo to nie obchodzi.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> to napięcie często wynika z chronicznego niedopasowania, nie z wadliwości. W środku zostaje wtedy bolesne wrażenie, że żadna wersja siebie nie jest wystarczająco „w sam raz”.</p><p><strong>Dla bliskich:</strong> mniej poprawiania, więcej uznania realnego wysiłku zwykle bardzo pomaga. Pomaga relacja, w której człowiek nie musi stale redukować siebie ani udowadniać, że nie jest „za trudny”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R15, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'47. Feeling “too much” and “not enough” at the same time — mainly clinical observation / lived experience · widespread','This is one of the most painful experiences shared by almost all people with AuDHD. “Too much” emotion, thought, intensity, words, sensitivity, reactions, needs. Too loud, too strong, too detailed, too direct.',NULL,NULL);
INSERT INTO content_sections VALUES(817,27,800,'heading',3,3,56,'48. Wewnętrzny „tłumacz" działający non-stop badania + obserwacja kliniczna powszechne','48-wewnetrzny-tlumacz-dzialajacy-non-stop','Osoby neurotypowe poruszają się po świecie społecznym w dużej mierze automatycznie — interpretacja mimiki, tonu głosu, kontekstu sytuacyjnego dzieje się poza świadomą uwagą, jak oddychanie. U osób AuDHD ten proces jest świadomy.',56,replace('<p>Osoby neurotypowe poruszają się po świecie społecznym w dużej mierze automatycznie — interpretacja mimiki, tonu głosu, kontekstu sytuacyjnego dzieje się poza świadomą uwagą, jak oddychanie. U osób AuDHD ten proces jest świadomy. Każda interakcja wymaga aktywnego dekodowania: co ta osoba miała na myśli? Czy to było sarkastyczne? Czy powinienem odpowiedzieć teraz czy poczekać? Czy moja odpowiedź była odpowiednia? Co znaczy ta mina? Jednocześnie osoba tłumaczy siebie dla świata: jak powiedzieć to, co myślę, w sposób, który będzie zrozumiały? Jak wyrazić emocje, których nie umiem nazwać? Jak ukryć to, co prawdopodobnie jest „dziwne"? To tłumaczenie symultaniczne, które nigdy się nie kończy — w pracy, w domu, w sklepie, w relacjach. To jest główne źródło chronicznego zmęczenia: nie sam kontakt z ludźmi jest wyczerpujący, ale ciągła praca tłumaczenia, która go towarzyszy.</p>\n<p class="small"><strong>Objaśnienie:</strong> „Wewnętrzny tłumacz” to dobre określenie kosztu stałego dekodowania świata i własnych reakcji. Ten proces może działać prawie bez przerwy, nawet jeśli z zewnątrz człowiek wygląda spokojnie.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Wewnętrzny tłumacz pracujący non-stop to mechanizm CAŁKOWICIE wtórny. Wynika z konieczności ciągłego dekodowania świata neurotypowego i tłumaczenia siebie na ''ich'' język. Ridcully nie tłumaczy — mówi swoim językiem i oczekuje, że inni się dostosują. Sam mechanizm dekodowania (trudność z automatycznym odczytywaniem) jest pierwotny, ale ciągła praca tłumaczenia to koszt wtórny.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ciągłe tłumaczenie świata i siebie kosztuje energię nawet wtedy, gdy z zewnątrz tego nie widać. Taki nieustanny przekład bywa tak automatyczny, że człowiek przestaje zauważać, ile energii zużywa na samo bycie w kontakcie.</p><p><strong>Dla bliskich:</strong> im mniej trzeba się ''przekładać'' na cudzy język, tym więcej zostaje siły na bycie w relacji. Mniej domysłów i więcej prostego mówienia wprost potrafi bardzo obniżyć koszt takiego codziennego tłumaczenia.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R9, R12</p>\n</div>\n<div class="symptom">','\n',char(10)),'48. An internal “translator” running non-stop — research + clinical observation · widespread','Neurotypical people move through the social world largely automatically: interpreting facial expressions, tone of voice, and situational context happens outside conscious attention, like breathing. For people with AuDHD, this process is conscious.',NULL,NULL);
INSERT INTO content_sections VALUES(818,27,800,'heading',3,3,57,'49. Nostalgia jako regulacja głównie obserwacja kliniczna / doświadczenie częste','49-nostalgia-jako-regulacja','Osoba AuDHD wraca do tych samych filmów, piosenek, gier, książek z dzieciństwa — nie z sentymentu (choć to też), ale z głębszego powodu.',57,replace('<p>Osoba AuDHD wraca do tych samych filmów, piosenek, gier, książek z dzieciństwa — nie z sentymentu (choć to też), ale z głębszego powodu. Znane bodźce są sensorycznie bezpieczne — mózg już je przetworzył, wie czego się spodziewać, nie ma ryzyka niespodzianki, przeciążenia ani rozczarowania. Nowe treści wymagają wysiłku przetwarzania: nowe bodźce sensoryczne, nowe wzorce fabularne, nowe postacie do zrozumienia, nowa muzyka do „osłuchania". To wszystko kosztuje energię. Stare treści dają ten sam komfort bez kosztu energetycznego — to jak włożenie wygodnego, rozciągniętego swetra, który idealnie pasuje, zamiast kupowania nowego, który może gryźć. Dlatego osoba AuDHD może po raz setny oglądać ten sam serial — i to nie jest „brak kreatywności". To aktywna regulacja systemu nerwowego za pomocą przewidywalnych, bezpiecznych bodźców.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Powrót do znanych bodźców jako regulacja sensoryczna wynika z właściwości systemu przetwarzania: znane bodźce są ''przetworzone'', nie wymagają nowego wysiłku, dają przewidywalność. Ridcully wraca do tych samych rytuałów, jedzenia, polowań. To samoregulacja, nie sentyment.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> powrót do znanych rzeczy może być regulacją, a nie cofaniem się. Znane rzeczy nie tylko uspokajają, ale też przywracają ciągłość własnego doświadczenia, gdy świat staje się zbyt rozproszony.</p><p><strong>Dla bliskich:</strong> warto szanować bezpieczne rytuały i znane treści jako element dbania o układ nerwowy. Nie trzeba tego od razu deprecjonować jako ucieczki; często to rozsądna i nieszkodliwa forma samoregulacji.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R10, R17</p>\n</div>\n<div class="symptom">','\n',char(10)),'49. Nostalgia as regulation — mainly clinical observation / lived experience · common','A person with AuDHD returns to the same films, songs, games, and childhood books, not merely out of sentimentality, although that can be part of it, but for a deeper reason.',NULL,NULL);
INSERT INTO content_sections VALUES(819,27,800,'heading',3,3,58,'50. Wewnętrzny monolog, który nigdy się nie wyłącza głównie obserwacja kliniczna / doświadczenie bardzo częste','50-wewnetrzny-monolog-ktory-nigdy-sie-nie-wylacza','Wewnętrzny monolog bywa u części osób z AuDHD bardzo intensywny: myśli, skojarzenia, rozmowy próbne, obrazy, plany i analizy mogą toczyć się niemal bez przerwy. Nie każda osoba opisze to tak samo, ale wiele mówi o poczuciu, że umysł rzadko naprawdę „milknie”.',58,replace('<p>Wewnętrzny monolog bywa u części osób z AuDHD bardzo intensywny: myśli, skojarzenia, rozmowy próbne, obrazy, plany i analizy mogą toczyć się niemal bez przerwy. Nie każda osoba opisze to tak samo, ale wiele mówi o poczuciu, że umysł rzadko naprawdę „milknie”. Taki ciągły ruch poznawczy może być twórczy i użyteczny, ale bywa też męczący, zwłaszcza wieczorem, przy przeciążeniu albo w sytuacjach, które uruchamiają analizowanie na wielu poziomach naraz. Z zewnątrz trudno to zobaczyć, bo człowiek może siedzieć nieruchomo, a wewnątrz wykonywać ogromną pracę poznawczą. To jedna z przyczyn, dla których zmęczenie psychiczne bywa duże nawet wtedy, gdy dzień nie wyglądał na szczególnie intensywny.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Intensywny, nieustający monolog wewnętrzny wynika z architektury poznawczej — myślenie asocjacyjne, wielopoziomowe, rzadko się wyłącza. To budowa, nie nawyk do ''nakręcania się''.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ciągły monolog wewnętrzny może męczyć nawet wtedy, gdy wygląda się na spokojnego. To męczy nawet wtedy, gdy myśli nie są dramatyczne — sam fakt ich stałej obecności może zabierać dużo energii.</p><p><strong>Dla bliskich:</strong> cisza zewnętrzna nie zawsze oznacza ciszę w środku. Zanim nazwiesz to „nakręcaniem się”, warto zobaczyć, czy dana osoba nie próbuje po prostu przetrwać nadmiaru we własnej głowie.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R4, R18, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'50. An internal monologue that never switches off — mainly clinical observation / lived experience · very common','For some people with AuDHD, the internal monologue can be extremely intense: thoughts, associations, rehearsal conversations, images, plans, and analyses may continue almost without interruption. Not everyone describes it in the same way, but many say that the mind rarely becomes truly “quiet”.',NULL,NULL);
INSERT INTO content_sections VALUES(820,27,800,'heading',3,3,59,'51. Poczucie, że czas działa inaczej badania + obserwacja kliniczna częste','51-poczucie-ze-czas-dziala-inaczej','Czas u osób AuDHD nie jest linearną, równomierną linią — jest raczej elastyczną substancją, która rozciąga się i kurczy. Godzina w hiperfokusie trwa subiektywnie pięć minut. Godzina w poczekalni u lekarza trwa subiektywnie trzy godziny.',59,replace('<p>Czas u osób AuDHD nie jest linearną, równomierną linią — jest raczej elastyczną substancją, która rozciąga się i kurczy. Godzina w hiperfokusie trwa subiektywnie pięć minut. Godzina w poczekalni u lekarza trwa subiektywnie trzy godziny. Przeszłość, teraźniejszość i przyszłość nie układają się w sekwencyjny porządek — raczej w coś na kształt chmury, w której wydarzenia z różnych okresów życia są „obok siebie", a nie „po kolei". Wspomnienie z dzieciństwa może być emocjonalnie tak samo żywe jak wczorajsze wydarzenie. Planowanie przyszłości jest trudne, bo przyszłość wydaje się abstrakcyjna i nierealna — to „kiedyś", które nie ma emocjonalnej wagi „teraz". To połączenie ADHD-owej ślepoty czasowej (mózg nie ma wewnętrznego zegara) z autystycznym monotropowym czasem (w „tunelu uwagi" czas zewnętrzny nie istnieje). W praktyce: spóźnianie się mimo szczerych intencji, poczucie że „dopiero co był styczeń, a teraz jest październik", trudność z realizowaniem długoterminowych planów, bo przyszłość nie „czuje się" realna.</p>\n<p class="small"><strong>Objaśnienie:</strong> Punkt o czasie jest mocno ludzki, ale ma też niezłe oparcie pośrednie przez ADHD-ową ślepotę czasową i nierówną regulację uwagi. W codzienności oznacza to często realne trudności z planowaniem, a nie tylko „słabe wyczucie”.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Atypowe odczuwanie czasu wynika z ADHD-owej ślepoty czasowej + monotropowego tunelu uwagi. Ridcully traci poczucie czasu w trakcie działania i nie wie, ile minęło. To neurobiologia, nie brak dyscypliny.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zaburzone poczucie czasu potrafi rozregulować cały dzień. W praktyce pomaga opieranie się bardziej na zewnętrznych kotwicach czasu niż na samym poczuciu, że „powinienem to wyczuć”.</p><p><strong>Dla bliskich:</strong> konkretne ramy, timery i punkty orientacyjne zwykle pomagają bardziej niż ogólne ponaglanie. Im bardziej konkretne są godziny, bufory i przypomnienia, tym mniej konfliktów bierze się z samego odmiennego czucia czasu.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R16, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'51. Feeling that time works differently — research + clinical observation · common','For people with AuDHD, time is not a linear, evenly moving line; it is more like an elastic substance that stretches and contracts. An hour in hyperfocus may feel like five minutes. An hour in a doctor''s waiting room may feel like three hours.',NULL,NULL);
INSERT INTO content_sections VALUES(821,27,800,'heading',3,3,60,'52. Kryzys tożsamości przy zmianie zainteresowań głównie obserwacja kliniczna / doświadczenie dość częste','52-kryzys-tozsamosci-przy-zmianie-zainteresowan','To doświadczenie jest głębsze niż „zmiana hobby". Osoby autystyczne często budują tożsamość wokół swoich zainteresowań specjalnych — „jestem osobą, która..." robi ceramikę / programuje / zna się na grzybach / gra na gitarze.',60,replace('<p>To doświadczenie jest głębsze niż „zmiana hobby". Osoby autystyczne często budują tożsamość wokół swoich zainteresowań specjalnych — „jestem osobą, która..." robi ceramikę / programuje / zna się na grzybach / gra na gitarze. Zainteresowanie nie jest dodatkiem do tożsamości — jest jej rdzeniem. Kiedy w AuDHD fascynacja przenosi się na nowy temat (bo ADHD-owa część mózgu potrzebuje nowości), to nie jest tylko zmiana aktywności — to mini-kryzys egzystencjalny. „Jeśli nie jestem już osobą, która robi ceramikę, to kim jestem?". To może wyjaśniać, dlaczego tak wielu dorosłych z AuDHD zmienia ścieżki kariery, kierunki studiów, hobby — nie z niestabilności, ale z desperackiego szukania odpowiedzi na pytanie „co jest naprawdę moje, a co jest tylko aktualną fascynacją?". Związane jest to z głębszą dyfuzją tożsamości wynikającą z chronicznego maskowania — warstwy adaptacji utrudniają dotarcie do „prawdziwego ja".</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Kryzys tożsamości przy zmianie zainteresowań wynika z faktu, że tożsamość była budowana wokół zainteresowań ZAMIAST wokół autentycznego ''ja'' — bo autentyczne ''ja'' było tłumione przez maskowanie. Ridcully zmienia zainteresowania i nie ma kryzysu tożsamości — bo nigdy nie musiał budować tożsamości na zainteresowaniach jako jedynym bezpiecznym fundamencie.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zmiana zainteresowań może poruszać głębiej niż sama treść hobby. Gdy zainteresowanie gaśnie, może chwilowo znikać także kawałek organizacji dnia, poczucia sensu i fragment tożsamości.</p><p><strong>Dla bliskich:</strong> nie warto lekceważyć żałoby po utracie ważnego obszaru tożsamości. Warto nie banalizować takiej zmiany, bo czasem dotyczy ona nie tylko hobby, ale też organizacji całego życia.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R9, R10</p>\n</div>\n<div class="symptom">','\n',char(10)),'52. Identity crisis when interests change — mainly clinical observation / lived experience · fairly common','This experience goes deeper than “changing hobbies”. Autistic people often build identity around special interests: “I am a person who…” makes ceramics / programs / knows about mushrooms / plays guitar.',NULL,NULL);
INSERT INTO content_sections VALUES(822,27,800,'heading',3,3,61,'53. Tęsknota za niepoznanym jeszcze sobą głównie obserwacja kliniczna / doświadczenie częste','53-tesknota-za-niepoznanym-jeszcze-soba','To poczucie, które trudno wytłumaczyć komuś, kto go nie doświadczył. Gdzieś pod warstwami maskowania, kompensacji, adaptacji i „grania roli" — jest prawdziwe „ja".',61,replace('<p>To poczucie, które trudno wytłumaczyć komuś, kto go nie doświadczył. Gdzieś pod warstwami maskowania, kompensacji, adaptacji i „grania roli" — jest prawdziwe „ja". Osoba wie, że ono istnieje, czuje je czasem — w krótkich momentach, zwykle w samotności, w nocy, przy jednej zaufanej osobie, w momencie głębokiego hiperfokusu. Ale kontakt z nim jest utrudniony, bo całe życie było poświęcone na budowanie „akceptowalnej wersji" siebie. Późna diagnoza AuDHD — a wiele dorosłych dowiaduje się o swoim AuDHD w trzeciej, czwartej czy piątej dekadzie życia — bywa momentem, w którym te warstwy zaczynają się odklejać. To może być jednocześnie wyzwalające i przerażające: wyzwalające, bo wreszcie jest wyjaśnienie; przerażające, bo pod warstwami adaptacji może nie być jeszcze gotowego „prawdziwego ja" — jest dopiero przestrzeń, w której można zacząć je odkrywać.</p>\n<p class="small"><strong>Objaśnienie:</strong> Ten punkt nie jest klasyczną cechą w sensie diagnostycznym. Bardziej opisuje skutek wieloletniego życia w maskowaniu, niezrozumieniu i próbach dopasowania się do norm, które były zbyt kosztowne.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Tęsknota za niepoznanym sobą to efekt WIELOLETNIEGO maskowania. Pod warstwami adaptacji brak gotowego ''prawdziwego ja'', bo całe życie było poświęcone budowaniu akceptowalnej wersji. Ridcully nie tęskni za sobą — bo nigdy się nie stracił. On jest sobą od pierwszej minuty.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> takie uczucie bywa częścią odzyskiwania siebie po latach adaptacji. Po późnej diagnozie ta tęsknota bywa połączona z ulgą, żalem i próbą odzyskania własnego języka dla dawnych doświadczeń.</p><p><strong>Dla bliskich:</strong> najlepiej pomaga ciekawość i miejsce na opowiedzenie tej historii bez poprawiania. Najczęściej nie trzeba tego od razu rozwiązywać; samo uważne wysłuchanie bywa tu bardzo ważne.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R10, R15</p>\n</div>\n<div class="symptom">','\n',char(10)),'53. Longing for a self you have not yet met — mainly clinical observation / lived experience · common','This feeling is difficult to explain to someone who has never experienced it. Somewhere beneath layers of masking, compensation, adaptation, and “playing a role” there is a real “self”.',NULL,NULL);
INSERT INTO content_sections VALUES(823,27,800,'heading',3,3,62,'54. Zbieranie informacji „na zapas" badania + obserwacja kliniczna częste','54-zbieranie-informacji-na-zapas','Setki otwartych zakładek w przeglądarce. Dziesiątki zapisanych artykułów „do przeczytania". Pliki na dysku o tematach, które „mogą się kiedyś przydać". Kursy online, których nikt nie ukończy, ale sam fakt posiadania dostępu daje komfort.',62,replace('<p>Setki otwartych zakładek w przeglądarce. Dziesiątki zapisanych artykułów „do przeczytania". Pliki na dysku o tematach, które „mogą się kiedyś przydać". Kursy online, których nikt nie ukończy, ale sam fakt posiadania dostępu daje komfort. To połączenie autystycznej potrzeby kompletności (jeśli poznaję temat, to muszę poznać go w pełni) z ADHD-owym skakaniem po tematach (każda nowa informacja ciągnie za sobą pięć kolejnych) i głębszego mechanizmu kontroli — w świecie, który jest sensorycznie i społecznie nieprzewidywalny, posiadanie informacji daje poczucie bezpieczeństwa. „Nie wiem, kiedy mi się to przyda, ale jak będę potrzebować, to będę mieć". To nie jest cyfrowe zagracanie — to tworzenie wewnętrznej biblioteki bezpieczeństwa.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: potrzeba kompletności (autyzm) + skakanie po tematach (ADHD) = gromadzenie informacji. WTÓRNA: funkcja bezpieczeństwa (''będę przygotowany'') nasila się przez lata życia w nieprzewidywalnym świecie, w którym osoba bywała zaskakiwana i bezradna. Ridcully zbiera informacje z ciekawości, nie z lęku przed nieprzygotowaniem.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zbieranie informacji może dawać poczucie bezpieczeństwa i przewidywalności. To często ma funkcję ochronną: lepiej wiedzieć za dużo niż znów zostać zaskoczonym, nieprzygotowanym albo bezradnym.</p><p><strong>Dla bliskich:</strong> nie wszystko trzeba od razu uznawać za ''przesadę'' czy ''obsesję''. Nie zawsze jest to „przesada informacyjna”; często to próba zbudowania zapasu bezpieczeństwa na przyszłość.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18, R19</p>\n</div>\n<div class="symptom">','\n',char(10)),'54. Collecting information “for later” — research + clinical observation · common','Hundreds of open browser tabs. Dozens of saved articles “to read”. Files on disk about subjects that “may come in useful someday”. Online courses nobody will finish, but simply having access to them provides comfort.',NULL,NULL);
INSERT INTO content_sections VALUES(824,27,800,'heading',3,3,63,'55. Specyficzny humor głównie obserwacja kliniczna / doświadczenie częste','55-specyficzny-humor','Humor osób z AuDHD bywa często oparty na mechanizmach, które wymagają nietypowego stylu przetwarzania: grze słów, dosłownym odczytaniu metafory, nieoczekiwanym skojarzeniu, absurdzie doprowadzonym do logicznej skrajności, niszowych odniesieniach albo…',63,replace('<p>Humor osób z AuDHD bywa często oparty na mechanizmach, które wymagają nietypowego stylu przetwarzania: grze słów, dosłownym odczytaniu metafory, nieoczekiwanym skojarzeniu, absurdzie doprowadzonym do logicznej skrajności, niszowych odniesieniach albo wielowarstwowości. Taki żart bywa zrozumiały dopiero wtedy, gdy druga osoba zna podobny kontekst i porusza się po podobnych skojarzeniach. Osoby z AuDHD często bawią się językiem w sposób, który wykracza poza standardowe wyobrażenie humoru, bo ich myślenie asocjacyjne produkuje połączenia, których wiele osób neurotypowych zwykle nie tworzy w ten sam sposób. Efekt bywa prosty: żart nie działa w jednym otoczeniu, a w innym wywołuje natychmiastowe porozumienie i śmiech. To mały, codzienny przykład problemu podwójnej empatii: nie chodzi o to, że humor jest „dziwny”, tylko o to, że potrzebuje wspólnego kodu, by zadziałał.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Specyficzny humor oparty na grze słów, absurdzie, dosłowności i nietypowych skojarzeniach wynika z asocjacyjnego myślenia i bottom-up przetwarzania. Ridcully jest zabawny w sposób, którego nikt nie rozumie — dokładnie ten sam mechanizm.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> własny humor może być sposobem łączenia się z ludźmi, którzy podobnie myślą. Dla osoby ten humor bywa naturalny i precyzyjny, nawet jeśli otoczenie nie zawsze łapie wszystkie warstwy i skojarzenia.</p><p><strong>Dla bliskich:</strong> niezrozumiały żart nie musi być złośliwością ani dziwactwem dla efektu. Śmiech może przyjść z innego miejsca i w innym rytmie — niekoniecznie mniej, tylko inaczej.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13</p>\n</div>\n<div class="symptom">','\n',char(10)),'55. A distinctive sense of humour — mainly clinical observation / lived experience · common','AuDHD humour is often based on mechanisms that require an atypical processing style: wordplay, literal readings of metaphor, unexpected associations, absurdity carried to its logical extreme, niche references, or…',NULL,NULL);
INSERT INTO content_sections VALUES(825,27,800,'heading',3,3,64,'56. Nadmierne tłumaczenie się i przepraszanie za istnienie głównie obserwacja kliniczna / doświadczenie bardzo częste','56-nadmierne-tlumaczenie-sie-i-przepraszanie-za-istnienie','„Przepraszam, że pytam". „Przepraszam, że przeszkadzam". „Przepraszam, że tak dużo mówię". „Przepraszam, że…" — kompulsywne przepraszanie za rzeczy, które nie wymagają przeprosin.',64,replace('<p>„Przepraszam, że pytam". „Przepraszam, że przeszkadzam". „Przepraszam, że tak dużo mówię". „Przepraszam, że…" — kompulsywne przepraszanie za rzeczy, które nie wymagają przeprosin. Do tego dochodzi potrzeba wyjaśniania kontekstu, motywacji i logiki każdej decyzji — nie dlatego, że osoba jest niepewna, ale dlatego że zakłada (często słusznie, z doświadczenia), że jej tok rozumowania nie jest oczywisty dla rozmówcy. Skąd to się bierze? Z lat otrzymywania komunikatów — jawnych i niejawnych — że się jest „za dużo", „za mało", „dziwnym", „trudnym", „niezrozumiałym". Po latach takich komunikatów samo istnienie — własne potrzeby, emocje, sposób bycia — zaczyna wydawać się czymś, za co trzeba przepraszać. To nie jest niska samoocena w klasycznym sensie. To wyuczona reakcja na świat, który konsekwentnie komunikował, że bycie sobą jest problemem.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Nadmierne przepraszanie i tłumaczenie się to efekt CAŁKOWICIE wtórny. Wynika z lat komunikatów ''jesteś za dużo / za dziwnie / za trudno''. Ridcully NIGDY nie przeprasza — nie dlatego, że jest arogancki, ale dlatego, że nikt nigdy nie nauczył go, że jego sposób bycia jest problemem.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> nadmierne przepraszanie często jest śladem wcześniejszych doświadczeń, nie prawdą o własnej wartości. Po czasie taki styl staje się niemal odruchowy i człowiek przeprasza nawet wtedy, gdy obiektywnie nic złego nie zrobił.</p><p><strong>Dla bliskich:</strong> spokojne przyjmowanie obecności bez ciągłego poprawiania może być bardzo odciążające i leczące. Najbardziej pomaga środowisko, w którym człowiek nie musi z góry zakładać, że jego obecność jest problemem.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R8, R10, R15</p>\n</div>\n<div class="symptom">','\n',char(10)),'56. Over-explaining yourself and apologising for existing — mainly clinical observation / lived experience · very common','“Sorry for asking.” “Sorry to bother you.” “Sorry I talk so much.” “Sorry that…” — compulsive apologising for things that require no apology.',NULL,NULL);
INSERT INTO content_sections VALUES(826,27,800,'heading',3,3,65,'57. Wykonywanie zadań „nie po kolei" głównie obserwacja kliniczna / doświadczenie częste','57-wykonywanie-zadan-nie-po-kolei','Zmywanie naczyń, ale zaczynanie od łyżeczek, bo mają najprzyjemniejszą fakturę. Sprzątanie pokoju, ale zaczynanie od segregowania książek według koloru. Pisanie raportu od trzeciego akapitu, bo ten jest najciekawszy.',65,replace('<p>Zmywanie naczyń, ale zaczynanie od łyżeczek, bo mają najprzyjemniejszą fakturę. Sprzątanie pokoju, ale zaczynanie od segregowania książek według koloru. Pisanie raportu od trzeciego akapitu, bo ten jest najciekawszy. Z zewnątrz wygląda to na nieefektywność, dezorganizację, może nawet unikanie „właściwej" pracy. Ale wewnętrznie ma głęboki sens. Mózg AuDHD potrzebuje sensorycznie lub emocjonalnie „łatwego wejścia" w zadanie — czegoś, co da minimalną satysfakcję lub komfort sensoryczny, żeby w ogóle uruchomić działanie. To jest jak rozgrzewka — nie da się wejść na bieżnię i natychmiast biec sprint. Mózg potrzebuje „rozbiegu", a rozbiegiem jest ten element zadania, który jest sensorycznie lub emocjonalnie przystępny. Problem polega na tym, że świat oczekuje „właściwej kolejności" — od najważniejszego, od początku, od tego, co trzeba. A mózg AuDHD działa od tego, co jest dostępne.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Robienie zadań ''nie po kolei'' wynika z tego, że mózg startuje od elementu sensorycznie lub emocjonalnie dostępnego, a nie od tego, który jest ''logicznie pierwszy''. Ridcully robi rzeczy w swojej kolejności — i nikt tego nie koryguje. To budowa przetwarzania, nie brak organizacji.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> wejście do zadania bokiem bywa realną strategią działania. Taki tryb często realnie pomaga ruszyć z miejsca, nawet jeśli z zewnątrz wygląda mniej elegancko niż klasyczna sekwencja.</p><p><strong>Dla bliskich:</strong> czasem ważniejsze jest, że zadanie ruszyło, niż że ruszyło ''we właściwej kolejności''. Czasem warto oceniać efekt i sens działania, a nie tylko to, czy kolejność była podręcznikowa.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R2, R18</p>\n</div>\n<div class="symptom">','\n',char(10)),'57. Doing tasks “out of order” — mainly clinical observation / lived experience · common','Washing dishes but starting with teaspoons because they have the most pleasant texture. Cleaning a room but beginning by sorting books by colour. Writing a report from the third paragraph because that one is the most interesting.',NULL,NULL);
INSERT INTO content_sections VALUES(827,27,800,'heading',3,3,66,'58. Poczucie „udawania dorosłego" głównie obserwacja kliniczna / doświadczenie bardzo częste','58-poczucie-udawania-doroslego','Osoby w tym samym wieku wydają się wiedzieć, jak się żyje — jak płacić rachunki na czas, umówić się do lekarza, utrzymać porządek, robić zakupy regularnie, zarządzać finansami, utrzymywać przyjaźnie.',66,replace('<p>Osoby w tym samym wieku wydają się wiedzieć, jak się żyje — jak płacić rachunki na czas, umówić się do lekarza, utrzymać porządek, robić zakupy regularnie, zarządzać finansami, utrzymywać przyjaźnie. Wydaje się, że mają jakiś wewnętrzny „autopilot", który prowadzi ich przez dorosłość. Osoba AuDHD robi te same rzeczy — ale każda z nich wymaga świadomego wysiłku i planowania, jakby tego autopilota nie było. „Umówić się do lekarza" to nie jedno proste zadanie — to: znaleźć numer, zadzwonić (pokonując lęk przed telefonem), wytłumaczyć, o co chodzi (dekodowanie społeczne), zapamiętać datę (pamięć robocza), nie zapomnieć iść (funkcje wykonawcze), poradzić sobie z poczekalnią (sensoryka), opisać objawy lekarzowi (aleksytymia), wrócić do domu i się z tego zregenerować (przeciążenie). Każdy z tych kroków wymaga zasobów, które u osób neurotypowych są automatyczne. To nie jest „syndrom oszusta" w zwykłym sensie — to realne doświadczenie życia bez autopilota w świecie, który zakłada, że wszyscy go mają.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Poczucie ''udawania dorosłego'' to efekt wtórny. PIERWOTNY jest brak automatyzmu funkcji wykonawczych — ale WTÓRNE jest poczucie, że jest się gorszym dorosłym. To porównywanie siebie do neurotypowej normy, która nie pasuje. Ridcully nie czuje się ''niedorosły'' — bo nikt nie oczekuje od niego neurotypowej dorosłości.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> poczucie udawania dorosłości często wynika z braku automatyzmu codziennych rzeczy. To bywa szczególnie bolesne, gdy otoczenie widzi tylko efekt końcowy, a nie ogrom ręcznej pracy potrzebnej do jego uzyskania.</p><p><strong>Dla bliskich:</strong> sprawność w jednej dziedzinie nie oznacza łatwości w całej dorosłości. Dobrze pamiętać, że z zewnątrz często widać dorosły rezultat, a nie cenę psychiczną jego utrzymania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R16, R20, R10</p>\n</div>\n<div class="symptom">','\n',char(10)),'58. Feeling like you are “pretending to be an adult” — mainly clinical observation / lived experience · very common','People of the same age seem to know how life works: how to pay bills on time, make a doctor''s appointment, keep things tidy, shop regularly, manage finances, maintain friendships.',NULL,NULL);
INSERT INTO content_sections VALUES(828,27,800,'heading',3,3,67,'59. Underachievement, który boli badania + obserwacja kliniczna częste','59-underachievement-ktory-boli','Poczucie, że ma się potencjał, którego nie potrafi się zrealizować. Osoba wie, że jest inteligentna — widzi wzorce, rozumie złożone systemy, ma głębokie, oryginalne przemyślenia.',67,replace('<p>Poczucie, że ma się potencjał, którego nie potrafi się zrealizować. Osoba wie, że jest inteligentna — widzi wzorce, rozumie złożone systemy, ma głębokie, oryginalne przemyślenia. Ale tłumaczenie tego potencjału na „produktywność" w formacie, którego oczekuje świat (punktualność, konsekwencja, systematyczność, hierarchiczne struktury), jest nieproporcjonalnie trudne. Otoczenie mówi „gdybyś się postarał" — a osoba stara się trzy razy mocniej niż inni, żeby osiągnąć połowę tego samego wyniku. To prowadzi do jednego z najbardziej bolesnych aspektów AuDHD: chronicznej rozbieżności między tym, co osoba wie, że potrafi, a tym, co potrafi pokazać światu. Zmienianie ścieżek kariery, porzucanie studiów, niestabilność zawodowa — nie wynikają z braku zdolności, ale z desperackiego szukania środowiska, w którym format „produktywności" pasuje do sposobu, w jaki mózg naprawdę działa. Wielu osobom AuDHD zajmuje to połowę życia.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: rozjazd między potencjałem a wykonalnością wynika z deficytów wykonawczych. WTÓRNA: ból underachievementu wynika z tego, że świat mierzy ''osiągnięcia'' w neurotypowym formacie (punktualność, konsekwencja, liniowa kariera). Ridcully jest ''underachiever'' w pewnym sensie (mógłby być genialnym magiem, gdyby się skupił), ale nie boli go to — bo jego środowisko nie wymaga neurotypowego formatu.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> ból underachievementu często wynika z rozjazdu między potencjałem a wykonalnością. Najbardziej boli zwykle nie sam wynik, tylko świadomość, ile rzeczy było możliwych, a ile regularnie rozpadało się po drodze.</p><p><strong>Dla bliskich:</strong> zawód warto kierować w stronę systemu i dopasowania, nie w stronę zawstydzania osoby. Wsparcie zwykle lepiej działa przez realne odciążenie i dostosowanie warunków niż przez odwoływanie się do „zmarnowanego talentu”.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R16, R19, R20</p>\n</div>\n<div class="symptom">','\n',char(10)),'59. Underachievement that hurts — research + clinical observation · common','The feeling of having potential you cannot turn into reality. The person knows they are intelligent: they see patterns, understand complex systems, and have deep, original thoughts.',NULL,NULL);
INSERT INTO content_sections VALUES(829,27,800,'heading',3,3,68,'60. Potrzeba rozumienia „dlaczego" przed zrobieniem czegokolwiek badania + obserwacja kliniczna bardzo częste','60-potrzeba-rozumienia-dlaczego-przed-zrobieniem-czegokolwiek','„Po prostu to zrób" nie działa. Nie z przekory, nie z lenistwa, nie z potrzeby kontroli. Mózg, który przetwarza świat „od dołu do góry", potrzebuje kontekstu, żeby umieścić zadanie w większej strukturze.',68,replace('<p>„Po prostu to zrób" nie działa. Nie z przekory, nie z lenistwa, nie z potrzeby kontroli. Mózg, który przetwarza świat „od dołu do góry", potrzebuje kontekstu, żeby umieścić zadanie w większej strukturze. Bez zrozumienia „dlaczego" i „po co" — nie ma na czym zaczepić uwagi. To jak próba ułożenia elementu puzzli, kiedy nie wiesz, jaki jest obrazek — nawet jeśli masz odpowiedni kawałek, nie wiesz, gdzie go włożyć. Jednocześnie ADHD sprawia, że zbieranie kontekstu jest frustrująco powolne w porównaniu z wewnętrzną potrzebą natychmiastowego działania. Efekt: albo paraliż (mózg czeka na kontekst, którego jeszcze nie ma), albo działanie bez zrozumienia (impuls ADHD wyprzedza autystyczne przetwarzanie), po którym następuje analiza i żal. Ludzie, którzy pracują z osobami AuDHD, zauważają: kiedy wyjaśnisz „dlaczego" — motywacja i jakość pracy wzrastają skokowo. Kiedy mówisz „bo tak trzeba" — blokada.</p>\n<div class="origin origin-primary"><strong>PIERWOTNA — z budowy.</strong> Potrzeba rozumienia ''dlaczego'' przed działaniem wynika z przetwarzania bottom-up — mózg potrzebuje kontekstu, żeby umieścić zadanie w strukturze. Ridcully pyta ''po co?'' zanim cokolwiek zrobi, i nie rusza się, jeśli nie ma sensu. To budowa, nie przekora.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> zrozumienie sensu zadania może być warunkiem uruchomienia, nie luksusem. Gdy sens jest jasny, spada opór i rośnie dostęp do energii, bo zadanie przestaje być czystym zewnętrznym wymaganiem.</p><p><strong>Dla bliskich:</strong> krótkie wyjaśnienie ''po co'' często daje więcej niż samo polecenie. Wyjaśnienie sensu nie jest tu zbędnym dodatkiem; dla wielu osób jest warunkiem uruchomienia działania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R18, R2</p>\n</div>\n<div class="symptom">','\n',char(10)),'60. Needing to understand “why” before doing anything — research + clinical observation · very common','“Just do it” does not work. Not out of defiance, laziness, or a need for control. A brain that processes the world bottom-up needs context in order to place a task inside a larger structure.',NULL,NULL);
INSERT INTO content_sections VALUES(830,27,800,'heading',3,3,69,'61. Poczucie „bycia z innej planety" badania + obserwacja kliniczna powszechne','61-poczucie-bycia-z-innej-planety','To poczucie inności, które towarzyszy większości osób AuDHD od najwcześniejszych wspomnień — zanim miały na to jakiekolwiek słowa. Nie chodzi o poczucie „bycia gorszym" (choć to może towarzyszyć).',69,replace('<p>To poczucie inności, które towarzyszy większości osób AuDHD od najwcześniejszych wspomnień — zanim miały na to jakiekolwiek słowa. Nie chodzi o poczucie „bycia gorszym" (choć to może towarzyszyć). Chodzi o fundamentalne poczucie, że inni ludzie komunikują się w języku, który musisz się uczyć, podczas gdy dla nich jest on naturalny. Naukowiec Damian Milton opisał to jako „Problem Podwójnej Empatii" — trudności w komunikacji między osobami o różnych neurotypach nie wynikają z deficytu po jednej stronie, ale ze wzajemnego niezrozumienia. To jak spotkanie dwóch osób mówiących różnymi językami — obie potrafią się komunikować, ale nie ze sobą. Badania potwierdzają coś, co osoby autystyczne wiedzą intuicyjnie: komunikacja między dwiema osobami autystycznymi jest równie efektywna jak między dwiema osobami neurotypowymi. To komunikacja między neurotypami jest trudna — i to dla obu stron. Dlatego tak wiele osób AuDHD czuje ulgę i głębokie „wreszcie ktoś mnie rozumie", trafiając do neurodywergentnej społeczności.</p>\n<div class="origin origin-mixed"><strong>PIERWOTNA + wtórne nasilenie.</strong> PIERWOTNA: inny styl przetwarzania = inna perspektywa na świat. WTÓRNA: poczucie ''bycia z innej planety'' to efekt lat chronicznego niezrozumienia i othering''u. Ridcully jest z innej planety — ale nie wie o tym, bo otoczenie nigdy mu tego nie powiedziało. Jego ''inność'' jest po prostu ''sposobem, w jaki jest nadrektor''.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> poczucie obcości może słabnąć, gdy trafia się na ludzi mówiących podobnym językiem doświadczenia. Ulga często pojawia się dopiero wtedy, gdy trafia się na ludzi, przy których nie trzeba nieustannie tłumaczyć podstaw własnego działania.</p><p><strong>Dla bliskich:</strong> celem nie zawsze jest ''naprawa'', czasem wystarczy lepsze wzajemne dostrojenie. Często to nie człowiek jest „zły w relacjach”, tylko relacja nie daje wystarczającego wzajemnego tłumaczenia i dopasowania.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R13, R15</p>\n</div>\n<div class="symptom">','\n',char(10)),'61. Feeling like you are “from another planet” — research + clinical observation · widespread','A sense of being different accompanies most people with AuDHD from their earliest memories, before they had any words for it. This is not necessarily a sense of “being worse”, although that can accompany it.',NULL,NULL);
INSERT INTO content_sections VALUES(831,27,800,'heading',3,3,70,'62. Głęboka potrzeba bycia zrozumianym, nie naprawionym głównie obserwacja kliniczna / doświadczenie powszechne','62-gleboka-potrzeba-bycia-zrozumianym-nie-naprawionym','Ten ostatni punkt nie opisuje pojedynczej cechy w ścisłym sensie. Bardziej zbiera to, do czego prowadzą wcześniejsze obserwacje: wiele osób z AuDHD po latach zawstydzania, ciągłego poprawiania i prób dopasowania najbardziej potrzebuje nie kolejnych rad, tylko…',70,replace('<p>Ten ostatni punkt nie opisuje pojedynczej cechy w ścisłym sensie. Bardziej zbiera to, do czego prowadzą wcześniejsze obserwacje: wiele osób z AuDHD po latach zawstydzania, ciągłego poprawiania i prób dopasowania najbardziej potrzebuje nie kolejnych rad, tylko trafnego zrozumienia własnego sposobu działania. Dla części osób dopiero na takim gruncie strategie, leczenie, organizacja życia czy wsparcie relacyjne zaczynają mieć realny sens. Bez tego nawet dobre rady mogą brzmieć jak kolejna próba przerobienia człowieka na bardziej akceptowalny format. Dlatego tak ważne bywa nie tylko nazywanie trudności, ale też rozumienie sensu, jaki te doświadczenia mają w codziennym życiu danej osoby.</p>\n<p class="small"><strong>Objaśnienie:</strong> Ten punkt zostaje na końcu nie dlatego, że jest „najbardziej naukowy”, lecz dlatego, że porządkuje całość w sposób praktyczny i ludzki. Pomaga zobaczyć, że celem nie jest udowodnienie, jak bardzo ktoś odbiega od normy, tylko lepsze zrozumienie, jak działa i czego realnie potrzebuje.</p>\n<div class="origin origin-secondary"><strong>WTÓRNA — z nacisku.</strong> Potrzeba bycia zrozumianym, nie naprawionym, jest CAŁKOWICIE wtórna. Wynika z lat poprawiania, korygowania i prób przerobienia na ''normalniejszy'' format. Ridcully nie potrzebuje bycia zrozumianym — bo nigdy nie był systematycznie ''naprawiany''. To cecha ludzi, którzy przeszli przez maszynkę normalizacji.</div>\n<div class="practice"><strong>W praktyce:</strong><p><strong>Dla samej osoby:</strong> potrzeba bycia rozumianym jest często bardziej podstawowa niż potrzeba kolejnych rad. Dopiero na tym gruncie rady, strategie i zmiana mają szansę zostać naprawdę przyjęte, a nie odebrane jako kolejna próba poprawiania człowieka.</p><p><strong>Dla bliskich:</strong> zanim pojawią się rozwiązania, dobrze najpierw pokazać, że naprawdę się słyszy i rozumie. Dopiero po doświadczeniu zrozumienia łatwiej przyjąć pomoc bez poczucia, że znowu ktoś próbuje człowieka przerobić na inny format.</p></div><p class="refs"><strong>Najbliższe źródła:</strong> R12, R10, R20</p>\n</div>','\n',char(10)),'62. A deep need to be understood, not fixed — mainly clinical observation / lived experience · widespread','This final point does not describe a single feature in the strict sense. Rather, it gathers what the earlier observations lead to: after years of shaming, constant correction, and pressure to fit in, many people with AuDHD need not more advice, but…',NULL,NULL);
INSERT INTO content_sections VALUES(832,27,762,'heading',2,2,71,'Uwagi końcowe','uwagi-koncowe','Jeżeli czytasz ten materiał po raz pierwszy, najważniejsze jest jedno: AuDHD nie oznacza po prostu „trochę autyzmu i trochę ADHD”.',71,replace('<p>Jeżeli czytasz ten materiał po raz pierwszy, najważniejsze jest jedno: AuDHD nie oznacza po prostu „trochę autyzmu i trochę ADHD”. W praktyce często oznacza bardzo nierówny profil funkcjonowania — dużo możliwości w jednych obszarach i duży koszt codzienności w innych. To właśnie ta nierówność bywa najbardziej myląca zarówno dla samej osoby, jak i dla jej otoczenia.</p><p>Najmocniej naukowo stoją w tym opracowaniu tematy takie jak funkcje wykonawcze, sensoryka, sen, dysregulacja emocjonalna, aleksytymia, masking, wypalenie i ogólny koszt funkcjonalny współwystępowania autyzmu i ADHD. Słabiej opisane, ale często bardzo trafne klinicznie i ludzko, są punkty dotyczące tożsamości, sposobu okazywania bliskości, przeżywania odrzucenia czy subtelnych form samoregulacji.</p><p>Najuczciwiej czytać ten dokument nie jak listę „cech do odhaczenia”, tylko jak mapę możliwych doświadczeń. Czasem jeden punkt daje komuś natychmiastowe poczucie ulgi, bo wreszcie nazywa coś ważnego. Innym razem dopiero kilka punktów razem pokazuje sens wcześniej porozrzucanych trudności. To, co ma tu największą wartość, to połączenie dwóch perspektyw: rzetelności wobec badań i szacunku wobec ludzkiego doświadczenia.</p>\n<div class="footer"><p>Wersja 4.5 opracowana z pomocą ChatGPT — model GPT-5.4 Thinking.</p><p>Wersja 5.1 (klasyfikacja pierwotna/wtórna + nota o dorosłych) opracowana z pomocą Claude — model Claude Opus 4.6 (Anthropic).</p><p>Wersja dokumentu 6.0 | Data: 2026-07-01, godz. 15:21 CEST.</p><p>Dokument łączy materiał naukowo ostrożny z objaśnieniami praktycznymi, tak aby był czytelny także dla osoby, która trafia na temat po raz pierwszy.</p><p><strong>v6.0 (2026-07-01):</strong> nowe formatowanie pod telefon &mdash; usunięte ramki wokół cech i pionowe kreski, płaska typografia; dodany spis treści z anchorami tekstowymi; ujednolicona wersja. Klasyfikacja pochodzenia (pierwotna / wtórna / mieszana) oraz treść cech bez zmian merytorycznych. Aktualizacja z pomocą Claude Opus 4.8 (Anthropic).</p></div>\n</main>','\n',char(10)),'Final notes','If you are reading this material for the first time, the most important point is this: AuDHD does not simply mean “a bit of autism and a bit of ADHD”.',NULL,NULL);
INSERT INTO content_sections VALUES(833,27,762,'heading',2,2,72,'Bibliografia główna','bibliografia-glowna','Część źródeł najlepiej podpiera cały obraz AuDHD, część lepiej podpiera konkretne punkty. Przy punktach bardziej doświadczeniowych dobierałem źródła najbliższe tematowi, zamiast udawać, że istnieje idealny artykuł dokładnie o danym sformułowaniu.',72,replace('<div class="sourcesbox"><p>Część źródeł najlepiej podpiera cały obraz AuDHD, część lepiej podpiera konkretne punkty. Przy punktach bardziej doświadczeniowych dobierałem źródła najbliższe tematowi, zamiast udawać, że istnieje idealny artykuł dokładnie o danym sformułowaniu.</p><ul>\n<li><strong>R1</strong>. Hours C, Recasens C, Baleyte JM. ASD and ADHD Comorbidity: What Are We Talking About? Frontiers in Psychiatry, 2022.<br/>Link: <a href="https://www.frontiersin.org/journals/psychiatry/articles/10.3389/fpsyt.2022.837424/full">https://www.frontiersin.org/journals/psychiatry/articles/10.3389/fpsyt.2022.837424/full</a></li>\n<li><strong>R2</strong>. Craig F i wsp. A review of executive function deficits in autism spectrum disorder and attention-deficit/hyperactivity disorder. Neuropsychiatric Disease and Treatment, 2016.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4869784/">https://pmc.ncbi.nlm.nih.gov/articles/PMC4869784/</a></li>\n<li><strong>R3</strong>. Pozo-Rodríguez M i wsp. A systematic review on the association between executive function and emotional regulation in autism, ADHD, and autism/ADHD. Neuroscience &amp; Biobehavioral Reviews, 2026.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/41579913/">https://pubmed.ncbi.nlm.nih.gov/41579913/</a></li>\n<li><strong>R4</strong>. Lugo J i wsp. Sleep in adults with autism spectrum disorder and attention deficit/hyperactivity disorder: A systematic review and meta-analysis. Neuroscience &amp; Biobehavioral Reviews, 2020.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/32712061/">https://pubmed.ncbi.nlm.nih.gov/32712061/</a></li>\n<li><strong>R5</strong>. Williams ZJ i wsp. Characterizing Interoceptive Differences in Autism: A Systematic Review and Meta-analysis. Neuroscience &amp; Biobehavioral Reviews, 2022.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9832174/">https://pmc.ncbi.nlm.nih.gov/articles/PMC9832174/</a></li>\n<li><strong>R6</strong>. Klein M i wsp. Interoception in individuals with autism spectrum disorder: A systematic review and meta-analysis, 2025.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12406136/">https://pmc.ncbi.nlm.nih.gov/articles/PMC12406136/</a></li>\n<li><strong>R7</strong>. Kinnaird E i wsp. Investigating alexithymia in autism: A systematic review and meta-analysis. European Psychiatry, 2019.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6331035/">https://pmc.ncbi.nlm.nih.gov/articles/PMC6331035/</a></li>\n<li><strong>R8</strong>. Cook J i wsp. Camouflaging in autism: A systematic review. Clinical Psychology Review, 2021.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/34563942/">https://pubmed.ncbi.nlm.nih.gov/34563942/</a></li>\n<li><strong>R9</strong>. Klein J i wsp. A systematic review of social camouflaging in autistic youth and adults, 2025.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/39370528/">https://pubmed.ncbi.nlm.nih.gov/39370528/</a></li>\n<li><strong>R10</strong>. Ali D i wsp. Burnout as experienced by autistic people: A systematic review. Autism, 2025/2026 indexing.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/41207162/">https://pubmed.ncbi.nlm.nih.gov/41207162/</a></li>\n<li><strong>R11</strong>. Bougoure M i wsp. Measuring autistic burnout: A psychometric validation of the AASPIRE Autistic Burnout Measure, 2025.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12717295/">https://pmc.ncbi.nlm.nih.gov/articles/PMC12717295/</a></li>\n<li><strong>R12</strong>. Brosnan M, Gillespie-Lynch K. Neuro-affirmative support for autism, the Double Empathy Problem and contemporary care. Frontiers in Psychiatry, 2025.<br/>Link: <a href="https://www.frontiersin.org/journals/psychiatry/articles/10.3389/fpsyt.2025.1538875/full">https://www.frontiersin.org/journals/psychiatry/articles/10.3389/fpsyt.2025.1538875/full</a></li>\n<li><strong>R13</strong>. Crompton CJ. Autism diagnosis and the double empathy problem. British Journal of Psychiatry, 2025.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/41305990/">https://pubmed.ncbi.nlm.nih.gov/41305990/</a></li>\n<li><strong>R14</strong>. Carnevali L i wsp. Interpersonal motor synchrony in autism: a systematic review and meta-analysis. Frontiers in Psychiatry, 2024.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10909819/">https://pmc.ncbi.nlm.nih.gov/articles/PMC10909819/</a></li>\n<li><strong>R15</strong>. Kentrou V i wsp. Perceived misdiagnosis of psychiatric conditions in autistic adults. EClinicalMedicine, 2024.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11001629/">https://pmc.ncbi.nlm.nih.gov/articles/PMC11001629/</a></li>\n<li><strong>R16</strong>. Yerys BE i wsp. Co-occurring ADHD symptoms in autistic adults are associated with less independence in daily living activities and lower subjective quality of life. Autism, 2022.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/35916251/">https://pubmed.ncbi.nlm.nih.gov/35916251/</a></li>\n<li><strong>R17</strong>. Huang Z i wsp. Relationships between Sensory Processing and Executive Functioning in ASD, ADHD, and ASD+ADHD. Brain Sciences, 2024.<br/>Link: <a href="https://www.mdpi.com/2076-3425/14/6/566">https://www.mdpi.com/2076-3425/14/6/566</a></li>\n<li><strong>R18</strong>. Ward T i wsp. Understanding phenomenological experiences of autistic inertia, 2026.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12873400/">https://pmc.ncbi.nlm.nih.gov/articles/PMC12873400/</a></li>\n<li><strong>R19</strong>. Capp SJ i wsp. Is quality of life related to high autistic traits, high ADHD traits and their interaction? 2023.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10465683/">https://pmc.ncbi.nlm.nih.gov/articles/PMC10465683/</a></li>\n<li><strong>R20</strong>. French B i wsp. Risks Associated With Undiagnosed ADHD and/or Autism: A Mixed-Method Systematic Review, 2023.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10498662/">https://pmc.ncbi.nlm.nih.gov/articles/PMC10498662/</a></li>\n\n<li><strong>R21</strong>. Murray D, Lesser M, Lawson W. Attention, monotropism and the diagnostic criteria for autism. Autism, 2005.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/15857859/">https://pubmed.ncbi.nlm.nih.gov/15857859/</a></li>\n<li><strong>R22</strong>. Dwyer P i wsp. Hyper-Focus, Sticky Attention, and Springy Attention in Young Autistic Children: Toward Better Characterizing Autistic Attention. Journal of Autism and Developmental Disorders, 2024.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11341259/">https://pmc.ncbi.nlm.nih.gov/articles/PMC11341259/</a></li>\n<li><strong>R23</strong>. Amso D i wsp. Bottom-Up Attention Orienting in Young Children with Autism. Journal of Autism and Developmental Disorders, 2014.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4089391/">https://pmc.ncbi.nlm.nih.gov/articles/PMC4089391/</a></li>\n<li><strong>R24</strong>. Ursino M i wsp. Bottom-up vs. top-down connectivity imbalance in individuals with high autistic traits. Frontiers in Human Neuroscience, 2022.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9412751/">https://pmc.ncbi.nlm.nih.gov/articles/PMC9412751/</a></li>\n<li><strong>R25</strong>. Brosnan M i wsp. Thinking, fast and slow on the autism spectrum. Trends in Cognitive Sciences / commentary review, 2022.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10291371/">https://pmc.ncbi.nlm.nih.gov/articles/PMC10291371/</a></li>\n<li><strong>R26</strong>. Stolte M i wsp. Characterizing Creative Thinking and Creative Achievements in Relation to Symptoms of Attention-Deficit/Hyperactivity Disorder and Autism. Brain Sciences, 2022.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9283685/">https://pmc.ncbi.nlm.nih.gov/articles/PMC9283685/</a></li>\n<li><strong>R27</strong>. Hoogman M i wsp. Creativity and ADHD: A review of behavioral studies, the effect of psychostimulants, and neural underpinnings. Neuroscience &amp; Biobehavioral Reviews, 2020.<br/>Link: <a href="https://pubmed.ncbi.nlm.nih.gov/33035524/">https://pubmed.ncbi.nlm.nih.gov/33035524/</a></li>\n<li><strong>R28</strong>. Green J. Autistic phenomenology: past, present, and potential future. Neuroscience &amp; Biobehavioral Reviews, 2023.<br/>Link: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10788129/">https://pmc.ncbi.nlm.nih.gov/articles/PMC10788129/</a></li>\n\n</ul></div>','\n',char(10)),'Main bibliography','Some sources support the overall picture of AuDHD best; others support specific points more directly. For the more experiential points, I selected sources closest to the subject rather than pretending there is a perfect paper about every exact formulation.',NULL,NULL);
INSERT INTO content_sections VALUES(834,28,NULL,'heading',1,1,1,'Autyzm i regulacja mówienia','autyzm-i-regulacja-mowienia','Bardzo za mało albo bardzo za dużo — i co z tego wynika',1,replace('<p class="subtitle">Bardzo za mało albo bardzo za dużo — i co z tego wynika</p>\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'Autism and regulation of speech','Far too little or far too much — and what follows from that',NULL,NULL);
INSERT INTO content_sections VALUES(835,28,834,'heading',2,2,2,'Teza w postaci kompaktowej','teza-w-postaci-kompaktowej','Osoby autystyczne zazwyczaj mówią albo bardzo za mało, albo bardzo za dużo w stosunku do tego, czego sytuacja społeczna od nich oczekuje.',2,replace('<!-- ═══════════════════════════════════════════ -->\n\n<div class="teza-box">\n<p>Osoby autystyczne zazwyczaj mówią albo bardzo za mało, albo bardzo za dużo w stosunku do tego, czego sytuacja społeczna od nich oczekuje. Środek — neurotypowa, intuicyjnie wyważana ilość — jest dla osoby autystycznej obszarem, w którym trzeba operować świadomie i z wysiłkiem, a nie automatycznie.</p>\n\n<p>W trybie „za dużo" osobę autystyczną łatwo „rozkręcić" — wystarczy okazać autentyczne zainteresowanie tematem, w którym dana osoba ma kompetencję. Wtedy potrafi powiedzieć wszystko, co wie, w tym rzeczy, których ze względu na relacje międzyludzkie, dyskrecję zawodową albo własny interes nie powinno się mówić wcale.</p>\n\n<p>Pracodawcy, szefowie i osoby z większą społeczną biegłością — często nieświadomie, czasem celowo — wykorzystują tę asymetrię. Najczęściej do wewnątrzbiurowych rozgrywek, do pozyskiwania informacji o innych pracownikach, do wybadania nastrojów w zespole, do uzyskania krytyki kogoś nieobecnego.</p>\n</div>\n\n<div class="przyklad">\nTypowa scena: szef wpada do gabinetu, siada na biurku, mówi „słuchaj, ja się znam na tych liczbach średnio, opowiedz mi jak to wszystko działa". Autystyczny pracownik, szczęśliwy że ktoś wreszcie pyta, zaczyna od architektury systemu. Po 40 minutach szef wie wszystko o procedurach, o tym, kto je obchodzi, kto pracuje wolno, kto źle, gdzie są dziury w kontroli, co o całości myśli sam pracownik. Pracownik wraca do biurka z poczuciem produktywnej rozmowy. Trzy tygodnie później dwie osoby tracą pracę, a on nie rozumie, skąd szef wiedział.\n</div>\n\n<hr class="section-divider">\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'The thesis in compact form','Autistic people usually speak either far too little or far too much relative to what the social situation expects of them.',NULL,NULL);
INSERT INTO content_sections VALUES(836,28,834,'heading',2,2,3,'Rozwinięcie','rozwiniecie','Omówienie zagadnienia „Rozwinięcie” w kontekście opracowania „Autyzm i regulacja mówienia — teza i mechanizm”.',3,'<!-- ═══════════════════════════════════════════ -->','Elaboration','Discussion of “Elaboration” in the context of “Autism and regulation of speech — thesis and mechanism”.',NULL,NULL);
INSERT INTO content_sections VALUES(837,28,836,'heading',3,3,4,'Skąd się bierze bimodalność „za mało lub za dużo"','skad-sie-bierze-bimodalnosc-za-malo-lub-za-duzo','U osób neurotypowych ilość mówienia jest regulowana automatycznie, podświadomie, w czasie rzeczywistym — przez ciągłe odczytywanie sygnałów zwrotnych od rozmówcy (kontakt wzrokowy, mimika, postawa ciała, mikroskinienia głową, długość pauz).',4,replace('<p>U osób neurotypowych ilość mówienia jest regulowana automatycznie, podświadomie, w czasie rzeczywistym — przez ciągłe odczytywanie sygnałów zwrotnych od rozmówcy (kontakt wzrokowy, mimika, postawa ciała, mikroskinienia głową, długość pauz). Ta regulacja używa zasobów, ale nie wymaga świadomej uwagi. Działa w tle.</p>\n\n<p>U osób autystycznych ten kanał działa inaczej. Sygnały społeczne dochodzą wolniej, niekompletnie albo trafiają do świadomego, korowego procesu interpretacji, który już z definicji nie jest w czasie rzeczywistym. Konsekwencja jest dwoista, zależnie od strategii radzenia sobie z tym deficytem:</p>\n\n<ul>\n<li><strong>Tryb „za mało".</strong> Jeśli system społeczny jest dla danej osoby przeciążający albo źle skalibrowany, domyślnym wyjściem jest milczenie. Mówić mało, nie inicjować, czekać aż ktoś zapyta wprost. Bezpiecznie. Nie generuje zewnętrznego konfliktu, choć generuje wewnętrzną izolację.</li>\n<li><strong>Tryb „za dużo".</strong> Kiedy temat dotyka obszaru kompetencji, zainteresowania, monotropowej fascynacji — uruchamia się przeciwny biegun. Wewnętrzna kompresja informacji szuka ujścia, słuchacz wydaje się zainteresowany (jakkolwiek subtelnie sygnalizowałby co innego), monolog się rozwija. Brak automatycznego mechanizmu „on już chce iść". Brak automatycznego filtra „tego nie powinienem mu mówić w tym kontekście".</li>\n</ul>\n\n<p>Murray, Lesser i Lawson (2005) opisują to przez teorię monotropizmu: autystyczna uwaga działa wąsko i głęboko, a nie szeroko i płytko. Kiedy jest na temacie — jest na nim całkowicie, w tym zasoby normalnie używane do monitorowania kontekstu społecznego są zaalokowane do tematu, nie do kontekstu.</p>','\n',char(10)),'Where the “too little or too much” bimodality comes from','In neurotypical people, the amount of speech is regulated automatically, subconsciously, and in real time through constant reading of feedback from the other person: eye contact, facial expression, posture, tiny nods, and the length of pauses.',NULL,NULL);
INSERT INTO content_sections VALUES(838,28,836,'heading',3,3,5,'Pragmatyka języka — gdzie leży specyficzny problem','pragmatyka-jezyka-gdzie-lezy-specyficzny-problem','Loukusa i Moilanen (2009) w przeglądzie literatury pokazują, że deficyty pragmatyczne są obecne w autyzmie nawet wtedy, kiedy strukturalne aspekty języka (gramatyka, słownictwo) są zachowane lub ponadprzeciętne.',5,replace('<p>Loukusa i Moilanen (2009) w przeglądzie literatury pokazują, że deficyty pragmatyczne są obecne w autyzmie nawet wtedy, kiedy strukturalne aspekty języka (gramatyka, słownictwo) są zachowane lub ponadprzeciętne. Pragmatyka — czyli reguły społecznego użycia języka — to oddzielny system. Składa się na nią między innymi to, co Paul Grice (1975) ujął jako cztery maksymy konwersacyjne: ilości (mów tyle, ile potrzeba), jakości (mów prawdę), istotności (mów na temat), sposobu (mów jasno).</p>\n\n<p>Maksyma ilości jest tu najistotniejsza. U osoby autystycznej jest często naruszana w obie strony: w trybie „za mało" — mniej informacji niż słuchacz potrzebuje do zrozumienia kontekstu („nie powiedziałem dlaczego, bo to oczywiste"). W trybie „za dużo" — więcej informacji niż słuchacz potrzebuje albo chce („opowiem ci wszystko, co wiem na ten temat, bo to ciekawe").</p>\n\n<p>U osób neurotypowych maksyma ilości jest stosowana automatycznie. U osób autystycznych jej zachowanie wymaga świadomego, jawnego pytania samego siebie: „ile tej osoby naprawdę potrzeba". To pytanie kosztuje energię i często odpada pierwsze, kiedy zasobów brakuje.</p>','\n',char(10)),'Language pragmatics — where the specific difficulty lies','In their literature review, Loukusa and Moilanen (2009) show that pragmatic deficits are present in autism even when the structural aspects of language — grammar and vocabulary — are preserved or above average.',NULL,NULL);
INSERT INTO content_sections VALUES(839,28,836,'heading',3,3,6,'Dlaczego łatwo „rozkręcić" osobę autystyczną','dlaczego-latwo-rozkrecic-osobe-autystyczna','Mechanizm jest prosty i wynika bezpośrednio z trybu „za dużo". Wystarczą trzy elementy:',6,replace('<p>Mechanizm jest prosty i wynika bezpośrednio z trybu „za dużo". Wystarczą trzy elementy:</p>\n\n<ol>\n<li><strong>Temat z obszaru kompetencji lub zainteresowania.</strong> Uruchamia tryb monotropowy. Uwaga osoby autystycznej skupia się na temacie, kontekst społeczny schodzi na drugi plan.</li>\n<li><strong>Sygnał autentycznego zainteresowania od rozmówcy.</strong> „Naprawdę chcę to zrozumieć". „Opowiedz mi". „Nigdy mi tego nikt nie wytłumaczył". Dla osoby autystycznej, która rzadko spotyka się z takim zainteresowaniem swoim tematem, jest to silnie nagradzające i obniża czujność co do intencji.</li>\n<li><strong>Brak jawnych granic czasowych albo tematycznych.</strong> Nie ma „mam piętnaście minut". Nie ma „interesuje mnie tylko procedura, nie ludzie". Brak granicy zewnętrznej + brak granicy wewnętrznej = monolog się rozwija aż do wyczerpania tematu.</li>\n</ol>\n\n<p>W tym trybie osoba autystyczna powie też rzeczy, których w stanie normalnej regulacji społecznej nie powiedziałaby — bo zwykle są blokowane nie przez ich treść, lecz przez metareguły relacyjne („o nieobecnych źle się nie mówi", „nie zdradza się szczegółów wewnętrznych zespołu komuś z zewnątrz", „nie krytykuje się przełożonego przed jego przełożonym"). Te metareguły są pragmatyczne, nie merytoryczne. Kiedy tryb monotropowy jest na pełnych obrotach, są one filtrem, który spadł pierwszy.</p>','\n',char(10)),'Why it is easy to “get an autistic person going”','The mechanism is simple and follows directly from the “too much” mode. Three elements are enough:',NULL,NULL);
INSERT INTO content_sections VALUES(840,28,836,'heading',3,3,7,'Jak to wygląda od strony wykorzystującego','jak-to-wyglada-od-strony-wykorzystujacego','Najczęściej nieświadomie. Przełożony, który chce wiedzieć, co naprawdę dzieje się w zespole, intuicyjnie wybiera do rozmowy osobę, która „wszystko wie i chętnie opowiada".',7,replace('<p>Najczęściej nieświadomie. Przełożony, który chce wiedzieć, co naprawdę dzieje się w zespole, intuicyjnie wybiera do rozmowy osobę, która „wszystko wie i chętnie opowiada". To racjonalna strategia społeczna: kierować pytania tam, skąd najłatwiej dostać szczerą odpowiedź. Tylko że dla osoby autystycznej koszt tej szczerości jest niewspółmiernie wyższy niż dla osoby neurotypowej w analogicznej rozmowie.</p>\n\n<p>Świadome wykorzystanie też się zdarza. Hartley i Fisher (2018) w eksperymentalnym badaniu z Ultimatum Game i Dictator Game pokazali, że dzieci autystyczne trzy razy częściej akceptują niesprawiedliwe oferty i o 37% rzadziej odwzajemniają fair offers — czyli wykazują systemowo niższy próg tolerancji na bycie wykorzystywanym. Dorosłe osoby autystyczne to często wiedzą o sobie, ale wiedza jest abstrakcyjna; w realnej sytuacji, w realnym czasie, w obecności autentycznie zainteresowanego rozmówcy, ten próg nadal nie podnosi się sam.</p>\n\n<p>Dochodzi do tego efekt Hull i wsp. (2017) — wieloletnie społeczne maskowanie. Osoby autystyczne, szczególnie późno zdiagnozowane, mają za sobą dekady tłumienia własnego stylu komunikacji, żeby pasować. Kiedy ktoś wreszcie sygnalizuje „możesz mówić jak ci wygodnie, chcę zrozumieć" — następuje zwolnienie hamulca. Wszystko, co zostało stłumione, wychodzi naraz. To samo w sobie jest produktywne i potrzebne (zob. Milton 2012 i 2022 o problemie podwójnej empatii — niedopasowanie ASD–NT nie jest deficytem ASD, tylko obustronnym niedopasowaniem stylów). Problem powstaje wtedy, kiedy „możesz mówić jak ci wygodnie" jest narzędziem, nie zaproszeniem.</p>','\n',char(10)),'What it looks like from the exploiter''s side','Most often, it is unconscious. A manager who wants to know what is really happening in the team intuitively chooses to talk to the person who “knows everything and is happy to tell you”.',NULL,NULL);
INSERT INTO content_sections VALUES(841,28,836,'heading',3,3,8,'Co z tym zrobić','co-z-tym-zrobic','Zewnętrzny licznik czasu. Zegar na biurku, alarm w telefonie. Trzy minuty na odpowiedź. Pięć minut na monolog. Wtedy się przerywa, niezależnie czy temat jest skończony. Wewnętrzna regulacja zawodzi, zewnętrzna — fizyczna, mechaniczna — działa.',8,replace('<p>Trzy reguły z praktyki:</p>\n\n<ol>\n<li><strong>Zewnętrzny licznik czasu.</strong> Zegar na biurku, alarm w telefonie. Trzy minuty na odpowiedź. Pięć minut na monolog. Wtedy się przerywa, niezależnie czy temat jest skończony. Wewnętrzna regulacja zawodzi, zewnętrzna — fizyczna, mechaniczna — działa.</li>\n<li><strong>Lista tematów off-limits.</strong> Przed wejściem do sytuacji zawodowej, w której wiadomo, że będzie rozmowa — wypisać sobie, czego się nie mówi. Wewnętrznie, na kartce, w notatce. „O Markusie nic. O wczorajszym spięciu nic. O własnym nastroju w pracy nic." Lista odbiera pracę filtrowi pragmatycznemu, który w trybie monotropowym i tak by zawiódł.</li>\n<li><strong>Reguła 24 godzin dla informacji zwrotnych.</strong> Jeśli ktoś prosi o opinię o czymś albo o kimś — „przemyślę i odezwę się jutro". Każda opinia wygłoszona natychmiast jest opinią wygłoszoną pod wpływem trybu, w którym nie ma czasu na filtr pragmatyczny.</li>\n</ol>\n\n<div class="nb">\n<strong>Co nie jest częścią tej tezy.</strong> „Mówienie za dużo" u osób autystycznych nie jest objawem braku kontroli, niedojrzałości emocjonalnej ani potrzeby uwagi. Jest skutkiem strukturalnie innej regulacji pragmatycznej, w której kanał automatyczny działa inaczej niż u osób neurotypowych, a kanał świadomy musi nadrobić wszystko, czego automat nie zrobił. To w pełni odpowiada ramie podwójnej empatii Miltona (2012, 2022): autystyczny styl komunikacji nie jest gorszy ani lepszy od neurotypowego — jest po prostu inny i niedopasowany do większościowych norm społecznych. Wykorzystanie tego niedopasowania jest problemem etycznym tej drugiej strony, nie wadą osoby autystycznej.\n</div>\n\n<hr class="section-divider">\n\n<!-- ═══════════════════════════════════════════ -->','\n',char(10)),'What to do about it','Use an external time counter. A clock on the desk, an alarm on the phone. Three minutes for an answer. Five minutes for a monologue. Then stop, regardless of whether the subject is finished. Internal regulation fails; external regulation — physical and mechanical — works.',NULL,NULL);
INSERT INTO content_sections VALUES(842,28,834,'heading',2,2,9,'Źródła','zrodla','Grice, H. P. (1975). Logic and conversation. In P. Cole & J. L. Morgan (Eds.), Syntax and Semantics, Vol. 3: Speech Acts (pp. 41–58). New York: Academic Press.',9,replace('<!-- ═══════════════════════════════════════════ -->\n\n<ol class="zrodla">\n\n<li>\n<strong>Grice, H. P. (1975).</strong> Logic and conversation. In P. Cole &amp; J. L. Morgan (Eds.), <em>Syntax and Semantics, Vol. 3: Speech Acts</em> (pp. 41–58). New York: Academic Press.<br>\nDOI: <a href="https://doi.org/10.1163/9789004368811_003">10.1163/9789004368811_003</a><br>\n[klasyczna teoria maksym konwersacyjnych — ilości, jakości, istotności, sposobu]\n</li>\n\n<li>\n<strong>Loukusa, S., &amp; Moilanen, I. (2009).</strong> Pragmatic inference abilities in individuals with Asperger syndrome or high-functioning autism. A review. <em>Research in Autism Spectrum Disorders</em>, 3(4), 890–904.<br>\nDOI: <a href="https://doi.org/10.1016/j.rasd.2009.05.002">10.1016/j.rasd.2009.05.002</a><br>\n[deficyty pragmatyczne w autyzmie wysokofunkcjonującym przy zachowanej strukturze języka]\n</li>\n\n<li>\n<strong>Murray, D., Lesser, M., &amp; Lawson, W. (2005).</strong> Attention, monotropism and the diagnostic criteria for autism. <em>Autism</em>, 9(2), 139–156.<br>\nDOI: <a href="https://doi.org/10.1177/1362361305051398">10.1177/1362361305051398</a><br>\nPubMed: <a href="https://pubmed.ncbi.nlm.nih.gov/15857859/">15857859</a><br>\n[teoria monotropizmu — wąska i głęboka alokacja uwagi, w tym przekierowanie zasobów społecznych do tematu]\n</li>\n\n<li>\n<strong>Milton, D. E. M. (2012).</strong> On the ontological status of autism: the „double empathy problem". <em>Disability &amp; Society</em>, 27(6), 883–887.<br>\nDOI: <a href="https://doi.org/10.1080/09687599.2012.710008">10.1080/09687599.2012.710008</a><br>\n[rama interpretacyjna — niedopasowanie komunikacyjne ASD–NT jako obustronne, nie jednostronny deficyt ASD]\n</li>\n\n<li>\n<strong>Milton, D., Gurbuz, E., &amp; López, B. (2022).</strong> The „double empathy problem": Ten years on. <em>Autism</em>, 26(8), 1901–1903.<br>\nDOI: <a href="https://doi.org/10.1177/13623613221129123">10.1177/13623613221129123</a><br>\n[uaktualnienie problemu podwójnej empatii po dekadzie badań]\n</li>\n\n<li>\n<strong>Hull, L., Petrides, K. V., Allison, C., Smith, P., Baron-Cohen, S., Lai, M.-C., &amp; Mandy, W. (2017).</strong> „Putting on My Best Normal": Social Camouflaging in Adults with Autism Spectrum Conditions. <em>Journal of Autism and Developmental Disorders</em>, 47(8), 2519–2534.<br>\nDOI: <a href="https://doi.org/10.1007/s10803-017-3166-5">10.1007/s10803-017-3166-5</a><br>\nPubMed: <a href="https://pubmed.ncbi.nlm.nih.gov/28527095/">28527095</a><br>\nPMC: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5509825/">PMC5509825</a><br>\n[społeczne maskowanie u dorosłych — koszt długotrwałego tłumienia własnego stylu komunikacji]\n</li>\n\n<li>\n<strong>Hartley, C., &amp; Fisher, S. (2018).</strong> Do Children with Autism Spectrum Disorder Share Fairly and Reciprocally? <em>Journal of Autism and Developmental Disorders</em>, 48(8), 2714–2726.<br>\nDOI: <a href="https://doi.org/10.1007/s10803-018-3528-7">10.1007/s10803-018-3528-7</a><br>\nPubMed: <a href="https://pubmed.ncbi.nlm.nih.gov/29512018/">29512018</a><br>\nPMC: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6061008/">PMC6061008</a><br>\n[eksperymentalne dowody na wyższą tolerancję wobec niesprawiedliwych ofert i niższe odwzajemnianie — podatność na wykorzystanie]\n</li>\n\n</ol>\n\n<div class="footer-meta">\n  autyzm-regulacja-mowienia-v01.00-2026-05-14.html · wersja 01.00 · 2026-05-14, 16:55 CEST<br>\n  stworzony z pomocą Claude (Anthropic) · Claude Opus 4.7 (claude-opus-4-7)<br>\n  rodzaj: notatka konceptualna (teza + rozwinięcie + źródła)\n</div>\n\n</div>','\n',char(10)),'Sources','Grice, H. P. (1975). Logic and conversation. In P. Cole & J. L. Morgan (Eds.), Syntax and Semantics, Vol. 3: Speech Acts (pp. 41–58). New York: Academic Press.',NULL,NULL);
INSERT INTO content_sections VALUES(843,29,NULL,'heading',1,1,1,'Co to znaczy, że mam AuDHD','co-to-znaczy-ze-mam-audhd','Krótki przewodnik dla bliskich',1,replace('<p style="font-size:1.05em; margin-top:0;">Krótki przewodnik dla bliskich</p>\n<div class="meta">\n  Wersja 3.01 · 9 lipca 2026<br>\n  Stworzony z&nbsp;pomocą Claude (Anthropic), model Opus 4.6\n</div>\n\n<p>Daję ci to do przeczytania. Nie dlatego, że potrzebuję twojej zgody — dlatego, że dotyczy to też ciebie. Przeczytaj do końca.</p>','\n',char(10)),'What it means that I have AuDHD','A short guide for people close to me',NULL,NULL);
INSERT INTO content_sections VALUES(844,29,843,'heading',2,2,2,'Czym jest AuDHD','czym-jest-audhd','AuDHD to skrót oznaczający, że u jednej osoby współwystępują dwie rzeczy: autyzm (ASD) i ADHD. Nie jedno albo drugie — obydwa naraz, i wzajemnie na siebie wpływają.',2,replace('<p>AuDHD to skrót oznaczający, że u jednej osoby współwystępują dwie rzeczy: autyzm (ASD) i ADHD. Nie jedno albo drugie — obydwa naraz, i wzajemnie na siebie wpływają. Do tego dochodzi u mnie dysleksja i zaburzenie lękowe uogólnione (GAD — taki lęk, który nie ma konkretnego powodu, po prostu jest).</p>\n\n<p>Zarówno ADHD, jak i autyzm mam potwierdzone diagnostycznie. Diagnostyka dorosłych jest trudna, bo narzędzia powstawały z myślą o dzieciach, nie o dorosłych, którzy przez dekady nauczyli się kompensować.</p>','\n',char(10)),'What AuDHD is','AuDHD is shorthand for two things co-occurring in one person: autism (ASD) and ADHD. Not one or the other — both at once, interacting with each other.',NULL,NULL);
INSERT INTO content_sections VALUES(845,29,843,'heading',2,2,3,'To, co prawdopodobnie myślisz o ADHD — i dlaczego to nieprawda','to-co-prawdopodobnie-myslisz-o-adhd-i-dlaczego-to-nieprawda','„ADHD to nadpobudliwe dziecko, które nie może usiedzieć w ławce."',3,replace('<p class="stereotype">„ADHD to nadpobudliwe dziecko, które nie może usiedzieć w ławce."</p>\n\n<p>To jest obraz z lat 90. i dotyczył wyłącznie chłopców w wieku szkolnym. ADHD to stan neurorozwojowy — nie choroba, nie faza, nie kwestia wychowania. Oznacza, że mózg inaczej zarządza uwagą, motywacją i kontrolą impulsów. Nie „gorzej" — inaczej. Ale w świecie zaprojektowanym pod neurotypowy mózg (czyli taki, który nie ma ADHD ani autyzmu), to „inaczej" generuje realne problemy.</p>\n\n<p class="correction">ADHD nie mija z wiekiem.</p>\n\n<p>Dorosły z ADHD nie skacze po meblach. Za to może nie być w stanie zacząć ważnego zadania, bo jest nudne. Zapominać o spotkaniach. Reagować emocjonalnie za mocno albo za szybko. Nie móc zasnąć, bo mózg nie chce się wyłączyć. To nie jest kwestia „weź się w garść" — to jest kwestia neurochemii.</p>\n\n<p>Jednocześnie ten sam mózg potrafi wejść w stan hiperfokusu — wielogodzinnej koncentracji na czymś, co go zainteresuje. To nie jest sprzeczność. To jest ten sam mechanizm widziany z dwóch stron.</p>','\n',char(10)),'What you probably think ADHD is — and why that is not true','“ADHD is a hyperactive child who cannot sit still at a desk.”',NULL,NULL);
INSERT INTO content_sections VALUES(846,29,843,'heading',2,2,4,'To, co prawdopodobnie myślisz o autyzmie — i dlaczego to nieprawda','to-co-prawdopodobnie-myslisz-o-autyzmie-i-dlaczego-to-nieprawda','„Autyzm to Rain Man. Albo dziecko, które się nie odzywa i kręci kółka."',4,replace('<p class="stereotype">„Autyzm to Rain Man. Albo dziecko, które się nie odzywa i kręci kółka."</p>\n\n<p>To jest najbardziej szkodliwy stereotyp, jaki istnieje w Polsce na temat autyzmu. Spektrum autyzmu jest ogromne. Na jednym końcu są osoby wymagające stałej opieki. Na drugim — ludzie, którzy skończyli studia, mają partnerów, pracują, prowadzą firmy. Nie wyglądają „autystycznie", bo nauczyli się wyglądać normalnie. To się nazywa masking — kamuflaż — i jest kluczem do zrozumienia, dlaczego nie widziałeś/aś tego przez lata.</p>\n\n<p class="correction">Autyzm u dorosłego o wysokim IQ wygląda zupełnie inaczej, niż myślisz.</p>\n\n<p>Wygląda tak: człowiek, który w towarzystwie jest sprawny, dowcipny, komunikatywny — ale po powrocie do domu jest kompletnie wykończony i potrzebuje być sam. Człowiek, który potrafi prowadzić skomplikowaną rozmowę — ale świadomie monitoruje swoją mimikę, ton głosu i kontakt wzrokowy, bo to nie przychodzi mu naturalnie. Człowiek, który ma silną potrzebę rutyny, przewidywalności, a nagłe zmiany planów odczuwa fizycznie — nie jako „irytację", ale jako coś bliższego bólowi.</p>\n\n<p>Autyzm to inny sposób przetwarzania bodźców — dźwięków, dotyku, światła, informacji społecznych. Inny, nie gorszy. Ale kosztowny, kiedy żyjesz w świecie, który jest skalibrowany pod neurotypowy układ nerwowy.</p>','\n',char(10)),'What you probably think autism is — and why that is not true','“Autism is Rain Man. Or a child who does not speak and spins wheels.”',NULL,NULL);
INSERT INTO content_sections VALUES(847,29,843,'heading',2,2,5,'Dlaczego AuDHD jest trudniejsze niż każde z osobna','dlaczego-audhd-jest-trudniejsze-niz-kazde-z-osobna','ADHD i autyzm w wielu miejscach ciągną w przeciwne strony. Autyzm potrzebuje rutyny — ADHD nie znosi monotonii. Autyzm każe kontrolować każdą interakcję społeczną — ADHD wpycha impulsywne komentarze w środku tej kontroli.',5,replace('<p>ADHD i autyzm w wielu miejscach ciągną w przeciwne strony. Autyzm potrzebuje rutyny — ADHD nie znosi monotonii. Autyzm każe kontrolować każdą interakcję społeczną — ADHD wpycha impulsywne komentarze w środku tej kontroli. Autyzm chce ciszy — ADHD potrzebuje stymulacji.</p>\n\n<p>Efekt jest taki, że jedno maskuje drugie. ADHD-owa impulsywność wygląda jak „spontaniczność", więc nikt nie widzi autyzmu. Autystyczna potrzeba struktury wygląda jak „zorganizowanie", więc nikt nie widzi ADHD. Obydwa są niewidoczne — ale obydwa działają non-stop.</p>','\n',char(10)),'Why AuDHD is harder than either condition on its own','ADHD and autism pull in opposite directions in many areas. Autism needs routine; ADHD cannot stand monotony. Autism pushes a person to control every social interaction; ADHD inserts impulsive comments right in the middle of that control.',NULL,NULL);
INSERT INTO content_sections VALUES(848,29,843,'heading',2,2,6,'„Ale przecież wyglądałeś normalnie"','ale-przeciez-wygladales-normalnie','Tak. Bo na to szło prawie wszystko.',6,replace('<p>Tak. Bo na to szło prawie wszystko.</p>\n\n<p>Masking — kamuflaż — to nie jest „udawanie" w sensie, który pewnie ci przychodzi do głowy. To jest wyuczony, wyczerpujący proces dostosowywania się do oczekiwań społecznych. Kontrola mimiki. Monitorowanie tonu głosu. Pamiętanie, kiedy się uśmiechnąć, kiedy skinąć głową, ile utrzymywać kontakt wzrokowy. Uczenie się skryptów społecznych — „jak ludzie reagują w tej sytuacji" — i odtwarzanie ich tak, żeby wyglądało to naturalnie.</p>\n\n<p>To nie jest coś, co włączam i wyłączam. To działa od dzieciństwa. To jest jak chodzenie po linie — z zewnątrz wygląda, jakby ktoś szedł po chodniku, ale koszt energetyczny jest zupełnie inny.</p>\n\n<div class="highlight">\nPrzy diagnostyce zbadano mój poziom kamuflaż u testem CAT-Q. Wynik: bardzo wysoki. Jednocześnie test obserwacyjny na autyzm (ADOS-2) dał wynik 0 — czyli „nie widać nic". To nie znaczy, że nic nie ma. To znaczy, że kamuflaż działa.\n</div>\n\n<p>Wiem, że to brzmi jak paradoks. To jest znany problem diagnostyczny u dorosłych z wysokim IQ — narzędzie mierzy to, co widać, a po 30+ latach kamuflaż u nic nie widać. Koszt tego „nic nie widać" jest realny i fizyczny.</p>','\n',char(10)),'“But you looked normal”','Yes. Because almost everything went into making that happen.',NULL,NULL);
INSERT INTO content_sections VALUES(849,29,843,'heading',2,2,7,'Co z tym zrobić','co-z-tym-zrobic','Nic specjalnego. Wiedzieć. Nie mówić, że „wszyscy są trochę ADHD" — bo to jest jak mówienie osobie z astmą, że każdemu się czasem ciężko oddycha. Nie szukać rozwiązań. Nie podważać diagnozy.',7,replace('<p>Nic specjalnego. Wiedzieć. Nie mówić, że „wszyscy są trochę ADHD" — bo to jest jak mówienie osobie z astmą, że każdemu się czasem ciężko oddycha. Nie szukać rozwiązań. Nie podważać diagnozy.</p>\n\n<p>Jeśli odwołuję spotkanie, znikam na parę dni albo reaguję nieproporcjonalnie do sytuacji — teraz wiesz, że za tym stoi coś więcej niż zły humor. Nie musisz tego rozumieć od razu. Wystarczy, że nie udajesz, że rozumiesz, kiedy nie rozumiesz.</p>\n\n<div class="separator">· · ·</div>\n\n<p style="font-size:0.92em;">Masz pytania — pytaj. Wolę odpowiedzieć na pytanie, nawet niezdarne, niż żyć z milczeniem, które udaje zrozumienie.</p>\n\n<div class="footer-note">\n  Dokument: co-to-znaczy-audhd-v03_01-2026-07-09.html · Wersja 03.01 · 9 lipca 2026, ~CEST<br>\n  Stworzony z&nbsp;pomocą Claude (Anthropic), model: Claude Opus 4.6\n</div>','\n',char(10)),'What to do about it','Nothing special. Know. Do not say “everyone is a little ADHD”, because that is like telling someone with asthma that everyone sometimes finds it hard to breathe. Do not look for solutions. Do not question the diagnosis.',NULL,NULL);
INSERT INTO content_sections VALUES(850,30,NULL,'heading',1,1,1,'Długa lista publikacji','dluga-lista-publikacji','Omówienie zagadnienia „Długa lista publikacji” w kontekście opracowania „Długa lista publikacji — 4.00”.',1,replace('<section>\n\n<div class="zestawienie">','\n',char(10)),'Long list of publications','Discussion of “Long list of publications” in the context of “Long list of publications — 4.00”.',NULL,NULL);
INSERT INTO content_sections VALUES(851,30,850,'heading',2,2,2,'Zestawienie','zestawienie','Książki, rozdziały i prace dyplomowe: 25 (książki samodzielne: 19; rozdziały w książkach: 5; thesis: 1). Artykuły naukowe: 77 (z DOI: 72; bez DOI: 5). Łącznie: 102 pozycje (lista główna: 77; Appendix 1: 20; Appendix 2: 5).',2,replace('<p>Książki, rozdziały i prace dyplomowe: <strong>25</strong> (książki samodzielne: 19; rozdziały w książkach: 5; thesis: 1). Artykuły naukowe: <strong>77</strong> (z DOI: 72; bez DOI: 5). Łącznie: <strong>102</strong> pozycje (lista główna: 77; Appendix 1: 20; Appendix 2: 5).</p>\n</div>\n\n\n<div class="top10-section">','\n',char(10)),'Overview','Books, chapters, and theses: 25 (stand-alone books: 19; book chapters: 5; thesis: 1). Scientific articles: 77 (with DOI: 72; without DOI: 5). Total: 102 items (main list: 77; Appendix 1: 20; Appendix 2: 5).',NULL,NULL);
INSERT INTO content_sections VALUES(852,30,850,'heading',2,2,3,'15 najważniejszych dla tego korpusu','15-najwazniejszych-dla-tego-korpusu','Wybór dla osoby AuDHD w środowisku korporacyjnym: maskowanie, otwarte pętle, podwójna empatia, monotropizm, samoleczenie, ryzyko oraz bezpośrednie nakładanie się ASD i ADHD w dorosłości. Pierwotny TOP 10 zachowano; pięć nowych pozycji dopisano z Appendix 1.',3,replace('<p class="top10-intro">Wybór dla osoby AuDHD w środowisku korporacyjnym: maskowanie, otwarte pętle, podwójna empatia, monotropizm, samoleczenie, ryzyko oraz bezpośrednie nakładanie się ASD i ADHD w dorosłości. Pierwotny TOP 10 zachowano; pięć nowych pozycji dopisano z Appendix 1.</p>\n\n<ol class="lista-top10">\n<li>Milton, D., Gurbuz, E., &amp; López, B. (2022). The ''double empathy problem'': Ten years on. <em>Autism</em>, 26(8), 1901–1903. DOI: <a class="link" href="https://doi.org/10.1177/13623613221129123">10.1177/13623613221129123</a></li>\n<li>Murray, D., Lesser, M., &amp; Lawson, W. (2005). Attention, monotropism and the diagnostic criteria for autism. <em>Autism</em>, 9(2), 139–156.<br>DOI: <a class="link" href="https://doi.org/10.1177/1362361305051398">10.1177/1362361305051398</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/15857859/">https://pubmed.ncbi.nlm.nih.gov/15857859/</a></li>\n<li>Hull, L., Petrides, K. V., Allison, C., Smith, P., Baron-Cohen, S., Lai, M.-C., &amp; Mandy, W. (2017). "Putting on My Best Normal": Social Camouflaging in Adults with Autism Spectrum Conditions. <em>Journal of Autism and Developmental Disorders</em>, 47(8), 2519–2534.<br>DOI: <a class="link" href="https://doi.org/10.1007/s10803-017-3166-5">10.1007/s10803-017-3166-5</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/28527095/">https://pubmed.ncbi.nlm.nih.gov/28527095/</a><br>PMC: <a class="link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5509825/">https://pmc.ncbi.nlm.nih.gov/articles/PMC5509825/</a></li>\n<li>Crane, L., Goddard, L., &amp; Pring, L. (2013). Autobiographical memory in adults with autism spectrum disorder: the role of depressed mood, rumination, working memory and theory of mind. <em>Autism</em>, 17(2), 205–219.<br>DOI: <a class="link" href="https://doi.org/10.1177/1362361311418690">10.1177/1362361311418690</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/21975036/">https://pubmed.ncbi.nlm.nih.gov/21975036/</a></li>\n<li>Egan, V., Linenberg, O., &amp; O''Nions, E. (2019). The measurement of adult pathological demand avoidance traits. <em>Journal of Autism and Developmental Disorders</em>, 49(2), 481–494.<br>DOI: <a class="link" href="https://doi.org/10.1007/s10803-018-3722-7">10.1007/s10803-018-3722-7</a><br>PMC: <a class="link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6373319/">https://pmc.ncbi.nlm.nih.gov/articles/PMC6373319/</a></li>\n<li>Kinnaird, E., Stewart, C., &amp; Tchanturia, K. (2019). Investigating alexithymia in autism: A systematic review and meta-analysis. <em>European Psychiatry</em>, 55, 80–89.<br>DOI: <a class="link" href="https://doi.org/10.1016/j.eurpsy.2018.09.004">10.1016/j.eurpsy.2018.09.004</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/30399531/">https://pubmed.ncbi.nlm.nih.gov/30399531/</a><br>PMC: <a class="link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6331035/">https://pmc.ncbi.nlm.nih.gov/articles/PMC6331035/</a></li>\n<li>Cooper, K., Smith, L. G. E., &amp; Russell, A. (2017). Social identity, self-esteem, and mental health in autism. <em>European Journal of Social Psychology</em>, 47(7), 844–854. DOI: <a class="link" href="https://doi.org/10.1002/ejsp.2297">10.1002/ejsp.2297</a></li>\n<li>Cassidy, S., Bradley, L., Shaw, R., &amp; Baron-Cohen, S. (2018). Risk markers for suicidality in autistic adults. <em>Molecular Autism</em>, 9, 42. DOI: <a class="link" href="https://doi.org/10.1186/s13229-018-0226-4">10.1186/s13229-018-0226-4</a>. PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/30083306/">https://pubmed.ncbi.nlm.nih.gov/30083306/</a></li>\n<li>Mariani, J. J., Khantzian, E. J., &amp; Levin, F. R. (2014). The Self-Medication Hypothesis and Psychostimulant Treatment of Cocaine Dependence: An Update. <em>The American Journal on Addictions</em>, 23(2), 189–193.<br>DOI: <a class="link" href="https://doi.org/10.1111/j.1521-0391.2013.12086.x">10.1111/j.1521-0391.2013.12086.x</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/25187055/">https://pubmed.ncbi.nlm.nih.gov/25187055/</a><br>PMC: <a class="link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4227391/">https://pmc.ncbi.nlm.nih.gov/articles/PMC4227391/</a></li>\n<li>Chapman, R., &amp; Botha, M. (2023). Neurodivergence-informed therapy. <em>Developmental Medicine &amp; Child Neurology</em>, 65(3), 310–317.<br>DOI: <a class="link" href="https://doi.org/10.1111/dmcn.15384">10.1111/dmcn.15384</a></li>\n<li>Waldren, L. H., Leung, F. Y. N., Hargitai, L. D., Burgoyne, A. P., Liceralde, V. R. T., Livingston, L. A., &amp; Shah, P. (2024). Unpacking the overlap between Autism and ADHD in adults: A multi-method approach. <em>Cortex</em>, 173, 120–137.<br>DOI: <a class="link" href="https://doi.org/10.1016/j.cortex.2023.12.016">10.1016/j.cortex.2023.12.016</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/38387375/">https://pubmed.ncbi.nlm.nih.gov/38387375/</a></li>\n<li>Shakeshaft, A., Heron, J., Blakey, R., Riglin, L., Davey Smith, G., Stergiakouli, E., Tilling, K., &amp; Thapar, A. (2023). Co-development of attention deficit hyperactivity disorder and autistic trait trajectories from childhood to early adulthood. <em>Journal of Child Psychology and Psychiatry</em>, 64(11), 1596–1607.<br>DOI: <a class="link" href="https://doi.org/10.1111/jcpp.13851">10.1111/jcpp.13851</a><br>PMC: <a class="link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7615536/">https://pmc.ncbi.nlm.nih.gov/articles/PMC7615536/</a></li>\n<li>Yerys, B. E., McQuaid, G. A., Lee, N. R., &amp; Wallace, G. L. (2022). Co-occurring ADHD symptoms in autistic adults are associated with less independence in daily living activities and lower subjective quality of life. <em>Autism</em>, 26(8), 2188–2195.<br>DOI: <a class="link" href="https://doi.org/10.1177/13623613221112198">10.1177/13623613221112198</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/35916251/">https://pubmed.ncbi.nlm.nih.gov/35916251/</a></li>\n<li>Hayashi, W., Hanawa, Y., Saga, N., Nakamura, D., &amp; Iwanami, A. (2022). ASD symptoms in adults with ADHD: a comparative study using ADOS-2. <em>European Archives of Psychiatry and Clinical Neuroscience</em>, 272(8), 1481–1494.<br>DOI: <a class="link" href="https://doi.org/10.1007/s00406-021-01362-9">10.1007/s00406-021-01362-9</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/34993599/">https://pubmed.ncbi.nlm.nih.gov/34993599/</a></li>\n<li>Wurth, P., Fuermaier, A. B. M., Strand, A. H., &amp; Thorell, L. B. (2025). Diagnosis acceptance, masking, and perceived benefits and challenges in adults with ADHD and ASD: associations with quality of life. <em>Frontiers in Psychiatry</em>, 16, 1668780.<br>DOI: <a class="link" href="https://doi.org/10.3389/fpsyt.2025.1668780">10.3389/fpsyt.2025.1668780</a><br>PubMed: <a class="link" href="https://pubmed.ncbi.nlm.nih.gov/41169493/">https://pubmed.ncbi.nlm.nih.gov/41169493/</a></li>\n</ol>\n</div>\n\n<hr class="separator">\n\n<p><strong>Lista główna: 77 pozycji.</strong> Sortowanie chronologiczne według roku, potem pierwszego autora. Appendix 1 zawiera 20 pozycji uzupełniających ASD ↔ ADHD / AuDHD; Appendix 2 — 5 prac o okresie po późnej diagnozie i wsparciu postdiagnostycznym. Łącznie dokument obejmuje 102 publikacje.</p>\n\n<ol class="lista-publikacji">\n<li>Boole, G. (1854). <em>An Investigation of the Laws of Thought, on Which are Founded the Mathematical Theories of Logic and Probabilities</em>. London: Walton &amp; Maberly; Cambridge: Macmillan &amp; Co.</li>\n<li>D