INSERT INTO content_sections VALUES(967,1,1,'volume',NULL,2,1030,'Tom IX. Korekta i przesłuchanie','korekta-przesluchanie','Adversarialna kontrola wcześniejszych tez: steelmanning systemu, krytyka własnej metody i zrewidowana konkluzja.',30,NULL,NULL,NULL,NULL,NULL);
